E["item:aged-gorilla-sinew"] = {t="item",n="Aged Gorilla Sinew",z="stranglethorn",s="Aged Gorilla Sinew comes from Elder Mistvale Gorillas east of Booty Bay in Stranglethorn Vale. Far Seer Mok'thardin needs one as a magical tether for his work.",h="Aged Gorilla Sinew comes from Elder Mistvale Gorillas east of Booty Bay in Stranglethorn Vale.",sec={{t="A Magical Tether",b="East of Booty Bay, Elder Mistvale Gorillas forage in the jungle. Far Seer Mok'thardin needs an aged sinew from one of them to bind feathers, claws, and a pristine fang in place. The sinew must be perfect, so finding one may take patience.",sp=0}},faq={{q="Where can I find Aged Gorilla Sinew?",a="Elder Mistvale Gorillas forage east of Booty Bay in Stranglethorn Vale, and one may yield an aged sinew.",al={"aged sinew location","where gorilla sinew","sinew where"}},{q="Who needs the sinew?",a="Far Seer Mok'thardin in Grom'gol needs an Aged Gorilla Sinew as a magical tether.",al={"who wants sinew","Mok'thardin sinew","far seer needs what"}},{q="What is the sinew used for?",a="Mok'thardin uses the sinew to hold feathers, claws, and a pristine fang in place.",al={"why sinew","what for aged gorilla sinew","magical tether"}},{q="Why must the sinew be perfect?",a="Mok'thardin requires a perfect sinew for his magical tether.",al={"perfect sinew why","good sinew","why aged"}}},kw={"aged gorilla sinew","booty bay","elder mistvale gorilla","far seer mok'thardin","gorilla sinew","magical tether","mistvale valley","stranglethorn vale"},rel={"zone:stranglethorn","subzone:booty-bay","quest:570"},src={"Wowpedia: Aged Gorilla Sinew","Mok'thardin's Enchantment (2)"}}
E["item:akiris-reed"] = {t="item",n="Akiris Reed",z="stranglethorn",s="Along the beaches of the Cape of Stranglethorn, naga gather Akiris Reed, a valuable ocean plant. Privateer Bloads in Booty Bay offers good pay for bundles of it.",h="Along the beaches of the Cape of Stranglethorn, naga gather Akiris Reed, a valuable ocean plant.",sec={{t="Reed from the Shore",b="Privateer Bloads in Booty Bay pays for bundles of Akiris Reed gathered along the northern beach. The naga call the ocean reed akiris, and Bloads says his friend Groy makes a good living selling it. What Groy uses the reed for, Bloads does not know; for him, ten stalks are enough to begin a profitable trade.",sp=0}},faq={{q="What is Akiris Reed?",a="Akiris Reed is a valuable ocean reed gathered by naga along the Cape of Stranglethorn's beaches.",al={"akir is reed","akiris plant","ocean reed"}},{q="Who wants Akiris Reed?",a="Privateer Bloads in Booty Bay pays for bundles of Akiris Reed on behalf of his friend Groy.",al={"who buys akiris","akir reed buyer","bloads reed"}},{q="What does Groy use the reed for?",a="Privateer Bloads says he does not know what Groy uses Akiris Reed for; he only knows Groy sells it at a profit.",al={"what is akiris for","groy akiris use","reed uses"}},{q="Where can I find Akiris Reed?",a="Naga gather Akiris Reed along the beaches north of Booty Bay in the Cape of Stranglethorn.",al={"akiris location","where reed","naga beach"}}},kw={"akiris","akiris reed","booty bay","cape of stranglethorn","groy","naga","privateer bloads"},rel={"quest:617","subzone:booty-bay","subzone:cape-of-stranglethorn","zone:stranglethorn"},src={"Wowpedia: Akiris Reed","Akiris by the Bundle (Classic)"}}
E["item:bag-of-water-elemental-bracers"] = {t="item",n="Bag of Water Elemental Bracers",z="stranglethorn",s="A bag of water elemental bracers is brought to Archmage Ansirem Runeweaver for study. Their magical residue may help him examine the Stone of the Tides’ curse.",h="A bag of water elemental bracers is brought to Archmage Ansirem Runeweaver for study.",sec={{t="A Mage’s Study",b="In Dalaran Crater, Archmage Ansirem Runeweaver has been asked to examine the water elemental bracers. At least one bears magical residue, and he believes it may shed light on the Stone of the Tides’ curse. Ansirem knows the legends of the Gurubashi Empire and has written a tome on the subject. Now he turns his attention to the bracers.",sp=0}},faq={{q="What is in the bag?",a="The bag holds water elemental bracers for Archmage Ansirem Runeweaver to examine.",al={"bag contents","bracers bag","what bracers"}},{q="Who is supposed to study the bracers?",a="Archmage Ansirem Runeweaver is asked to study the water elemental bracers in Dalaran Crater.",al={"who studies them","ansirem bracers","mage in dalaran crater"}},{q="Why does Ansirem want the bracers?",a="At least one bracer bears magical residue that Ansirem can analyze for clues about the Stone of the Tides’ curse.",al={"why bracers","bracers curse","stone curse"}},{q="What does Ansirem know about the Stone?",a="Ansirem says he knows quite a bit about the Stone of the Tides and has written a tome about legends of the Gurubashi Empire.",al={"ansirem stone knowledge","stone of tides lore","gurubashi tome"}}},ang={["class:Mage"]="As a mage, you bring Ansirem a magical puzzle: residue on a water elemental bracer that may help him study the Stone of the Tides’ curse."},kw={"archmage ansirem runeweaver","bag of water elemental bracers","curse","dalaran crater","gurubashi empire","magical residue","stone of the tides","water elemental bracers"},rel={"quest:602","item:water-elemental-bracers","item:stone-of-the-tides","quest:578","npc:archmage-ansirem-runeweaver","zone:stranglethorn"},src={"Wowpedia: Bag of Water Elemental Bracers","Magical Analysis"}}
E["item:balia-mah-trophy"] = {t="item",n="Balia'mah Trophy",z="stranglethorn",s="The Balia'mah Trophy is a Skullsplitter trophy skull taken from the ruins in Stranglethorn Vale. Nezzliok asks for it alongside two other trophies at the Bubbling Cauldron in Grom'gol Base Camp.",h="The Balia'mah Trophy is a Skullsplitter trophy skull taken from the ruins in Stranglethorn Vale.",sec={{t="A Skullsplitter Trophy",b="Among the ruins of Balia'mah in Stranglethorn Vale, the Skullsplitters keep trophy skulls in a pile. One skull from that pile is the Balia'mah Trophy, wanted with trophies from Ziata'jai and Zul'Mamwe.",sp=0}},faq={{q="What is the Balia'mah Trophy?",a="The Balia'mah Trophy is a skull taken from the Skullsplitter trophy pile at Balia'mah Ruins in Stranglethorn Vale.",al={"balia'mah trophy","balia mah skull","trophy skull"}},{q="Who wants the Balia'mah Trophy?",a="The dead witch doctor Nezzliok asks for the Balia'mah Trophy along with trophies from Ziata'jai and Zul'Mamwe.",al={"who wants this skull","nezzliok trophy","trophy for nezzliok"},sp=1},{q="Where is the Balia'mah Trophy from?",a="The Balia'mah Trophy comes from the pile of trophy skulls at Balia'mah Ruins in Stranglethorn Vale.",al={"where find balia'mah","balia'mah ruins skull","skullsplitter trophy"}},{q="Where do the three trophies go?",a="Nezzliok asks that the Balia'mah, Ziata'jai and Zul'Mamwe trophies be placed at the Bubbling Cauldron in Grom'gol Base Camp.",al={"where put skulls","bubbling cauldron trophies","three skulls"}}},kw={"balia'mah","balia'mah ruins","balia'mah trophy","grom'gol","nezzliok","skullsplitter","trophy skull","ziata'jai","zul'mamwe"},rel={"subzone:balia-mah-ruins","quest:585","item:ziata-jai-trophy","item:zul-mamwe-trophy","subzone:grom-gol-base-camp","topic:darkspear-tribe","zone:stranglethorn"},src={"Wowpedia: Balia'mah Trophy","Speaking with Nezzliok (Classic)"}}
E["item:bloodsail-charts"] = {t="item",n="Bloodsail Charts",z="stranglethorn",s="Bloodsail Charts are taken from the Buccaneer camp on the Wild Shore. Fleet Master Seahorn wants them brought to Booty Bay with the Bloodsail Orders so he can learn what the pirates are planning.",h="Bloodsail Charts are taken from the Buccaneer camp on the Wild Shore.",sec={{t="Charts from the Shore",b="Fleet Master Seahorn sends you to the Bloodsail Buccaneers’ camp on the Wild Shore. He wants their charts and written orders carried back to Booty Bay. With both in hand, he says the fleet can learn the Bloodsails’ plan.",sp=0}},faq={{q="Where are the Bloodsail Charts?",a="The Bloodsail Charts are in the Bloodsail Buccaneer camp on the Wild Shore in the Cape of Stranglethorn.",al={"bloodsail charts location","where charts","charts wild shore"}},{q="Who wants the charts?",a="Fleet Master Seahorn in Booty Bay wants the Bloodsail Charts and Bloodsail Orders.",al={"who needs charts","seahorn charts","fleet master charts"}},{q="Why does Seahorn need them?",a="Seahorn wants the charts and written orders to learn what the Bloodsail Buccaneers are planning.",al={"why charts","what are charts for","bloodsail plan"}},{q="What should I bring back with the charts?",a="Bring the Bloodsail Orders with the Bloodsail Charts to Fleet Master Seahorn in Booty Bay.",al={"charts and what","bloodsail orders too","bring back orders"}}},kw={"bloodsail buccaneers","bloodsail charts","bloodsail orders","booty bay","cape of stranglethorn","fleet master seahorn","wild shore"},rel={"quest:595","item:bloodsail-orders-classic","npc:fleet-master-seahorn","subzone:wild-shore","subzone:booty-bay","subzone:cape-of-stranglethorn"},src={"Wowpedia: Bloodsail Charts","The Bloodsail Buccaneers (4)"}}
E["item:bloodsail-orders-classic"] = {t="item",n="Bloodsail Orders",z="stranglethorn",s="Bloodsail Orders are written instructions held by the Bloodsail Buccaneers on the Wild Shore. Fleet Master Seahorn in Booty Bay seeks them to learn what the buccaneers are planning.",h="Bloodsail Orders are written instructions held by the Bloodsail Buccaneers on the Wild Shore.",sec={{t="Orders from the Shore",b="On the Wild Shore, the Bloodsail Buccaneers keep written orders at their southern command post. Fleet Master Seahorn in Booty Bay wants those instructions brought back with the Bloodsail Charts. He means to learn what the buccaneers are planning near the cape.",sp=0}},faq={{q="What are the Bloodsail Orders?",a="They are written instructions kept by the Bloodsail Buccaneers at their Wild Shore encampment.",al={"bloodsail orders","orders item"}},{q="Where are the Bloodsail Orders?",a="The Bloodsail Orders are held at the Bloodsail Buccaneers' encampment on the Wild Shore in Stranglethorn Vale.",al={"where orders","wild shore orders"}},{q="Who wants the orders?",a="Fleet Master Seahorn in Booty Bay wants the Bloodsail Orders brought back to him.",al={"who wants orders","seahorn orders"}},{q="Why does Fleet Master Seahorn want them?",a="Fleet Master Seahorn wants to learn what the Bloodsail Buccaneers are planning by studying their written orders and charts.",al={"why orders","what's seahorn after"}},{q="What should I bring back with the orders?",a="Fleet Master Seahorn also wants the Bloodsail Charts from the Wild Shore encampment.",al={"orders and charts","what else bring"}}},kw={"bloodsail","bloodsail orders","booty bay","buccaneers","fleet master seahorn","stranglethorn vale","wild shore","written orders"},rel={"zone:stranglethorn","subzone:wild-shore","subzone:booty-bay","npc:fleet-master-seahorn","item:bloodsail-charts","quest:595"},src={"Wowpedia: Bloodsail Orders (Classic)","The Bloodsail Buccaneers (4)"}}
E["item:bloodscalp-tusk"] = {t="item",n="Bloodscalp Tusk",z="stranglethorn",s="A Bloodscalp Tusk is taken from a Bloodscalp troll in northern Stranglethorn Vale. Nimboya at Grom'gol Base Camp asks for tusks as proof that you can help search for Yenniku.",h="A Bloodscalp Tusk is taken from a Bloodscalp troll in northern Stranglethorn Vale.",sec={{t="A Hunter's Proof",b="At Grom'gol Base Camp, Nimboya asks you to bring him nine Bloodscalp Tusks. He needs to know you can hunt the tribe before he trusts you to help find Yenniku, his chief's youngest son. The tusks are proof of your strength.",sp=0}},faq={{q="What is a Bloodscalp Tusk?",a="A Bloodscalp Tusk comes from a troll of the Bloodscalp tribe in Stranglethorn Vale.",al={"bloodscalp tusk","what tusks are these"}},{q="Who wants Bloodscalp Tusks?",a="Nimboya at Grom'gol Base Camp asks you to bring him nine Bloodscalp Tusks.",al={"who wants tusks","Nimboya tusks"}},{q="Why does Nimboya need the tusks?",a="Nimboya wants the tusks as proof that you are strong enough to help him search for Yenniku.",al={"why tusks","tusk reason"}},{q="Who is Yenniku?",a="Yenniku is the youngest son of Nimboya's chief, and Nimboya believes the Bloodscalp tribe has him.",al={"Yenniku who","Nimboya's chief son"}},{q="Where can I find Bloodscalp trolls?",a="The Bloodscalp tribe lives in northern Stranglethorn Vale.",al={"Bloodscalp location","where Bloodscalps"}}},ang={["race:Troll"]="As a troll, you may recognize the weight of Yenniku's loss: he is a Darkspear child separated from his people.",["faction:Horde"]="As a member of the Horde, you can help Nimboya, a Darkspear sent from Orgrimmar to seek his chief's lost son."},kw={"bloodscalp","bloodscalp tusk","grom'gol","nimboya","stranglethorn","troll","yenniku"},rel={"quest:581","topic:darkspear-tribe","topic:troll","subzone:grom-gol-base-camp","zone:stranglethorn"},src={"Wowpedia: Bloodscalp Tusk","Hunt for Yenniku (Classic)"}}
E["item:bloody-bone-necklace"] = {t="item",n="Bloody Bone Necklace",z="stranglethorn",s="A Bloody Bone Necklace is a Bloodscalp troll trophy taken in Stranglethorn Vale. Kin'weelay at Grom'gol Base Camp uses the necklaces in a ritual against his tribe's enemy.",h="A Bloody Bone Necklace is a Bloodscalp troll trophy taken in Stranglethorn Vale.",sec={{t="A Troll Trophy",b="Kin'weelay asks you to bring twenty-five Bloody Bone Necklaces to Grom'gol Base Camp. The Bloodscalp tribe dwells to the north and is Kin'weelay's enemy. He believes taking their trophies will give his own tribe power over them.",sp=0},{t="Kin'weelay's Rite",b="At Grom'gol, Kin'weelay boils the necklaces and leeches them, rendering them to paste. He says the rite will weaken the spirits of their owners. For this service, he repays the debt that brought him to the camp.",sp=1}},faq={{q="What is a Bloody Bone Necklace?",a="A Bloody Bone Necklace is a trophy taken from a Bloodscalp troll in Stranglethorn Vale.",al={"bloody bone necklace","bone necklace","bloodscalp trophy"}},{q="Who wants the necklaces?",a="Kin'weelay at Grom'gol Base Camp asks for twenty-five Bloody Bone Necklaces.",al={"who wants these","kin weelay necklace","necklace npc"}},{q="Where do the necklaces come from?",a="Bloodscalp trolls in Stranglethorn Vale wear the bloody bone necklaces.",al={"where get necklaces","bloodscalp necklaces","necklace source"}},{q="Why does Kin'weelay want them?",a="Kin'weelay says taking trophies from the Bloodscalp tribe gives his own tribe power over its enemy.",al={"why kin wants bones","why collect necklace","tribe power"}},{q="What does Kin'weelay do with the necklaces?",a="Kin'weelay boils and leeches the necklaces, then renders them to paste in a rite meant to weaken their owners' spirits.",al={"what happens to necklaces","boil necklaces","necklace ritual"}},{q="Where is Kin'weelay?",a="Kin'weelay is at Grom'gol Base Camp in Stranglethorn Vale.",al={"kin weelay location","gromgol npc","kin at gromgol"}}},ang={["race:Troll"]="As a troll, you can see Kin'weelay turn a trophy of the Bloodscalp tribe into a ritual weapon against its owners.",["faction:Horde"]="As a member of the Horde, you can help Kin'weelay, a troll at the Horde camp of Grom'gol, oppose the Bloodscalp tribe."},kw={"bloodscalp","bloody bone necklace","bloody bone necklaces","grom'gol","kin'weelay","stranglethorn","troll trophy"},rel={"quest:596","npc:kin-weelay","subzone:grom-gol-base-camp","zone:stranglethorn","topic:troll"},src={"Wowpedia: Bloody Bone Necklace","Bloody Bone Necklaces"}}
E["item:broken-armor-of-ana-thek"] = {t="item",n="Broken Armor of Ana'thek",z="stranglethorn",s="The Broken Armor of Ana'thek is a shattered trophy tied to the Skullsplitters of Stranglethorn Vale. Gan'zulah demands it as proof of Ana'thek's defeat.",h="The Broken Armor of Ana'thek is a shattered trophy tied to the Skullsplitters of Stranglethorn Vale.",sec={{t="A Chieftain's Demand",b="At Grom'gol Base Camp, Gan'zulah's head commands you to face the Skullsplitters in the eastern mountains. He demands the broken armor of their chief, Ana'thek the Cruel, if you survive the fight.",sp=0}},faq={{q="Who was Ana'thek?",a="Ana'thek the Cruel was the chief of the Skullsplitters in Stranglethorn Vale.",al={"ana'thek who","who is anathekh","ana'thek backstory"}},{q="Why does Gan'zulah want the armor?",a="Gan'zulah demands Ana'thek's shattered armor as proof that you defeated the Skullsplitter chief.",al={"why armor","gan'zula armor","what does gan'zulah want"}},{q="Where did the armor come from?",a="The Broken Armor of Ana'thek comes from Ana'thek the Cruel in Stranglethorn Vale.",al={"armor source","where armor from","ana'thek armor"}},{q="Where do I bring the armor?",a="Bring the Broken Armor of Ana'thek to the Bubbling Cauldron at Grom'gol Base Camp.",al={"armor turn in","where take armor","bubbling cauldron"}}},kw={"ana'thek","ana'thek the cruel","broken armor","bubbling cauldron","gan'zulah","grom'gol base camp","skullsplitters","stranglethorn vale"},rel={"quest:586","subzone:grom-gol-base-camp","subzone:ruins-of-zul-mamwe","zone:stranglethorn"},src={"Wowpedia: Broken Armor of Ana'thek","Speaking with Gan'zulah"}}
E["item:bundle-of-akiris-reeds"] = {t="item",n="Bundle of Akiris Reeds",z="stranglethorn",s="A Bundle of Akiris Reeds is a shipment carried to Privateer Groy in Theramore. He checks it for a client who wants more.",h="A Bundle of Akiris Reeds is a shipment carried to Privateer Groy in Theramore.",sec={{t="A Fresh Shipment",b="Privateer Groy receives the reeds in Theramore after Bloads sends another shipment his way. Groy looks the bundle over, pleased that it will satisfy his client. Then he pays the courier and sends them off his docks.",sp=0}},faq={{q="Who is the bundle for?",a="Privateer Groy receives the Bundle of Akiris Reeds in Theramore for a client who wants more.",al={"who wants the reeds","akiris bundle client","reeds for who"}},{q="Where do I take the bundle?",a="Bring the Bundle of Akiris Reeds to Privateer Groy in Theramore.",al={"where to bring reeds","groy location","take bundle where"}},{q="Who sends the bundle?",a="Bloads asks you to carry the shipment to Privateer Groy in Theramore.",al={"who gave me reeds","bloads shipment","where from"}},{q="What does Groy do with it?",a="Groy inspects the reeds and says another bundle will please his client.",al={"groy checks bundle","what's the shipment for","client wants more"}}},kw={"akiris","akiris reeds","bloads","bundle of akiris reeds","privateer groy","shipment","theramore"},rel={"quest:617","item:akiris-reed","zone:dustwallow","zone:stranglethorn"},src={"Wowpedia: Bundle of Akiris Reeds","Akiris by the Bundle (2)"}}
E["item:catelyn-s-blade"] = {t="item",n="Catelyn's Blade",z="stranglethorn",s="Near Booty Bay, Catelyn's Blade is a knife with a history among Stranglethorn's trolls. Catelyn needs it back from the Bloodsail Buccaneers.",h="Near Booty Bay, Catelyn's Blade is a knife with a history among Stranglethorn's trolls.",sec={{t="A Daughter's Knife",b="Catelyn's Blade is missing from its owner, Catelyn the Blade, in Stranglethorn Vale. She says \"Pretty Boy\" Duncan of the Bloodsail Buccaneers took it after knocking her unconscious. Her father, Ansirem Runeweaver, sent word after her, and she asks you to recover the knife from Duncan.",sp=0},{t="At the Sunken Altar",b="The knife is a troll relic found in Stranglethorn Vale by Ansirem Runeweaver, who gave it to his daughter. Once Catelyn has it back, she lends it to you for the altar in the Vile Reef. There, the blade can destroy the Altar of the Tides, drawing out Gazban and the Stone of the Tides. Baron Revilgaz wants the stone for his collection, and Catelyn expects her knife returned.",sp=0}},faq={{q="Who owns Catelyn's Blade?",a="Catelyn the Blade owns the knife. Her father, Ansirem Runeweaver, gave it to her.",al={"catelyn blade owner","whose knife is it"}},{q="How did Duncan get the knife?",a="Catelyn says \"Pretty Boy\" Duncan knocked her unconscious and took the knife.",al={"duncan stole blade","how'd catelyn lose it"}},{q="Who is Catelyn?",a="Catelyn the Blade is Ansirem Runeweaver's daughter. She left her father's scholarly life to become a pirate.",al={"catelyn backstory","who's the blade girl"}},{q="What is the blade used for?",a="Catelyn lends the knife so you can destroy the Altar of the Tides in the Vile Reef.",al={"knife altar","blade purpose"},sp=1},{q="Where is the altar?",a="The Altar of the Tides lies in the ruins of a sunken troll city at the Vile Reef, off Stranglethorn Vale's coast.",al={"vile reef altar","sunken altar location"}},{q="Why does Baron Revilgaz want the Stone of the Tides?",a="Baron Revilgaz wants the Stone of the Tides for his collection of ancient troll artifacts.",al={"revilgaz stone","why collect stone"},sp=1}},ang={["class:Mage"]="Ansirem Runeweaver is a mage, and Catelyn fled the life of books and stiff-backed mages he expected her to lead."},kw={"altar of the tides","ansirem runeweaver","bloodsail buccaneers","catelyn the blade","catelyn's blade","pretty boy duncan","stone of the tides","troll relic"},rel={"quest:610","quest:611","item:stone-of-the-tides","subzone:vile-reef","npc:baron-revilgaz","zone:stranglethorn"},src={"Wowpedia: Catelyn's Blade","\"Pretty Boy\" Duncan (quest)","The Curse of the Tides"}}
E["item:chucky-s-huge-ring"] = {t="item",n="Chucky's Huge Ring",z="stranglethorn",s="At the Ruins of Aboraz, Chucky “Ten Thumbs” has a ring that Sea Wolf MacKinley wants. It is one of three valuables sought for debts left unpaid.",h="At the Ruins of Aboraz, Chucky “Ten Thumbs” has a ring that Sea Wolf MacKinley wants.",sec={{t="A Debt in the Jungle",b="MacKinley’s list leads you to Chucky “Ten Thumbs” among the jungle ruins of Stranglethorn Vale. The pirate says Chucky and two other debtors vanished after their debts went unpaid. He wants their valuables gathered, and Chucky’s huge ring is one of them.",sp=0}},faq={{q="Who is Chucky?",a="Chucky “Ten Thumbs” is a debtor sought by Sea Wolf MacKinley. He wanders the Ruins of Aboraz in Stranglethorn Vale.",al={"chucky ten thumbs","who's chucky","ten thumbs"}},{q="Where can I find Chucky's ring?",a="Chucky’s Huge Ring is at the Ruins of Aboraz in Stranglethorn Vale, where Chucky “Ten Thumbs” wanders.",al={"chucky ring location","where ring","huge ring"}},{q="Why does MacKinley want the ring?",a="MacKinley wants valuables from three debtors whose payments are months overdue. Chucky’s ring is one of the items he asks you to bring to Booty Bay.",al={"why mac kinley wants ring","ring debt","voodoo dues"}},{q="What is Chucky's Huge Ring for?",a="The ring is one of three valuables Sea Wolf MacKinley requests for the debts owed by Chucky and two other pirates.",al={"ring use","what do with chucky ring","huge ring purpose"}}},kw={"chucky","chucky's huge ring","ruins of aboraz","sea wolf mackinley","stranglethorn vale","ten thumbs","voodoo dues"},rel={"quest:609","zone:stranglethorn","subzone:ruins-of-aboraz"},src={"Wowpedia: Chucky's Huge Ring","Voodoo Dues"}}
E["item:fang-of-bhag-thera"] = {t="item",n="Fang of Bhag'thera",z="stranglethorn",s="Bhag'thera's fang is proof of a hunter's skill in Stranglethorn Vale. Sir S. J. Erlgadin asks for it as the final measure of Panther Mastery.",h="Bhag'thera's fang is proof of a hunter's skill in Stranglethorn Vale.",sec={{t="A Hunter's Proof",b="Erlgadin sends you after Bhag'thera, an elusive panther prowling the jungle near Nesingwary's Expedition. His party has failed to catch the great beast, and your hunt will decide whether you have earned Erlgadin's respect. Bring him the fang, and he will hail you as a mighty hunter.",sp=0}},faq={{q="Who wants Bhag'thera's fang?",a="Sir S. J. Erlgadin of Nesingwary's Expedition asks you to bring him Bhag'thera's fang.",al={"who wants it","fang for who"}},{q="What is Bhag'thera?",a="Bhag'thera is an elusive panther prowling the jungle in Stranglethorn Vale.",al={"who's Bhag'thera","bhagthera"}},{q="Why does Erlgadin want the fang?",a="The fang proves that you have hunted Bhag'thera and earned Erlgadin's respect as a panther hunter.",al={"why fang","what's it for"}},{q="Where can I find Bhag'thera?",a="Bhag'thera prowls the jungle in Stranglethorn Vale, near Nesingwary's Expedition.",al={"where is Bhag'thera","find bhagthera"}}},ang={["class:Hunter"]="As a hunter, Bhag'thera's fang marks the final test in Sir S. J. Erlgadin's Panther Mastery trial."},kw={"bhag'thera","fang of bhag'thera","nesingwary's expedition","panther","panther mastery","sir s. j. erlgadin","stranglethorn vale"},rel={"quest:190","zone:stranglethorn","subzone:nesingwary-s-expedition","topic:hunter"},src={"Wowpedia: Fang of Bhag'thera","Panther Mastery (4)"}}
E["item:filled-soul-gem"] = {t="item",n="Filled Soul Gem",z="stranglethorn",s="Nimboya asks you to bring the Soul Gem to Grom'gol, where his people await Yenniku's return.",h="Nimboya asks you to bring the Soul Gem to Grom'gol, where his people await Yenniku's return.",sec={{t="A Soul Restored",b="At the Ruins of Aboraz on the Cape of Stranglethorn, the Soul Gem is placed upon Yenniku's head to capture his soul. Bring the filled gem to Nimboya in Grom'gol, where his people await his return.",sp=0}},faq={{q="What is the Filled Soul Gem?",a="The Filled Soul Gem contains Yenniku's soul, captured with the Soul Gem at the Ruins of Aboraz.",al={"filled gem","soul gem with yenniku","what's in the gem"},sp=1},{q="Who is Yenniku?",a="Yenniku is a member of Nimboya's tribe who is held under Zanzil the Outcast's will.",al={"yenniku story","who's yenniku","yenniku"}},{q="Where do I take the gem?",a="Bring the Filled Soul Gem to Nimboya at Grom'gol.",al={"where gem go","bring gem where","nimboya gem"}},{q="How was the Soul Gem made?",a="Kin'weelay reshaped the Mind's Eye into a Soul Gem, which captures Yenniku's soul.",al={"mind's eye gem","how fill soul gem","soul gem recipe"},sp=1}},kw={"filled soul gem","grom'gol","kin'weelay","mind's eye","nimboya","soul gem","yenniku","zanzil"},rel={"item:mind-s-eye","quest:592","quest:593","npc:kin-weelay","subzone:ruins-of-aboraz","zone:stranglethorn"},src={"Wowpedia: Filled Soul Gem","Saving Yenniku (Classic)"}}
E["item:gan-zulah-s-head"] = {t="item",n="Gan'zulah's Head",z="stranglethorn",s="Gan'zulah's Head is taken from the Bloodscalp chief at Zul'Kunda. At Grom'gol, it is brought to a bubbling cauldron as part of the search for Yenniku.",h="Gan'zulah's Head is taken from the Bloodscalp chief at Zul'Kunda.",sec={{t="A Chief's Head",b="At Zul'Kunda in northwestern Stranglethorn, Gan'zulah's Head is sought alongside the head of Nezzliok the Dire. Nimboya asks you to bring both to the bubbling cauldron at Grom'gol Base Camp. The Darkspear hope the dead leaders can reveal the truth about Yenniku.",sp=0}},faq={{q="Who was Gan'zulah?",a="Gan'zulah was the chief of the Bloodscalp trolls at Zul'Kunda, an enemy of the Darkspear tribe.",al={"gan zulah","bloodscalp chief","gan'zulah backstory"}},{q="Where does Gan'zulah's Head come from?",a="Gan'zulah's Head is taken from Gan'zulah at the ruins of Zul'Kunda in Stranglethorn Vale.",al={"where head from","gan zulah head location","find gan'zulah"}},{q="Why does Nimboya want the head?",a="Nimboya wants Gan'zulah's Head and Nezzliok's Head placed in the bubbling cauldron at Grom'gol Base Camp, hoping to learn the truth about Yenniku.",al={"why head","what nimboya wants","head for nimboya"}},{q="What is the cauldron for?",a="The Darkspear place the heads of Gan'zulah and Nezzliok in the cauldron, hoping to make the dead leaders speak about Yenniku.",al={"bubbling cauldron","cauldron at gromgol","what cauldron do"},sp=1},{q="Who is Yenniku?",a="Yenniku is a Darkspear troll whose fate remains unknown to Nimboya and his people.",al={"yenniku","where is yenniku","hunt for yenniku"}}},ang={["race:Troll"]="As a troll, you stand amid the conflict between the Darkspear and the Bloodscalp clan, whose chief's head Nimboya seeks.",["faction:Horde"]="As a member of the Horde, you help the Darkspear at Grom'gol seek the truth about Yenniku from their Bloodscalp enemies."},kw={"bloodscalp","cauldron","darkspear","gan'zulah","gan'zulah's head","grom'gol","nimboya","yenniku","zul'kunda"},rel={"quest:584","item:nezzliok-s-head","quest:581","subzone:grom-gol-base-camp","zone:stranglethorn","topic:darkspear-tribe"},src={"Wowpedia: Gan'zulah's Head","Bloodscalp Clan Heads"}}
E["item:green-hills-of-stranglethorn-chapter-i"] = {t="item",n="Green Hills of Stranglethorn - Chapter I",z="stranglethorn",s="Scattered pages from The Green Hills of Stranglethorn have been gathered into Chapter I. Barnil is assembling the chapters for Master Nesingwary’s manuscript.",h="Scattered pages from The Green Hills of Stranglethorn have been gathered into Chapter I.",sec={{t="Scattered Pages",b="A gust swept through Master Nesingwary’s camp and scattered the pages of his manuscript across Stranglethorn. Barnil gathered many, but pages for all four chapters were still missing. This chapter belongs to the book Barnil is piecing together, and he is ready to organize the pages once they are found.",sp=0}},faq={{q="What is Chapter I?",a="Chapter I is one of the four parts of Master Nesingwary’s scattered manuscript, The Green Hills of Stranglethorn.",al={"green hills chapter one","chapter i book","what is this chapter"}},{q="Who is Barnil?",a="Barnil is helping assemble Master Nesingwary’s manuscript and asks for the chapters once they are complete.",al={"barnil who","who wants the pages","barnil manuscript"}},{q="Why are the pages scattered?",a="A large gust of wind blew through Master Nesingwary’s camp and scattered pages of the manuscript across the jungle.",al={"pages blew away","why pages missing","manuscript pages"}},{q="Who wrote The Green Hills of Stranglethorn?",a="Master Nesingwary is the author of The Green Hills of Stranglethorn, a novel Barnil is helping assemble.",al={"nesingwary book","who wrote green hills","master nesingwary manuscript"}}},kw={"barnil","chapter i","chapter one","green hills of stranglethorn","manuscript","master nesingwary","scattered pages","stranglethorn"},rel={"quest:338","quest:339","item:green-hills-of-stranglethorn-chapter-ii","item:green-hills-of-stranglethorn-chapter-iii","item:green-hills-of-stranglethorn-chapter-iv","zone:stranglethorn"},src={"Wowpedia: Green Hills of Stranglethorn - Chapter I","The Green Hills of Stranglethorn (Classic)"}}
E["item:green-hills-of-stranglethorn-chapter-ii"] = {t="item",n="Green Hills of Stranglethorn - Chapter II",z="stranglethorn",s="Chapter II is one of four parts of Master Nesingwary’s scattered manuscript, The Green Hills of Stranglethorn. Its pages must be gathered so Barnil can assemble the chapters and return the book to Nesingwary.",h="Chapter II is one of four parts of Master Nesingwary’s scattered manuscript, The Green Hills of Stranglethorn.",sec={{t="Scattered Pages",b="Barnil had gathered most of the manuscript when a gust swept through Master Nesingwary’s camp. The pages of Chapter II were scattered through Stranglethorn with the rest. You can help Barnil put the four chapters in order, then carry them back to him.",sp=0}},faq={{q="What is Chapter II?",a="Chapter II is one part of Master Nesingwary’s manuscript, The Green Hills of Stranglethorn.",al={"chapter 2","green hills chapter ii"}},{q="Who is gathering the chapters?",a="Barnil is collecting and organizing the scattered chapters for Master Nesingwary.",al={"who wants the pages","barnil pages"}},{q="Why are the pages scattered?",a="A large gust of wind swept through Master Nesingwary’s camp and scattered the manuscript pages through the jungle.",al={"what happened to the pages","wind blew pages"}},{q="What should I do with the chapters?",a="Gather all four chapters and return them to Barnil so he can organize them for Master Nesingwary.",al={"where return chapters","what does barnil need"}},{q="Who wrote The Green Hills of Stranglethorn?",a="Master Nesingwary is the author of The Green Hills of Stranglethorn.",al={"nesingwary book","master nesingwary novel"}}},kw={"barnil","chapter 2","chapter ii","green hills of stranglethorn","manuscript","nesingwary","scattered pages","stranglethorn"},rel={"quest:338","quest:340","item:green-hills-of-stranglethorn-chapter-i","item:green-hills-of-stranglethorn-chapter-iii","item:green-hills-of-stranglethorn-chapter-iv","zone:stranglethorn"},src={"Wowpedia: Green Hills of Stranglethorn - Chapter II","The Green Hills of Stranglethorn (Classic)"}}
E["item:green-hills-of-stranglethorn-chapter-iii"] = {t="item",n="Green Hills of Stranglethorn - Chapter III",z="stranglethorn",s="Chapter III is one of four scattered parts of Master Nesingwary’s manuscript, The Green Hills of Stranglethorn. Barnil is gathering the pages at the camp in Stranglethorn Vale.",h="Chapter III is one of four scattered parts of Master Nesingwary’s manuscript, The Green Hills of...",sec={{t="Scattered Pages",b="A gust swept through Master Nesingwary’s camp in Stranglethorn Vale and scattered the manuscript pages through the jungle. Barnil gathered most of them, but the four chapters remain incomplete. He is collecting the pages so the manuscript can be put back in order.",sp=0}},faq={{q="What is Chapter III?",a="Chapter III is one of the four parts of Master Nesingwary’s scattered manuscript, The Green Hills of Stranglethorn.",al={"chapter three","green hills chapter 3"}},{q="Who is collecting the pages?",a="Barnil is gathering the scattered pages and organizing the chapters for Master Nesingwary.",al={"who wants the pages","barnil pages"}},{q="Why are the pages scattered?",a="A large gust of wind blew through Master Nesingwary’s camp and scattered the manuscript pages across the jungle.",al={"what happened to the pages","wind blew pages"}},{q="What is the manuscript called?",a="The manuscript is called The Green Hills of Stranglethorn.",al={"nesingwary book","green hills book"}}},kw={"barnil","chapter iii","chapter three","green hills of stranglethorn","manuscript","nesingwary","scattered pages","stranglethorn vale"},rel={"quest:338","quest:341","item:green-hills-of-stranglethorn-chapter-i","item:green-hills-of-stranglethorn-chapter-ii","item:green-hills-of-stranglethorn-chapter-iv","zone:stranglethorn"},src={"Wowpedia: Green Hills of Stranglethorn - Chapter III","The Green Hills of Stranglethorn (Classic)"}}
E["item:green-hills-of-stranglethorn-chapter-iv"] = {t="item",n="Green Hills of Stranglethorn - Chapter IV",z="stranglethorn",s="In Stranglethorn Vale, Barnil needs the scattered chapters of Master Nesingwary’s manuscript gathered and put back in order. Chapter IV is one of the four pieces needed to complete the book.",h="In Stranglethorn Vale, Barnil needs the scattered chapters of Master Nesingwary’s manuscript gathered and put...",sec={{t="Scattered Pages",b="A gust tore through Master Nesingwary’s camp and scattered pages from his novel across the jungle. Barnil gathered most of them, but the missing pages still need to be collected and arranged into four chapters. Chapter IV belongs with the other three before the manuscript can be returned to Barnil.",sp=0}},faq={{q="What is Chapter IV?",a="Chapter IV is one of the four chapters of Master Nesingwary’s novel, The Green Hills of Stranglethorn.",al={"chapter four","green hills chapter iv","chapter 4 book"}},{q="Who needs this chapter?",a="Barnil is gathering the chapters of Master Nesingwary’s manuscript and asks for them once all four are complete.",al={"who wants chapter iv","give chapter four to who","barnil pages"}},{q="Why are the pages scattered?",a="A large gust of wind blew through Master Nesingwary’s camp and scattered pages from his manuscript around the jungle.",al={"why pages everywhere","what happened to the book","wind blew pages"}},{q="What is The Green Hills of Stranglethorn about?",a="It is a novel by Master Nesingwary. The gathered chapters are meant to complete its manuscript.",al={"nesingwary novel","green hills book","what's the manuscript"}}},kw={"barnil","chapter four","chapter iv","green hills of stranglethorn","manuscript","master nesingwary","scattered pages","stranglethorn vale"},rel={"quest:342","quest:338","item:green-hills-of-stranglethorn-chapter-i","item:green-hills-of-stranglethorn-chapter-ii","item:green-hills-of-stranglethorn-chapter-iii","zone:stranglethorn"},src={"Wowpedia: Green Hills of Stranglethorn - Chapter IV","The Green Hills of Stranglethorn (Classic)"}}
E["item:head-of-bangalash"] = {t="item",n="Head of Bangalash",z="stranglethorn",s="Hemet Nesingwary seeks the Head of Bangalash in Stranglethorn Vale. The great white tiger is the latest quarry in his hunt.",h="Hemet Nesingwary seeks the Head of Bangalash in Stranglethorn Vale.",sec={{t="The Great White Tiger",b="Hemet Nesingwary has hunted King Bangalash for a long while. After the hunts for Sin'Dall, Bhag'thera, and Tethis, the great white tiger is the prize he still seeks. The tiger's head proves the hunt is done.",sp=0}},faq={{q="Who wants the Head of Bangalash?",a="Hemet Nesingwary wants the Head of Bangalash as the prize of his hunt for King Bangalash.",al={"who wants the tiger head","Hemet's trophy","who is it for"}},{q="What is Bangalash?",a="King Bangalash is a great white tiger in Stranglethorn Vale.",al={"who is Bangalash","white tiger","king tiger"}},{q="Why does Hemet want the head?",a="Hemet has pursued King Bangalash for a long while and calls the tiger the true prize of the hunt.",al={"why Hemet wants it","Bangalash hunt","why kill Bangalash"}},{q="What hunts came before Bangalash?",a="Hemet names Sin'Dall, Bhag'thera, and Tethis among the earlier hunts before King Bangalash.",al={"previous big game","Sin'Dall Bhag'thera Tethis","what did Hemet hunt"}}},ang={["class:Hunter"]="As a hunter, Hemet's pursuit of King Bangalash is a measure of skill in hunting and tracking."},kw={"big game hunter","head of bangalash","hem et nesingwary","hunting trophy","king bangalash","stranglethorn","white tiger"},rel={"quest:208","quest:5762","zone:stranglethorn"},src={"Wowpedia: Head of Bangalash","Big Game Hunter (Classic)"}}
E["item:heart-of-mokk"] = {t="item",n="Heart of Mokk",z="stranglethorn",s="The Heart of Mokk is taken from Mokk the Savage in Cape of Stranglethorn. Fin Fizracket seeks it as a cure for Stranglethorn Fever.",h="The Heart of Mokk is taken from Mokk the Savage in Cape of Stranglethorn.",sec={{t="A Fever's Cure",b="Fin Fizracket is stricken with a deadly fever in Booty Bay and believes only Mokk the Savage's heart can cure him. Witch Doctor Unbagwa, hidden in a cave on the southern cape, can summon the elusive white beast. The heart is what Fin needs to regain his strength.",sp=0}},faq={{q="What is the Heart of Mokk?",a="The Heart of Mokk is the heart of Mokk the Savage, an elusive white beast in Cape of Stranglethorn.",al={"mokk heart","heart item","what's mokk's heart"}},{q="Who needs the Heart of Mokk?",a="Fin Fizracket in Booty Bay seeks the Heart of Mokk as a cure for Stranglethorn Fever.",al={"who wants it","fin fizracket heart","who needs mokk"}},{q="Where does the Heart of Mokk come from?",a="The Heart of Mokk comes from Mokk the Savage in Cape of Stranglethorn.",al={"where heart","mokk location","find heart of mokk"}},{q="How can Mokk be summoned?",a="Witch Doctor Unbagwa, in a hidden cave on the southern cape, can summon Mokk the Savage.",al={"summon mokk","unbagwa where","witch doctor mokk"}}},kw={"cape of stranglethorn","fin fizracket","heart of mokk","mokk the savage","stranglethorn fever","witch doctor unbagwa"},rel={"quest:349","zone:stranglethorn","subzone:booty-bay","subzone:cape-of-stranglethorn"},src={"Wowpedia: Heart of Mokk","Wowpedia: Stranglethorn Fever"}}
E["item:jon-jon-s-golden-spyglass"] = {t="item",n="Jon-Jon's Golden Spyglass",z="stranglethorn",s="Jon-Jon's Golden Spyglass is among the valuables Sea Wolf MacKinley seeks in Booty Bay. He wants it returned with two other debts from the jungle ruins.",h="Jon-Jon's Golden Spyglass is among the valuables Sea Wolf MacKinley seeks in Booty Bay.",sec={{t="A Debt in Gold",b="Sea Wolf MacKinley in Booty Bay wants Jon-Jon's Golden Spyglass returned with two other valuables. Jon-Jon the Crow is one of three debtors MacKinley says vanished into the jungle ruins. Their debts have gone unpaid for months, and MacKinley wants what he is owed.",sp=0}},faq={{q="Who wants Jon-Jon's spyglass?",a="Sea Wolf MacKinley of Booty Bay wants it back, along with two other valuables owed to him.",al={"who wants it","MacKinley spyglass","spyglass debt"}},{q="Who is Jon-Jon the Crow?",a="Jon-Jon the Crow is one of three debtors MacKinley says wandered into the jungle ruins after their debts went unpaid.",al={"jon jon","jon-jon backstory","the crow"}},{q="Why does MacKinley want the spyglass?",a="MacKinley says Jon-Jon owes him, and he wants the valuables he is owed returned.",al={"why spyglass","MacKinley debt","why collect it"}},{q="Where can Jon-Jon's spyglass be found?",a="MacKinley points you toward the Ruins of Aboraz and the Ruins of Jubuwal, northeast of Booty Bay, where the debtors wander.",al={"spyglass location","where is jon jon","find golden spyglass"}},{q="What other valuables does MacKinley want?",a="MacKinley also seeks Maury's Clubbed Foot and Chucky's Huge Ring.",al={"other debts","Maury and Chucky","three valuables"}},{q="What does MacKinley say about the debtors?",a="MacKinley says he heard the debtors were cursed and bewitched and now wander the jungle ruins.",al={"why are they in ruins","debtors cursed","what happened to them"}}},kw={"booty bay","golden spyglass","jon-jon","jon-jon the crow","ruins of aboraz","ruins of jubuwal","sea wolf mackinley","spyglass","voodoo dues"},rel={"quest:609","zone:stranglethorn","subzone:booty-bay","subzone:ruins-of-aboraz","subzone:ruins-of-jubuwal","item:chucky-s-huge-ring","item:maury-s-clubbed-foot"},src={"Wowpedia: Jon-Jon's Golden Spyglass","Voodoo Dues"}}
E["item:jungle-remedy"] = {t="item",n="Jungle Remedy",z="stranglethorn",s="At the Rebel Camp, Jungle Remedy can help keep the wounded fighting fit against Kurzen’s forces. Sergeant Yohwa needs remedies from the Kurzen Compound to treat the camp’s fighters.",h="At the Rebel Camp, Jungle Remedy can help keep the wounded fighting fit against Kurzen’s forces.",sec={{t="A Camp’s Need",b="Kurzen’s Medicine Men use Jungle Remedies to heal their fighters in the compound. Sergeant Yohwa needs them at the Rebel Camp, where they can help keep his own people alive and ready to fight.",sp=0}},faq={{q="What is Jungle Remedy for?",a="Sergeant Yohwa needs Jungle Remedies to treat the Rebel Camp’s fighters and keep them in fighting shape against Kurzen.",al={"jungle remedy use","what remedy do"}},{q="Who carries Jungle Remedies?",a="Kurzen Medicine Men, Witch Doctors, and Headshrinkers carry Jungle Remedies. Jungle Fighters have them occasionally.",al={"where get remedies","kurzen medicine"}},{q="Why does Sergeant Yohwa need them?",a="The Kurzen forces use the remedies to heal their own fighters, and Sergeant Yohwa needs them to care for the wounded at the Rebel Camp.",al={"why yohwa wants them","rebel camp medicine"}},{q="Where can I find Jungle Remedies?",a="Search the Kurzen Compound in Stranglethorn Vale; Kurzen’s healers and other fighters carry the remedies.",al={"remedy location","where remedies"}}},kw={"headshrinkers","jungle remedy","kurzen","medicine men","rebel camp","sergeant yohwa","stranglethorn vale","witch doctors"},rel={"quest:204","item:venom-fern-extract","subzone:rebel-camp","zone:stranglethorn"},src={"Wowpedia: Jungle Remedy","Bad Medicine (Classic)"}}
E["item:jungle-stalker-feather"] = {t="item",n="Jungle Stalker Feather",z="stranglethorn",s="Jungle Stalker Feathers come from raptors in Stranglethorn Vale. Far Seer Mok'thardin needs them for an enchantment meant to aid the Horde.",h="Jungle Stalker Feathers come from raptors in Stranglethorn Vale.",sec={{t="Raptor Trinkets",b="Far Seer Mok'thardin at Grom'gol Base Camp needs ten Jungle Stalker Feathers for his enchantment. The feathers are worn on the raptors' armbands, and their tribe lives south of the camp, near the great arena.",sp=0}},faq={{q="Where do Jungle Stalker Feathers come from?",a="Jungle Stalkers in Stranglethorn Vale wear these feathers on their armbands.",al={"jungle stalker feather source","where feather","raptor feathers"}},{q="Who wants the feathers?",a="Far Seer Mok'thardin asks for ten of them at Grom'gol Base Camp, for an enchantment of his.",al={"who needs feather","mokthardin feathers","far seer wants"}},{q="Why does Mok'thardin need them?",a="Mok'thardin combines the feathers with a shamanistic ritual to make a useful enchanted tool for aiding the Horde and the Warchief.",al={"why feathers","what are they for","enchantment feathers"}}},ang={["faction:Horde"]="Mok'thardin's enchantment is meant to provide a useful tool for aiding the Horde and its Warchief.",["class:Shaman"]="Mok'thardin uses a shamanistic ritual to prepare the feathers for his enchantment."},kw={"enchantment","feather","grom'gol","jungle stalker","jungle stalker feather","mok'thardin","raptor","stranglethorn vale"},rel={"quest:570","subzone:grom-gol-base-camp","topic:horde","zone:stranglethorn"},src={"Wowpedia: Jungle Stalker Feather","Mok'thardin's Enchantment (3)"}}
E["item:kurzen-s-head"] = {t="item",n="Kurzen's Head",z="stranglethorn",s="Kurzen’s Head is proof sought by the rebels at their camp in Stranglethorn Vale. Lieutenant Doren needs it to learn whether Colonel Kurzen’s command has been broken.",h="Kurzen’s Head is proof sought by the rebels at their camp in Stranglethorn Vale.",sec={{t="Proof for Doren",b="Lieutenant Doren waits at Rebel Camp for word from the Stockpile, where Colonel Kurzen commands his men. The rebels face Kurzen’s Elite and Subchiefs as well as the Colonel himself. Doren asks for Kurzen’s Head as proof that the enemy leaders have been defeated. His band’s safety rests on the answer.",sp=0}},faq={{q="Who wants Kurzen’s Head?",a="Lieutenant Doren at Rebel Camp asks for Kurzen’s Head as proof that Colonel Kurzen and his leaders are defeated.",al={"who wants the head","doren head","where bring kurzen head"}},{q="Where is Colonel Kurzen?",a="Colonel Kurzen commands his men from deep within the Stockpile in Stranglethorn Vale.",al={"kurzen location","where kurzen","stockpile guy"}},{q="Why do the rebels need Kurzen’s Head?",a="The rebels need Kurzen’s Head as proof that Colonel Kurzen and his leaders have been defeated.",al={"why head","kurzen head purpose","proof for doren"}},{q="What threat does Kurzen pose?",a="Lieutenant Doren calls Kurzen a cruel and formidable commander whose men threaten the rebel band.",al={"kurzen threat","why fight kurzen","kurzen backstory"}},{q="What happens when Kurzen is defeated?",a="Lieutenant Doren says Kurzen’s defeat saves the rebel band and lets them breathe easier.",al={"kurzen defeated","what happens to rebels","kurzen ending"},sp=1}},kw={"colonel kurzen","kurzen","kurzen elite","kurzen subchief","kurzen's head","lieutenant doren","rebel camp","stockpile","stranglethorn vale"},rel={"npc:colonel-kurzen","npc:doren","subzone:rebel-camp","zone:stranglethorn"},src={"Wowpedia: Kurzen's Head","Colonel Kurzen (quest)"}}
E["item:maury-s-clubbed-foot"] = {t="item",n="Maury's Clubbed Foot",z="stranglethorn",s="Maury “Club Foot” Wilkins carries one of the debts Sea Wolf MacKinley means to collect in Booty Bay. His clubbed foot holds something MacKinley believes is valuable.",h="Maury “Club Foot” Wilkins carries one of the debts Sea Wolf MacKinley means to collect in Booty Bay.",sec={{t="A Debt in the Jungle",b="Among the debtors MacKinley names, Maury “Club Foot” Wilkins wanders the jungle ruins with Jon-Jon the Crow and Chucky “Ten Thumbs.” Their debts have gone unpaid for months, and MacKinley sends you to find them at the Ruins of Aboraz and the Ruins of Jubuwal. Maury’s clubbed foot is among the valuables he wants returned to Booty Bay.",sp=0},{t="MacKinley’s Price",b="When you bring the three valuables back, MacKinley says he can get a good price for them. He speaks of what is inside Maury’s foot, then warns that the three should have been careful who they gambled with.",sp=1}},faq={{q="Who is Maury “Club Foot” Wilkins?",a="Maury “Club Foot” Wilkins is a debtor of Sea Wolf MacKinley who wanders the jungle ruins.",al={"who is maury","maury club foot","maury wilkins"}},{q="Why does MacKinley want Maury’s foot?",a="MacKinley wants Maury’s Clubbed Foot among the valuables he collects from the debtors.",al={"why foot","maury's foot","what macKinley wants"}},{q="What is inside Maury’s foot?",a="MacKinley says there is something inside Maury’s foot that he can sell for a good price.",al={"inside foot","maury foot secret","what's in the foot"},sp=1},{q="Where can Maury be found?",a="Maury wanders the jungle ruins near the Ruins of Aboraz and the Ruins of Jubuwal.",al={"where maury","maury location","clubfoot where"}},{q="Who else owes MacKinley?",a="Jon-Jon the Crow and Chucky “Ten Thumbs” are also among MacKinley’s debtors.",al={"other debtors","jon jon and chucky","who owes sea wolf"}}},kw={"booty bay","club foot","clubbed foot","maury","maury wilkins","ruins of aboraz","sea wolf mackinley","voodoo dues"},rel={"quest:609","quest:613","item:jon-jon-s-golden-spyglass","item:chucky-s-huge-ring","subzone:booty-bay","subzone:ruins-of-aboraz"},src={"Wowpedia: Maury's Clubbed Foot","Voodoo Dues"}}
E["item:maury-s-key"] = {t="item",n="Maury's Key",z="stranglethorn",s="Maury's Key is sought by Sea Wolf MacKinley in Booty Bay. He needs it to open the lock on Maury's foot and claim what is owed him.",h="Maury's Key is sought by Sea Wolf MacKinley in Booty Bay.",sec={{t="A Locked Foot",b="MacKinley says Maury locked his foot, leaving the loot inside beyond reach. The dead gambler once played against the Mosh'Ogg ogres at their mound northeast of Booty Bay. After winning too much, Maury was chased away, and MacKinley suspects the ogres have his key.",sp=0}},faq={{q="What is Maury's Key for?",a="Sea Wolf MacKinley needs Maury's Key to open the lock on Maury's foot and get the loot inside.",al={"maury key","key for maurys foot","unlock foot"}},{q="Who wants Maury's Key?",a="Sea Wolf MacKinley in Booty Bay wants Maury's Key so he can open the lock on Maury's foot.",al={"who needs maury key","mac kinley key","sea wolf key"}},{q="Where did Maury lose the key?",a="MacKinley thinks the Mosh'Ogg ogres at their mound northeast of Booty Bay may have Maury's Key.",al={"where key","mosh ogg key","maury lost key"}},{q="Why might the ogres have it?",a="Maury gambled with the Mosh'Ogg ogres and was chased away after winning too much. MacKinley suspects they kept the key.",al={"why ogres have key","maury ogres","gambling key"}}},kw={"booty bay","gambling","key","locked foot","maury","maury's key","mosh'ogg","sea wolf mackinley"},rel={"quest:613","subzone:booty-bay","quest:607","quest:606","quest:609"},src={"Wowpedia: Maury's Key","Cracking Maury's Foot"}}
E["item:mind-s-eye"] = {t="item",n="Mind's Eye",z="stranglethorn",s="The Mind’s Eye is an artifact held by Mai’Zoth, an ogre mage in Stranglethorn Vale. Its magic is feared for corrupting and strengthening those who wield it.",h="The Mind’s Eye is an artifact held by Mai’Zoth, an ogre mage in Stranglethorn Vale.",sec={{t="The Ogre Mage",b="Brother Nimetz believes Mai’Zoth used the Mind’s Eye to corrupt Kurzen. The ogre mage keeps the artifact within the Mosh’Ogg ogre mound in eastern Stranglethorn Vale. Nimetz fears its influence could corrupt others as well.",sp=0},{t="A Choice for the Eye",b="Kin’weelay seeks the Mind’s Eye as the only hope of saving Yenniku. After it is recovered, Kin’weelay means to bend its power to the Darkspears’ needs. Brother Nimetz plans to study the artifact and decide whether it can be used for good or must be destroyed.",sp=0}},faq={{q="What is the Mind’s Eye?",a="The Mind’s Eye is an artifact held by the ogre mage Mai’Zoth. Its magic is said to make his power stronger and to corrupt others.",al={"minds eye","what is minds eye","the eye"}},{q="Who has the Mind’s Eye?",a="Mai’Zoth, an ogre mage, holds the Mind’s Eye deep within the Mosh’Ogg ogre mound in Stranglethorn Vale.",al={"who has the eye","mai'zoth eye","mind eye holder"}},{q="What did the Mind’s Eye do to Kurzen?",a="Brother Nimetz believes Mai’Zoth used the Mind’s Eye to corrupt Kurzen. He fears its influence could corrupt others.",al={"kurzen corruption","why kurzen evil","mind eye and kurzen"}},{q="Why does Kin’weelay want the Mind’s Eye?",a="Kin’weelay seeks the Mind’s Eye as the only hope of saving Yenniku, the Darkspear chief’s son.",al={"kinweelay eye","save yenniku","why eye"}},{q="What will Brother Nimetz do with it?",a="Brother Nimetz plans to study the Mind’s Eye and decide whether it can be used for good or must be destroyed.",al={"nimetz and eye","destroy minds eye","study the eye"}},{q="Where is Mai’Zoth?",a="Mai’Zoth dwells within the Mosh’Ogg ogre mound in eastern Stranglethorn Vale.",al={"mai'zoth location","mosh'ogg mound","where is the ogre mage"}}},ang={["faction:Horde"]="As a member of the Horde, the Mind’s Eye concerns the Darkspears’ effort to save Yenniku, the chief’s son."},kw={"brother nimetz","kin'weelay","kurzen","mai'zoth","mind's eye","mosh'ogg","ogre mage","stranglethorn","yenniku"},rel={"quest:591","quest:206","quest:592","zone:stranglethorn","subzone:mosh-ogg-ogre-mound","npc:kin-weelay","subzone:rebel-camp","subzone:grom-gol-base-camp"},src={"Wowpedia: Mind's Eye","Mai'Zoth (quest)","The Mind's Eye (Classic)"}}
E["item:miscellaneous-goblin-supplies"] = {t="item",n="Miscellaneous Goblin Supplies",z="stranglethorn",s="Miscellaneous Goblin Supplies are regular deliveries meant for Lieutenant Doren’s camp near the Stranglethorn entrance. They contain land mines to defend against Kurzen and his men.",h="Miscellaneous Goblin Supplies are regular deliveries meant for Lieutenant Doren’s camp near the Stranglethorn...",sec={{t="A Needed Delivery",b="Private Thorsen receives the supplies at Lieutenant Doren’s camp, northwest of the road from Duskwood into Stranglethorn Vale. Troll attacks have delayed the regular delivery, and Doren’s followers need it. Thorsen may be at the camp or patrolling south of it. The mines are meant to help defend the camp from Kurzen and his men.",sp=0}},faq={{q="What are the goblin supplies?",a="They are land mines provided by the goblins for Lieutenant Doren’s camp.",al={"goblin supplies","misc supplies","what's in the package"}},{q="Who needs these supplies?",a="Private Thorsen receives the supplies for Lieutenant Doren’s followers at their camp.",al={"who gets the supplies","who wants them","deliver to who"}},{q="Where is Doren’s camp?",a="The camp lies northwest of the road at the entrance to Stranglethorn Vale from Duskwood.",al={"doren camp location","where's the camp","camp near stranglethorn"}},{q="Why are the mines needed?",a="The mines will help defend Doren’s camp from Kurzen and his men.",al={"why mines","what are mines for","defense against kurzen"}}},kw={"duskwood","goblin supplies","kurzen","land mines","lieutenant doren","miscellaneous goblin supplies","private thorsen","stranglethorn vale"},rel={"quest:198","npc:doren","zone:stranglethorn","zone:duskwood","topic:goblin"},src={"Wowpedia: Miscellaneous Goblin Supplies","Supplies to Private Thorsen"}}
E["item:muddy-note"] = {t="item",n="Muddy Note",z="stranglethorn",s="A muddy, barely legible note found among a strongbox’s valuables. Its details about Private Thorsen’s patrols may help Lieutenant Doren uncover a traitor at Rebel Camp.",h="A muddy, barely legible note found among a strongbox’s valuables.",sec={{t="The Scribbled Note",b="Private Thorsen’s patrol routes and habits are set down in a muddy note from a strongbox in Stranglethorn Vale. It also records who he speaks with among the rebels. The writing is hard to read, but Lieutenant Doren needs the note to find the traitor.",sp=0}},faq={{q="What does the muddy note say?",a="The note records Private Thorsen’s patrol routes, his conversations, and how he spends his time with the rebels. Its writing is barely legible.",al={"what's on the note","muddy note details","thorsen note"}},{q="Where do I take the note?",a="Take the muddy note to Lieutenant Doren at Rebel Camp.",al={"who wants the note","where to bring it","doren note"}},{q="Who wrote the note?",a="The note is signed with the single letter M. It does not identify its writer by name.",al={"who signed it","note author","who is M"}},{q="Why is the note important?",a="The note shows that its writer knew Private Thorsen’s routines and dealings. Lieutenant Doren needs it as a clue to find the traitor among the rebels.",al={"why does doren need it","traitor clue","what's the note for"}}},kw={"lieutenant doren","muddy note","private thorsen","rebel camp","stranglethorn vale","strongbox","traitor"},rel={"quest:329","npc:doren","subzone:rebel-camp","zone:stranglethorn"},src={"Wowpedia: Muddy Note","The Spy Revealed!"}}
E["item:nezzliok-s-head"] = {t="item",n="Nezzliok's Head",z="stranglethorn",s="Nezzliok's Head is taken from the Bloodscalp witchdoctor in Zul'Kunda. Nimboya needs it at Grom'gol Base Camp as he searches for the truth about Yenniku.",h="Nezzliok's Head is taken from the Bloodscalp witchdoctor in Zul'Kunda.",sec={{t="A Bitter Offering",b="At Grom'gol Base Camp, Nimboya asks for the heads of Gan'zulah and Nezzliok. The two Bloodscalp leaders may know what became of Yenniku, who was not among the heads already found. Nezzliok's Head is brought with Gan'zulah's to the bubbling cauldron beside Nimboya.",sp=0}},faq={{q="Who is Nezzliok?",a="Nezzliok the Dire is a witchdoctor of the Bloodscalp clan, found in Zul'Kunda in northwestern Stranglethorn Vale.",al={"nezzliok","nezzliok the dire","bloodscalp witchdoctor"}},{q="Why does Nimboya want Nezzliok's head?",a="Nimboya believes Nezzliok and the Bloodscalp chief Gan'zulah may know the truth about Yenniku, so he asks for both their heads.",al={"why head","nimboya needs head","nezzliok head"}},{q="Where do I take Nezzliok's Head?",a="Bring Nezzliok's Head to the bubbling cauldron at Grom'gol Base Camp, beside Nimboya.",al={"where head go","take it to nimboya","cauldron"}},{q="What happened to Yenniku?",a="Yenniku was not among the heads Nimboya found, and Nimboya fears the Bloodscalp chief and witchdoctor alone know the truth.",al={"yenniku missing","where is yenniku","what happened"}}},ang={["faction:Horde"]="As a member of the Horde, you can help Nimboya and the Darkspear tribe pursue the truth about Yenniku, their missing kinsman.",["race:Troll"]="As a troll, you may know the Darkspear and Bloodscalp as rival tribes. Nimboya seeks the truth about Yenniku from the Bloodscalp leaders."},kw={"bloodscalp","grom'gol","nezzliok","nezzliok the dire","nezzliok's head","nimboya","witchdoctor","yenniku","zul'kunda"},rel={"quest:584","item:gan-zulah-s-head","quest:581","subzone:grom-gol-base-camp","zone:stranglethorn","topic:darkspear-tribe","topic:troll"},src={"Wowpedia: Nezzliok's Head","Bloodscalp Clan Heads"}}
E["item:paw-of-sin-dall"] = {t="item",n="Paw of Sin'Dall",z="stranglethorn",s="Ajeck Rouack asks you to track Sin'Dall, an elusive tiger in Stranglethorn Vale, and bring back proof of the hunt.",h="Ajeck Rouack asks you to track Sin'Dall, an elusive tiger in Stranglethorn Vale, and bring back proof of the...",sec={{t="Proof of the Hunt",b="At Nesingwary's Expedition, Ajeck Rouack sets you after Sin'Dall, an elusive tiger tracked for weeks. He asks you to return with her paw as proof of the hunt. Bring it back, and he will hail you as a true Master Tiger Hunter.",sp=0}},faq={{q="Who is Sin'Dall?",a="Sin'Dall is an elusive tiger in Stranglethorn Vale, hunted by Ajeck Rouack and the trackers at Nesingwary's Expedition.",al={"sin'dall tiger","who's sin'dall"}},{q="Why does Ajeck want Sin'Dall's paw?",a="Ajeck Rouack asks you to bring Sin'Dall's paw as proof that you hunted and killed her.",al={"paw proof","why the paw"},sp=1},{q="Where do I take the Paw of Sin'Dall?",a="Bring the Paw of Sin'Dall to Ajeck Rouack at Nesingwary's Expedition.",al={"where paw goes","ajeck rouack paw"}},{q="What does the paw prove?",a="The paw proves to Ajeck Rouack that you completed the hunt for Sin'Dall.",al={"paw meaning","sin'dall proof"},sp=1}},ang={["class:Hunter"]="As a Hunter, Ajeck Rouack's challenge asks you to track and kill Sin'Dall, then bring back proof of the hunt."},kw={"ajeck rouack","nesingwary's expedition","paw of sin'dall","sin'dall","stranglethorn vale","tiger","tiger mastery"},rel={"quest:185","subzone:nesingwary-s-expedition","zone:stranglethorn","topic:hunter"},src={"Wowpedia: Paw of Sin'Dall","Tiger Mastery (4)"}}
E["item:pristine-tigress-fang"] = {t="item",n="Pristine Tigress Fang",z="stranglethorn",s="A Pristine Tigress Fang is a specimen Far Seer Mok'thardin seeks at Grom'gol Base Camp. Its condition matters to his enchantments for the Horde.",h="A Pristine Tigress Fang is a specimen Far Seer Mok'thardin seeks at Grom'gol Base Camp.",sec={{t="A Fine Specimen",b="Across the river southeast of Mizjah Ruins, Stranglethorn Tigresses prowl the jungle. Far Seer Mok'thardin asks for a fang kept in pristine condition, along with Shadowmaw Panther claws. He says his rituals have already shown success, and he means to harness the jungle's magic for the Horde.",sp=0}},faq={{q="Who wants the Pristine Tigress Fang?",a="Far Seer Mok'thardin at Grom'gol Base Camp wants a Pristine Tigress Fang for his enchantments.",al={"who wants the fang","mok'thardin fang","fang for who"}},{q="Why does the fang have to be pristine?",a="Mok'thardin says only a fang in pristine condition will do for his work with the jungle's magic.",al={"why pristine","perfect fang","fang condition"}},{q="Where can I find a Pristine Tigress Fang?",a="Stranglethorn Tigresses in Stranglethorn Vale carry Pristine Tigress Fangs. Mok'thardin points to the jungle southeast of Mizjah Ruins, across the river.",al={"where fang","tigress fang location","fang from tigresses"}},{q="What else does Mok'thardin need?",a="Mok'thardin also asks for eight Shadowmaw Claws alongside the Pristine Tigress Fang.",al={"what else does he need","claws too","mok'thardin needs"}},{q="What is Mok'thardin trying to do?",a="Mok'thardin seeks to harness the power of the jungle's magic for the Horde through powerful enchantments.",al={"mok'thardin magic","jungle enchantment","why does he want it"}}},ang={["faction:Horde"]="Mok'thardin seeks the fang and Shadowmaw claws to harness the jungle's magic for the Horde."},kw={"enchantment","fang","grom'gol","mizjah ruins","mok'thardin","pristine tigress fang","stranglethorn","tigress"},rel={"quest:570","subzone:grom-gol-base-camp","subzone:mizjah-ruins","zone:stranglethorn","item:shadowmaw-claw","topic:horde"},src={"Wowpedia: Pristine Tigress Fang","Mok'thardin's Enchantment"}}
E["item:pulsing-blue-shard"] = {t="item",n="Pulsing Blue Shard",z="stranglethorn",s="Pulsing Blue Shards are rare crystals taken from Ironjaw Basilisks in Stranglethorn Vale. Kin'weelay needs their magic to control the Mind's Eye.",h="Pulsing Blue Shards are rare crystals taken from Ironjaw Basilisks in Stranglethorn Vale.",sec={{t="A Singing Crystal",b="Kin'weelay, a troll at Grom'gol Base Camp, asks you to bring him Pulsing Blue Shards from Ironjaw Basilisks in Crystalvein Mine. He needs their magic for the Mind's Eye, a jewel said to hold great power.",sp=0}},faq={{q="What are Pulsing Blue Shards?",a="Pulsing Blue Shards are rare crystals taken from Ironjaw Basilisks in Stranglethorn Vale. Their magic can help Kin'weelay control the Mind's Eye.",al={"blue shard","pulsing crystal"}},{q="Who needs the shards?",a="Kin'weelay at Grom'gol Base Camp needs Pulsing Blue Shards for his work with the Mind's Eye.",al={"who wants blue shards","kinweelay shards"}},{q="Where do the shards come from?",a="Ironjaw Basilisks in Crystalvein Mine yield Pulsing Blue Shards.",al={"where get shards","crystalvein shards"}},{q="What is the Mind's Eye?",a="The Mind's Eye is a jewel hidden deep in Stranglethorn Vale, said to hold great power. Kin'weelay believes the shards can help him bend its magic to his will.",al={"minds eye","singing crystals"}},{q="Why does Kin'weelay want them?",a="Kin'weelay needs the shards' magic to control the Mind's Eye, which he hopes to use to bring Yenniku back from the darkness.",al={"why shards","what are shards for"},sp=1}},kw={"blue shards","crystalvein mine","ironjaw basilisk","kin'weelay","mind's eye","pulsing blue shard","stranglethorn","yenniku"},rel={"quest:589","item:mind-s-eye","npc:kin-weelay","subzone:crystalvein-mine","subzone:grom-gol-base-camp","zone:stranglethorn"},src={"Wowpedia: Pulsing Blue Shard","The Singing Crystals"}}
E["item:pupellyverbos-port"] = {t="item",n="Pupellyverbos Port",z="stranglethorn",s="A crate of Pupellyverbos Port went overboard near the Hinterlands during a storm. Whiskey Slim in Booty Bay needs the bottles back before the captain discovers they are missing.",h="A crate of Pupellyverbos Port went overboard near the Hinterlands during a storm.",sec={{t="Lost at Sea",b="Off the Overlook Cliffs, a storm struck the ship carrying Pupellyverbos Port toward Stormwind. The captain had taken the crate from a privateer, and Whiskey Slim broke into it for courage as the waves rose. A great wave swept the bottles overboard. Now the grog lies scattered along the shore, and Slim fears the captain's anger.",sp=0}},faq={{q="What is Pupellyverbos Port?",a="Pupellyverbos Port is a grog carried in a crate aboard a ship bound for Stormwind.",al={"pupellyverbos","what port is this","pupellyverbos booze"}},{q="How did the bottles get lost?",a="A storm near the Overlook Cliffs sent a great wave over the ship and swept the bottles into the sea.",al={"where'd the bottles go","how lost port","what happened to the grog"}},{q="Who is looking for the port?",a="Whiskey Slim in Booty Bay wants the lost bottles returned before the captain learns they are missing.",al={"who wants the booze","whiskey slim bottles","slim's grog"}},{q="Where did the crate come from?",a="The captain's crew commandeered the crate from a privateer traveling toward Stormwind.",al={"who had the crate","port origin","privateer booze"}}},kw={"booty bay","hinterlands","lost grog","overlook cliffs","privateer","pupellyverbos port","storm","whiskey slim"},rel={"quest:580","subzone:booty-bay","zone:stranglethorn"},src={"Wowpedia: Pupellyverbos Port","Whiskey Slim's Lost Grog"}}
E["item:shackle-key-stranglethorn-vale"] = {t="item",n="Shackle Key",z="stranglethorn",s="The Shackle Key is held by King Mukla on Jaguero Isle. Princess Poobah needs it to escape her captivity.",h="The Shackle Key is held by King Mukla on Jaguero Isle.",sec={{t="A Captive Princess",b="Princess Poobah is chained on Jaguero Isle, where King Mukla keeps her against her will. The key to her shackle is tied to her freedom, and she asks for aid from anyone willing to face the great Skymane king.",sp=0}},faq={{q="What does the Shackle Key open?",a="The Shackle Key opens the shackle holding Princess Poobah captive on Jaguero Isle.",al={"what's the key for","key opens what"}},{q="Who has the Shackle Key?",a="King Mukla has the Shackle Key on Jaguero Isle.",al={"who has the key","mukla key"}},{q="Where is Princess Poobah held?",a="Princess Poobah is held on Jaguero Isle in Stranglethorn Vale.",al={"where's poobah","poobah captive"}},{q="Why does Princess Poobah need the key?",a="Princess Poobah needs the Shackle Key to free herself from the chain holding her captive.",al={"why key needed","free poobah"}}},kw={"captivity","jaguero isle","king mukla","princess poobah","shackle","shackle key","stranglethorn vale"},rel={"quest:594","zone:stranglethorn"},src={"Wowpedia: Shackle Key (Stranglethorn Vale)","Message in a Bottle (2)"}}
E["item:shadowmaw-claw"] = {t="item",n="Shadowmaw Claw",z="stranglethorn",s="A Shadowmaw Claw comes from a panther in Stranglethorn Vale. Far Seer Mok'thardin needs these claws for an enchantment serving the Horde.",h="A Shadowmaw Claw comes from a panther in Stranglethorn Vale.",sec={{t="Panther Claws",b="Across the river from Mizjah Ruins, Shadowmaw Panthers and their elders hunt in the jungle. Far Seer Mok'thardin at Grom'gol Base Camp seeks their claws, along with a pristine tigress fang, for his enchantment. He believes the jungle's magic can be harnessed for the Horde.",sp=0}},faq={{q="Where do Shadowmaw Claws come from?",a="Shadowmaw Panthers and Elder Shadowmaw Panthers in Stranglethorn Vale bear these claws.",al={"shadowmaw claw source","panther claw","where claw"}},{q="Who wants Shadowmaw Claws?",a="Far Seer Mok'thardin at Grom'gol Base Camp seeks eight Shadowmaw Claws and a Pristine Tigress Fang.",al={"who needs claws","mokthardin claws","claws for who"}},{q="Why does Mok'thardin need the claws?",a="Mok'thardin needs Shadowmaw Claws and a Pristine Tigress Fang for an enchantment he means to make for the Horde.",al={"why claws","mokthardin enchantment","what for"}},{q="Where are the panthers?",a="Mok'thardin says Shadowmaw Panthers lurk across the river from Mizjah Ruins, to the southeast.",al={"shadowmaw location","panthers near gromgol","where panthers"}}},ang={["faction:Horde"]="Mok'thardin seeks these claws to harness the jungle's magic for a special enchantment in service of the Horde."},kw={"elder shadowmaw panther","grom'gol base camp","mok'thardin","mok'thardin's enchantment","pristine tigress fang","shadowmaw claw","shadowmaw panther","stranglethorn vale"},rel={"quest:570","item:pristine-tigress-fang","subzone:mizjah-ruins","subzone:grom-gol-base-camp","zone:stranglethorn","topic:horde"},src={"Wowpedia: Shadowmaw Claw","Mok'thardin's Enchantment"}}
E["item:shrunken-head"] = {t="item",n="Shrunken Head",z="stranglethorn",s="A Shrunken Head is taken from Bloodscalp headhunters in northern Stranglethorn. Nimboya at Grom'gol Base Camp examines them while seeking word of Yenniku.",h="A Shrunken Head is taken from Bloodscalp headhunters in northern Stranglethorn.",sec={{t="Nimboya's Search",b="At Grom'gol Base Camp, Nimboya asks you to bring him Shrunken Heads from Bloodscalp Headhunters. He searches each one for signs of Yenniku, the chief's son, whose fate is unknown to him. The ruins of Zuuldaia and Zul'Kunda lie along the northern coast, where many Headhunters can be found.",sp=0}},faq={{q="What is a Shrunken Head for?",a="Nimboya examines Shrunken Heads to learn whether Yenniku is among the dead.",al={"shrunken head use","why collect heads"}},{q="Who is looking for Yenniku?",a="Nimboya at Grom'gol Base Camp fears for Yenniku, the chief's son, and seeks signs of his fate.",al={"who wants yenniku","nimboya search"}},{q="Where do Shrunken Heads come from?",a="Bloodscalp Headhunters in northern Stranglethorn carry the heads Nimboya seeks.",al={"where get heads","bloodscalp heads"}},{q="Where can I find Bloodscalp Headhunters?",a="Nimboya points to the ruins of Zuuldaia and Zul'Kunda along the northern coast.",al={"headhunter location","where are headhunters"}}},ang={["faction:Horde"]="As a member of the Horde, you can bring Nimboya the heads he needs to search for Yenniku, the chief's son."},kw={"bloodscalp","grom'gol","headhunter","nimboya","shrunken head","yenniku","zul'kunda","zuuldaia"},rel={"quest:582","subzone:grom-gol-base-camp","topic:troll","zone:stranglethorn"},src={"Wowpedia: Shrunken Head","Headhunting (Classic)"}}
E["item:singing-blue-crystal"] = {t="item",n="Singing Blue Crystal",z="stranglethorn",s="Singing Blue Crystals are mined by the Venture Company in the hills around Crystalvein Mine. Crank Fizzlebub in Booty Bay wants them as proof that the goblins are losing ground.",h="Singing Blue Crystals are mined by the Venture Company in the hills around Crystalvein Mine.",sec={{t="Crystals in the Hills",b="Near Crystalvein Mine, Venture Company crews dig Singing Blue Crystals from the surrounding hills. They had meant to work inside the mine, but its basilisks drove them out. Crank Fizzlebub in Booty Bay asks you to bring him crystals taken from the company's miners. He says their retreat would leave more room for honest trade in Stranglethorn.",sp=0}},faq={{q="What are Singing Blue Crystals?",a="They are crystals mined by the Venture Company in the hills around Crystalvein Mine.",al={"singing crystals","blue crystal","what are these crystals"}},{q="Where does the Venture Company mine them?",a="The Venture Company digs Singing Blue Crystals from the hills surrounding Crystalvein Mine in Stranglethorn Vale.",al={"where are the crystals","crystal location","where venture co mine"}},{q="Why aren't they mining inside Crystalvein Mine?",a="Basilisks in Crystalvein Mine drove the Venture Company out, so its crews mine the surrounding hills instead.",al={"why not in the mine","basilisk mine","crystalvein basilisks"}},{q="Who wants the crystals?",a="Crank Fizzlebub in Booty Bay wants Singing Blue Crystals as proof that the Venture Company is losing ground.",al={"who needs singing crystals","crank fizzlebub crystals","crystals for crank"}},{q="What does the Venture Company want with the crystals?",a="The Venture Company planned to mine Singing Blue Crystals from Crystalvein Mine, then turned to the hills after basilisks drove them out.",al={"why mine crystals","venture co crystals","what are goblins digging for"}}},kw={"basilisks","booty bay","crank fizzlebub","crystalvein mine","singing blue crystal","singing crystals","stranglethorn vale","venture company"},rel={"quest:600","subzone:crystalvein-mine","subzone:booty-bay","topic:venture-company","zone:stranglethorn"},src={"Wowpedia: Singing Blue Crystal","Venture Company Mining (Classic)"}}
E["item:singing-crystal-shard"] = {t="item",n="Singing Crystal Shard",z="stranglethorn",s="Singing Crystal Shards are valuable blue crystals found in Stranglethorn Vale. Basilisks there eat the crystals, hardening their skin.",h="Singing Crystal Shards are valuable blue crystals found in Stranglethorn Vale.",sec={{t="Crystal and Scale",b="In Stranglethorn Vale, basilisks eat Singing Crystals, and the crystals harden their skin. A shard can sometimes be harvested from them. Crank Fizzlebub says the crystals are unique to Stranglethorn and valuable to certain parties. The Venture Company makes it difficult for him to gather them.",sp=0}},faq={{q="What are Singing Crystal Shards?",a="Singing Crystal Shards are pieces of crystals found in Stranglethorn Vale. Basilisks eat the crystals, which harden their skin.",al={"singing shards","blue crystal shards"}},{q="Why do basilisks have hardened skin?",a="Basilisks in Stranglethorn Vale eat Singing Crystals, and the crystals harden their skin.",al={"basilisk hard skin","why are basilisks tough"}},{q="Where can I find the shards?",a="Singing Crystal Shards can be harvested from basilisks in Stranglethorn Vale.",al={"shards location","where are singing crystals"}},{q="Why does Crank Fizzlebub want them?",a="Crank Fizzlebub says the crystals are valuable to certain parties, and he can move them for a profit.",al={"crank wants shards","what does crank need"}},{q="What does the Venture Company have to do with the crystals?",a="The Venture Company makes it difficult for Crank Fizzlebub to gather the crystals.",al={"venture company crystals","why venture company"}}},kw={"basilisk","blue shards","crank fizzlebub","singing crystal shard","singing crystals","stranglethorn vale","venture company"},rel={"zone:stranglethorn","quest:605","quest:589","topic:venture-company"},src={"Wowpedia: Singing Crystal Shard","Singing Blue Shards"}}
E["item:skullsplitter-fetish"] = {t="item",n="Skullsplitter Fetish",z="stranglethorn",s="A Skullsplitter Fetish is an instrument of troll magic gathered for Brother Nimetz at the Rebel Camp. He hopes it may shed light on Colonel Kurzen's corruption.",h="A Skullsplitter Fetish is an instrument of troll magic gathered for Brother Nimetz at the Rebel Camp.",sec={{t="Troll Magic",b="Brother Nimetz at the Rebel Camp seeks Skullsplitter Fetishes from the Skullsplitter Witch Doctors and Mystics in Stranglethorn Vale. He studies these charms for signs of what has brought Colonel Kurzen to evil.",sp=0}},faq={{q="What is a Skullsplitter Fetish?",a="A Skullsplitter Fetish is an instrument of troll magic carried by Skullsplitter Witch Doctors and Mystics.",al={"skullsplitter fetish meaning","what's the fetish","troll charm"}},{q="Who wants the fetishes?",a="Brother Nimetz at the Rebel Camp wants Skullsplitter Fetishes so he can study their magic.",al={"who wants fetish","where do fetishes go","brother nimetz"}},{q="Why does Brother Nimetz want them?",a="Brother Nimetz hopes the fetishes may reveal the secret behind Colonel Kurzen's corruption.",al={"why fetishes","kurzen corruption","nimetz wants what"}},{q="Where are Skullsplitter fetishes found?",a="Skullsplitter Witch Doctors and Mystics in Stranglethorn Vale carry the fetishes.",al={"fetish location","where skullsplitters","get fetishes"}},{q="How many fetishes does Nimetz need?",a="Brother Nimetz asks for four Skullsplitter Fetishes.",al={"fetish count","how many charms","four fetishes"}}},ang={["faction:Alliance"]="As an Alliance traveler, you can bring Brother Nimetz these fetishes to aid his study of Colonel Kurzen's corruption."},kw={"brother nimetz","colonel kurzen","mystic","skullsplitter","skullsplitter fetish","stranglethorn","troll magic","witch doctor"},rel={"quest:205","quest:207","subzone:rebel-camp","zone:stranglethorn","topic:troll"},src={"Wowpedia: Skullsplitter Fetish","Troll Witchery"}}
E["item:skullsplitter-tusk"] = {t="item",n="Skullsplitter Tusk",z="stranglethorn",s="A Skullsplitter Tusk is a troll’s tusk used to forge false tiger fangs for sale in the South Seas. Kebok in Booty Bay wants a large shipment for his trade.",h="A Skullsplitter Tusk is a troll’s tusk used to forge false tiger fangs for sale in the South Seas.",sec={{t="A False Fang",b="Kebok in Booty Bay sends you after the Skullsplitter trolls for their tusks. Their tusks make convincing copies of tiger fangs, which are costly to gather from the beasts themselves. The forgeries go into a shipment bound for the islands of the South Seas.",sp=0}},faq={{q="What is a Skullsplitter Tusk?",a="A Skullsplitter Tusk is a troll’s tusk that Kebok uses to make false tiger fangs.",al={"skullsplitter tusk","troll tusk","what tusk"}},{q="Who wants Skullsplitter Tusks?",a="Kebok in Booty Bay wants Skullsplitter Tusks for his shipment of forged tiger fangs.",al={"who wants tusks","kebok tusks","tusk buyer"}},{q="Why does Kebok need the tusks?",a="Kebok uses Skullsplitter Tusks as convincing forgeries of tiger fangs, which are costly to gather.",al={"why tusks","fake tiger fangs","tusk purpose"}},{q="Where do Skullsplitter Tusks come from?",a="The tusks come from Skullsplitter trolls in Stranglethorn Vale.",al={"where tusks from","skullsplitter location","troll tusks"}}},kw={"booty bay","kebok","skullsplitter tusk","skullsplitter tusks","south seas","stranglethorn vale","tiger fangs"},rel={"quest:209","zone:stranglethorn","subzone:booty-bay","subzone:south-seas"},src={"Wowpedia: Skullsplitter Tusk","Skullsplitter Tusks"}}
E["item:small-brass-key"] = {t="item",n="Small Brass Key",z="stranglethorn",s="The Small Brass Key is hidden in a ledger book at Kurzen’s Compound. It may fit a strongbox in the Stockpile.",h="The Small Brass Key is hidden in a ledger book at Kurzen’s Compound.",sec={{t="A Key in the Ledger",b="Herod’s papers point you toward the Stockpile, a cavern behind Kurzen’s Compound in Stranglethorn Vale. The Small Brass Key is tucked inside the binding of one of his ledger books. There, it may open the secure strongbox mentioned in his notes.",sp=0},{t="Inside the Box",b="The strongbox holds Herod’s more valuable coins and items. Opening it with the Small Brass Key also reveals a Muddy Note, which carries the search for the traitor onward.",sp=1}},faq={{q="Where do I find the Small Brass Key?",a="The Small Brass Key is hidden in the binding of one of Bookie Herod’s ledger books.",al={"small key location","where is brass key","herod key"}},{q="What does the Small Brass Key open?",a="The Small Brass Key opens Bookie Herod’s secure strongbox in the Stockpile at Kurzen’s Compound.",al={"what key unlocks","brass key box","strongbox key"}},{q="What is in Herod’s strongbox?",a="Herod keeps his more valuable coins and items in the strongbox. A Muddy Note is also found there.",al={"herod strongbox contents","what's in the box","bookie herod box"}},{q="What does the Muddy Note mean?",a="The Muddy Note leads the search further toward discovering the traitor.",al={"muddy note clue","note from the box","traitor note"},sp=1}},kw={"bookie herod","herod","hidden key","kurzen's compound","muddy note","small brass key","stockpile","stranglethorn vale","strongbox"},rel={"quest:328","npc:herod","item:muddy-note","subzone:kurzen-s-compound","zone:stranglethorn"},src={"Wowpedia: Small Brass Key","The Hidden Key"}}
E["item:smotts-cutlass"] = {t="item",n="Smotts' Cutlass",z="stranglethorn",s="Captain Smotts wants his cutlass back in Stranglethorn Vale. He asks you to bring wine and Barbecued Buzzard Wings to his old lifeboat on the coast.",h="Captain Smotts wants his cutlass back in Stranglethorn Vale.",sec={{t="A Captain's Blade",b="Captain Smotts asks you to bring wine and Barbecued Buzzard Wings to his old lifeboat on the coast. Negolash, the hungry giant who destroyed the captain's ship, is fond of both. Smotts means to draw the giant close and reclaim his cutlass. The blade is in Negolash's hands.",sp=0}},faq={{q="Who owns Smotts' Cutlass?",a="Captain Smotts owns the cutlass and asks for its return.",al={"smotts cutlass owner","captain's sword","who is smotts"}},{q="How did Negolash get the cutlass?",a="Negolash took the cutlass after the giant destroyed Captain Smotts' ship.",al={"negolash cutlass","how'd giant get it","cutlass stolen"},sp=1},{q="Why does Smotts want wine and buzzard wings?",a="Negolash craves wine and Captain Smotts' Barbecued Buzzard Wings, so Smotts uses them to lure the giant to his old lifeboat.",al={"negolash bait","why wine and wings","smotts food"}},{q="Where is Smotts' Cutlass?",a="Negolash has Smotts' Cutlass in Stranglethorn Vale.",al={"cutlass location","where's smotts blade","negolash item"},sp=1}},kw={"barbecued buzzard wings","captain smotts","cutlass","negolash","ruined lifeboat","smotts' cutlass","stranglethorn vale"},rel={"quest:618","quest:619","zone:stranglethorn","quest:8553"},src={"Wowpedia: Smotts' Cutlass","Facing Negolash"}}
E["item:split-bone-necklace"] = {t="item",n="Split Bone Necklace",z="stranglethorn",s="Split Bone Necklaces are trophies taken from the Skullsplitter trolls of Stranglethorn Vale. Kin'weelay asks for them to aid the Darkspears in their long war.",h="Split Bone Necklaces are trophies taken from the Skullsplitter trolls of Stranglethorn Vale.",sec={{t="A Darkspear Tally",b="At Grom'gol Base Camp, Kin'weelay sends you southeast toward the Skullsplitter tribe. Their warriors dwell among the troll ruins of Stranglethorn Vale, and the Darkspears have fought them for years. Though the Darkspears no longer live in the Vale, Kin'weelay says they remain bound to this conflict. Bring the necklaces to him, and your deeds will aid his people.",sp=0}},faq={{q="Who wants the Split Bone Necklaces?",a="Kin'weelay of the Darkspear tribe asks you to bring the Split Bone Necklaces to him at Grom'gol Base Camp.",al={"who wants these necklaces","kinweelay necklace","necklace for who"}},{q="Who wears these necklaces?",a="The Skullsplitter trolls carry Split Bone Necklaces. Kin'weelay seeks them as trophies in the Darkspears' war against the Skullsplitters.",al={"what are necklaces from","split bone necklace meaning","skullsplitter necklace"}},{q="Why does Kin'weelay want them?",a="Kin'weelay wants the necklaces to aid the Darkspears in their long conflict with the Skullsplitter tribe.",al={"why collect split bones","why does kinweelay need them","darkspear war"}},{q="Where are the Skullsplitters?",a="The Skullsplitters live southeast of Grom'gol Base Camp among the troll ruins of Stranglethorn Vale.",al={"where to find skullsplitters","skullsplitter location","troll ruins"}},{q="How many necklaces does Kin'weelay ask for?",a="Kin'weelay asks you to bring him twenty-five Split Bone Necklaces.",al={"necklace count","how many split bones","25 necklaces"}}},ang={["race:Troll"]="As a troll, you see one tribe's old war carried on by another. The Darkspears no longer dwell in Stranglethorn, yet Kin'weelay says they remain bound to their conflict with the Skullsplitters."},kw={"darkspear","grom'gol base camp","kin'weelay","necklace","skullsplitter","split bone necklace","stranglethorn vale","troll"},rel={"quest:598","npc:kin-weelay","topic:darkspear-tribe","topic:troll","zone:stranglethorn"},src={"Wowpedia: Split Bone Necklace","Split Bone Necklace (quest)"}}
E["item:stone-of-the-tides"] = {t="item",n="Stone of the Tides",z="stranglethorn",s="The Stone of the Tides is an ancient Gurubashi relic coveted by Baron Revilgaz for his collection. It commands water and can summon water elementals.",h="The Stone of the Tides is an ancient Gurubashi relic coveted by Baron Revilgaz for his collection.",sec={{t="A Sunken Relic",b="Baron Revilgaz seeks the Stone of the Tides for his collection of ancient troll artifacts. The relic once belonged to the mighty Gurubashi Empire and can command water and summon water elementals. Yet its power bears a curse: its user slowly fades from existence.",sp=0}},faq={{q="What is the Stone of the Tides?",a="The Stone of the Tides is a powerful magical artifact once used by the Gurubashi Empire. It commands water and summons water elementals.",al={"stone of tides","what's the tide stone"}},{q="What does the Stone of the Tides do?",a="The Stone of the Tides lets its user control water and summon water elementals.",al={"stone powers","what can the tide stone do"}},{q="What is the curse of the Stone of the Tides?",a="The Stone of the Tides slowly makes its user fade from existence.",al={"tide stone curse","why does it fade you"},sp=1},{q="Why does Baron Revilgaz want the Stone?",a="Baron Revilgaz wants the Stone of the Tides for his collection of ancient troll artifacts.",al={"revilgaz wants stone","why does baron want it"}},{q="Where did the Stone come from?",a="The Stone of the Tides was once used by the Gurubashi Empire.",al={"stone origin","gurubashi tide stone"}}},ang={["faction:Alliance"]="As an Alliance traveler in Stranglethorn Vale, you may help Baron Revilgaz recover the Stone for his collection of ancient troll artifacts.",["race:Troll"]="As a troll, you can recognize the Stone of the Tides as an artifact once used by the Gurubashi Empire."},kw={"baron revilgaz","curse","gurubashi","stone of the tides","troll artifact","water","water elementals"},rel={"quest:611","quest:578","npc:baron-revilgaz","item:catelyn-s-blade","zone:stranglethorn","topic:troll","topic:mage"},src={"Stone of the Tides","The Curse of the Tides"}}
E["item:tablet-shard"] = {t="item",n="Tablet Shard",z="stranglethorn",s="The Tablet Shard comes from an ancient troll tablet beneath the Vile Reef. Kin'weelay seeks it for a sacred place in Orgrimmar, where it can honor the Darkspear hero Gri'lek.",h="The Tablet Shard comes from an ancient troll tablet beneath the Vile Reef.",sec={{t="A Fragment of Gri'lek",b="Beneath the waters of the Savage Coast, the Tablet Shard is taken from a tablet bearing the tale of Gri'lek the Wanderer. Kin'weelay wants a fragment for the Darkspear tribe's new home in Orgrimmar. There, it will remind the tribe of Gri'lek's might and honor.",sp=0}},faq={{q="What is the Tablet Shard?",a="The Tablet Shard is a fragment of an ancient troll tablet beneath the Vile Reef. It bears the tale of Gri'lek the Wanderer.",al={"tablet shard","what shard","troll tablet piece"}},{q="Who wants the Tablet Shard?",a="Kin'weelay at Grom'gol Base Camp wants the Tablet Shard for a sacred place in Orgrimmar.",al={"who wants shard","Kin'weelay shard","who do I give it to"}},{q="Why does the Darkspear tribe want it?",a="The shard will honor Gri'lek the Wanderer and remind the Darkspear tribe of his might and honor.",al={"why shard","darkspear tablet","what's it for"}},{q="Where is the tablet?",a="The tablet lies beneath the waters of the Savage Coast, in the ruins known as the Vile Reef.",al={"tablet location","where shard from","vile reef tablet"}}},ang={["race:Troll"]="As a troll, the Tablet Shard carries the sacred tale of Gri'lek, a hero of troll legends, and is meant to honor him among the Darkspear.",["faction:Horde"]="The Darkspear tribe seeks the Tablet Shard for a sacred place in its new home in Orgrimmar."},kw={"darkspear","gri'lek","gri'lek the wanderer","kin'weelay","savage coast","tablet shard","troll tablet","vile reef"},rel={"quest:629","zone:stranglethorn","subzone:savage-coast","subzone:grom-gol-base-camp","topic:troll","topic:darkspear-tribe"},src={"Wowpedia: Tablet Shard","The Vile Reef (quest)"}}
E["item:talon-of-tethis"] = {t="item",n="Talon of Tethis",z="stranglethorn",s="The Talon of Tethis is proof of a hunt in Stranglethorn Vale. Hemet Nesingwary asks you to bring it back after defeating the elusive raptor.",h="The Talon of Tethis is proof of a hunt in Stranglethorn Vale.",sec={{t="A Hunter’s Proof",b="Hemet Nesingwary names Tethis as a raptor few hunters can claim to have slain. Bring him the talon, and he calls you a master raptor slayer.",sp=0}},faq={{q="What is the Talon of Tethis?",a="The Talon of Tethis is proof that you defeated the raptor Tethis for Hemet Nesingwary.",al={"tethis talon","talon item","what's the talon for"}},{q="Who wants Tethis's talon?",a="Hemet Nesingwary wants Tethis's talon as proof of the hunt.",al={"who wants talon","hemet talon","where take tethis talon"}},{q="Where can I find Tethis?",a="Tethis wanders around the Gurubashi Arena, mainly to its north.",al={"where tethis","tethis location","find the raptor"}},{q="Why does Hemet want the talon?",a="Hemet asks for the talon as proof that you killed Tethis, a raptor he has failed to bring down himself.",al={"why talon","tethis hunt reason","hemet wants what"}}},ang={["class:Hunter"]="As a hunter, Hemet's challenge tests your skill against Tethis, a raptor he has failed to kill."},kw={"gurubashi arena","hemet nesingwary","raptor","raptor mastery","stranglethorn","talon of tethis","tethis"},rel={"quest:194","zone:stranglethorn","subzone:gurubashi-arena","topic:hunter"},src={"Wowpedia: Talon of Tethis","Raptor Mastery (4)"}}
E["item:the-first-troll-legend"] = {t="item",n="The First Troll Legend",z="stranglethorn",s="At Bal’lal Ruins, the tablet called Moon Over the Vale bears the First Troll Legend. Brother Nimetz seeks its markings for his studies of the troll legends.",h="At Bal’lal Ruins, the tablet called Moon Over the Vale bears the First Troll Legend.",sec={{t="Moon Over the Vale",b="Among the stones of Bal’lal Ruins, the tablet called Moon Over the Vale bears the First Troll Legend. Brother Nimetz at Rebel Camp asks you to transcribe its markings. He hopes the legends may explain what has corrupted Colonel Kurzen, once a noble man.",sp=0}},faq={{q="Where is the First Troll Legend?",a="The First Troll Legend is on the Moon Over the Vale tablet in the Bal’lal Ruins of Stranglethorn Vale.",al={"first troll legend location","where tablet","moon over vale"}},{q="What is Moon Over the Vale?",a="Moon Over the Vale is the tablet in Bal’lal Ruins that bears the First Troll Legend.",al={"moon over the vale tablet","first tablet","troll tablet"}},{q="Who wants the legend transcribed?",a="Brother Nimetz at Rebel Camp asks you to transcribe the troll legends.",al={"who wants the tablet","brother nimetz legend","nimetz"}},{q="Why is Brother Nimetz studying troll legends?",a="Brother Nimetz hopes the troll legends will reveal what caused Colonel Kurzen’s fall into depravity.",al={"kurzen's mystery","why study trolls","kurzen mystery"},sp=1},{q="Are there other troll legends?",a="Brother Nimetz seeks four legends from tablets in Stranglethorn Vale. The first is in Bal’lal Ruins; the second is in Vile Reef, and the third and fourth are in Zul’Kunda.",al={"other troll tablets","second third fourth legend","four troll legends"}}},ang={["faction:Alliance"]="Brother Nimetz’s search concerns Colonel Kurzen, an Alliance officer whose fall troubles those at Rebel Camp."},kw={"bal'lal ruins","brother nimetz","colonel kurzen","first troll legend","kurzen's mystery","moon over the vale","stranglethorn vale","troll tablet"},rel={"quest:207","subzone:bal-lal-ruins","zone:stranglethorn","item:the-second-troll-legend","item:the-third-troll-legend","item:the-fourth-troll-legend","npc:colonel-kurzen"},src={"Wowpedia: The First Troll Legend","Kurzen's Mystery"}}
E["item:the-fourth-troll-legend"] = {t="item",n="The Fourth Troll Legend",z="stranglethorn",s="At the Ruins of Zul'Kunda, the Fourth Troll Legend draws Brother Nimetz's search into the old stones of Stranglethorn. Its markings may help explain Colonel Kurzen's corruption.",h="At the Ruins of Zul'Kunda, the Fourth Troll Legend draws Brother Nimetz's search into the old stones of...",sec={{t="A Tablet in Zul'Kunda",b="Among the northern ruins of Zul'Kunda, the Emperor's Tomb bears the Fourth Troll Legend. Brother Nimetz seeks its markings alongside three other troll legends. He hopes the old words will shed light on Colonel Kurzen's fall, and has sent you to bring them back for study.",sp=0}},faq={{q="What is the Fourth Troll Legend?",a="The Fourth Troll Legend is a set of markings on a stone tablet called the Emperor's Tomb in the Ruins of Zul'Kunda.",al={"fourth troll legend","fourth tablet","troll legend four"}},{q="Where can I find the Fourth Troll Legend?",a="The Emperor's Tomb stands among the Ruins of Zul'Kunda in northwestern Stranglethorn Vale.",al={"fourth legend location","where is emperor's tomb","zul'kunda tablet"}},{q="Who wants the Fourth Troll Legend?",a="Brother Nimetz at the Rebel Camp wants the markings from the Fourth Troll Legend so he can study them.",al={"who needs fourth legend","brother nimetz tablet","nimetz legends"}},{q="Why is Brother Nimetz studying troll legends?",a="Brother Nimetz hopes the troll legends may reveal what caused Colonel Kurzen's corruption.",al={"kurzen mystery","why troll legends","kurzen corruption"}},{q="What are the other troll legends?",a="The other tablets bear the First, Second, and Third Troll Legends. They are found in Stranglethorn's Bal'lal Ruins, Vile Reef, and Ruins of Zul'Kunda.",al={"first second third legends","other tablets","all four legends"}}},ang={["faction:Alliance"]="As an Alliance traveler, you can help Brother Nimetz investigate Colonel Kurzen's fall by bringing him the markings from Zul'Kunda."},kw={"brother nimetz","colonel kurzen","emperor's tomb","fourth troll legend","stranglethorn","troll tablet","zul'kunda"},rel={"item:the-first-troll-legend","item:the-second-troll-legend","item:the-third-troll-legend","quest:207","subzone:rebel-camp","zone:stranglethorn"},src={"Wowpedia: The Fourth Troll Legend","Kurzen's Mystery"}}
E["item:the-second-troll-legend"] = {t="item",n="The Second Troll Legend",z="stranglethorn",s="The Second Troll Legend lies on a tablet in the drowned ruins of Vile Reef, off Stranglethorn Vale. Brother Nimetz seeks its markings as part of his inquiry into Colonel Kurzen’s fall.",h="The Second Troll Legend lies on a tablet in the drowned ruins of Vile Reef, off Stranglethorn Vale.",sec={{t="Gri’lek the Wanderer",b="Far beneath the water at Vile Reef, the Second Troll Legend marks one of the ruins’ stone tablets. Its name is Gri’lek the Wanderer. Brother Nimetz asks for its markings alongside three other troll legends, hoping they may shed light on Colonel Kurzen’s corruption.",sp=0}},faq={{q="Where is the Second Troll Legend?",a="The Second Troll Legend is on a tablet called Gri’lek the Wanderer in the drowned ruins of Vile Reef, off Stranglethorn Vale.",al={"second troll legend location","where's gri'lek","gri'lek tablet"}},{q="Who wants the legend?",a="Brother Nimetz at Rebel Camp seeks the Second Troll Legend and three other tablet inscriptions for his inquiry into Colonel Kurzen.",al={"who needs this legend","brother nimetz tablet","nimetz legends"}},{q="Why is Brother Nimetz collecting troll legends?",a="Brother Nimetz hopes the troll legends will help explain what caused Colonel Kurzen’s fall into depravity.",al={"why collect troll tablets","kurzen mystery why","kurzen's mystery"}},{q="What is Gri’lek the Wanderer?",a="Gri’lek the Wanderer is the stone tablet that bears the Second Troll Legend in Vile Reef.",al={"gri'lek wanderer","gri'lek tablet","second tablet name"}}},ang={["faction:Alliance"]="Brother Nimetz, an Alliance scholar at Rebel Camp, seeks these inscriptions to investigate Colonel Kurzen’s corruption."},kw={"brother nimetz","colonel kurzen","gri'lek the wanderer","kurzen's mystery","second troll legend","stranglethorn","troll tablet","vile reef"},rel={"item:the-first-troll-legend","item:the-third-troll-legend","item:the-fourth-troll-legend","quest:207","subzone:vile-reef","subzone:rebel-camp"},src={"Wowpedia: The Second Troll Legend","Kurzen's Mystery"}}
E["item:the-third-troll-legend"] = {t="item",n="The Third Troll Legend",z="stranglethorn",s="At the Ruins of Zul'Kunda, the Third Troll Legend is one of four tablet transcriptions Brother Nimetz seeks. He hopes the old markings will shed light on Colonel Kurzen's corruption.",h="At the Ruins of Zul'Kunda, the Third Troll Legend is one of four tablet transcriptions Brother Nimetz seeks.",sec={{t="Stone in Zul'Kunda",b="Among the roofless rooms of the Ruins of Zul'Kunda, the Third Troll Legend lies on a stone tablet called Fall of Gurubashi. Its markings are sought by Brother Nimetz at the Rebel Camp. He is studying four troll legends for a possible link to Colonel Kurzen's corruption.",sp=0}},faq={{q="What is the Third Troll Legend?",a="The Third Troll Legend is a transcription of markings from the Fall of Gurubashi tablet in the Ruins of Zul'Kunda.",al={"third troll legend","troll tablet","zul'kunda legend"}},{q="Where is the Fall of Gurubashi tablet?",a="The Fall of Gurubashi tablet is in the southwestern room of the Ruins of Zul'Kunda, on the plateau.",al={"fall of gurubashi location","third tablet where","zul'kunda tablet"}},{q="Who wants the Third Troll Legend?",a="Brother Nimetz at the Rebel Camp seeks the four troll legends to study their possible connection to Colonel Kurzen's corruption.",al={"who wants the tablet","brother nimetz legend","kurzen mystery"}},{q="Why is Brother Nimetz collecting troll legends?",a="Brother Nimetz suspects troll magic may have a connection to Colonel Kurzen's corruption, and hopes the legends will help him investigate.",al={"why nimetz wants legends","kurzen troll magic","kurzen mystery why"}}},ang={["faction:Alliance"]="Brother Nimetz's concern is Colonel Kurzen, an Alliance officer whose corruption has alarmed him. The legends may help explain what befell Kurzen."},kw={"brother nimetz","colonel kurzen","fall of gurubashi","kurzen's mystery","third troll legend","troll tablet","zul'kunda"},rel={"item:the-first-troll-legend","item:the-second-troll-legend","item:the-fourth-troll-legend","quest:207","subzone:rebel-camp","zone:stranglethorn"},src={"Wowpedia: The Third Troll Legend","Kurzen's Mystery"}}
E["item:tumbled-crystal"] = {t="item",n="Tumbled Crystal",z="stranglethorn",s="Tumbled Crystals are strange blue stones found by Venture Co. geologists near Lake Nazferiti. Their unusual finish has drawn the company’s interest and Revilgaz’s attention.",h="Tumbled Crystals are strange blue stones found by Venture Co.",sec={{t="Blue Stone",b="Kebok sends you to Booty Bay with a request from Revilgaz, the notorious pirate. The Venture Co. geologists near Lake Nazferiti have been finding blue crystals in their mines, and their samples are wanted. Revilgaz suspects the company plans to use the stones as fuel or a catalyst, though he knows little more. The samples are to be sent to Head Chemist Gigglefont for study.",sp=0}},faq={{q="What is a Tumbled Crystal?",a="A Tumbled Crystal is a strange blue stone found by Venture Co. geologists near Lake Nazferiti.",al={"tumbled crystal meaning","blue crystal","what stone"}},{q="Where do the crystals come from?",a="Venture Co. geologists find Tumbled Crystals in their mines near Lake Nazferiti in Stranglethorn Vale.",al={"crystal location","where crystal","lake nazferiti crystals"}},{q="Why does Revilgaz want the crystals?",a="Revilgaz wants samples because the Venture Co. geologists are interested in the blue stones, and he suspects they may be fuel or a catalyst.",al={"revilgaz crystal","why he wants them","crystal for pirate"}},{q="Who is Kebok?",a="Kebok in Booty Bay asks you to bring him Tumbled Crystals for Revilgaz.",al={"kebok who","who wants the crystals","booty bay crystal"}},{q="Who studies the samples?",a="Head Chemist Gigglefont is to receive the Tumbled Crystal samples for study.",al={"head chemist","gigglefont crystals","who gets samples"}}},ang={["profession:Mining"]="As a miner, you can see why the Venture Co. geologists prize unusual stones found in their workings."},kw={"crystal","geologist","gigglefont","kebok","lake nazferiti","revilgaz","tumbled crystal","venture co."},rel={"quest:213","quest:600","zone:stranglethorn","subzone:lake-nazferiti","subzone:booty-bay","topic:venture-company"},src={"Wowpedia: Tumbled Crystal","Hostile Takeover"}}
E["item:venom-fern-extract"] = {t="item",n="Venom Fern Extract",z="stranglethorn",s="Kurzen's stores in Stranglethorn hold Venom Fern Extract, a poison used against Rebel Camp fighters. Sergeant Yohwa needs a sample to help the camp prepare its own remedies.",h="Kurzen's stores in Stranglethorn hold Venom Fern Extract, a poison used against Rebel Camp fighters.",sec={{t="Kurzen's Stores",b="Near the bonfire in Kurzen Compound, supply crates hold Venom Fern Extract. Kurzen's Medicine Men use it to poison Rebel Camp fighters, while Jungle Remedies help heal Kurzen's forces. Sergeant Yohwa seeks both kinds of medicine: the remedies to treat the wounded, and an extract sample to study. The camp hopes to make remedies of its own.",sp=0}},faq={{q="What is Venom Fern Extract?",a="Venom Fern Extract is a poison Kurzen's Medicine Men use against Rebel Camp fighters.",al={"venom fern","fern extract","what's the extract"}},{q="Where can I find Venom Fern Extract?",a="Kurzen stores Venom Fern Extract in supply crates near the bonfire in the center of Kurzen Compound.",al={"where is venom fern","extract location","kurzen crates"}},{q="Who wants Venom Fern Extract?",a="Sergeant Yohwa at Rebel Camp wants a sample of Venom Fern Extract to study.",al={"who needs the extract","sergeant yohwa","rebel camp medicine"}},{q="Why does Sergeant Yohwa need it?",a="Sergeant Yohwa hopes the camp can study the extract and make its own remedies.",al={"why bring extract","what's it for","study the poison"}},{q="What are Jungle Remedies for?",a="Kurzen's Medicine Men use Jungle Remedies to heal their forces; Rebel Camp also needs them to treat its wounded.",al={"jungle remedy","kurzen medicine","remedies for what"}}},ang={["faction:Alliance"]="As an Alliance fighter, Rebel Camp's effort matters to the struggle against Kurzen: its healers need remedies to keep their people alive."},kw={"jungle remedy","kurzen","kurzen compound","poison","rebel camp","sergeant yohwa","supply crates","venom fern","venom fern extract"},rel={"quest:204","zone:stranglethorn","subzone:rebel-camp","item:jungle-remedy"},src={"Wowpedia: Venom Fern Extract","Bad Medicine (Classic)"}}
E["item:water-elemental-bracers"] = {t="item",n="Water Elemental Bracers",z="stranglethorn",s="Water Elemental Bracers are magical remains taken from lesser water elementals on the Haunted Isle. Baron Revilgaz wants specimens examined for a way to counter the Stone of the Tides’ curse.",h="Water Elemental Bracers are magical remains taken from lesser water elementals on the Haunted Isle.",sec={{t="Island Specimens",b="The Haunted Isle in northern Stranglethorn is home to lesser water elementals, whose bracers hold magical residue. Baron Revilgaz asks you to bring him six specimens from the island. He hopes a mage in Dalaran can study them and find a way to counter the Stone of the Tides’ curse.",sp=0}},faq={{q="Where do Water Elemental Bracers come from?",a="Lesser water elementals on the Haunted Isle in northern Stranglethorn carry Water Elemental Bracers.",al={"where bracers from","water bracer source"}},{q="Who wants these bracers?",a="Baron Revilgaz in Booty Bay wants six Water Elemental Bracers so a mage in Dalaran can examine their magical residue.",al={"who needs bracers","revilgaz bracers"}},{q="Why does Revilgaz want the bracers?",a="Revilgaz hopes a mage in Dalaran can study the bracers’ magical residue and find a way to counter the Stone of the Tides’ curse.",al={"why bracers","stone tides curse"}},{q="What is the Stone of the Tides?",a="The Stone of the Tides is said to curse its bearer, causing them to fade in and out of existence.",al={"stone tides","what stone"}},{q="How many bracers does Revilgaz need?",a="Baron Revilgaz asks for six Water Elemental Bracers.",al={"bracers count","how many"}}},ang={["class:Mage"]="As a mage, you may be asked to study the magical residue on these bracers for a way to counter the Stone of the Tides’ curse."},kw={"baron revilgaz","bracers","dalaran","haunted isle","lesser water elementals","stone of the tides","stranglethorn","water elemental bracers"},rel={"quest:601","quest:578","item:stone-of-the-tides","subzone:booty-bay","subzone:dalaran","zone:stranglethorn"},src={"Wowpedia: Water Elemental Bracers","Water Elementals (Classic)"}}
E["item:zanzil-s-mixture"] = {t="item",n="Zanzil's Mixture",z="stranglethorn",s="Zanzil's Mixture is brewed from jungle plants and used on the Outcast's followers. Crank Fizzlebub in Booty Bay seeks samples for his own purposes.",h="Zanzil's Mixture is brewed from jungle plants and used on the Outcast's followers.",sec={{t="Jungle Mixture",b="In the ruins northeast of Booty Bay, Zanzil the Outcast and his followers use a mixture made from jungle plants. It suppresses the will and strengthens the body of those who take it. Crank Fizzlebub wants samples, and keeps his reasons close.",sp=0}},faq={{q="What does Zanzil's Mixture do?",a="Zanzil's Mixture suppresses the will and strengthens the bodies of his followers.",al={"what is the mixture for","zanzil potion","what does it do"}},{q="Who is Zanzil the Outcast?",a="Zanzil the Outcast lives with his followers among the Jubuwal and Aboraz ruins northeast of Booty Bay. His own tribe exiled him because its leaders feared his power to bend minds.",al={"who's zanzil","zanzil backstory","zanzil guy"}},{q="Why does Crank Fizzlebub want the mixture?",a="Crank Fizzlebub in Booty Bay wants samples of Zanzil's Mixture and promises an extra payment for discretion.",al={"why crank wants it","crank fizzlebub mixture","what's crank up to"}},{q="What is Fool's Stout made from?",a="Fool's Stout is made with Zanzil's Mixture. Crank Fizzlebub asks for more mixture when he needs to make more stout.",al={"fools stout ingredients","fool's stout","stout recipe"},sp=1}},ang={["race:Gnome"]="As a gnome, you may hear of Zanzil's Mixture through Crank Fizzlebub in Booty Bay, who uses it to make Fool's Stout."},kw={"booty bay","crank fizzlebub","fool's stout","jungle plants","mind control","zanzil","zanzil the outcast","zanzil's mixture"},rel={"quest:621","quest:1127","zone:stranglethorn"},src={"Wowpedia: Zanzil's Mixture","Zanzil's Secret (Classic)","Fool's Stout (quest)"}}
E["item:ziata-jai-trophy"] = {t="item",n="Ziata'jai Trophy",z="stranglethorn",s="The Ziata'jai Trophy is a Skullsplitter trophy skull taken from the ruins in Northern Stranglethorn. Nezzliok demands it as part of a tribute tied to the search for Yenniku.",h="The Ziata'jai Trophy is a Skullsplitter trophy skull taken from the ruins in Northern Stranglethorn.",sec={{t="A Skullsplitter Trophy",b="Among the Skullsplitters' trophies at Ziata'jai Ruins in Northern Stranglethorn lies a skull Nezzliok demands. The dead witch doctor seeks three skulls from his people's rivals, the Skullsplitters, and this one is taken from their pile at Ziata'jai. It is brought to the Bubbling Cauldron at Grom'gol Base Camp with trophies from Balia'mah and Zul'Mamwe. Nezzliok promises knowledge of Yenniku's whereabouts in return for appeasement.",sp=0}},faq={{q="Where do you find the Ziata'jai Trophy?",a="The Ziata'jai Trophy is found in the Skullsplitter trophy pile at Ziata'jai Ruins in Northern Stranglethorn.",al={"ziata jai trophy location","where skull","ziata'jai skull"}},{q="Who wants the Ziata'jai Trophy?",a="The dead witch doctor Nezzliok demands the Ziata'jai Trophy as one of three Skullsplitter skulls.",al={"who wants it","nezzliok trophy","witch doctor skull"}},{q="Where do you take the Ziata'jai Trophy?",a="Bring the Ziata'jai Trophy to the Bubbling Cauldron at Grom'gol Base Camp with trophies from Balia'mah and Zul'Mamwe.",al={"where to bring skull","bubbling cauldron","gromgol trophy"}},{q="Why does Nezzliok want the trophy skulls?",a="Nezzliok demands three Skullsplitter trophy skulls to appease his spirit. He promises to reveal where Yenniku was taken.",al={"why skulls","nezzliok tribute","what does he want"},sp=1}},kw={"grom'gol","nezzliok","northern stranglethorn","skullsplitter","trophy skull","yenniku","ziata'jai","ziata'jai trophy"},rel={"quest:585","item:balia-mah-trophy","item:zul-mamwe-trophy","subzone:grom-gol-base-camp","topic:darkspear-tribe","zone:stranglethorn"},src={"Wowpedia: Ziata'jai Trophy","Speaking with Nezzliok (Classic)"}}
E["item:zul-mamwe-trophy"] = {t="item",n="Zul'Mamwe Trophy",z="stranglethorn",s="The Zul'Mamwe Trophy is a skull taken from a Skullsplitter trophy pile in the Ruins of Zul'Mamwe. Nezzliok demands it as part of an appeasement tied to the search for Yenniku.",h="The Zul'Mamwe Trophy is a skull taken from a Skullsplitter trophy pile in the Ruins of Zul'Mamwe.",sec={{t="A Skullsplitter Trophy",b="Among the Skullsplitter trophies in the Ruins of Zul'Mamwe, one skull is meant for the Bubbling Cauldron at Grom'gol Base Camp. Nezzliok, a dead witch doctor, demands it along with skulls from Balia'mah and Ziata'jai. He promises knowledge of Yenniku's whereabouts in return for appeasement.",sp=0}},faq={{q="What is the Zul'Mamwe Trophy?",a="The Zul'Mamwe Trophy is a skull taken from the Skullsplitter trophy pile in the Ruins of Zul'Mamwe.",al={"zul'mamwe skull","zul mamwe trophy","trophy skull"}},{q="Who wants the trophy?",a="Nezzliok, a dead witch doctor, demands the Zul'Mamwe Trophy as part of an appeasement.",al={"who needs this skull","nezzliok trophy","who wants zul'mamwe"}},{q="Where does the trophy come from?",a="The trophy comes from a pile of Skullsplitter trophy skulls in the Ruins of Zul'Mamwe in northern Stranglethorn.",al={"where is zul'mamwe","zul'mamwe location","find the skull"}},{q="Where must the skulls be brought?",a="The Balia'mah, Ziata'jai and Zul'Mamwe trophies are to be placed at the Bubbling Cauldron in Grom'gol Base Camp.",al={"where to take trophies","bubbling cauldron","trophy destination"}},{q="Why does Nezzliok ask for it?",a="Nezzliok says the Skullsplitter skulls will appease his spirit, and promises to reveal where Yenniku was taken.",al={"why skulls","nezzliok wants trophies","what does he promise"}}},kw={"bubbling cauldron","nezzliok","ruins of zul'mamwe","skullsplitter","trophy skull","yenniku","zul'mamwe","zul'mamwe trophy"},rel={"subzone:ruins-of-zul-mamwe","quest:585","subzone:grom-gol-base-camp","zone:stranglethorn","item:balia-mah-trophy","item:ziata-jai-trophy"},src={"Wowpedia: Zul'Mamwe Trophy","Speaking with Nezzliok (Classic)"}}
E["npc:baron-revilgaz"] = {t="npc",n="Baron Revilgaz",z="stranglethorn",s="On Booty Bay’s high balcony, Baron Revilgaz holds the port and its trade in his hands. He leads the Blackwater Raiders for the Steamwheedle Cartel, keeping the harbor open to Alliance and Horde while guarding his own interests. He hires help to watch rivals and seek ancient relics in the jungle.",h="On Booty Bay’s high balcony, Baron Revilgaz holds the port and its trade in his hands.",sec={{t="Master of Booty Bay",b="From the Salty Sailor Tavern, Baron Revilgaz watches Booty Bay’s docks with Fleet Master Seahorn, his trusted tauren advisor, beside him. Cutpurses, merchants, and privateers all answer to his firm hand. Blackwater Cove began as a human settlement, but trolls overwhelmed it before the First War. Goblins claimed and fortified the port, and it grew into the Blackwater Raiders’ commercial hub.\n\nRevilgaz keeps Booty Bay officially open to Alliance and Horde travelers. He enforces neutrality within the harbor so trade can continue.",sp=0},{t="A Web of Ambition",b="When wars elsewhere in Azeroth slowed business, Revilgaz found a way to draw crowds back to Booty Bay. The discovery of tastyfish gave him the means: he created the Stranglethorn Fishing Extravaganza. Across Stranglethorn Vale, he keeps watch on rivals and threats.\n\nHe hires sabotage against the Venture Company at Lake Nazferiti. He also watches Nesingwary’s hunting expedition and rogue human military camps in the north. With Monte Gazlowe and Pozzik at the Mirage Raceway, he keeps trade ties active.",sp=0},{t="The Stone of the Tides",b="Beyond the harbor, Revilgaz pursues wealth and ancient power. Rumors tell of a haunted island off the coast, and he sends adventurers to seek the legendary Stone of the Tides. They consult ancient tomes in the Stormwind Library and study elemental residues with Archmage Ansirem Runeweaver. Then they recover an ancient troll dagger from the Bloodsail Buccaneers.\n\nThe dagger breaks the coastal altar’s protection. Revilgaz breaks a deadly elemental curse and claims the priceless relic for his vaults.",sp=1}},faq={{q="Who is Baron Revilgaz?",a="Baron Revilgaz leads Booty Bay and the Blackwater Raiders for the Steamwheedle Cartel. Greed and practical diplomacy guide his rule of the pirate port.",al={"who is revilgaz","revilgaz backstory","booty bay boss","leader of booty bay"}},{q="Where can Baron Revilgaz be found?",a="Baron Revilgaz keeps to the top balcony of the Salty Sailor Tavern in Booty Bay. Fleet Master Seahorn, his trusted advisor, stands with him as he looks over the cove.",al={"where is revilgaz","revilgaz location","how to find revilgaz"}},{q="What is Revilgaz's relationship with the Bloodsail Buccaneers?",a="The Bloodsail Buccaneers are bitter enemies of Revilgaz. They reject the Steamwheedle Cartel’s rules and raid Booty Bay shipping. Their leaders plot to kill Revilgaz and Seahorn.",al={"revilgaz bloodsail","bloodsail vs revilgaz","why hate bloodsail"}},{q="What is Revilgaz's stake in the Mirage Raceway?",a="Revilgaz backs Pozzik’s goblin racing team against the gnomes in the Shimmering Flats. He sends adventurers to steal the Venture Company’s proprietary fuel regulator blueprints at Lake Nazferiti and bring them to the raceway.",al={"revilgaz racing","revilgaz shimmer flats","revilgaz pozik"}},{q="What is the Stranglethorn Fishing Extravaganza?",a="The Stranglethorn Fishing Extravaganza is a weekly fishing contest along the Stranglethorn coast. When wars elsewhere in Azeroth slowed trade, Revilgaz backed angler Riggle Bassbait and made the local tastyfish catch a tournament to revive Booty Bay’s economy.",al={"fishing tournament lore","who started the fishing contest","tastyfish revilgaz"}},{q="What is the Stone of the Tides?",a="The Stone of the Tides is an ancient cursed stone hidden at the Vile Reef. Revilgaz learns its legend from Stormwind records and hires Dalaran scholar Archmage Ansirem Runeweaver to help adventurers break its elemental wards and claim it.",al={"stone of the tides quest","vile reef stone","altar of the tides"},sp=1}},ang={["class:Rogue"]="As a rogue, you may find that Revilgaz values thieves, spies, and opportunists. He hires rogues for risky theft, sabotage against rival cartels, and secret retrieval of rare jungle artifacts.",["faction:Alliance"]="As an Alliance traveler, you can trace Booty Bay to the ruins of Blackwater Cove, a Stormwind enclave from before the First War. Revilgaz works with human scholars and librarians in Stormwind when ancient lore may bring profit.",["profession:Engineering"]="As an engineer, you’ll find Revilgaz caught up in goblin engineering rivalries. He uses underhanded means to obtain advanced blueprints and fuel regulators from the Venture Company."},kw={"blackwater raiders","bloodsail buccaneers","booty bay","lake nazferiti","revilgaz","salty sailor tavern","seahorn","steamwheedle cartel","stone of the tides"},rel={"subzone:booty-bay","npc:fleet-master-seahorn","zone:stranglethorn","subzone:salty-sailor-tavern","subzone:vile-reef","npc:archmage-ansirem-runeweaver","npc:monte-gazlowe","quest:764"},src={"Baron Revilgaz"}}
E["npc:colonel-kurzen"] = {t="npc",n="Colonel Kurzen",z="stranglethorn",s="In northern Stranglethorn Vale, Colonel Kurzen's former soldiers seek to end his rule. Once trusted by Stormwind, he now commands a rogue militia from an armed compound.",h="In northern Stranglethorn Vale, Colonel Kurzen's former soldiers seek to end his rule.",sec={{t="A Fall from Grace",b="Colonel Conrad Kurzen once served Stormwind as a capable and honorable officer. The kingdom's leaders trusted him with an expeditionary unit sent south into Stranglethorn Vale. Deep in the jungle, his behavior grew erratic and grandiose. He claimed the wilderness as his own and cast aside his loyalty to Stormwind.",sp=0},{t="The Rebellion",b="Kurzen's change divided his soldiers. Some followed him with blind loyalty or zeal, while others recoiled from his madness and brutality. When Emerine Junis rejected his advances, he threw her into the compound's prison. Lieutenant Doren led the soldiers who broke away and founded Rebel Camp along the northern road. Now they fight Kurzen's rampaging force to stop it.",sp=0},{t="The Ogre Behind the Curtain",b="Mai'Zoth, an ogre mage of the Mosh'ogg clan, used dark sorcery to possess Colonel Kurzen's mind. Jungle fever and exhaustion did not cause Kurzen's madness. Mai'Zoth turned a disciplined Stormwind detachment into violent pawns. Through the colonel, the ogre sought control of the region without open war.",sp=2}},faq={{q="Why did Colonel Kurzen turn against Stormwind?",a="During his expedition into Stranglethorn Vale, Kurzen grew erratic and grandiose, then abandoned his loyalty to Stormwind. His former soldiers at Rebel Camp still seek the cause of his madness.",al={"why is kurzen evil","what happened to kurzen","kurzen backstory"},sp=2},{q="Where is Colonel Kurzen located?",a="Colonel Kurzen commands his militia from Kurzen's Compound in the hills of northern Stranglethorn Vale. He lives in the fortified Stockpile building at the rear of the encampment.",al={"where to find kurzen","kurzen location","colonel kurzen compound"}},{q="Who are the rebels at the Rebel Camp?",a="The rebels are former soldiers under Kurzen's command who refused to follow his madness. Lieutenant Doren leads them from Rebel Camp near the northern border. They fight to end Kurzen's rogue army and remain loyal to Stormwind.",al={"rebel camp lore","who is lieutenant doren","why rebel camp"}},{q="Who is Emerine Junis?",a="Emerine Junis was attached to the expedition and rejected Kurzen's advances. As his cruelty and delusion grew, he locked her in the compound's prison cages.",al={"emerine junis","kurzen prisoner"}},{q="Is Kurzen acting alone in the jungle?",a="No. Kurzen commands the human mercenaries, soldiers, and jungle fighters who stayed loyal to him after the rebels left for Rebel Camp.",al={"who does kurzen work for","kurzen allies"},sp=2},{q="What happens if Colonel Kurzen is slain?",a="Lieutenant Doren asks Alliance adventurers to take Kurzen's head as proof of his death. He wants them to break the militia's chain of command and restore the Stormwind Army's honor.",al={"kurzen quest end","doren kurzen head"},sp=1}},ang={["faction:Alliance"]="For the Alliance, Kurzen's fall is a grave military scandal and a tragic loss of Stormwind troops. Alliance command and local loyalists have authorized his death.",["race:Human"]="As a human of Stormwind, you can remember Kurzen as a respected leader. His fall into tyranny shows the dangers of the jungle.",["class:Warrior"]="As a warrior, you can see how disciplined martial strength can be twisted when will and honor are lost."},kw={"colonel kurzen","conrad kurzen","doren","kurzen","kurzen's compound","rebel camp","stockpile","stranglethorn vale"},rel={"subzone:kurzen-s-compound","subzone:rebel-camp","npc:doren","zone:stranglethorn","topic:stormwind-kingdom"},src={"Colonel Kurzen"}}
E["npc:doren"] = {t="npc",n="Doren",z="stranglethorn",s="At the Rebel Camp, Doren leads soldiers who have turned against Colonel Kurzen. They once served on Stormwind's expedition and now seek the cause of his madness.",h="At the Rebel Camp, Doren leads soldiers who have turned against Colonel Kurzen.",sec={{t="A Mutiny in the Jungle",b="Lieutenant Doren leads the Rebel Camp beside the road in Stranglethorn Vale. He came south under Stormwind's banner with Colonel Kurzen on an expedition to establish a foothold in the jungle. But Kurzen and his inner circle grew erratic and violent. Doren would not follow them into madness, so he and loyal soldiers broke ranks and fled north. They chose defection over service to a mad commander.",sp=0},{t="Uncovering the Truth",b="Doren directs attacks on Kurzen's Compound and keeps his dwindling troops supplied through neutral contacts, including Krazek in Booty Bay. He sends spies such as Private Thorsen behind enemy lines to learn what afflicted Kurzen and to find traitors and collaborators like Bookie Herod. Doren believes ending Kurzen is the only way to preserve what remains of the expedition's honor.",sp=1}},faq={{q="Who is Lieutenant Doren?",a="Lieutenant Doren leads the Rebel Camp in northern Stranglethorn Vale. He once served Colonel Kurzen on a Stormwind expedition, then led soldiers who refused to follow Kurzen after he went mad.",al={"who is doren","doren lore","rebel camp leader"}},{q="Why is Doren considered a rebel?",a="Doren and his soldiers mutinied against their commander, Colonel Kurzen. Kurzen led the expedition under Stormwind's authority, so Doren and his followers became rebels when they broke away and took up arms against him. They seek to preserve their sanity and oppose his tyranny.",al={"why is it called rebel camp","why did doren rebel","kurzen mutiny"}},{q="What drove Colonel Kurzen mad?",a="Doren does not know what caused the madness that afflicted Kurzen and his inner circle. He sends spies and scouts to learn what corrupted his former commander in the jungle.",al={"why did kurzen go crazy","kurzens madness"}},{q="How does Doren keep the Rebel Camp supplied?",a="Doren keeps the Rebel Camp supplied through covert runs and arrangements with neutral parties. He works with goblin merchants such as Krazek in Booty Bay to outfit his troops.",al={"rebel camp supplies","doren supplies"}},{q="Who is Bookie Herod and what is his connection to Doren?",a="Bookie Herod is an associate of Kurzen's forces. Doren suspects Herod helped uncover the loyalties of Private Thorsen, Doren's agent inside the compound.",al={"bookie herod","herod rebel camp"}},{q="Does Doren answer to Stormwind?",a="Doren broke ranks with his commander and now acts on his own, while remaining loyal to the Alliance's ideals. He welcomes Alliance adventurers who can help set right the failed expedition.",al={"doren alliance","doren stormwind allegiance"}}},ang={["faction:Alliance"]="As an Alliance soldier, you can help Doren confront the fallout of Stormwind's jungle expedition and restore order in the frontier.",["race:Human"]="As a human traveler, you may recognize Doren's military discipline. His story shows the toll that isolated service far from Stormwind can take on mind and morale."},kw={"bookie herod","colonel kurzen","doren","kurzen","kurzen's compound","lieutenant doren","rebel camp","stranglethorn","thorsen"},rel={"subzone:rebel-camp","npc:colonel-kurzen","subzone:kurzen-s-compound","zone:stranglethorn","subzone:booty-bay"},src={"Doren"}}
E["npc:fleet-master-seahorn"] = {t="npc",n="Fleet Master Seahorn",z="stranglethorn",s="From Booty Bay, Fleet Master Seahorn guards the harbor against the Bloodsail Buccaneers. The seasoned tauren commands the Blackwater Raiders from the Salty Sailor Tavern, beside Baron Revilgaz.",h="From Booty Bay, Fleet Master Seahorn guards the harbor against the Bloodsail Buccaneers.",sec={{t="A Bull on the High Seas",b="Fleet Master Seahorn commands the Blackwater Raiders from the Salty Sailor Tavern. Though many tauren across Kalimdor live on the plains, Seahorn chose the sea and wears pirate regalia. The Raiders serve as the Steamwheedle Cartel's private navy in Stranglethorn Vale. From his post above Booty Bay, Seahorn works with Baron Revilgaz to direct shipping routes, crew deployments, and coastal defenses for a port both lawless and tightly managed.",sp=0},{t="Defending the Bay",b="Bloodsail Buccaneers threaten Booty Bay from fortified camps along the southern Wild Shore and from warships offshore. Reports reveal that Fleet Master Firallon and the Bloodsail leaders plan a direct assault to sack the port. Seahorn answers with force. He sends mercenaries to seize enemy correspondence and neutralize Firallon, Keelhaul, and Stillwater aboard their flagship. The move shields Booty Bay from outright devastation.",sp=1},{t="Eyes Across the Seas",b="Seahorn oversees trade and salvage ventures across the Eastern Kingdoms. Near Faldir's Cove on the Arathi coast, he coordinates the recovery of sunken treasures and works with salvage divers to secure elven relics. He also keeps Revilgaz informed of profitable opportunities in town, including competitive angling and local trade. These ventures help fund the Blackwater fleet and keep it ahead of rivals.",sp=0}},faq={{q="Where is Fleet Master Seahorn located?",a="Fleet Master Seahorn keeps to the top floor and balcony of the Salty Sailor Tavern in Booty Bay. He stands beside Baron Revilgaz, overlooking the docks.",al={"where is seahorn","seahorn location","find seahorn"}},{q="Why is a tauren serving as a pirate fleet master?",a="Seahorn chose a seafaring, mercenary naval life despite the plains traditions of many tauren in Mulgore. His nautical skill and commanding presence earned him leadership of the Blackwater Raiders under Baron Revilgaz.",al={"tauren pirate","why is seahorn a pirate","tauren in booty bay"}},{q="What is Seahorn's relationship with Baron Revilgaz?",a="Seahorn is Baron Revilgaz's second-in-command and commands the Blackwater Raiders at sea. Revilgaz handles politics, trade, and finances, while Seahorn oversees the fleet, tactical intelligence, and Booty Bay's defenses.",al={"seahorn and revilgaz","is seahorn revilgaz bodyguard","who works for revilgaz"}},{q="Who are the Blackwater Raiders?",a="The Blackwater Raiders are a private fleet of corsairs loyal to the Steamwheedle Cartel and based in Booty Bay. They are a sanctioned navy, protecting goblin merchants and maintaining order in the southern seas, unlike outlaw raiders who plunder without restraint.",al={"blackwater raiders","what faction is seahorn","booty bay pirates"}},{q="Why does Seahorn want to stop the Bloodsail Buccaneers?",a="The Bloodsail Buccaneers are bitter rivals of the Blackwater Raiders. Led by Fleet Master Firallon, they have camps along the Wild Shore and intend to conquer Booty Bay. Seahorn works to get ahead of their invasion plans.",al={"seahorn vs bloodsail","bloodsail conflict","why fight bloodsail"}},{q="Does Seahorn have dealings outside of Stranglethorn Vale?",a="Yes. Seahorn works with salvage agents such as Doctor Draxlegauge and Shakes O'Breen to recover lost cargo and elven treasures sunk near Faldir's Cove off the Arathi Highlands. Valuable artifacts are delivered to his post in Booty Bay.",al={"faldirs cove seahorn","seahorn sunken treasure","arathi quests seahorn"}}},ang={["race:Tauren"]="As a tauren, you share a homeland with one of the rare few who left Kalimdor's inland plains to master the open ocean and serve a neutral goblin port.",["faction:Horde"]="Though Seahorn is a tauren, his allegiance belongs to the Steamwheedle Cartel and the Blackwater Raiders. He remains neutral toward Horde and Alliance travelers alike.",["class:Rogue"]="As a rogue in Booty Bay, you may find Seahorn coordinating coastal espionage, covert raids against Bloodsail warships, and efforts to intercept enemy orders."},kw={"blackwater raiders","bloodsail","booty bay","faldir's cove","firallon","fleet master seahorn","revilgaz","salty sailor tavern","seahorn","wild shore"},rel={"npc:baron-revilgaz","subzone:booty-bay","subzone:salty-sailor-tavern","subzone:wild-shore","subzone:faldir-s-cove","zone:stranglethorn","topic:pirate","topic:tauren"},src={"Fleet Master Seahorn"}}
E["npc:kin-weelay"] = {t="npc",n="Kin'weelay",z="stranglethorn",s="At Grom'gol Base Camp, Kin'weelay brings Darkspear witchcraft to the Horde's effort to free young Yenniku. His knowledge of spirits guides the work in Stranglethorn Vale.",h="At Grom'gol Base Camp, Kin'weelay brings Darkspear witchcraft to the Horde's effort to free young Yenniku.",sec={{t="A Master of Darkspear Mojo",b="Kin'weelay is a powerful Darkspear witch doctor who knows spirits, hexes, and soul magic. Horde scouts seek his counsel in Stranglethorn Vale when ancestral spirits stir or hostile troll enchantments block their way.",sp=0},{t="The Mission to Grom'gol",b="Kin'weelay was sent south from Orgrimmar to support Nimboya at Grom'gol Base Camp. He works to break the bindings on Yenniku, the abducted son of Chieftain Vol'jin's trusted bloodline.\n\nTo undo the dark craft, Kin'weelay seeks powerful reagents, especially the Mind's Eye. He means to shape a soul gem that can free captured spirits.",sp=1}},faq={{q="Who is Kin'weelay?",a="At Grom'gol Base Camp in northern Stranglethorn Vale, Kin'weelay is a Darkspear troll witch doctor. Horde leaders sent him from Orgrimmar for his mastery of spiritual and soul magic.",al={"kinweelay lore","who is kin'weelay","gromgol witch doctor"}},{q="Why is Kin'weelay in Stranglethorn Vale?",a="Kin'weelay came to Grom'gol Base Camp to aid Nimboya and the local Darkspear expedition. He brings his mystical talents to the effort to find and restore young Yenniku from the hostile jungle trolls.",al={"why is kinweelay in gromgol","kinweelay purpose"}},{q="What is Kin'weelay trying to create?",a="Kin'weelay seeks to make a soul gem from the Mind's Eye. He means it to capture and preserve Yenniku's soul, freeing the boy from the dark control upon him.",al={"kinweelay minds eye","what does kinweelay make"}},{q="Where does Kin'weelay come from?",a="Kin'weelay came from Orgrimmar, where the Darkspear have had strong ties and a presence since joining the Horde and settling the Echo Isles.",al={"kinweelay background","where did kinweelay come from"}},{q="How does he view the other troll tribes of Stranglethorn?",a="Kin'weelay sees hostile jungle tribes such as the Bloodscalp and Skullsplitter as dangerous rivals. Their rituals are violent and corrupted, so he uses his craft against their charms and to recover stolen Darkspear youth.",al={"kinweelay other trolls","kinweelay and bloodscalp"}},{q="What kind of items does Kin'weelay study?",a="Kin'weelay studies local curiosities with natural or hexed resonance, including singing crystals and the bone necklaces worn by hostile jungle trolls. He examines their mojo to devise countermeasures.",al={"kinweelay items","singing crystals kinweelay"}}},ang={["race:Troll"]="As a Darkspear troll, you can look to Kin'weelay as one of your tribe's respected spiritual authorities. He works to undo the cruel curses of your jungle kin.",["faction:Horde"]="As a member of the Horde, you can see how troll spiritualism aids the war effort. Kin'weelay offers magical ways to counter threats that strength alone cannot break."},kw={"darkspear","grom'gol","kin'weelay","kinweelay","mind's eye","stranglethorn","witch doctor","yenniku"},rel={"subzone:grom-gol-base-camp","zone:stranglethorn","topic:troll","topic:horde","zone:orgrimmar","subzone:vile-reef"},src={"Kin'weelay"}}
E["npc:scooty"] = {t="npc",n="Scooty",z="stranglethorn",s="From Booty Bay’s busy pirate port, Scooty keeps a teleport link to Gnomeregan. The goblin engineer trusts his craft and his transponders, though the experimental pad lies in the fallen gnome city. For the Horde, his device opens a perilous route into Dun Morogh.",h="From Booty Bay’s busy pirate port, Scooty keeps a teleport link to Gnomeregan.",sec={{t="Booty Bay's Teleportation Expert",b="Among Booty Bay’s wharves and workshops, Scooty pursues ambitious tinkering for the Steamwheedle Cartel. While many goblins favor gunpowder and explosives, he works to move matter across great distances. His transponders keep a working link to a teleportation pad inside Gnomeregan. Horde forces rely on his craft to reach the subterranean gnome stronghold without crossing dangerous Alliance territory.",sp=0},{t="Gnomish Gadgets and Goblin Risk",b="Experimental goblin teleporters rarely run without a hitch. After hearing of a new gnomish rig in Gnomeregan, Scooty and his partner Sovik built the Transpolyporter 6000. Scooty cheerfully admits it has exploded a dozen or so times. Crossing continents as scattered matter carries clear physical dangers, yet Scooty remains sure of his genius. To him, every mechanical failure is a small obstacle on the road to innovation.",sp=0}},faq={{q="Who is Scooty?",a="Scooty works as a goblin engineer in Booty Bay and claims to be a master engineer. He maintains and calibrates the Goblin Transponder network, which links the port to an experimental teleportation pad deep inside Gnomeregan.",al={"who is scooty","scooty lore","scooty npc","booty bay scooty"},it="identity"},{q="Why does Scooty have a teleporter to Gnomeregan?",a="Scooty linked Booty Bay to an experimental teleportation pad inside Gnomeregan to allow direct travel into the gnome city. For the Horde, it offers an indispensable route into Dun Morogh without crossing the heavily fortified Alliance homelands.",al={"why gnomeregan teleporter","how does scooty teleporter work","scooty port to gnomer"},it="purpose"},{q="Where is Scooty located?",a="Scooty works in Booty Bay, the neutral goblin port at the southern tip of Stranglethorn Vale.",al={"where is scooty","scooty location","find scooty"},it="place",gp=true},{q="Is using Scooty's teleporter safe?",a="Scooty’s teleporter successfully sends adventurers into Gnomeregan, but its workings can go awry. Mechanical mishaps and miscalibrated transponders make each trip a hazard.",al={"is scooty safe","teleporter safe","teleporter risks"},it="danger"},{q="Whose side is Scooty on?",a="Scooty operates out of Booty Bay as part of the neutral goblin enterprise. He maintains his engineering services and experimental transport device for any traveler willing to do business, regardless of their faction ties.",al={"scooty faction","is scooty horde or alliance","scooty allegiance"},it="side",add="6ce6cf89"},{q="Why is Scooty in Booty Bay?",a="Operating out of Booty Bay gives Scooty access to independent trade networks and curious adventurers far from the meddling oversight of mainland authorities. Here, he can manage his transponder network and tinker with long-range goblin teleportation at his own leisure.",al={"why is scooty here","scooty booty bay why","what brought scooty here"},it="why_here",add="04182db4"}},ang={["faction:Horde"]="As a member of the Horde, you can use Scooty’s indispensable shortcut into Gnomeregan to bypass Alliance defenses in Dun Morogh.",["profession:Engineering"]="As an engineer, you can appreciate Scooty’s audacious use of transponder physics, though goblin disregard for safety makes every activation a gamble."},kw={"booty bay","gnomeregan","goblin","scooty","stranglethorn","teleporter","transponder"},rel={"subzone:booty-bay","zone:gnomeregan","quest:2904","topic:goblin"},src={"Scooty"}}
E["quest:1041"] = {t="quest",n="The Caravan Road",z="stranglethorn",s="In Booty Bay, the search for Velinde Starsong turns north toward Darkshire. Caravaneer Ruzzgot recalls carrying the missing night elf priestess through Stranglethorn Vale.",h="In Booty Bay, the search for Velinde Starsong turns north toward Darkshire.",sec={{t="A Priestess in the Jungle",b="Caravaneer Ruzzgot remembers Velinde Starsong as a passenger on his caravan. Your search for the missing night elf priestess has brought you from Ashenvale to Booty Bay, at the southern edge of Stranglethorn Vale. She traveled with his caravan through the jungle, an unusual path for a night elf priestess.",sp=0},{t="North to Darkshire",b="Ruzzgot says he and Velinde parted ways as they traveled north through Stranglethorn Vale. She set out for Duskwood, and her trail leads to Darkshire. Clerk Daltry keeps the town's records, including the names of unfamiliar travelers who enter. His ledger may hold the next clue to Velinde's whereabouts.",sp=0}},faq={{q="Who is Velinde Starsong?",a="Velinde Starsong is a night elf priestess of Elune who left her homeland in Kalimdor under mysterious circumstances. Her disappearance has led a search across the continents, following her trail from Ashenvale through the Eastern Kingdoms.",al={"velinde","who is velinde","who are we looking for"},it="identity"},{q="Why was Velinde traveling with a caravan?",a="Velinde traveled through goblin territory with Caravaneer Ruzzgot's shipping outfit. She hired passage for the dangerous journey north through Stranglethorn Vale.",al={"why caravan","velinde caravan","ruzzgot caravan"},it="why_here"},{q="Who is Clerk Daltry?",a="Clerk Daltry is Darkshire's town clerk and archivist in Duskwood. He records outsiders and visitors amid the strange occurrences and threats in the region.",al={"clerk daltry","daltry darkshire","who is daltry"},it="identity"},{q="Where does this quest chain lead after Darkshire?",a="After you consult Clerk Daltry's records, he directs you to Jonathan Carevin. Speaking with Jonathan begins the search into Velinde's stay in Duskwood through his family.",al={"next quest","what comes next","after darkshire"},sp=1,it="next_step"},{q="Why is traveling from Booty Bay to Darkshire dangerous?",a="Stranglethorn Vale is home to predatory beasts, hostile troll tribes, and Bloodsail buccaneers. The journey north is dangerous, so travelers need to stay close to the main road.",al={"jungle danger","stranglethorn level","stranglethorn dangerous"},it="danger"},{q="Where did this investigation start?",a="The search began in Ashenvale, where night elf investigators noticed Velinde's unexplained departure with an artifact of great power. Clues pointed to a ship bound for the southern seas.",al={"starting point","where did chain start","ashenvale start"},it="origin"},{q="Why does Caravaneer Ruzzgot help you find Velinde?",a="Caravaneer Ruzzgot initially misjudged you, but after you proved yourself, he is willing to share what he knows in good faith. A night elf priestess traveling alongside his rough-and-tumble shipping outfit was unusual enough to stick in his memory. Having parted ways with Velinde Starsong on the road north, he has nothing to lose by pointing you toward Darkshire and its record-keeper.",al={"ruzzgot motive","why does ruzzgot help","why help find velinde"},it="motive",add="a495199a"}},ang={["race:NightElf"]="As a night elf, you may share your kin's concern for Velinde Starsong, a Sentinel priestess of Elune whose secretive actions have taken her to the Eastern Kingdoms.",["faction:Alliance"]="As an Alliance traveler, you carry news between neutral goblin ports and remote Alliance outposts such as Darkshire, linking places in a world fractured by recent wars."},kw={"booty bay","caravaneer ruzzgot","clerk daltry","darkshire","duskwood","stranglethorn vale","the caravan road","velinde starsong"},rel={"npc:clerk-daltry","subzone:darkshire","subzone:booty-bay","quest:1040","quest:1042","zone:stranglethorn","zone:ashenvale","topic:night-elf"},m={start="Caravaneer Ruzzgot",["end"]="Clerk Daltry",level="30",faction="Alliance",id=1041},src={"The Caravan Road"}}
E["quest:1116"] = {t="quest",n="Dream Dust in the Swamp",z="stranglethorn",s="In the Swamp of Sorrows, Krazek asks you to gather ten specks of dream dust from dragon whelps. He contacts sources about Nazz while seeking dust for his snuff pouch. Bring it back to him for the information you seek.",h="In the Swamp of Sorrows, Krazek asks you to gather ten specks of dream dust from dragon whelps.",sec={{t="A Favor for a Favor",b="Krazek says that learning about Nazz is a considerable favor, and you have traveled a long way from the Shimmering Flats to ask. While he contacts sources, he asks you to gather ten specks of dream dust from dragon whelps in the Swamp of Sorrows. The dust is for his snuff pouch. Bring it back, and Krazek will give you the information you seek.",sp=0},{t="Where the Dust Is Found",b="Green dragons in the Swamp of Sorrows carry dream dust. Adolescent whelps and dreaming whelps can be found in the swamp’s south-western corner.",sp=0}},faq={{q="Who is asking for the dream dust?",a="Krazek of Booty Bay asks you for dream dust in exchange for information about Nazz.",al={"who gives dream dust quest","who sends me to swamp of sorrows","dream dust quest giver"}},{q="Why does Krazek want dream dust?",a="Krazek wants the dust for a snuff pouch. He asks for it while he contacts sources about Nazz.",al={"what is dream dust for","why krazek wants dust","dream dust snuff"}},{q="Where is the dream dust found?",a="You can take dream dust from dragon whelps in the Swamp of Sorrows. Adolescent and dreaming whelps live in the swamp’s south-western corner.",al={"where to find dream dust","where is dream dust swamp of sorrows","dream dust location"}},{q="How does this connect back to Kravel Koalbeard?",a="Kravel Koalbeard of the Mirage Raceway sent you to Krazek to ask about the goblin racer pilot Nazz Steamboil. You came from the Shimmering Flats seeking an answer.",al={"why am i in booty bay","how does this relate to kravel","shimmering flats connection"}},{q="What comes next?",a="Rumors for Kravel comes next.",al={"what after dream dust in the swamp","next quest dream dust","rumors for kravel next"}}},kw={"booty bay","dream dust","kravel koalbeard","krazek","mirage raceway","nazz","swamp of sorrows","whelps"},rel={"quest:1115","quest:1117","npc:kravel-koalbeard","subzone:booty-bay","zone:swampofsorrows","subzone:mirage-raceway","subzone:shimmering-flats","topic:goblin"},m={start="Krazek",["end"]="Krazek",level="36",id=1116},src={"Dream Dust in the Swamp"}}
E["quest:1117"] = {t="quest",n="Rumors for Kravel",z="stranglethorn",s="At last, Krazek has a letter about Nazz Steamboil for you to carry to Kravel Koalbeard at the Mirage Raceway on the Shimmering Flats. Keep its origin secret.",h="At last, Krazek has a letter about Nazz Steamboil for you to carry to Kravel Koalbeard at the Mirage Raceway...",sec={{t="A Letter From Krazek",b="Krazek spent favors, a rare bottle of elven wine, and hours of deducing to learn about Nazz Steamboil. His letter holds very interesting bits about the goblin racer pilot. Krazek considers the letter too dangerous to use and leaves it to you, provided nobody learns where it came from. Carry it to Kravel Koalbeard on the Shimmering Flats.",sp=0},{t="Kravel's Verdict",b="Kravel Koalbeard finds the letter very interesting. He wonders if he should bow to the goblin pilot the next time they meet. He expects Nazz Steamboil to pay a small fortune to keep the secret buried.",sp=1}},faq={{q="Where does this begin?",a="Krazek gives you the letter in Booty Bay after you bring him the dream dust.",al={"who gives rumors for kravel","rumors for kravel starter","where do i get the rumors"}},{q="To whom should the letter be brought?",a="Bring the letter to Kravel Koalbeard at the Mirage Raceway on the Shimmering Flats of Thousand Needles.",al={"where to turn in rumors for kravel","who gets the goblin rumors","where is kravel koalbeard"}},{q="Who is the subject of Krazek's findings?",a="Krazek's findings concern Nazz Steamboil, the goblin racer pilot. His letter holds very interesting bits about Nazz.",al={"who is nazz steamboil","what is the rumor about","who are the rumors on"}},{q="How did Krazek uncover the information?",a="Krazek spent favors, hours deducing, and a rare bottle of elven wine to uncover the information.",al={"how did krazek get the info","krazek favors"}},{q="What comes next?",a="Next, you return to Booty Bay.",al={"next quest after rumors for kravel","rumors for kravel follow up"}}},kw={"booty bay","goblin rumors","kravel koalbeard","krazek","mirage raceway","nazz steamboil","rumors for kravel","shimmering flats","thousand needles"},rel={"npc:kravel-koalbeard","subzone:mirage-raceway","subzone:shimmering-flats","subzone:booty-bay","zone:thousandneedles","quest:1116","quest:1118","topic:goblin"},m={start="Krazek",["end"]="Kravel Koalbeard",level="36",id=1117},src={"Rumors for Kravel"}}
E["quest:1119"] = {t="quest",n="Zanzil's Mixture and a Fool's Stout",z="stranglethorn",s="At the Mirage Raceway, Kravel Koalbeard awaits a stout blended with Zanzil's Mixture. Crank Fizzlebub calls it Fool's Stout and believes Kravel needs it, so you carry it to him on the Shimmering Flats before it spoils.",h="At the Mirage Raceway, Kravel Koalbeard awaits a stout blended with Zanzil's Mixture.",sec={{t="A Libation for Kravel",b="Crank Fizzlebub has blended Zanzil's Mixture into stout, making a potent drink he calls Fool's Stout. He believes Kravel needs it and wants to hear how it works. So you carry the drink to Kravel Koalbeard at the Mirage Raceway on the Shimmering Flats.",sp=0},{t="Do Not Let It Sit",b="Crank warns you not to keep the stout long. The mixture drives the yeast into high gear, and the drink will not stay fresh forever.",sp=0}},faq={{q="Who sends you on this delivery?",a="Crank Fizzlebub in Booty Bay gives you Fool's Stout to carry.",al={"who starts zanzil's mixture and a fool's stout","quest giver"}},{q="Who receives the Fool's Stout?",a="Kravel Koalbeard receives Fool's Stout at the Mirage Raceway on the Shimmering Flats in Thousand Needles.",al={"who gets the stout","where do i turn this in","kravel location"}},{q="Why does the drink need to be delivered quickly?",a="The mixture drives the yeast hard, so stout that sits too long goes off.",al={"does fool's stout expire","why is it timed","fermentation effect"}},{q="What came before this?",a="It follows Back to Booty Bay and Zanzil's Secret.",al={"prerequisite quests","previous step"}},{q="What comes after delivering the stout?",a="The chain continues with Fool's Stout, Get the Gnomes Drunk and Get the Goblins Drunk.",al={"next quest","what happens next"}}},kw={"booty bay","fizzlebub","kravel","mixture","raceway","shimmering flats","stout","zanzil"},rel={"npc:kravel-koalbeard","subzone:mirage-raceway","subzone:shimmering-flats","subzone:booty-bay","quest:621","quest:1127","zone:thousandneedles","zone:stranglethorn"},m={start="Crank Fizzlebub",["end"]="Kravel Koalbeard",level="44",id=1119},src={"Zanzil's Mixture and a Fool's Stout"}}
E["quest:1127"] = {t="quest",n="Fool's Stout",z="stranglethorn",s="In Booty Bay, travelers seek more Fool's Stout for the Shimmering Flats raceway. Crank Fizzlebub needs twelve flasks of Zanzil's mixture to brew another batch.",h="In Booty Bay, travelers seek more Fool's Stout for the Shimmering Flats raceway.",sec={{t="A Second Batch",b="Travelers bound for the gnomes at the raceway may find their Fool's Stout has expired before they arrive. In Booty Bay, Crank Fizzlebub can brew a replacement. The goblin needs twelve flasks of Zanzil's mixture, and offers compensation for fetching them, with a little extra for discretion.",sp=0}},faq={{q="Who offers to brew Fool's Stout?",a="In Booty Bay in southern Stranglethorn Vale, Crank Fizzlebub offers to brew Fool's Stout.",al={"who gives fools stout","fools stout questgiver","crank fizzlebub"}},{q="What ingredients does Crank Fizzlebub need?",a="Crank Fizzlebub needs twelve flasks of Zanzil's mixture to brew another batch of Fool's Stout.",al={"what items needed fools stout","fools stout ingredients","zanzils mixture requirement"}},{q="Why would someone need another batch of Fool's Stout?",a="Fool's Stout evaporates after two hours, so travelers who miss that window need fresh ingredients for a replacement.",al={"why do fools stout again","fools stout expired","fools stout duration"}},{q="Where is the brew intended to go?",a="The brew is meant for the gnomes at the raceway.",al={"where does fools stout go","who drinks fools stout","fools stout destination"}}},kw={"booty bay","crank fizzlebub","fools stout","raceway","stranglethorn vale","zanzils mixture"},rel={"subzone:booty-bay","zone:stranglethorn","topic:gnome"},m={start="Crank Fizzlebub",["end"]="Crank Fizzlebub",level="44",id=1127,ri={"Zanzil's Mixture"}},src={"Fool's Stout (quest)"}}
E["quest:1181"] = {t="quest",n="Goblin Sponsorship",z="stranglethorn",s="At the Mirage Raceway, the goblin racers still need their missing fuel regulator. Wharfmaster Lozgil sends you to Baron Revilgaz in Booty Bay for help.",h="At the Mirage Raceway, the goblin racers still need their missing fuel regulator.",sec={{t="Asking the Baron",b="Wharfmaster Lozgil can do little more to trace the missing shipment bound for Ratchet. He sends you to Baron Revilgaz, since the Baron knows his own business best. You will find him on the top floor of the tavern across the harbor in Booty Bay.",sp=0},{t="The Baron's Answer",b="Baron Revilgaz knows about the missing fuel regulator but cannot help. Some of his men went to find its blueprints and returned empty-handed.",sp=1}},faq={{q="Where can I find Baron Revilgaz?",a="Baron Revilgaz is on the top floor of the tavern across the harbor in Booty Bay.",al={"baron revilgaz location","where is revilgaz","find revilgaz booty bay"}},{q="Why does Wharfmaster Lozgil send you to Revilgaz?",a="Wharfmaster Lozgil can do little more to help, and says the Baron knows his own business best.",al={"why talk to revilgaz","lozgil sends to baron","why see baron revilgaz"}},{q="What shipment is being tracked down?",a="The shipment is a new fuel regulator bound for Ratchet, for the goblin racers of the Mirage Raceway.",al={"what shipment is missing","what are we looking for","missing ratchet cargo"}},{q="Where does this step fit in the chain?",a="This follows your talk with Wharfmaster Lozgil in Goblin Sponsorship two. The next step is Goblin Sponsorship four.",al={"what came before goblin sponsorship 3","chain progress goblin sponsorship"}}},kw={"baron revilgaz","booty bay","fuel regulator","goblin sponsorship","mirage raceway","ratchet","wharfmaster lozgil"},rel={"npc:baron-revilgaz","subzone:booty-bay","subzone:mirage-raceway","subzone:ratchet","zone:thousandneedles","topic:goblin","quest:1180","quest:1182"},m={start="Wharfmaster Lozgil",["end"]="Baron Revilgaz",level="37",id=1181},src={"Goblin Sponsorship (3)"}}
E["quest:1182"] = {t="quest",n="Goblin Sponsorship",z="stranglethorn",s="Baron Revilgaz is seeking the Venture Company’s new fuel regulator plans for Pozzik at Lake Nazferiti. Foreman Cozzle has outsmarted him, so the Baron sends you after the blueprints.",h="Baron Revilgaz is seeking the Venture Company’s new fuel regulator plans for Pozzik at Lake Nazferiti.",sec={{t="The Foreman's Blueprints",b="Baron Revilgaz says the Venture Company’s shredders at Lake Nazferiti in northern Stranglethorn carry a new model of fuel regulator. Pozzik could use its details, but Foreman Cozzle has proved cleverer than the Baron expected. So Revilgaz believes you may have better luck finding the plans.\n\nThe blueprints are kept in Cozzle’s house, almost certainly under lock and key. The Venture Company’s base lies around Lake Nazferiti, in the vale’s north-eastern corner. Cozzle keeps the key in his cabin atop the oil tower. The box of blueprints is in the small house near the tower’s base. Revilgaz admits the gnome team there is good, and his team needs every advantage it can find.",sp=0},{t="A Copy for the Baron",b="Revilgaz wants a copy of the blueprints for his own notes. Then he sends you to Pozzik, so the goblin does not think one of his sponsors has abandoned him.",sp=1}},faq={{q="Why does Baron Revilgaz want fuel regulator blueprints?",a="The Venture Company’s shredders at Lake Nazferiti carry a new model of fuel regulator. Revilgaz believes Pozzik could use the details.",al={"why steal blueprints","why fuel regulator","revilgaz motive"}},{q="Where are the blueprints kept?",a="The blueprints are in a box inside a small house at the foot of the oil tower, at the Venture Company’s base by Lake Nazferiti in northern Stranglethorn.",al={"where are blueprints","fuel regulator blueprints location","cozzle house"}},{q="Who holds the key?",a="Foreman Cozzle carries the key and works in the cabin atop the oil tower.",al={"cozzle key","where is key","how to open chest"}},{q="Where does this step fit in the chain?",a="Wharfmaster Lozgil sent you to Baron Revilgaz in the previous step, Goblin Sponsorship number three. Goblin Sponsorship number five comes next.",al={"what comes before this","what quest is next","goblin sponsorship chain"}}},ang={["class:Rogue"]="As a Rogue, you can pick the lock on the blueprints box without Cozzle’s key."},kw={"baron revilgaz","blueprints","foreman cozzle","fuel regulator","goblin sponsorship","lake nazferiti","mirage raceway","pozzik","venture company"},rel={"npc:baron-revilgaz","npc:pozzik","subzone:lake-nazferiti","topic:venture-company","subzone:booty-bay","subzone:mirage-raceway","zone:stranglethorn","zone:thousandneedles","quest:1181","quest:1183"},m={start="Baron Revilgaz",["end"]="Baron Revilgaz",level="37",faction="Neutral",id=1182},src={"Goblin Sponsorship (4)"}}
E["quest:1183"] = {t="quest",n="Goblin Sponsorship",z="stranglethorn",s="At the Shimmering Flats, Baron Revilgaz's regards reach Pozzik with the Fuel Regulator Blueprints. The Baron invites Pozzik to ask for anything he needs.",h="At the Shimmering Flats, Baron Revilgaz's regards reach Pozzik with the Fuel Regulator Blueprints.",sec={{t="Regards for Pozzik",b="Baron Revilgaz sends you to the Shimmering Flats with the Fuel Regulator Blueprints and his regards for Pozzik. The Baron says Pozzik should ask if he ever needs anything. Revilgaz waits to hear that Pozzik breaks the track record.",sp=0},{t="Improving the Design",b="Pozzik had hoped the regulator would already be assembled. Instead, he sees a chance to improve its design from the ground up. He plans to sketch new schematics, build the part and have it installed soon.",sp=1}},faq={{q="Who sends you with the blueprints?",a="Baron Revilgaz sends you from Booty Bay with his regards for Pozzik.",al={"who gives goblin sponsorship 5","quest giver","revilgaz quest"}},{q="Who receives the fuel regulator blueprints?",a="Pozzik receives the Fuel Regulator Blueprints on the Shimmering Flats.",al={"where do i take the blueprints","who gets the schematics","pozzik location"}},{q="What does Baron Revilgaz hope to hear?",a="Baron Revilgaz waits for news that Pozzik breaks the track record.",al={"revilgaz motivation","baron revilgaz sponsor"}},{q="What comes before this delivery?",a="Before this delivery, you fetched the blueprints for Revilgaz. The next step is The Eighteenth Pilot.",al={"previous quest","what led to this","goblin sponsorship chain"}}},kw={"baron revilgaz","fuel regulator blueprints","goblin sponsorship","mirage raceway","pozzik","shimmering flats","thousand needles"},rel={"npc:pozzik","npc:baron-revilgaz","subzone:mirage-raceway","subzone:shimmering-flats","quest:1182","quest:1186","zone:thousandneedles","topic:goblin"},m={start="Baron Revilgaz",["end"]="Pozzik",level="37",faction="Neutral",id=1183},src={"Goblin Sponsorship (5)"}}
E["quest:1261"] = {t="quest",n="Marg Speaks",z="stranglethorn",s="Near Theramore, Marg's stolen pendant and unfinished duty still weigh on them. Marg asks you to find the muckshell that killed them, recover the jeweled pendant taken from Alliance soldiers, and carry it to Nazeer Bloodpike in Brackenwall Village.",h="Near Theramore, Marg's stolen pendant and unfinished duty still weigh on them.",sec={{t="What Marg Saw Near Theramore",b="Alliance soldiers had made camp on the beach near Theramore. One wore a pendant set with more gems than a soldier could pay for. Marg slipped into the camp that night and stole it. On the way back to base, a muckshell crab-man killed Marg. Now Marg asks you to find the muckshell, recover the pendant, and bring it to Nazeer in Brackenwall Village.",sp=0},{t="What Nazeer Makes of It",b="Nazeer is startled that a Stormwind soldier wore the pendant. You have learned how Marg died, yet the pendant raises a new question. Nazeer warns that it may bring dire effects to both the Alliance and the Horde.",sp=1}},faq={{q="Who is Marg and how did Marg die?",a="Marg stole a jeweled pendant from Alliance soldiers camped near Theramore. A muckshell crab-man killed Marg on the way back to base.",al={"how did marg die","who is marg","marg story"}},{q="Where did the jeweled pendant come from?",a="An Alliance soldier wore the pendant at a beach camp near Theramore. It held more gems than a soldier could pay for, and Marg stole it that night.",al={"where did the pendant come from","who had the pendant","marg pendant origin"}},{q="Who receives the recovered pendant?",a="Nazeer Bloodpike receives the recovered pendant in Brackenwall Village.",al={"who gets the pendant","where do i take the pendant","nazeer bloodpike pendant"}},{q="What comes directly before this quest?",a="It follows The Troll Witchdoctor.",al={"previous quest","what quest comes before marg speaks"}}},kw={"bloodpike","brackenwall","marg","muckshell","nazeer","pendant","stormwind","theramore"},rel={"quest:1240","quest:1262","subzone:brackenwall-village","zone:dustwallow","topic:stormwind-kingdom","topic:horde","topic:alliance"},m={start="Bubbling Cauldron",["end"]="Nazeer Bloodpike",level="40",faction="Horde",id=1261},src={"Marg Speaks"}}
E["quest:185"] = {t="quest",n="Tiger Mastery",z="stranglethorn",s="At Nesingwary's Expedition, Ajeck Rouack trains hunters to track big cats. She begins with young tigers near the northern camp, testing a newcomer's hunting and tracking skills.",h="At Nesingwary's Expedition, Ajeck Rouack trains hunters to track big cats.",sec={{t="First Lessons in the Jungle",b="Ajeck Rouack learned to hunt tigers from her father when she was a girl. Now she shares his craft with travelers who reach Nesingwary's Expedition after Welcome to the Jungle. Young tigers are the first quarry. Tracking and hunting them prepare you to pursue greater prey.",sp=0},{t="Hunting the Prowlers",b="Young Stranglethorn tigers prowl the jungle near the expedition camp. Ajeck Rouack asks you to hunt ten. She wants proof of your skill before she offers further training.",sp=0}},faq={{q="Who offers to train you in tiger hunting?",a="Ajeck Rouack offers to train you in tiger hunting at Nesingwary's Expedition in northern Stranglethorn Vale.",al={"who gives tiger mastery","ajeck rouack quest","tiger quest giver"}},{q="Why does Ajeck Rouack target young tigers first?",a="Ajeck Rouack begins with young tigers because she considers them easier to track and hunt. They test your tracking skills before you pursue more dangerous quarry.",al={"why young tigers","why start easy tiger mastery"}},{q="Where are the young tigers found?",a="Young Stranglethorn tigers prowl the jungle near Nesingwary's Expedition camp.",al={"where are young stranglethorn tigers","young tiger location"}},{q="What comes before this hunt?",a="You arrive at the safari camp after Welcome to the Jungle, which introduces you to the camp.",al={"tiger mastery prerequisite","tiger mastery previous quest"}}},kw={"ajeck rouack","hunting","nesingwary","stranglethorn vale","tiger mastery","young stranglethorn tiger"},rel={"subzone:nesingwary-s-expedition","zone:stranglethorn"},m={start="Ajeck Rouack",["end"]="Ajeck Rouack",level="31",id=185},src={"Tiger Mastery (Classic)"}}
E["quest:186"] = {t="quest",n="Tiger Mastery",z="stranglethorn",s="At Nesingwary's Expedition in northern Stranglethorn Vale, Ajeck Rouack sends you to hunt mature tigers. After you defeat young stalkers, she sets you against ten mature Stranglethorn Tigers.",h="At Nesingwary's Expedition in northern Stranglethorn Vale, Ajeck Rouack sends you to hunt mature tigers.",sec={{t="Hunting the Mature Cats",b="Ajeck Rouack sends you to hunt ten mature Stranglethorn Tigers. Your success against younger predators has brought you to a harder test in the wilds of Stranglethorn Vale. Greater challenges lie beyond this hunt.",sp=0}},faq={{q="Who assigns this hunt?",a="Ajeck Rouack, a hunter at Nesingwary's Expedition in northern Stranglethorn Vale, assigns the hunt.",al={"who gives tiger mastery","ajeck rouack location","who gives this quest"}},{q="What beasts are you tasked with hunting?",a="You are sent to track and slay ten mature Stranglethorn Tigers in the surrounding jungle.",al={"what tigers do i kill","which cats","tiger mastery targets"}},{q="Where does this trial fit in the hunt?",a="This hunt follows your first Tiger Mastery trial and leads to a third stage under Ajeck Rouack's guidance.",al={"what comes before tiger mastery 2","what is next","tiger mastery chain"}}},kw={"ajeck rouack","nesingwary's expedition","stranglethorn tigers","stranglethorn vale","tiger mastery"},rel={"subzone:nesingwary-s-expedition","zone:stranglethorn"},m={start="Ajeck Rouack",["end"]="Ajeck Rouack",level="33",id=186},src={"Tiger Mastery (2)"}}
E["quest:187"] = {t="quest",n="Tiger Mastery",z="stranglethorn",s="At Nesingwary's Expedition, Ajeck Rouack sends you after ten elder Stranglethorn tigers. Their deaths will prove your skill before the final test.",h="At Nesingwary's Expedition, Ajeck Rouack sends you after ten elder Stranglethorn tigers.",sec={{t="A Test of Skill",b="Ajeck Rouack sends you into the wilds to hunt ten elder Stranglethorn tigers. He says they are the hardest cats to track and the fiercest to overcome. Their deaths prepare you for a final trial. After it, he promises to proclaim you a master tiger hunter before Master Nesingwary.",sp=0}},faq={{q="Who assigns this trial?",a="Ajeck Rouack assigns the trial at Nesingwary's Expedition camp in northern Stranglethorn Vale.",al={"who gives tiger mastery","ajeck rouack quest","quest giver"}},{q="What quarry are you tracking?",a="You are hunting ten elder Stranglethorn tigers.",al={"what do i kill","which tigers","tiger mastery targets"}},{q="Why are elder Stranglethorn tigers singled out?",a="Ajeck Rouack says elder Stranglethorn tigers are the hardest local cats to find and the most ferocious to defeat.",al={"why elder tigers","elder tiger difficulty"}},{q="What comes before this hunt?",a="This hunt follows the second stage of Ajeck Rouack's Tiger Mastery series.",al={"previous quest","prerequisite"}}},kw={"ajeck rouack","big game hunting","elder stranglethorn tiger","nesingwary","stranglethorn vale","tiger mastery"},rel={"subzone:nesingwary-s-expedition","zone:stranglethorn","topic:hunter"},m={start="Ajeck Rouack",["end"]="Ajeck Rouack",level="35",id=187},src={"Tiger Mastery (3)"}}
E["quest:188"] = {t="quest",n="Tiger Mastery",z="stranglethorn",s="At Nesingwary's Expedition, Ajeck Rouack sends you after a tiger his hunters have tracked for weeks. Sin'Dall waits in northern Stranglethorn Vale, and her paw will prove the hunt is done.",h="At Nesingwary's Expedition, Ajeck Rouack sends you after a tiger his hunters have tracked for weeks.",sec={{t="The Final Tiger",b="At Nesingwary's Expedition, Ajeck Rouack sends you on one last hunt after your earlier trials against Stranglethorn's tigers. His hunters have tracked Sin'Dall through the jungle for weeks. Find the elusive tiger, kill her, and bring back her paw as proof.",sp=0},{t="Master Tiger Hunter",b="When you return to Nesingwary's camp with Sin'Dall's paw, Ajeck Rouack recognizes your skill at tracking. He names you a true Master Tiger Hunter.",sp=1}},faq={{q="Who offers this hunt?",a="Ajeck Rouack, a seasoned hunter at Nesingwary's Expedition in northern Stranglethorn Vale, offers you this final hunt.",al={"quest giver","who gives tiger mastery","ajeck rouack location"}},{q="What is Sin'Dall?",a="Sin'Dall is an elusive tiger pursued through the jungles of Stranglethorn Vale by the hunters of Nesingwary's Expedition for weeks.",al={"what is sindall","sindall lore","who is sin dall"}},{q="What proof does Ajeck Rouack require?",a="Ajeck Rouack asks you to return with Sin'Dall's paw as proof that you bested the tiger.",al={"what do i bring back","tiger mastery proof","paw of sindall"}},{q="What precedes this hunt?",a="This hunt is the fourth and final step in Ajeck Rouack's series. It follows the third Tiger Mastery trial in northern Stranglethorn Vale.",al={"prerequisites","tiger mastery chain","previous quest"}}},kw={"ajeck rouack","master tiger hunter","nesingwary's expedition","paw of sin'dall","sin'dall","stranglethorn vale","tiger mastery"},rel={"subzone:nesingwary-s-expedition","zone:stranglethorn","topic:hunter"},m={start="Ajeck Rouack",["end"]="Ajeck Rouack",level="37",id=188,ri={"Paw of Sin'Dall"}},src={"Tiger Mastery (4)"}}
E["quest:189"] = {t="quest",n="Bloodscalp Ears",z="stranglethorn",s="In Booty Bay, Bloodscalp Ears bring Kebok a way to answer for mounting losses. He pays for proof of a kill after clashes with the Bloodscalp tribe have cost him guards and agents.",h="In Booty Bay, Bloodscalp Ears bring Kebok a way to answer for mounting losses.",sec={{t="Mounting Costs",b="In Stranglethorn Vale, Bloodscalp trolls are killing Kebok's agents and guards. Many of his best guards have fallen in jungle skirmishes. The mounting costs leave him anxious about explaining them to Baron Revilgaz.",sp=0},{t="A Bounded Bounty",b="Kebok offers coin to travelers who hunt Bloodscalp trolls in the jungle. He asks you to bring back fifteen severed ears as proof of the kills.",sp=0}},faq={{q="Who is Kebok?",a="Kebok is a goblin in Booty Bay whose agents and guards work in the jungle. He must answer to Baron Revilgaz for their costs.",al={"kebok","who is kebok","who gives bloodscalp ears"}},{q="Why does Kebok want Bloodscalp ears?",a="Bloodscalp trolls have killed Kebok's agents and many of his best guards in jungle skirmishes. The costs are mounting, and he must answer to Baron Revilgaz for them.",al={"why ears","why bloodscalp ears","why collect ears"}},{q="How many ears are required?",a="Kebok asks you to bring him fifteen Bloodscalp ears before he pays you.",al={"how many ears","ear count"}},{q="Where does this bounty lead next?",a="After Kebok pays you for the Bloodscalp ears, he turns to another local threat: Skullsplitter Tusks.",al={"what comes next","bloodscalp ears follow up","next quest"},sp=1}},kw={"bloodscalp","booty bay","ears","kebok","revilgaz","stranglethorn","troll"},rel={"subzone:booty-bay","npc:baron-revilgaz","topic:troll","quest:209","zone:stranglethorn"},m={start="Kebok",["end"]="Kebok",level="35",faction="Neutral",id=189},src={"Bloodscalp Ears","In-game quest text: Bloodscalp Ears"}}
E["quest:190"] = {t="quest",n="Panther Mastery",z="stranglethorn",s="At Nesingwary's Expedition, Sir S. J. Erlgadin tests those who seek a place in Hemet's hunt. They must bring down ten young panthers to prove their skill at tracking.",h="At Nesingwary's Expedition, Sir S.",sec={{t="A Crack Group of Hunters",b="Hemet Nesingwary has gathered seasoned big-game hunters in northern Stranglethorn Vale. Sir S. J. Erlgadin asks newcomers to prove they can hunt panthers before they join the party.",sp=0},{t="Tracking the Prowlers",b="Before trusting newcomers with larger game, Erlgadin sets them a test. They must find and slay ten young panthers. Finding the prowlers is only half the challenge.",sp=0}},faq={{q="Who gives this hunting challenge?",a="Sir S. J. Erlgadin gives the challenge at Nesingwary's Expedition camp in northern Stranglethorn Vale. He tests newcomers who hope to join Hemet's hunting party.",al={"panther mastery quest giver","who starts panther mastery","erlgadin quest"}},{q="What quarry must be hunted?",a="Hunters must track and slay ten young panthers in the surrounding jungle brush.",al={"what do i kill for panther mastery","panther mastery target","young panthers"}},{q="Why does Sir S. J. Erlgadin assign this test?",a="Hemet Nesingwary has gathered a seasoned hunting crew. Erlgadin asks newcomers to prove they can hunt panthers before joining the hunt.",al={"why kill young panthers","purpose of panther mastery"}},{q="What comes next after completing this hunt?",a="After this opening trial, Sir S. J. Erlgadin sets a harder hunt in Panther Mastery two.",al={"panther mastery next quest","what comes after panther mastery"}}},kw={"hemet","nesingwary","panther mastery","sir s. j. erlgadin","stranglethorn vale","young panthers"},rel={"subzone:nesingwary-s-expedition","zone:stranglethorn","topic:hunter"},m={start="Sir S. J. Erlgadin",["end"]="Sir S. J. Erlgadin",level="31",faction="Neutral",id=190},src={"Panther Mastery (Classic)"}}
E["quest:191"] = {t="quest",n="Panther Mastery",z="stranglethorn",s="At Nesingwary's Expedition, Sir S. J. Erlgadin asks you to prove your worth among the seasoned hunters. After your hunt for young panthers, he sends you into Stranglethorn Vale for ten fully grown beasts.",h="At Nesingwary's Expedition, Sir S.",sec={{t="A Higher Standard",b="Your hunt for young panthers is done, and Sir S. J. Erlgadin sets a higher standard. He asks you to prove you can keep company with the expedition's seasoned big game hunters. So you set out to track and slay ten mature panthers, stronger and more dangerous than their young kin.",sp=0}},faq={{q="Who offers this trial?",a="Sir S. J. Erlgadin, a hunter at Nesingwary's Expedition in northern Stranglethorn Vale, oversees this stage of the hunt.",al={"who gives panther mastery","erlgadin quest","quest giver"}},{q="What quarry are you asked to hunt?",a="You are asked to track and slay ten mature panthers in the surrounding jungle. They are tougher than the younger panthers you hunted before.",al={"what panthers to kill","which beasts","panther mastery target"}},{q="What comes before this challenge?",a="An earlier trial, also titled Panther Mastery, tested your skill against younger jungle panthers.",al={"previous quest","prior step","panther mastery prerequisite"}},{q="What is the purpose of hunting these panthers?",a="Sir S. J. Erlgadin asks you to prove your skill and courage so you can hunt and spend time alongside the expedition's seasoned big game hunters.",al={"why kill panthers","erlgadin motive","nesingwary purpose"}}},kw={"big game","erlgadin","hunting","mastery","nesingwary","panther","stranglethorn"},rel={"subzone:nesingwary-s-expedition","zone:stranglethorn","quest:208","topic:hunter"},m={start="Sir S. J. Erlgadin",["end"]="Sir S. J. Erlgadin",level="33",id=191},src={"Panther Mastery (2)"}}
E["quest:192"] = {t="quest",n="Panther Mastery",z="stranglethorn",s="In Stranglethorn Vale, Panther Mastery sends you after the deadliest panthers. After your earlier trials, ten Shadowmaw Panthers are your quarry.",h="In Stranglethorn Vale, Panther Mastery sends you after the deadliest panthers.",sec={{t="The Deadliest Quarry",b="Sir S. J. Erlgadin calls Shadowmaw Panthers the most dangerous cats in Stranglethorn's jungles. To prove yourself as a stalker, you crawl through dense underbrush and track ten elusive beasts. Their ferocity makes them harder to kill than to find.",sp=0}},faq={{q="Who offers this hunt?",a="Sir S. J. Erlgadin offers this hunt from the Nesingwary Expedition camp in northern Stranglethorn Vale.",al={"who gives panther mastery","panther mastery quest giver","who gives this quest"}},{q="What beasts are you hunting?",a="You hunt ten Shadowmaw Panthers, which Erlgadin calls the deadliest panthers in all of Stranglethorn.",al={"what do i kill","target of panther mastery","which panthers"}},{q="Where does this fit in the hunting trials?",a="This is the third panther hunting trial, after the second Panther Mastery trial and before the fourth.",al={"what quest comes before this","panther mastery chain","prerequisite quest"}}},ang={["class:Hunter"]="As a hunter, you face Erlgadin's challenge to your reputation as a big game hunter. He expects you to stalk and slay the jungle's fiercest predators."},kw={"big game","nesingwary","panther mastery","shadowmaw panther","sir s. j. erlgadin","stranglethorn vale"},rel={"subzone:nesingwary-s-expedition","zone:stranglethorn","topic:hunter"},m={start="Sir S. J. Erlgadin",["end"]="Sir S. J. Erlgadin",level="38",faction="Neutral",id=192},src={"Panther Mastery (3)"}}
E["quest:193"] = {t="quest",n="Panther Mastery",z="stranglethorn",s="At Nesingwary's Expedition, Sir S. J. Erlgadin sets one final trial for you. You have hunted panthers before, but the expedition's party has failed to find Bhag'thera. Bring back the predator's fang to prove your skill as a master of the hunt.",h="At Nesingwary's Expedition, Sir S.",sec={{t="The Elusive Prowler",b="At Nesingwary's Expedition, Sir S. J. Erlgadin sets one last test for you. Bhag'thera still prowls Stranglethorn Vale, beyond the expedition's party's reach. Track down the great panther and bring back its fang as proof of your skill.",sp=0}},faq={{q="Who offers this hunt?",a="Sir S. J. Erlgadin offers this hunt at Nesingwary's Expedition in northern Stranglethorn Vale.",al={"quest giver","who gives panther mastery","erlgadin quest"}},{q="What beast are you hunting?",a="You are hunting Bhag'thera, a great panther that prowls the jungle and has eluded the expedition's party.",al={"what is the target","who is bhag'thera","panther target"}},{q="What trophy is required?",a="Sir S. J. Erlgadin requires the Fang of Bhag'thera as proof that you defeated the beast.",al={"what proof","what item","bhag'thera trophy"}},{q="What came before this hunt?",a="This hunt follows the third trial in the Panther Mastery line and builds on your earlier panther hunts.",al={"previous quest","panther mastery prerequisite"}}},kw={"bhag'thera","fang of bhag'thera","nesingwary's expedition","panther mastery","sir s. j. erlgadin","stranglethorn vale"},rel={"subzone:nesingwary-s-expedition","zone:stranglethorn","topic:hunter"},m={start="Sir S. J. Erlgadin",["end"]="Sir S. J. Erlgadin",level="40",id=193,ri={"Fang of Bhag'thera"}},src={"Panther Mastery (4)"}}
E["quest:194"] = {t="quest",n="Raptor Mastery",z="stranglethorn",s="At his northern Stranglethorn camp, Hemet Nesingwary tests your hunting skill. He asks you to find and slay ten Stranglethorn Raptors.",h="At his northern Stranglethorn camp, Hemet Nesingwary tests your hunting skill.",sec={{t="A Test of Skill",b="After Welcome to the Jungle, Hemet Nesingwary tests your skill at tracking and hunting in the jungle. He gives you no map or directions. Finding the Stranglethorn Raptors is part of the trial, and you need to bring down ten of the fierce beasts.",sp=0}},faq={{q="Who gives this hunting challenge?",a="Hemet Nesingwary, the renowned big game hunter, gives the challenge at his expedition camp in northern Stranglethorn Vale.",al={"who gives raptor mastery","raptor mastery quest giver","hemet nesingwary raptors"}},{q="What beasts are you asked to track down?",a="You are asked to track down and slay ten Stranglethorn Raptors scattered through the jungle.",al={"which raptors","what do i kill for raptor mastery","target of raptor mastery"}},{q="Why does Hemet refuse to tell you where the raptors live?",a="Hemet believes finding your quarry is half the trial of becoming a true big game hunter. So he leaves the search to you.",al={"where are the raptors","why no raptor location","raptor locations"}},{q="What step comes before this trial?",a="This trial follows your first greeting in the wilderness, Welcome to the Jungle.",al={"prerequisite for raptor mastery","previous quest raptor mastery","raptor mastery chain start"}}},ang={["class:Hunter"]="As a hunter, you face Hemet Nesingwary's trials in the wild. There, you prove your tracking and marksmanship."},kw={"big game hunter","hemet nesingwary","raptor mastery","stranglethorn raptor","stranglethorn vale"},rel={"quest:5762","zone:stranglethorn","topic:hunter","quest:208"},m={start="Hemet Nesingwary",["end"]="Hemet Nesingwary",level="34",faction="Neutral",id=194},src={"Raptor Mastery (Classic)"}}
E["quest:195"] = {t="quest",n="Raptor Mastery",z="stranglethorn",s="In Stranglethorn Vale, Hemet Nesingwary sends hunters after deadlier quarry. After their first raptor hunt, he asks them to track and kill ten Lashtail Raptors.",h="In Stranglethorn Vale, Hemet Nesingwary sends hunters after deadlier quarry.",sec={{t="A Steeper Challenge",b="North of Grom'gol Base Camp, Hemet Nesingwary sends hunters into dense jungle brush. After their first raptor hunt, he expects them to prove their focus and skill with deadlier quarry. Ten fierce Lashtail Raptors must be tracked and killed.",sp=0},{t="Trophies for the Hearth",b="Hemet Nesingwary welcomes hunters back from the jungle with hearty approval. To the seasoned hunter, these dangerous predators are worthy quarry and trophies above the hearth. He readies the hunter for greater challenges.",sp=1}},faq={{q="Who offers this hunting challenge?",a="Hemet Nesingwary, the famed big game hunter, offers the challenge from his expedition camp in northern Stranglethorn Vale.",al={"who starts raptor mastery 2","raptor mastery quest giver","where to get raptor mastery"}},{q="What quarry are you tasked with hunting?",a="You must track and kill ten Lashtail Raptors in the jungle.",al={"what raptors to kill","which raptor quest","lashtail raptor target"}},{q="Where are the Lashtail Raptors found?",a="Lashtail Raptors roam the wild foliage of northern Stranglethorn Vale, especially north of Grom'gol Base Camp.",al={"where are lashtail raptors","lashtail raptor location","where to find lashtails"}},{q="Where does this hunt fit into Nesingwary's trials?",a="This is the second trial in Nesingwary's raptor series. It follows the introductory Raptor Mastery hunt and leads to a third part of the challenge.",al={"what comes before this raptor hunt","raptor mastery progression","raptor quest chain"}}},ang={["class:Hunter"]="As a hunter, you test your discipline against the deadlier predators roaming Stranglethorn Vale in Hemet Nesingwary's trials."},kw={"grom'gol base camp","hemet nesingwary","hunting","lashtail raptor","raptor mastery","stranglethorn vale"},rel={"quest:5762","zone:stranglethorn","subzone:grom-gol-base-camp","topic:hunter"},m={start="Hemet Nesingwary",["end"]="Hemet Nesingwary",level="36",id=195},src={"Raptor Mastery (2)"}}
E["quest:196"] = {t="quest",n="Raptor Mastery",z="stranglethorn",s="In Stranglethorn Vale, Hemet Nesingwary sends you after Jungle Stalkers. Ten wary raptors stand between you and his finest hunt.",h="In Stranglethorn Vale, Hemet Nesingwary sends you after Jungle Stalkers.",sec={{t="A Cagey Quarry",b="Hemet Nesingwary sends you after Jungle Stalkers, a harder quarry than the raptors you hunted before. They are wary and hard to track or kill. Find and fell ten in the jungle, then return to camp. Hemet will give you a lead on his finest hunt yet.",sp=0}},faq={{q="Who offers this hunt?",a="Hemet Nesingwary, the big game hunter, offers this hunt from his camp in northern Stranglethorn Vale.",al={"quest giver","who starts raptor mastery 3","hemet nesingwary hunt"}},{q="What beast are you asked to track down?",a="You are asked to track and kill ten Jungle Stalkers, a wary and elusive kind of raptor.",al={"what raptor","target raptor","which raptors to kill"}},{q="Where are Jungle Stalkers found?",a="Jungle Stalkers roam Stranglethorn Vale, especially north and west of the Gurubashi Arena.",al={"jungle stalker location","where do jungle stalkers roam","find jungle stalkers"}},{q="What comes before this challenge?",a="This hunt follows the second stage of the Raptor Mastery trials, as Hemet Nesingwary continues through the local raptor breeds.",al={"prerequisite quest","previous raptor mastery","what quest comes before"}}},ang={["class:Hunter"]="As a hunter, tracking wary Jungle Stalkers tests your skill with prey and your marksmanship in the wilderness under Hemet Nesingwary's watch."},kw={"big game hunter","gurubashi arena","hemet nesingwary","jungle stalkers","raptor mastery","stranglethorn vale"},rel={"quest:5762","subzone:gurubashi-arena","zone:stranglethorn","topic:hunter","quest:208"},m={start="Hemet Nesingwary",["end"]="Hemet Nesingwary",level="41",id=196},src={"Raptor Mastery (3)"}}
E["quest:197"] = {t="quest",n="Raptor Mastery",z="stranglethorn",s="In Stranglethorn Vale, Hemet Nesingwary sends you after the raptor that has eluded even him. After your trials against lesser beasts, you are to track Tethis and bring its talon back to Hemet.",h="In Stranglethorn Vale, Hemet Nesingwary sends you after the raptor that has eluded even him.",sec={{t="The Wily Predator of the Vale",b="Hemet Nesingwary tells you of Tethis, a vicious raptor that has escaped every hunter, even the expedition leader. Ajeck Rouack gave the beast its name. Among Stranglethorn's raptors, Tethis is the greatest challenge for a hunter.",sp=0},{t="Claiming the Talon",b="Tethis roams north of the Gurubashi Arena. Bring Hemet a talon from the slain raptor, and he will recognize you as a master raptor slayer. No other big game hunter has achieved that feat.",sp=0}},faq={{q="Who sends you to hunt Tethis?",a="Hemet Nesingwary sends you to hunt Tethis from his expedition encampment in northern Stranglethorn Vale, after you prove your tracking skill against ordinary jungle raptors.",al={"who gives raptor mastery","raptor mastery questgiver","who wants tethis dead"}},{q="Where can Tethis be found?",a="Tethis prowls the jungle around the Gurubashi Arena, most often in the brush north of the colosseum.",al={"tethis location","where is tethis","where to find tethis"}},{q="What proof does Hemet require of the kill?",a="Hemet requires Tethis's talon as proof that you have brought the raptor down.",al={"what do i bring hemet","tethis proof","raptor mastery turn in item"}},{q="Who originally named the raptor Tethis?",a="Ajeck Rouack, one of the hunters at Nesingwary's expedition camp, gave the raptor the name Tethis.",al={"who named tethis","origin of tethis name"}}},kw={"ajeck rouack","gurubashi arena","hemet nesingwary","raptor mastery","stranglethorn vale","talon of tethis","tethis"},rel={"quest:208","subzone:gurubashi-arena","zone:stranglethorn","topic:hunter","quest:5762"},m={start="Hemet Nesingwary",["end"]="Hemet Nesingwary",level="43",id=197,ri={"Talon of Tethis"}},src={"Raptor Mastery (4)"}}
E["quest:198"] = {t="quest",n="Supplies to Private Thorsen",z="stranglethorn",s="Krazek needs a courier in Booty Bay to carry supplies north to Private Thorsen. Troll attacks have stopped the regular shipments to Lieutenant Doren's camp near the northern border.",h="Krazek needs a courier in Booty Bay to carry supplies north to Private Thorsen.",sec={{t="A Route Disrupted",b="Lieutenant Doren's men guard the border between Stranglethorn Vale and Duskwood. Krazek arranges regular shipments for them, but local trolls keep attacking. The usual deliveries have become dangerous, so the goblin merchant hires you to carry a package north along the jungle road. Private Thorsen can receive it at the camp northwest of the road or along his patrol route to the south.",sp=0},{t="The Shipment's True Contents",b="Private Thorsen's shipment holds land mines, though its listing calls them miscellaneous goblin supplies. He says the explosives will help defend the post against Colonel Kurzen and his men.",sp=1}},faq={{q="Who is sending these supplies?",a="Krazek, a goblin merchant doing business in Booty Bay, arranges and provides the supplies.",al={"who gives supplies to thorsen","krazek delivery","who starts supplies to private thorsen"}},{q="Why have the supplies been delayed?",a="Local troll attacks in Stranglethorn Vale have disrupted regular deliveries, leaving Lieutenant Doren's men waiting for their scheduled goods.",al={"why delayed","troll attacks delivery","why wasn't it delivered"}},{q="Where can Private Thorsen be found?",a="Private Thorsen can be found at Lieutenant Doren's camp, northwest of the main road near the entrance to Stranglethorn from Duskwood. He also patrols the path just south of the camp.",al={"where is thorsen","thorsen location","find private thorsen"}},{q="What happens if the supplies are lost?",a="Krazek warns that anyone who fails to deliver the shipment will be held financially responsible and owe him restitution.",al={"what if i lose supplies","krazek restitution","failing krazek"}}},ang={["faction:Alliance"]="As an Alliance soldier, you guard the northern entrance from Duskwood into Stranglethorn Vale with Lieutenant Doren's men. You rely on goblin supplies to hold your position."},kw={"booty bay","duskwood","goblin supplies","krazek","kurzen","lieutenant doren","private thorsen","stranglethorn vale"},rel={"npc:doren","topic:goblin","zone:stranglethorn","zone:duskwood","topic:troll"},m={start="Krazek",["end"]="Private Thorsen",level="32",faction="Alliance",id=198},src={"Supplies to Private Thorsen"}}
E["quest:200"] = {t="quest",n="Bookie Herod",z="stranglethorn",s="A leak has Lieutenant Doren searching his ranks for a traitor. Kurzen has learned Thorsen's secret, and Doren wants the records of Bookie Herod, Kurzen's logistics officer, from Kurzen's Compound.",h="A leak has Lieutenant Doren searching his ranks for a traitor.",sec={{t="A Leak in the Ranks",b="Lieutenant Doren suspects a traitor among his men. Kurzen learned Thorsen's secret, and the leak threatens their operations. So Doren needs to find its source. Thorsen kept a line into Kurzen's Compound through Bookie Herod, the colonel's logistics officer. Herod's written records may show how the operation was exposed.",sp=0},{t="The Logistics Office",b="Bookie Herod's papers are inside Kurzen's Compound. When Doren served under Kurzen, Herod's office was on the top floor of the compound's only two-story house. Supply requisitions and messages from Colonel Kurzen may reveal how Thorsen's secret was betrayed.",sp=0}},faq={{q="Who is Bookie Herod?",a="Bookie Herod is the logistics officer for Colonel Kurzen's men. He oversees supplies and camp operations at Kurzen's Compound. He once served as Thorsen's inside contact.",al={"herod role","who is the bookie","bookie herod lore"}},{q="Why does Lieutenant Doren want Herod's records?",a="Lieutenant Doren suspects a spy betrayed their camp after Colonel Kurzen learned Thorsen's secret. He hopes Herod's logistics logs and correspondence will show how the information leaked.",al={"why get herod records","doren spy","how was thorsen caught"}},{q="Where are Bookie Herod's records located?",a="Herod's office is on the top floor of the only two-story house inside Kurzen's Compound. Doren believes his records are probably still there.",al={"where are the records","herod office location","two story house kurzen"}},{q="What comes before this investigation?",a="The investigation follows Jungle Secrets. There, Lieutenant Doren concludes that someone must have betrayed Thorsen's secret to Kurzen's men.",al={"prior quest","bookie herod prerequisite"}}},ang={["faction:Alliance"]="Lieutenant Doren and his men once served under Colonel Kurzen before breaking away. Now they search their own ranks for a spy."},kw={"bookie herod","colonel kurzen","kurzen's compound","lieutenant doren","stranglethorn vale","thorsen"},rel={"quest:215","quest:328","subzone:kurzen-s-compound","npc:colonel-kurzen","zone:stranglethorn"},m={start="Lieutenant Doren",["end"]="Bookie Herod's Records",level="35",faction="Alliance",id=200},src={"Bookie Herod (quest)"}}
E["quest:201"] = {t="quest",n="Investigate the Camp",z="stranglethorn",s="Krazek has heard Hemet Nesingwary may be in Stranglethorn Vale. He asks you to find the hunters' camp near Lake Nazferiti and confirm the report.",h="Krazek has heard Hemet Nesingwary may be in Stranglethorn Vale.",sec={{t="Reports in the Jungle",b="Booty Bay reports place a hunters' camp in northern Stranglethorn Vale. Krazek has heard it lies along the river, just beyond the Venture Company's mining claim near Lake Nazferiti. The jungle is lawless, with dangers and competing interests. An armed camp draws notice.",sp=0},{t="A Renowned Marksman",b="Hemet Nesingwary may be among the hunters at the camp. The renowned dwarven marksman is known across the lands as an elite explorer with influential ties. Krazek sends you upriver to learn whether the legendary hunter has arrived.",sp=0}},faq={{q="Who gives the task to investigate the camp?",a="Krazek, an operative in Booty Bay, sends you to find the camp and report where it lies.",al={"who wants camp investigated","who gave this quest","krazek booty bay"}},{q="Who is Hemet Nesingwary?",a="Hemet Nesingwary is a renowned dwarven big-game hunter and explorer. Reports in Booty Bay place him among hunters camping near Lake Nazferiti, and his reputation and connections have drawn interest.",al={"hemet nesingwary stranglethorn","who is hemet nesingwary","famous dwarf hunter stranglethorn"}},{q="Where is the hunters' camp located?",a="The hunters' camp lies upriver from the Venture Company's mining operations, along Lake Nazferiti in northern Stranglethorn Vale.",al={"hunters camp location","where is nesingwary camp","where is the camp upriver"}},{q="Why is Krazek interested in this hunting camp?",a="Reports say Hemet Nesingwary may be at the camp. His influence and connections make Krazek cautious and curious.",al={"why does krazek care","why investigate hunters","krazek motive"}},{q="What is the hunters' relationship to the Venture Company?",a="The hunters are separate from the Venture Company. Their camp lies upriver from the company's mining outfit near Lake Nazferiti, which marks its location.",al={"venture company connection","are hunters with venture co","venture co lake nazferiti"}},{q="To whom do you report after finding the camp?",a="After you find and scout the riverside camp, return south to Booty Bay and report directly to Krazek.",al={"what do you do after finding camp","who to report to","where to turn in investigate camp"}}},ang={["class:Hunter"]="As a hunter, you may be drawn to the rumored gathering led by Hemet Nesingwary. There, you can test your tracking and marksmanship in the jungle.",["race:Dwarf"]="As a dwarf, you may take pride in Hemet Nesingwary, one of the most famous dwarven marksmen and adventurers. His reported presence in Stranglethorn Vale's distant southern wilds may stir your curiosity."},kw={"booty bay","hemet nesingwary","hunters camp","investigate the camp","krazek","lake nazferiti","stranglethorn vale","venture company"},rel={"quest:5762","subzone:lake-nazferiti","subzone:booty-bay","topic:venture-company","topic:hunter"},m={id=201},src={"In-game quest text: Investigate the Camp"},fv=true}
E["quest:202"] = {t="quest",n="Colonel Kurzen",z="stranglethorn",s="At the Rebel Camp, Lieutenant Doren sends you against Colonel Kurzen and his inner guard. Their defeat could secure the rebels' survival.",h="At the Rebel Camp, Lieutenant Doren sends you against Colonel Kurzen and his inner guard.",sec={{t="The Heart of the Stockpile",b="Lieutenant Doren's defectors have reached the final struggle against their former commander. You have helped suppress Kurzen's elite specialists, but the rebels remain in danger while he holds his jungle redoubt. Doren sends you into the Stockpile cave, where Kurzen directs his forces beside his subchiefs and elites.",sp=0},{t="Striking the Serpent's Head",b="Lieutenant Doren needs proof that Kurzen has fallen. He asks you to bring back the rogue colonel's head and defeat his elites and subchiefs. The cave confrontation gives the rebels their only chance to breathe easier amid the dangers of northern Stranglethorn.",sp=0}},faq={{q="Who assigns this task?",a="After you complete Special Forces, Lieutenant Doren sends you from the Rebel Camp in northern Stranglethorn Vale.",al={"who gives the quest","quest giver","where to pick up colonel kurzen"}},{q="Where is Colonel Kurzen located?",a="Kurzen directs his troops deep within the Stockpile cave system, inside the Kurzen compound in northern Stranglethorn Vale.",al={"where is kurzen","kurzen location","how to find colonel kurzen"}},{q="What proof does Lieutenant Doren require?",a="Lieutenant Doren asks you to bring back Kurzen's head as proof that the rogue commander has fallen, and to defeat his elites and subchiefs.",al={"what proof is needed","kurzen proof","turn in item"}},{q="What came before this confrontation?",a="In Special Forces, you weakened Kurzen's specialized battlefield operatives. Then you turned toward his core command structure.",al={"prerequisite quest","what is previous quest","chain before kurzen"}}},ang={["faction:Alliance"]="As an Alliance member, you can help break a rogue Stormwind officer's grip on the northern reaches of Stranglethorn Vale by eliminating Kurzen."},kw={"colonel kurzen","kurzen","lieutenant doren","rebel camp","stockpile","stranglethorn vale"},rel={"quest:574","subzone:rebel-camp","npc:doren","zone:stranglethorn"},m={start="Lieutenant Doren",["end"]="Lieutenant Doren",level="40",faction="Alliance",id=202,ri={"Kurzen's Head"}},src={"Colonel Kurzen (quest)"}}
E["quest:203"] = {t="quest",n="The Second Rebellion",z="stranglethorn",s="At the Rebel Camp in northern Stranglethorn Vale, Sergeant Yohwa calls for aid against Colonel Kurzen's overwhelming force. Outnumbered ten to one, the rebels cannot fight a long, open war. They strike swiftly and in secret, hoping to thin Kurzen's ranks and ease the pressure on their refuge.",h="At the Rebel Camp in northern Stranglethorn Vale, Sergeant Yohwa calls for aid against Colonel Kurzen's...",sec={{t="A Losing Battle",b="At the Rebel Camp, the rebels face Colonel Kurzen's force with at least ten foes for every one of their own. Sergeant Yohwa knows the Colonel is a brilliant military tactician. An open war of attrition would leave the rebels with no chance.\n\nSo they turn Kurzen's covert methods against him. They strike quickly at his encampment, then flee before heavy reinforcements can answer.",sp=0},{t="Striking the Compound",b="Sergeant Yohwa asks you to head east into Kurzen's stronghold and eliminate a sizable contingent of his jungle fighters. Their numbers press hard on the Rebel Camp. Thin their ranks, and the refuge can breathe easier.",sp=0}},faq={{q="Who is Sergeant Yohwa?",a="Sergeant Yohwa is an officer at the Rebel Camp in northern Stranglethorn Vale. She coordinates covert strikes against Colonel Kurzen's host.",al={"yohwa","who gives the second rebellion","sergeant yohwa"}},{q="Where is Colonel Kurzen's camp located?",a="Colonel Kurzen's compound lies east of the Rebel Camp, amid the dense wilderness of northern Stranglethorn Vale.",al={"kurzen camp location","where are the jungle fighters","kurzen location"}},{q="Why are the rebels using covert tactics instead of open war?",a="The rebels face at least ten of Colonel Kurzen's fighters for every one of their own. Against a brilliant military strategist, an open assault is impossible, so they depend on swift guerrilla strikes.",al={"why covert","why not fight kurzen openly","rebel tactics"}},{q="What comes after The Second Rebellion?",a="After you cut down Kurzen's jungle fighters, Sergeant Yohwa offers the next step, Special Forces.",al={"next quest","what is after the second rebellion","follow up to the second rebellion"}}},kw={"colonel kurzen","jungle fighter","kurzen","rebel camp","sergeant yohwa","special forces","stranglethorn vale","yohwa"},rel={"subzone:rebel-camp","npc:colonel-kurzen","quest:574","zone:stranglethorn"},m={start="Sergeant Yohwa",["end"]="Sergeant Yohwa",level="33",faction="Alliance",id=203},src={"The Second Rebellion"}}
E["quest:204"] = {t="quest",n="Bad Medicine",z="stranglethorn",s="At the Rebel Camp in northern Stranglethorn Vale, Sergeant Yohwa seeks a way to weaken Colonel Kurzen's force. His medicine men heal his soldiers and poison Yohwa's fighters, and the resistance needs their remedies and toxins.",h="At the Rebel Camp in northern Stranglethorn Vale, Sergeant Yohwa seeks a way to weaken Colonel Kurzen's force.",sec={{t="Stripping the Compound's Support",b="Colonel Kurzen's medicine men heal his soldiers and poison Yohwa's fighters with venom fern extract. Sergeant Yohwa asks you to gather their supplies from the Kurzen Compound. The remedies can treat wounded fighters at the Rebel Camp. A sample of venom fern extract will let the resistance study the toxin and make cures of its own.",sp=0}},faq={{q="Who offers this assignment?",a="At the Rebel Camp in northern Stranglethorn Vale, Sergeant Yohwa asks you to recover the medical supplies.",al={"who gives bad medicine","bad medicine quest giver","yohwa quest"}},{q="Why does Sergeant Yohwa want Jungle Remedies?",a="Kurzen's medicine men use Jungle Remedies to heal their soldiers. The resistance needs the remedies to treat its wounded fighters.",al={"why need jungle remedies","jungle remedy purpose"}},{q="What is the Venom Fern Extract used for?",a="Kurzen's forces use venom fern extract to poison Yohwa's fighters. Yohwa needs a sample so the camp can study the toxin and make remedies against it.",al={"why venom fern extract","extract use"}},{q="Where are these medical supplies kept?",a="The supplies are inside the Kurzen Compound. Medicine men carry the remedies, while supply boxes around the encampment hold the venom fern extracts.",al={"where to find jungle remedies","extract location"}}},ang={["faction:Alliance"]="For the Alliance, cutting off Kurzen's healing support can help keep more Rebel Camp fighters alive against his force."},kw={"jungle remedy","kurzen","kurzen compound","medicine men","rebel camp","sergeant yohwa","stranglethorn","venom fern extract"},rel={"subzone:rebel-camp","zone:stranglethorn"},m={start="Sergeant Yohwa",["end"]="Sergeant Yohwa",level="34",faction="Alliance",id=204,ri={"Jungle Remedy","Venom Fern Extract"}},src={"Bad Medicine (Classic)"}}
E["quest:205"] = {t="quest",n="Troll Witchery",z="stranglethorn",s="Brother Nimetz sends you into Skullsplitter territory to learn what has corrupted Colonel Kurzen. After Kurzen's Mystery, he asks you to gather fetishes from the tribe's spellcasters.",h="Brother Nimetz sends you into Skullsplitter territory to learn what has corrupted Colonel Kurzen.",sec={{t="Unraveling the Corruption",b="Brother Nimetz suspects dark troll magic lies behind Colonel Kurzen's fall into evil. Legends recovered from the jungle have led him to the second troll tribe farther south. So he asks you to enter Skullsplitter lands and take fetishes from their Witch Doctors and Mystics. He will study the magic they carry at the Rebel Camp.",sp=0}},faq={{q="Who gives the quest Troll Witchery?",a="Brother Nimetz gives Troll Witchery at the Rebel Camp in northern Stranglethorn Vale.",al={"troll witchery quest giver","who starts troll witchery","where to get troll witchery"}},{q="Why does Brother Nimetz want Skullsplitter fetishes?",a="Brother Nimetz wants to study the dark magical implements and learn whether troll witchcraft explains Colonel Kurzen's fall into evil.",al={"why brother nimetz needs fetishes","purpose of troll witchery","kurzen corruption fetishes"}},{q="Which enemies carry the fetishes?",a="Skullsplitter Witch Doctors and Skullsplitter Mystics carry fetishes in Skullsplitter territory.",al={"who drops skullsplitter fetishes","which trolls have fetishes","troll witchery fetish source"}},{q="What quest precedes Troll Witchery?",a="Troll Witchery follows Kurzen's Mystery and continues Brother Nimetz's investigation into the colonel's madness.",al={"troll witchery chain","what comes before troll witchery","prerequisite for troll witchery"}}},ang={["faction:Alliance"]="As an Alliance traveler, you can help Brother Nimetz at the Rebel Camp uncover what corrupted Colonel Kurzen."},kw={"brother nimetz","colonel kurzen","mystic","rebel camp","skullsplitter","stranglethorn vale","troll witchery","witch doctor"},rel={"subzone:rebel-camp","npc:colonel-kurzen","topic:troll","zone:stranglethorn","subzone:balia-mah-ruins","subzone:ruins-of-zul-mamwe","topic:alliance"},m={start="Brother Nimetz",level="40",faction="Alliance",id=205,ri={"Skullsplitter Fetish"}},src={"Troll Witchery"}}
E["quest:206"] = {t="quest",n="Mai'Zoth",z="stranglethorn",s="In the eastern mountains of Stranglethorn Vale, Mai'Zoth keeps a relic said to twist minds. Brother Nimetz believes the ogre mage corrupted Colonel Kurzen and wants the relic recovered before another commander suffers the same fate.",h="In the eastern mountains of Stranglethorn Vale, Mai'Zoth keeps a relic said to twist minds.",sec={{t="The Source of Corruption",b="Brother Nimetz believes the power behind Kurzen's rebellion remains. His research points to Mai'Zoth, an ogre mage who lives in an ogre mound in the eastern heights of Stranglethorn Vale. Nimetz says Mai'Zoth used sorcery to warp Kurzen's thoughts. While Mai'Zoth lives, another commander could suffer the same corruption.",sp=0},{t="Securing the Relic",b="Brother Nimetz asks you to slay Mai'Zoth and take the Mind's Eye from him. Bring the artifact to the Rebel Camp.",sp=0},{t="After the Delivery",b="Brother Nimetz blesses whoever brings him the Mind's Eye. He plans to study its power and learn whether it can serve good. If it cannot, he says it must be destroyed.",sp=1}},faq={{q="Who is Mai'Zoth?",a="Mai'Zoth is an ogre mage who lives in an ogre mound in the eastern mountains of Stranglethorn Vale. Brother Nimetz believes Mai'Zoth's sorcery corrupted Colonel Kurzen's mind.",al={"who is maizoth","maizoth lore","ogre mage maizoth"}},{q="What is the Mind's Eye?",a="Mai'Zoth holds the Mind's Eye, an artifact reputed to wield magic that controls minds. He uses it to corrupt and influence others.",al={"minds eye lore","what is the artifact","mind's eye"}},{q="Why does Brother Nimetz want Mai'Zoth slain?",a="Brother Nimetz fears Mai'Zoth's corruption could turn someone else into another Kurzen, so he wants the ogre slain.",al={"nimetz motive","why kill maizoth","reason for hunting maizoth"}}},ang={["faction:Alliance"]="Brother Nimetz works from the Rebel Camp in northern Stranglethorn Vale. He seeks Alliance champions to end the hidden evil that corrupted Kurzen."},kw={"brother nimetz","kurzen","mai'zoth","maizoth","mind's eye","ogre mound","rebel camp","stranglethorn"},rel={"subzone:rebel-camp","quest:591","zone:stranglethorn"},m={start="Brother Nimetz",["end"]="Brother Nimetz",level="46",faction="Alliance",id=206,ri={"Mind's Eye"}},src={"Mai'Zoth (quest)"}}
E["quest:207"] = {t="quest",n="Kurzen's Mystery",z="stranglethorn",s="At the Rebel Camp, Brother Nimetz seeks the reason for Colonel Kurzen’s fall. He suspects troll magic and sends you to copy legends from four tablets in Stranglethorn’s troll ruins.",h="At the Rebel Camp, Brother Nimetz seeks the reason for Colonel Kurzen’s fall.",sec={{t="Searching for Answers",b="Brother Nimetz at the Rebel Camp seeks the cause of Colonel Kurzen’s fall from greatness into depravity. He suspects troll magic has taken hold of the colonel. Legends carved on four old tablets may test that suspicion. You are asked to copy each tablet’s markings and carry them back to camp.",sp=0},{t="Where the Tablets Lie",b="One tablet stands in the Bal'lal Ruins. Another lies deep underwater in the Vile Reef, off the coast near a sunken city held by Saltscale murlocs. The last two tablets are in the Ruins of Zul'Kunda.",sp=0}},faq={{q="Who starts the search for the troll tablets?",a="Brother Nimetz begins the search at the Rebel Camp.",al={"who gives kurzens mystery","where do i start kurzens mystery","brother nimetz quest"}},{q="Why does Brother Nimetz want copies of troll legends?",a="Brother Nimetz seeks to learn why Colonel Kurzen, once a great and noble man, sank into depravity. He suspects troll magic, and the tablet legends may confirm it.",al={"why need troll tablets","kurzens mystery purpose","why nimetz wants legends"}},{q="Where are the four troll tablets located?",a="One tablet is in the Bal'lal Ruins. Another lies deep underwater in the Vile Reef, west of Grom'gol. The remaining two are in the Ruins of Zul'Kunda.",al={"tablet locations","where are the tablets","kurzen tablets map"}},{q="What comes after the four tablets are brought back?",a="Brother Nimetz studies the legends for a link between the trolls and Colonel Kurzen’s fall. The tale continues with Troll Witchery.",al={"what next after kurzens mystery","kurzens mystery follow up","quest chain after tablets"}}},kw={"bal'lal ruins","brother nimetz","colonel kurzen","rebel camp","stranglethorn vale","troll legend","vile reef","zul'kunda"},rel={"quest:205","subzone:rebel-camp","npc:colonel-kurzen","subzone:bal-lal-ruins","subzone:vile-reef","zone:stranglethorn","topic:alliance","topic:troll"},m={start="Brother Nimetz",level="38",faction="Alliance",id=207,ri={"The First Troll Legend","The Fourth Troll Legend","The Second Troll Legend","The Third Troll Legend"}},src={"Kurzen's Mystery"}}
E["quest:208"] = {t="quest",n="Big Game Hunter",z="stranglethorn",s="In Stranglethorn Vale, Hemet Nesingwary’s hunt for King Bangalash reaches its last trial. The famed marksman came to the jungle for the great white tiger.",h="In Stranglethorn Vale, Hemet Nesingwary’s hunt for King Bangalash reaches its last trial.",sec={{t="The Master's Quarry",b="You have slain Sin'Dall, Bhag'thera, and Tethis in the trials set by the expedition's huntsmen. Hemet Nesingwary now knows your skill with weapons. Few have shown him finer skill on Lordaeron's battlefields or deep in the jungle.\n\nOne hunt remains. Bring down King Bangalash, the great white tiger Hemet came to hunt, and prove your abilities unmatched.",sp=0},{t="A Storied Beast",b="King Bangalash drew Hemet Nesingwary to Stranglethorn Vale. The great beast has driven the expedition leader back to camp in defeat time and again. Its head would prove your hunting skill second to none.",sp=0}},faq={{q="Who gives this hunt?",a="Hemet Nesingwary gives this hunt at his expedition encampment in northern Stranglethorn Vale, after you finish the earlier hunting masteries.",al={"quest giver","who starts big game hunter","hemet nesingwary quest"}},{q="What prerequisite hunts must be finished first?",a="First, finish all three hunts for the camp. Slay Sin'Dall in Tiger Mastery, Bhag'thera in Panther Mastery, and Tethis in Raptor Mastery.",al={"prerequisites","what quests come before big game hunter","bangalash requirements"}},{q="Why does Hemet Nesingwary want King Bangalash?",a="King Bangalash drew Hemet to Stranglethorn Vale. The great white tiger has eluded him repeatedly and driven the veteran marksman back to camp more than once.",al={"why king bangalash","why hunt bangalash","bangalash lore"}},{q="What proof does Hemet require?",a="Hemet requires King Bangalash's head as proof that you have slain the great white tiger.",al={"what item do i need","bangalash objective","proof of kill"}},{q="Where does Hemet say he has seen combat before?",a="Hemet compares your skill with weapons to what he has seen on Lordaeron's battlefields and deep in the jungle. He says he has rarely seen better.",al={"hemet war history","hemet past","lordaeron hunter"}}},ang={["class:Hunter"]="As a hunter, bringing down King Bangalash proves your mastery of tracking and the hunt to Hemet Nesingwary."},kw={"bangalash","bhag'thera","big game hunter","hemet nesingwary","sin'dall","stranglethorn vale","tethis","white tiger"},rel={"quest:5762","zone:stranglethorn","topic:lordaeron","topic:hunter"},m={start="Hemet Nesingwary",["end"]="Hemet Nesingwary",level="43",faction="Neutral",id=208,ri={"Head of Bangalash"}},src={"Big Game Hunter (Classic)"}}
E["quest:209"] = {t="quest",n="Skullsplitter Tusks",z="stranglethorn",s="In Booty Bay, Kebok struggles to fill orders for tiger fangs bound for the South Seas. Real fangs cost too much to supply, so he has found another way to meet demand.",h="In Booty Bay, Kebok struggles to fill orders for tiger fangs bound for the South Seas.",sec={{t="A Lucrative Substitute",b="Kebok’s trade in tiger fangs for buyers across the South Seas has grown costly and hard to supply through ordinary hunting. So he has found a way to shape horn-like objects into convincing fangs without leaving a sign of the trick. Skullsplitter troll tusks make the closest match. Kebok hires adventurers to take eighteen from the jungle tribe for his next shipment.",sp=0}},faq={{q="Why does Kebok need Skullsplitter tusks?",a="Hunting enough real tigers for South Seas buyers has grown too costly and difficult. Kebok can shape troll tusks into convincing tiger fangs without leaving a trace, keeping his monthly export orders supplied.",al={"why skullsplitter tusks","kebok tusk plan","why fake tiger fangs"}},{q="Who is buying the fangs?",a="Trading partners on islands throughout the South Seas buy the counterfeit fangs.",al={"who buys the tusks","south seas buyers","where do the fangs go"}},{q="Where does this task fall in Kebok's chain?",a="This follows Kebok’s earlier request for Bloodscalp Ears.",al={"what comes before skullsplitter tusks","skullsplitter tusks prerequisite","kebok quest order"}}},kw={"booty bay","forgery","kebok","skullsplitter","south seas","stranglethorn","tiger fangs","tusks"},rel={"quest:189","zone:stranglethorn","topic:troll","subzone:south-seas"},m={start="Kebok",["end"]="Kebok",level="42",faction="Neutral",id=209,ri={"Skullsplitter Tusk"}},src={"Skullsplitter Tusks"}}
E["quest:210"] = {t="quest",n="Krazek's Cookery",z="stranglethorn",s="In Booty Bay, Corporal Kaleb has a broken pot to get mended. He asks you to carry the mechanical cooker he bought from a goblin trader to Krazek.",h="In Booty Bay, Corporal Kaleb has a broken pot to get mended.",sec={{t="A Broken Pot",b="Corporal Kaleb handles most of the camp's cooking. Before he bought a mechanical pot from a goblin trader in Booty Bay, cooking took hours. The pot spared him that work until it broke. Now he asks you to carry Krazek's Crock Pot to Krazek, the goblin who can repair it.",sp=0},{t="Krazek Takes a Look",b="Krazek calls the pot ingenious work, though a spring can pop or a gear can slip. On inspection, he finds the steam charger rusted out, the knuckle-gasket cracked and the fobulator missing teeth. Krazek can mend it, but the repairs come at a price.",sp=1}},faq={{q="Who sends you to Krazek?",a="Corporal Kaleb sends you to Krazek. Kaleb handles most of the camp's cooking, and the mechanical pot he bought has broken down.",al={"who gives krazek's cookery","who starts krazek cookery","corporal kaleb quest"}},{q="Where can Krazek be found?",a="Krazek is a goblin trader in Booty Bay, where he sold the pot to Kaleb.",al={"where is krazek","krazek location","krazek booty bay"}},{q="What does Corporal Kaleb want carried to Krazek?",a="Kaleb asks you to carry Krazek's Crock Pot, a mechanical cooking pot that broke after saving him many hours of work.",al={"what is krazek's crock pot","what do i bring krazek"}},{q="Why did Kaleb buy a cooking pot from Krazek?",a="Kaleb handles most of the camp's cooking, and the pot spared him many hours of work until it broke.",al={"why mechanical cooking pot","kaleb cooking pot"}}},kw={"booty bay","corporal kaleb","crock pot","krazek","stranglethorn vale"},rel={"quest:627","subzone:booty-bay","zone:stranglethorn","topic:goblin"},m={start="Corporal Kaleb",["end"]="Krazek",level="37",faction="Alliance",id=210},src={"Classic quest text: Krazek's Cookery"}}
E["quest:213"] = {t="quest",n="Hostile Takeover",z="stranglethorn",s="In Booty Bay, Gelriz's latest move draws Baron Revilgaz's wrath in Hostile Takeover. Gelriz has pushed aside moguls appointed by the trade princes and now moves against the most notorious pirate of all. Kebok sends you to steal strange blue crystals Venture Company geologists have found near Lake Nazferiti.",h="In Booty Bay, Gelriz's latest move draws Baron Revilgaz's wrath in Hostile Takeover.",sec={{t="A Matter of Business",b="Baron Revilgaz gives Kebok leave to answer the insult as he sees fit. Kebok chooses theft, targeting the strange blue stones Venture Company mining crews have been unearthing.",sp=0},{t="The Geologists' Cache",b="Venture Company geologists working around Lake Nazferiti have taken a keen interest in the unusual crystals. Kebok wants you to bring eight samples back to Booty Bay. How you get them matters little to him, so long as they end up in his hands.",sp=0},{t="A Tumbling Discovery",b="The returned crystals have been tumbled, suggesting the Venture Company means to use them as fuel or an industrial catalyst. Kebok plans to send samples to Head Chemist Gigglefont for closer study.",sp=1}},faq={{q="Who gives the quest Hostile Takeover?",a="Kebok, in Booty Bay in Stranglethorn Vale, gives you this assignment on Baron Revilgaz's behalf.",al={"hostile takeover questgiver","who starts hostile takeover","kebok quest"}},{q="Why is Baron Revilgaz angry with Gelriz?",a="Gelriz pushed aside moguls appointed by the trade princes and has now moved against the most notorious pirate. Baron Revilgaz will not tolerate it.",al={"why revilgaz mad","gelriz revilgaz conflict","why does kebok want crystals"}},{q="Where are the crystals located?",a="Venture Company geologists working around Lake Nazferiti carry the crystals.",al={"where to find tumbled crystals","tumbled crystal location","lake nazferiti crystals"}}},kw={"booty bay","gelriz","gigglefont","kebok","lake nazferiti","revilgaz","tumbled crystal","venture co."},rel={"subzone:booty-bay","subzone:lake-nazferiti","topic:pirate","zone:stranglethorn"},m={start="Kebok",["end"]="Kebok",level="36",id=213,ri={"Tumbled Crystal"}},src={"Hostile Takeover"}}
E["quest:215"] = {t="quest",n="Jungle Secrets",z="stranglethorn",s="In northern Stranglethorn Vale, Private Thorsen explains why he rejoined Kurzen's men after you rescued him from an ambush. He sends you to the Rebel Camp to have his commander confirm the reason.",h="In northern Stranglethorn Vale, Private Thorsen explains why he rejoined Kurzen's men after you rescued him...",sec={{t="A Covert Undertaking",b="Private Thorsen says the scene looks grim and asks you to hear him out. Lieutenant Doren ordered him to re-enlist with Colonel Kurzen's men and gather desperately needed intelligence for the rebellion. Thorsen hoped this would let him enter Kurzen's Compound, but the effort soon went badly. He sends you to Doren at the Rebel Camp for confirmation and begs you to keep the matter secret.",sp=0},{t="Suspicions at Camp",b="Lieutenant Doren confirms that Private Thorsen acted on his orders. The rebels were once fiercely loyal to Kurzen, but corruption twisted that loyalty into rage. If Thorsen's dealings came to light, his own comrades would slit his throat. Only Doren, Sergeant Yohwa, and Thorsen were meant to know the plan. The failed ambush points to an unknown traitor among the rebels.",sp=1}},faq={{q="Why was Private Thorsen meeting with Kurzen's forces?",a="Lieutenant Doren ordered Private Thorsen to re-enlist among Colonel Kurzen's men and gather vital military intelligence for the rebels.",al={"why did thorsen meet kurzen","is thorsen a traitor","why was thorsen outside camp"}},{q="Where does Private Thorsen send you?",a="Private Thorsen sends you to Lieutenant Doren at the Rebel Camp in northern Stranglethorn Vale, where his commander can confirm the story.",al={"where do i go","thorsen turn in","where is doren"}},{q="Why does Thorsen insist on secrecy?",a="The rebels were once fiercely loyal to Colonel Kurzen. If they learned Thorsen had dealt with Kurzen's men, they could kill him in the night.",al={"why keep it secret","why secret mission"}},{q="What comes after reporting to Lieutenant Doren?",a="After you speak with Lieutenant Doren, your search leads to Bookie Herod.",al={"next quest","what follows jungle secrets"}}},ang={["faction:Alliance"]="The Rebel Camp depends on the urgently needed intelligence Private Thorsen hopes to bring back from Kurzen's men."},kw={"doren","kurzen","rebel camp","stranglethorn","thorsen","traitor","yohwa"},rel={"npc:doren","npc:colonel-kurzen","subzone:rebel-camp","subzone:kurzen-s-compound","zone:stranglethorn"},m={start="Private Thorsen",["end"]="Lieutenant Doren",level="33",faction="Alliance",id=215},src={"Jungle Secrets"}}
E["quest:2761"] = {t="quest",n="Smelt On, Smelt Off",z="stranglethorn",s="Galvan the Ancient in Stranglethorn asks you to bring him Mithril Bars and Iron Bars. The request calls for forty of each.",h="Galvan the Ancient in Stranglethorn asks you to bring him Mithril Bars and Iron Bars.",sec={{t="Bars for Galvan",b="Galvan the Ancient is waiting in Stranglethorn. You are to bring him forty Mithril Bars and forty Iron Bars, with both kinds of metal needed for his request.",sp=0}},faq={{q="What does Galvan need?",a="Galvan the Ancient asks you for forty Mithril Bars and forty Iron Bars.",al={"what bars does Galvan want","galvan materials","smelt bars"}},{q="Where do I bring the bars?",a="Bring the bars to Galvan the Ancient in Stranglethorn.",al={"where is Galvan","Galvan location","where to take bars"}},{q="How many Mithril Bars does Galvan need?",a="Galvan asks for forty Mithril Bars.",al={"mithril amount","how much mithril","40 mithril"}},{q="How many Iron Bars does Galvan need?",a="Galvan asks for forty Iron Bars.",al={"iron amount","how much iron","40 iron"}}},kw={"galvan the ancient","iron bars","mithril bars","smelt on smelt off","smelting","stranglethorn"},m={id=2761},src={"In-game quest text: Smelt On, Smelt Off"},fv=true}
E["quest:2763"] = {t="quest",n="The Art of the Imbue",z="stranglethorn",s="Galvan the Ancient asks you to bring him mithril and citrines in Stranglethorn. He needs them for an imbue.",h="Galvan the Ancient asks you to bring him mithril and citrines in Stranglethorn.",sec={{t="Materials for Galvan",b="The materials Galvan the Ancient requests are specific: forty Mithril Bars and four Citrines. You are to bring them to him in Stranglethorn for the imbue he seeks.",sp=0}},faq={{q="What does Galvan need?",a="Galvan the Ancient asks you to bring him forty Mithril Bars and four Citrines.",al={"galvan materials","what items","mithril and citrines"}},{q="Where do I bring the materials?",a="Bring the Mithril Bars and Citrines to Galvan the Ancient in Stranglethorn.",al={"where is galvan","deliver to galvan","stranglethorn"}},{q="What are the materials for?",a="Galvan the Ancient needs the materials for an imbue.",al={"why mithril bars","citrines for what","imbue materials"}}},kw={"citrines","galvan the ancient","imbue","mithril bars","stranglethorn"},m={id=2763},src={"In-game quest text: The Art of the Imbue"},fv=true}
E["quest:2872"] = {t="quest",n="Stoley's Debt",z="stranglethorn",s="At Steamwheedle Port, “Sea Wolf” MacKinley wants the rum Stoley wagered with him. He asks you to speak with the barkeep about it.",h="At Steamwheedle Port, “Sea Wolf” MacKinley wants the rum Stoley wagered with him.",sec={{t="A Matter of Rum and Coin",b="“Sea Wolf” MacKinley says Stoley owes him a special bottle of rum. Stoley boasted that Steamwheedle Port’s rum was stronger than anything in Booty Bay. He promised to double the money he owes MacKinley if MacKinley tried it and disagreed.\n\nNow MacKinley thinks Stoley has lost his nerve about handing over the bottle. But MacKinley never backs away from a wager, so he asks you to speak with Stoley at the Steamwheedle Port bar.",sp=0},{t="Stoley's Answer",b="Stoley says he is not afraid to hand over Steamwheedle Bilge Rum. But there is no rum left to give.",sp=1}},faq={{q="Who is \"Sea Wolf\" MacKinley?",a="“Sea Wolf” MacKinley is Stoley’s old friend. They have a wager over whose rum is stronger.",al={"who is mackinley","sea wolf mackinley","who gives stoleys debt"}},{q="Where is Stoley located?",a="Stoley tends the bar at Steamwheedle Port in Tanaris.",al={"where is stoley","stoley location","find stoley"}},{q="What bet did Stoley make with MacKinley?",a="That Steamwheedle Port’s rum beats anything in Booty Bay. Stoley swore it was stronger, and promised MacKinley double the money owed if MacKinley tried it and disagreed.",al={"what is the wager","what bet","stoley wager"}}},kw={"bilge rum","booty bay","mackinley","rum","steamwheedle port","stoley","tanaris","wager"},rel={"quest:2873","quest:2874","subzone:steamwheedle-port","subzone:booty-bay","zone:tanaris"},m={start="\"Sea Wolf\" MacKinley",["end"]="Stoley",level="45",id=2872},src={"Stoley's Debt"}}
E["quest:2932"] = {t="quest",n="Grim Message",z="stranglethorn",s="In Stranglethorn, Nimboya sends you north to punish the Witherbark trolls for betraying Thrall. He gives you a pike to bear their skulls and plant in one of their Hinterlands villages.",h="In Stranglethorn, Nimboya sends you north to punish the Witherbark trolls for betraying Thrall.",sec={{t="A Warning in Blood",b="Nimboya sends you from Stranglethorn to the Hinterlands, far to the north and northeast of Tarren Mill, a village held by the Forsaken. The Witherbark trolls once stood with the Horde, but betrayed Thrall. Hunt them for their skulls, then plant Nimboya's pike in Hiri'watha or Zun'watha, two of their smaller villages. The warning will show them what their deeds cost. Nimboya waits in Stranglethorn.",sp=0}},faq={{q="Why does Nimboya want to punish the Witherbark trolls?",a="The Witherbark trolls once allied with the Horde, then turned against Thrall. Nimboya says their betrayal cannot go unpunished.",al={"why attack witherbark","witherbark betrayal","grim message reason"}},{q="Where does Nimboya send you to plant the pike?",a="Plant the pike in Hiri'watha or Zun'watha, two lesser Witherbark villages in the Hinterlands.",al={"where to plant pike","nimboya pike location","grim message location"}},{q="Where are the Hinterlands from Tarren Mill?",a="The Hinterlands lie northeast of Tarren Mill, the village held by the Forsaken. They lie far north of Nimboya in Stranglethorn.",al={"hinterlands location","where is hinterlands"}},{q="Who gives Grim Message?",a="Nimboya gives you the pike in Stranglethorn and waits there for word.",al={"grim message questgiver","who is nimboya"}}},kw={"grim message","hinterlands","hiri'watha","nimboya","tarren mill","thrall","witherbark","zun'watha"},rel={"npc:thrall","zone:hinterlands","topic:horde","topic:troll","subzone:tarren-mill","topic:forsaken"},m={start="Nimboya",["end"]="Nimboya",level="42",faction="Horde",id=2932},src={"Wowpedia: Grim Message"}}
E["quest:328"] = {t="quest",n="The Hidden Key",z="stranglethorn",s="Bookie Herod's papers lead you to a strongbox in the Stockpile. Its contents may reveal how Private Thorsen's cover was blown.",h="Bookie Herod's papers lead you to a strongbox in the Stockpile.",sec={{t="A Secret in the Bindings",b="Bookie Herod's ledgers never name Private Thorsen. But one book hides a small brass key in its binding. Scraps among the papers point to a strongbox in the Stockpile, the cavern complex behind Kurzen's Compound. Inside may lie the reason Thorsen's cover was blown.",sp=0},{t="Deep into the Stockpile",b="Deep in the cave system behind Kurzen's Compound, the strongbox waits among stacked crates. The sturdy chest is heavy and bound in bronze.",sp=0}},faq={{q="Where did this brass key come from?",a="The small brass key was hidden in the binding of one of Bookie Herod's ledger books, found among his paperwork.",al={"where was the key","how did i get the key","small brass key source"}},{q="Where is Bookie Herod's strongbox located?",a="Bookie Herod's strongbox sits in the Stockpile, the cave complex at the rear of Kurzen's Compound.",al={"strongbox location","where is the strongbox","where is the chest"}},{q="Why search for Herod's strongbox?",a="Bookie Herod's loose papers do not explain how Private Thorsen's presence was compromised. They point to a secure strongbox that may hold the answer.",al={"why find the strongbox","what is in the box","purpose of the strongbox"}},{q="What came before this step?",a="This follows the search through Bookie Herod's ledger records during the investigation of him.",al={"previous quest","what quest comes first"}}},kw={"bookie herod","brass key","kurzen's compound","private thorsen","stockpile","stranglethorn vale","strongbox"},rel={"quest:200","quest:329","subzone:kurzen-s-compound","npc:colonel-kurzen","zone:stranglethorn"},m={start="Bookie Herod's Records",["end"]="Bookie Herod's Strongbox",level="37",faction="Alliance",id=328},src={"The Hidden Key"}}
E["quest:329"] = {t="quest",n="The Spy Revealed!",z="stranglethorn",s="You have found a muddy note in Bookie Herod's strongbox. Its account of Private Thorsen's daily routines points to an informant among the rebels in northern Stranglethorn Vale, and it is meant for Lieutenant Doren.",h="You have found a muddy note in Bookie Herod's strongbox.",sec={{t="A Traitor in the Ranks",b="At the Rebel Camp, the note traces Private Thorsen's patrols, companions, and daily activities. Someone has watched him closely. The signature is only -M, and the detail points to a traitor living beside him in the camp.",sp=0},{t="Reporting to Doren",b="You carry the damp parchment back to the Rebel Camp and set it before Lieutenant Doren. The initialed note gives him evidence to search for an infiltrator within the rebels' own perimeter.",sp=1}},faq={{q="What is written on the muddy note?",a="The muddy note records Private Thorsen's daily routines, including where he patrols, whom he speaks to, and how he spends his hours in camp. It bears only the signature -M.",al={"muddy note text","what does the note say","spy note details"}},{q="Where did this note come from?",a="You find the note among the contents of Bookie Herod's strongbox after unlocking it.",al={"where do i find the muddy note","spy revealed start","how to start the spy revealed"}},{q="Who receives the note?",a="Lieutenant Doren receives the note at the Rebel Camp in northern Stranglethorn Vale.",al={"who do i turn the muddy note to","where to take the note","lieutenant doren turn in"}},{q="What comes next after reporting the note?",a="After you report the note, Lieutenant Doren continues his investigation with Patrol Schedules.",al={"what quest is next","next step after the spy revealed","after the spy revealed"}}},ang={["faction:Alliance"]="As an Alliance rebel, you help protect your precarious foothold in Stranglethorn Vale from local threats by finding an informant."},kw={"doren","herod","muddy note","rebel camp","spy","stranglethorn","strongbox","thorsen","traitor"},rel={"npc:doren","subzone:rebel-camp","quest:328","quest:330","zone:stranglethorn"},m={start="Bookie Herod's Strongbox",["end"]="Lieutenant Doren",level="37",faction="Alliance",id=329},src={"The Spy Revealed!"}}
E["quest:330"] = {t="quest",n="Patrol Schedules",z="stranglethorn",s="At the Rebel Camp, Lieutenant Doren searches for the writer behind a note signed only with an initial. The writer says they shared patrol routes with Private Thorsen the previous week, and the duty records may reveal their name.",h="At the Rebel Camp, Lieutenant Doren searches for the writer behind a note signed only with an initial.",sec={{t="A Clue in the Rosters",b="A note found at the Rebel Camp bears the initial M. Its writer says they walked regular routes with Private Thorsen during the previous week. That may point to the one aiding the Kurzen forces. Lieutenant Doren sends you to Corporal Sethman, who keeps the duty logs. His records may show who patrolled beside Thorsen.",sp=0},{t="What the Records Show",b="Private Merle shared Thorsen's duty times and routes throughout the previous week. The match reveals Merle as the informant feeding intelligence to Kurzen's men. Merle flees the encampment toward Duskwood's northern boundary.",sp=1}},faq={{q="Why does Lieutenant Doren send you to Corporal Sethman?",a="Corporal Sethman keeps the Rebel Camp's duty logs and schedules. The note says its writer walked regular routes with Private Thorsen, so Sethman's records may show who served beside him.",al={"why talk to sethman","corporal sethman role","sethman patrol schedules"}},{q="What clue is found in the recovered note?",a="The recovered note bears the letter M. Its writer says they walked the same duty paths as Private Thorsen during the previous week.",al={"note clue","letter clue","who signed note"}},{q="Where does this inquiry take place?",a="The inquiry takes place inside the Rebel Camp in northern Stranglethorn Vale, between Lieutenant Doren and Corporal Sethman.",al={"where is patrol schedules","patrol schedules location"}},{q="What event preceded this inquiry?",a="Before this inquiry, you brought Lieutenant Doren the muddy note found among Bookie Herod's valuables in The Spy Revealed! It bore only an initial.",al={"previous quest","what led to patrol schedules"}}},kw={"corporal sethman","kurzen","lieutenant doren","patrol schedules","private thorsen","rebel camp","stranglethorn vale"},rel={"quest:329","quest:331","subzone:rebel-camp","zone:stranglethorn","npc:doren","zone:duskwood"},m={start="Lieutenant Doren",["end"]="Corporal Sethman",level="37",faction="Alliance",id=330},src={"Patrol Schedules"}}
E["quest:331"] = {t="quest",n="Report to Doren",z="stranglethorn",s="Corporal Sethman sends you to report the patrol findings to Lieutenant Doren. The rebels' commander receives them at Rebel Camp in northern Stranglethorn Vale.",h="Corporal Sethman sends you to report the patrol findings to Lieutenant Doren.",sec={{t="Delivering the Intelligence",b="Corporal Sethman wants you to give Lieutenant Doren a direct account of the patrol information. Bring back what you learned.",sp=0},{t="A Traitor Revealed",b="Lieutenant Doren learns that Merle betrayed the camp when you present the patrol information. He mourns a soldier he once believed brave and loyal. Yet he feels great relief that the traitor is found before Colonel Kurzen can take advantage.",sp=1}},faq={{q="Who sends you to Lieutenant Doren?",a="Corporal Sethman sends you to Lieutenant Doren after reviewing the patrol schedules with you.",al={"who starts report to doren","who sends me to doren","report to doren giver"}},{q="What came before this report?",a="This follows Patrol Schedules, where Corporal Sethman reviews the patrol schedules with you.",al={"previous quest","what is before report to doren","patrol schedules"}},{q="Where is this report delivered?",a="You deliver the report to Lieutenant Doren at Rebel Camp in northern Stranglethorn Vale.",al={"where is lieutenant doren","doren location","where do i go"}}},kw={"doren","kurzen","patrol schedules","sethman","stranglethorn"},rel={"npc:doren","quest:330","npc:colonel-kurzen","zone:stranglethorn"},m={start="Corporal Sethman",["end"]="Lieutenant Doren",level="37",faction="Alliance",id=331},src={"Report to Doren"}}
E["quest:338"] = {t="quest",n="The Green Hills of Stranglethorn",z="stranglethorn",s="Across Stranglethorn Vale, loose pages from Hemet Nesingwary's novel lie scattered through the jungle. Barnil Stonepot asks you to gather them into four chapters and return them.",h="Across Stranglethorn Vale, loose pages from Hemet Nesingwary's novel lie scattered through the jungle.",sec={{t="A Scattered Manuscript",b="At the expedition camp, Barnil Stonepot is troubled after Welcome to the Jungle. While he proofread Hemet Nesingwary's draft, a gale snatched its loose pages and flung them into the wild. Barnil recovered many, but others remain lost in the brush. He needs you to find them and assemble Chapter I, Chapter II, Chapter III, and Chapter IV before Nesingwary learns what happened.",sp=0},{t="Preserving the Hunter's Tale",b="Once you return all four chapters, Barnil can avoid an unpleasant confrontation with Nesingwary. He hopes the restored manuscript will soon reach libraries across the world.",sp=0}},faq={{q="Who wrote The Green Hills of Stranglethorn?",a="Hemet Nesingwary, leader of the expedition, wrote the novel and entrusted its draft to Barnil Stonepot for proofreading.",al={"author of green hills of stranglethorn","who wrote the book","nesingwary book"}},{q="How were the pages lost?",a="A powerful gust swept through the hunting camp as Barnil reviewed the manuscript and scattered loose pages across the jungle.",al={"why are pages scattered","what happened to the pages","how did pages blow away"}},{q="What is needed to finish the manuscript?",a="Gather the scattered pages, assemble Chapter I, Chapter II, Chapter III, and Chapter IV, then bring the complete set to Barnil.",al={"what chapters are needed","how to complete green hills","manuscript requirements"}},{q="Where did this assignment come from?",a="Barnil offers this work at the expedition camp in Stranglethorn Vale after you complete Welcome to the Jungle.",al={"green hills prerequisite","quest before green hills","how do i get this quest"}},{q="What does Barnil intend to do with the restored novel?",a="Barnil hopes the restored manuscript will reach libraries across the world. Its return will also spare him Nesingwary's anger.",al={"why collect the pages","what happens to the book","where will the book go"}}},kw={"barnil stonepot","chapters","green hills of stranglethorn","hemet nesingwary","manuscript","pages","stranglethorn vale"},rel={"quest:339","quest:340","quest:341","quest:342","zone:stranglethorn"},m={start="Barnil Stonepot",["end"]="Barnil Stonepot",level="40",id=338,ri={"Green Hills of Stranglethorn - Chapter I","Green Hills of Stranglethorn - Chapter II","Green Hills of Stranglethorn - Chapter III","Green Hills of Stranglethorn - Chapter IV"}},src={"The Green Hills of Stranglethorn (Classic)"}}
E["quest:339"] = {t="quest",n="Chapter I",z="stranglethorn",s="In Stranglethorn, Barnil Stonepot searches the jungle for four lost pages of Hemet Nesingwary's hunting manuscript.",h="In Stranglethorn, Barnil Stonepot searches the jungle for four lost pages of Hemet Nesingwary's hunting...",sec={{t="The Missing Introduction",b="Barnil Stonepot wants the opening passage of The Green Hills of Stranglethorn restored. He says it sets the stage for the wider story and describes Hemet Nesingwary's hunting party, including Barnil himself. Pages one, four, six, and eight are missing in the jungle.",sp=0},{t="Binding the First Section",b="When you return the four missing leaves, Barnil pieces the first section of Hemet Nesingwary's text back together.",sp=0}},faq={{q="Who is asking for these pages?",a="Barnil Stonepot, Hemet Nesingwary's companion at their camp in Stranglethorn Vale, needs the pages to assemble the scattered hunting memoirs.",al={"who gives chapter 1","barnil stonepot","quest giver"}},{q="Which pages are needed for this part of the manuscript?",a="Barnil needs pages one, four, six, and eight to reassemble the manuscript's opening section.",al={"what pages are needed","missing pages","which pages"}},{q="What is described in this part of the manuscript?",a="Barnil says the opening section sets the story's background and introduces Hemet Nesingwary's hunting companions, including Barnil himself.",al={"what is chapter 1 about","manuscript contents"}},{q="What led up to this step?",a="Barnil first told you about the missing pages while working to recover The Green Hills of Stranglethorn.",al={"prerequisite","previous quest"}}},kw={"barnil stonepot","chapter i","green hills of stranglethorn","hemet nesingwary","stranglethorn vale"},rel={"quest:338","zone:stranglethorn"},m={start="Barnil Stonepot",["end"]="Barnil Stonepot",level="40",id=339},src={"Chapter I"}}
E["quest:340"] = {t="quest",n="Chapter II",z="stranglethorn",s="In Stranglethorn Vale, Barnil Stonepot searches for leaves missing from Hemet Nesingwary's manuscript. He gathered most of them himself, but travelers must help find the rest.",h="In Stranglethorn Vale, Barnil Stonepot searches for leaves missing from Hemet Nesingwary's manuscript.",sec={{t="Hunts of the Jungle Cats",b="Barnil Stonepot has recovered many leaves from Hemet Nesingwary's scattered manuscript across Stranglethorn Vale. The second chapter follows panthers and tigers through the wilderness. Pages ten, eleven, fourteen, and sixteen remain missing, so those hunting accounts are incomplete.",sp=0}},faq={{q="Who is asking for these manuscript pages?",a="Barnil Stonepot, who helps the Nesingwary expedition in Stranglethorn Vale, asks for the missing leaves.",al={"who gives chapter 2","quest giver chapter ii","barnil stonepot"}},{q="Which pages are needed for the second chapter?",a="Barnil needs pages ten, eleven, fourteen, and sixteen for the second chapter.",al={"what pages are needed","pages for chapter 2","chapter ii pages"}},{q="What stories are recorded in the second chapter?",a="The second chapter tells of stalking and hunting the panthers and tigers that prowl Stranglethorn Vale.",al={"what is chapter 2 about","chapter ii lore","green hills chapter 2 content"}},{q="What comes before this request?",a="Barnil's request follows his first call for help recovering Hemet Nesingwary's scattered manuscript, The Green Hills of Stranglethorn.",al={"prior quest","prerequisite chapter 2","green hills chain"}}},kw={"barnil stonepot","chapter ii","green hills of stranglethorn","nesingwary","pages","panther","stranglethorn vale","tiger"},rel={"quest:338","zone:stranglethorn"},m={start="Barnil Stonepot",["end"]="Barnil Stonepot",level="40",id=340},src={"Chapter II"}}
E["quest:341"] = {t="quest",n="Chapter III",z="stranglethorn",s="Barnil Stonepot searches Stranglethorn Vale for the missing leaves of Hemet Nesingwary's hunting manuscript. Its third chapter tells of Sir Erlgadin and Lady Rouack's first kill with a dwarven rifle.",h="Barnil Stonepot searches Stranglethorn Vale for the missing leaves of Hemet Nesingwary's hunting manuscript.",sec={{t="A Hunt Recorded",b="Barnil Stonepot favors this part of The Green Hills of Stranglethorn. It follows Sir Erlgadin and Lady Rouack in their early exploits, including their first kill with a dwarven rifle. Then the tale breaks off at a sharp cliffhanger.",sp=0},{t="Missing Leaves",b="Barnil needs four leaves to restore the story: pages eighteen, twenty, twenty-one, and twenty-four. They were carried off with the rest of the manuscript and scattered across Stranglethorn Vale.",sp=0}},faq={{q="Who is looking for Chapter III?",a="Barnil Stonepot is searching for Chapter III. He proofread Hemet Nesingwary's manuscript at the expedition camp in northern Stranglethorn Vale, and now he is trying to rebuild its missing pages.",al={"who gives chapter 3","chapter 3 quest giver","barnil stonepot chapter iii"}},{q="What happens in Chapter III of the book?",a="Chapter III recounts Sir Erlgadin and Lady Rouack's first kill with a dwarven rifle. The tale ends on an unresolved cliffhanger.",al={"what is chapter 3 about","chapter iii story","erlgadin and rouack"}},{q="Which pages are needed to finish Chapter III?",a="Barnil needs pages eighteen, twenty, twenty-one, and twenty-four to assemble Chapter III.",al={"what pages chapter 3","chapter iii pages needed","pages for chapter 3"}},{q="What came before this quest?",a="This follows The Green Hills of Stranglethorn, when Barnil first explained how Hemet Nesingwary's manuscript was lost.",al={"chapter 3 prerequisite","what leads to chapter iii"}}},kw={"barnil stonepot","chapter iii","erlgadin","green hills of stranglethorn","hemet nesingwary","page 18","page 20","page 21","page 24","rouack","stranglethorn vale"},rel={"quest:338","zone:stranglethorn"},m={start="Barnil Stonepot",["end"]="Barnil Stonepot",level="40",id=341},src={"Chapter III"}}
E["quest:342"] = {t="quest",n="Chapter IV",z="stranglethorn",s="Barnil Stonepot is searching for the ending of Hemet Nesingwary's hunting tale in Chapter IV. Three pages are missing from the jungle.",h="Barnil Stonepot is searching for the ending of Hemet Nesingwary's hunting tale in Chapter IV.",sec={{t="The Grand Finale",b="Barnil Stonepot calls the fourth chapter Hemet Nesingwary's grand finale. He needs you to find pages twenty-five, twenty-six, and twenty-seven. The three sheets lie scattered across the jungle. Without them, he cannot restore the tale's conclusion.",sp=0}},faq={{q="Who wants Chapter IV restored?",a="Barnil Stonepot wants you to gather the scattered pages so he can piece together the ending of Hemet Nesingwary's hunting book.",al={"who gives chapter iv","chapter iv quest giver","who needs chapter 4"}},{q="Which pages are required to finish Chapter IV?",a="You need pages twenty-five, twenty-six, and twenty-seven of The Green Hills of Stranglethorn to finish the fourth chapter.",al={"chapter 4 pages","which pages for chapter iv","what pages do i need"}},{q="What comes before this request?",a="Barnil Stonepot first asked for the scattered leaves of The Green Hills of Stranglethorn. Now he seeks the pages that restore the ending.",al={"chapter iv prerequisites","chapter 4 previous quest"}}},kw={"barnil stonepot","chapter 4","chapter iv","green hills of stranglethorn","hemet nesingwary","page 25","page 26","page 27","stranglethorn vale"},rel={"quest:338","zone:stranglethorn"},m={start="Barnil Stonepot",["end"]="Barnil Stonepot",level="40",id=342},src={"Chapter IV"}}
E["quest:348"] = {t="quest",n="Stranglethorn Fever",z="stranglethorn",s="In Booty Bay, Fin Fizracket grows weaker with Stranglethorn Fever. He believes he is dying and says only Mokk the Savage's heart can cure him.",h="In Booty Bay, Fin Fizracket grows weaker with Stranglethorn Fever.",sec={{t="A Desperate Cure",b="Fin Fizracket stammers as his strength fails. Certain he has caught Stranglethorn Fever, he says he must eat the heart of Mokk the Savage to be cured. Mokk is an elusive white beast, and only Witch Doctor Unbagwa can summon him. Fin sends you to find Unbagwa in the Spirit Den, a hidden cave on the southern cape.",sp=0},{t="Back at Fin's Side",b="After Fin receives Mokk's heart, his strength begins to return. He wakes unsure where he is, then learns he is in Booty Bay and speaks of a strange dream. Yet some of his weakness remains.",sp=1}},faq={{q="What illness is Fin Fizracket suffering from?",a="Fin says he has Stranglethorn Fever, a deadly virus that leaves him cold and delirious. He believes he is dying.",al={"what disease does fin have","stranglethorn fever illness","fin fizracket sick"}},{q="What is required to cure the fever?",a="Fin says he must eat the heart of Mokk the Savage, an elusive white beast, to be cured.",al={"how to cure stranglethorn fever","cure for fin fizracket","mokk heart cure"}},{q="Who is Witch Doctor Unbagwa?",a="Witch Doctor Unbagwa alone can summon Mokk the Savage. He is in the Spirit Den, a hidden cave on the southern cape in Stranglethorn Vale.",al={"where is unbagwa","who can summon mokk","witch doctor unbagwa role"}},{q="Where can Fin Fizracket be found?",a="Fin Fizracket is in Booty Bay.",al={"fin fizracket location","where is fin fizracket","booty bay fever guy"}}},kw={"booty bay","fin fizracket","heart of mokk","mokk the savage","stranglethorn fever","stranglethorn vale","witch doctor unbagwa"},rel={"quest:349","subzone:booty-bay","subzone:cape-of-stranglethorn","zone:stranglethorn"},m={start="Fin Fizracket",["end"]="Fin Fizracket",level="45",faction="Neutral",id=348,ri={"Heart of Mokk"}},src={"Wowpedia: Stranglethorn Fever"}}
E["quest:349"] = {t="quest",n="Stranglethorn Fever",z="stranglethorn",s="In Stranglethorn Vale, Witch Doctor Unbagwa prepares a chant to draw Mokk the Savage from the jungle. He needs ten Gorilla Fangs to begin. As he communes with the spirits, nearby gorillas come to threaten him.",h="In Stranglethorn Vale, Witch Doctor Unbagwa prepares a chant to draw Mokk the Savage from the jungle.",sec={{t="A Ritual for the Savage",b="Witch Doctor Unbagwa knows a ritual that can draw Mokk the Savage from the jungle. He asks for ten Gorilla Fangs before beginning the chant. As he communes with the spirits, the chant draws nearby gorillas. They threaten the witch doctor while he tries to finish the ritual.",sp=0}},faq={{q="Who is Witch Doctor Unbagwa?",a="Witch Doctor Unbagwa is a troll in Stranglethorn Vale who claims to speak with the spirits and draw out the great ape Mokk the Savage.",al={"unbagwa","who is unbagwa","witch doctor unbagwa"}},{q="What does Witch Doctor Unbagwa require to start?",a="Witch Doctor Unbagwa requires ten Gorilla Fangs before he agrees to speak with the spirits.",al={"gorilla fang quest","what item for unbagwa","unbagwa requirements"}},{q="Why must the witch doctor be defended?",a="Speaking with the spirits draws nearby gorillas to Unbagwa. They threaten him as he communes with the spirits, and he cannot finish or summon Mokk if they overrun him.",al={"why defend unbagwa","defend witch doctor unbagwa","gorilla beasts ritual"}},{q="Who is Mokk the Savage?",a="Mokk the Savage is a formidable gorilla prowling Stranglethorn Vale, and Witch Doctor Unbagwa knows how to summon him.",al={"mokk","who is mokk","mokk the savage"}}},kw={"gorilla fang","mokk the savage","stranglethorn fever","stranglethorn vale","unbagwa","witch doctor"},rel={"zone:stranglethorn"},m={start="Witch Doctor Unbagwa",["end"]="Witch Doctor Unbagwa",level="35",faction="Neutral",id=349},src={"Stranglethorn Fever (Classic)"}}
E["quest:3625"] = {t="quest",n="Enchanted Azsharite Fel Weaponry",z="stranglethorn",s="In Stranglethorn Vale, Galvan the Ancient prepares enchanted arms against a powerful demon. Their Felcurse is meant to weaken Razelikh the Defiler and his servitors.",h="In Stranglethorn Vale, Galvan the Ancient prepares enchanted arms against a powerful demon.",sec={{t="A Weapon Against the Defiler",b="Just south of the path into Zul'Gurub, Galvan the Ancient works with care. Forging a blade, staff, or dagger takes patience, and haste risks a flaw. Each weapon bears the Felcurse, which can be unleashed from time to time against Razelikh the Defiler and his demonic underlings. Its weakening effect lasts for different lengths of time.",sp=0}},faq={{q="Who forges these weapons?",a="Galvan the Ancient, a master smith, forges the weapons just south of the road toward Zul'Gurub in Stranglethorn Vale.",al={"who makes the weapon","galvan the ancient","who is the smith"}},{q="What power does the forged weapon hold?",a="Each weapon channels the Felcurse, magic meant to weaken Razelikh the Defiler and his demonic minions. The effect lasts for different lengths of time.",al={"what does the weapon do","felcurse power","how does felcurse work"}},{q="Where does the journey lead after the weapon is forged?",a="When Galvan finishes and presents the weapon, you return along the path with Return to the Blasted Lands.",al={"what next","where do i go next","next quest"}}},kw={"azsharite","blasted lands","felbane","felcurse","galvan the ancient","razelikh the defiler","stranglethorn vale"},rel={"quest:3626","zone:stranglethorn","zone:blastedlands","subzone:zul-gurub"},m={start="Galvan the Ancient",["end"]="Galvan the Ancient",level="58",id=3625},src={"Enchanted Azsharite Fel Weaponry"}}
E["quest:3626"] = {t="quest",n="Return to the Blasted Lands",z="stranglethorn",s="Galvan the Ancient sends you back to the Blasted Lands with your newly forged weapons. The Fallen Hero of the Horde waits there, ready to ask if you will face Razelikh.",h="Galvan the Ancient sends you back to the Blasted Lands with your newly forged weapons.",sec={{t="A Call to Redemption",b="Galvan the Ancient says your hour of redemption has come. Your enchanted weapons are complete, so you carry them back to the Blasted Lands to find the Fallen Hero of the Horde. The ghostly warrior asks if you are ready to face Razelikh and his minions.",sp=0}},faq={{q="Who sends you back to the Blasted Lands?",a="Galvan the Ancient forges your weapons, then sends you back with them to the Blasted Lands.",al={"who gives this quest","quest giver","galvan the ancient"}},{q="Whom are you sent to meet in the Blasted Lands?",a="You are sent to meet the Fallen Hero of the Horde again. He awaits your return and will reveal your final confrontation.",al={"who do i turn this in to","where to turn in","fallen hero"}},{q="What comes before this step?",a="This follows Enchanted Azsharite Fel Weaponry, where your specialized weapons were completed.",al={"previous quest","prerequisite"}},{q="Who is the enemy awaiting you in the Blasted Lands?",a="The Fallen Hero of the Horde asks if you are ready to face Razelikh and his minions.",al={"who are we fighting","razelikh","final boss"}}},kw={"blasted lands","fallen hero of the horde","fel weaponry","galvan the ancient","razelikh","redemption","stranglethorn vale"},rel={"quest:3625","npc:fallen-hero-of-the-horde","zone:blastedlands","zone:stranglethorn","topic:horde"},m={start="Galvan the Ancient",["end"]="Fallen Hero of the Horde",level="58",id=3626},src={"Return to the Blasted Lands"}}
E["quest:568"] = {t="quest",n="The Defense of Grom'gol",z="stranglethorn",s="At Grom'gol, Commander Aggro'gosh guards the Horde's foothold in Stranglethorn Vale. He works to keep supplies moving safely to Stonard by thinning the Lashtail Raptors outside the base camp.",h="At Grom'gol, Commander Aggro'gosh guards the Horde's foothold in Stranglethorn Vale.",sec={{t="Securing the Foothold",b="Commander Aggro'gosh guards the Horde at Grom'gol Base Camp. The camp is vital to a safe supply line to Stonard, but local inhabitants stand in the way.",sp=0},{t="Thinning the Jungle Predators",b="Lashtail Raptors outside Grom'gol threaten the supply line. Aggro'gosh calls on loyal fighters to thin their numbers, then report back for new orders.",sp=0}},faq={{q="Who orders the defense of the camp?",a="Commander Aggro'gosh, officer in charge of the Warchief's stronghold at Grom'gol Base Camp, orders the Lashtail Raptors thinned out.",al={"who gives the quest","commander aggrogosh","quest giver"}},{q="Why is Grom'gol Base Camp important to the Horde?",a="Grom'gol Base Camp is vital to a safe supply line to the Horde encampment at Stonard in the Swamp of Sorrows.",al={"gromgol purpose","why gromgol","supply line"}},{q="What threats are targeting the camp's operations?",a="Local inhabitants hamper the Horde's supply line to Stonard. Aggro'gosh wants the Lashtail Raptors outside the camp thinned out.",al={"what enemies","why raptors","what beasts"}},{q="What happens after culling the raptors?",a="After thinning out the raptors, you report to Commander Aggro'gosh for new orders.",al={"what is next","quest continuation","follow up"}}},ang={["faction:Horde"]="As a member of the Horde, you hold a foothold in the jungle at Grom'gol Base Camp and keep a safe supply line to Stonard."},kw={"aggrogosh","gromgol","horde","lashtail","raptors","stonard","stranglethorn"},rel={"subzone:grom-gol-base-camp","subzone:stonard","topic:horde","zone:stranglethorn"},m={start="Commander Aggro'gosh",["end"]="Commander Aggro'gosh",level="36",faction="Horde",id=568},src={"The Defense of Grom'gol"}}
E["quest:569"] = {t="quest",n="The Defense of Grom'gol",z="stranglethorn",s="At Grom'gol, Commander Aggro'gosh moves to guard the supply road to Stonard. After the raptor hunt outside camp, Mosh'Ogg ogres at Mizjah Ruins keep attacking the caravans.",h="At Grom'gol, Commander Aggro'gosh moves to guard the supply road to Stonard.",sec={{t="Securing the Caravans",b="Commander Aggro'gosh must keep supplies moving from Grom'gol through Stranglethorn Vale to Stonard, an outpost vital to the Horde. He did not come to fight every people of the Vale. Yet the Mosh'Ogg ogres have taken Mizjah Ruins southeast of camp, and warnings have not stopped their repeated attacks on Horde caravans. So Aggro'gosh orders a strike against the ogres and witch doctors holding the ruins.",sp=0}},faq={{q="Where are the ogres based?",a="The ogres occupy Mizjah Ruins, southeast of Grom'gol Base Camp in northern Stranglethorn Vale.",al={"ogre location","where is mizjah ruins","ogre camp"}},{q="Why is Grom'gol targeting these ogres?",a="Grom'gol sends supplies to Stonard. The ogres at Mizjah Ruins keep ambushing the caravans despite formal warnings to stop.",al={"why kill the ogres","defense of gromgol reason","why fight moshogg"}},{q="Who orders this strike?",a="Commander Aggro'gosh, Grom'gol Base Camp's military leader, directs the strike against the ogres.",al={"quest giver","who gives the quest","who is aggrogosh"}},{q="What comes before this request?",a="Before this request, Aggro'gosh ordered a hunt to thin the raptors outside Grom'gol.",al={"prerequisite","previous quest","chain start"}}},ang={["faction:Horde"]="As a member of the Horde, you know the caravans between Grom'gol and Stonard sustain the Horde's presence in the southern Eastern Kingdoms."},kw={"aggro'gosh","grom'gol","mizjah ruins","mosh'ogg","ogre brutes","stonard","stranglethorn vale","witch doctors"},rel={"quest:568","subzone:grom-gol-base-camp","subzone:mizjah-ruins","subzone:stonard","zone:stranglethorn"},m={start="Commander Aggro'gosh",["end"]="Commander Aggro'gosh",level="37",faction="Horde",id=569},src={"The Defense of Grom'gol (2)"}}
E["quest:570"] = {t="quest",n="Mok'thardin's Enchantment",z="stranglethorn",s="At Grom'gol Base Camp, Far Seer Mok'thardin gathers the jungle's power for the Horde. His earlier rites have succeeded, and he seeks sharp claws and a pristine feline fang for an enchantment.",h="At Grom'gol Base Camp, Far Seer Mok'thardin gathers the jungle's power for the Horde.",sec={{t="Harnessing the Jungle",b="At Grom'gol Base Camp, Far Seer Mok'thardin studies the wild's feral power. He seeks to bend it for the Horde. His first rites have succeeded, and he offers to shape an enchanted relic. Those willing must enter the thick underbrush and hunt the deadly predators nearby.",sp=0},{t="The Stalkers of Mizjah",b="Mok'thardin's rite calls for eight claws from shadowmaw panthers and a pristine fang from a tigress. The fierce cats roam across Stranglethorn Vale. Many prowl southeast of the Mizjah Ruins, just beyond the river.",sp=0}},faq={{q="Who is requesting these beast parts?",a="Far Seer Mok'thardin, an orc shaman at Grom'gol Base Camp in Stranglethorn Vale, asks for the ingredients for his rites.",al={"who gives mok'thardin's enchantment","quest giver mok'thardin","who is mok'thardin"}},{q="Where can the panthers and tigresses be found?",a="The panthers and tigresses roam the dense jungle. Mok'thardin points hunters southeast of the Mizjah Ruins, just across the river.",al={"shadowmaw claws location","pristine tigress fang location","where to hunt beasts"}},{q="Why does Far Seer Mok'thardin need these items?",a="Mok'thardin seeks to harness the jungle's natural magic, cast powerful enchantments, and craft a special item for Horde champions.",al={"why collect claws and fangs","mok'thardin ritual purpose","why shadowmaw claws"}},{q="What comes next in Mok'thardin's ritual work?",a="Once Mok'thardin has the claws and fang, he continues his ritual crafting in the next stage of the enchantment series.",al={"what is after mok'thardin's enchantment 2","next quest after shadowmaw claws","mok'thardin continuation"}}},ang={["faction:Horde"]="As a member of the Horde, you know Far Seer Mok'thardin seeks to harness the jungle's magic for your people."},kw={"enchantment","far seer","grom'gol","mizjah","mok'thardin","shadowmaw","stranglethorn","tigress"},rel={"subzone:grom-gol-base-camp","subzone:mizjah-ruins","zone:stranglethorn","topic:horde"},m={start="Far Seer Mok'thardin",["end"]="Far Seer Mok'thardin",level="38",faction="Horde",id=570,ri={"Pristine Tigress Fang","Shadowmaw Claw"}},src={"Mok'thardin's Enchantment"}}
E["quest:571"] = {t="quest",n="Mok'thardin's Enchantment",z="stranglethorn",s="At Grom'gol Base Camp, Far Seer Mok'thardin needs a strong binding for the Stranglethorn trophies gathered so far. Aged sinew from elder primates in southern Stranglethorn Vale will hold the feathers, claws, and fang fast.",h="At Grom'gol Base Camp, Far Seer Mok'thardin needs a strong binding for the Stranglethorn trophies gathered so...",sec={{t="A Magical Tether",b="The feathers, claws, and pristine fang bring Far Seer Mok'thardin to the next stage of his ritual. He needs a tough magical tether to bind them together. Only aged sinew from an Elder Mistvale Gorilla can endure the magic he plans to weave.",sp=0},{t="Hunting the Mistvale Elders",b="Elder Mistvale Gorillas forage in the jungles east of Booty Bay. Mok'thardin needs flawless sinew, so you may have to hunt several before finding one fit for his enchantment.",sp=0}},faq={{q="What is the aged gorilla sinew needed for?",a="Far Seer Mok'thardin needs aged sinew as a magical tether to hold the gathered feathers, claws, and pristine fang securely together for his enchantment.",al={"why sinew","what does mokthardin need the sinew for","gorilla sinew purpose"}},{q="Where are the Elder Mistvale Gorillas located?",a="Elder Mistvale Gorillas forage in the southern jungles of Stranglethorn Vale, east of Booty Bay.",al={"where to find elder mistvale gorilla","mistvale gorilla location","where are gorillas"}},{q="Who requests this hunt?",a="Far Seer Mok'thardin, an orc spiritual guide at Grom'gol Basecamp in Stranglethorn Vale, asks for the sinew.",al={"who gives quest","quest giver"}},{q="Where does this fit into Mok'thardin's enchantment work?",a="The hunt follows the gathering of the claws and pristine fang. Far Seer Mok'thardin's enchantment work continues afterward.",al={"what comes before this","chain order","prerequisite"}}},ang={["faction:Horde"]="As a Horde adventurer, you can seek Far Seer Mok'thardin's aid at Grom'gol Basecamp. He crafts potent jungle magic to bolster your standing in Stranglethorn Vale."},kw={"aged gorilla sinew","booty bay","gorilla","grom'gol","mistvale","mok'thardin","sinew","stranglethorn"},rel={"zone:stranglethorn","subzone:booty-bay"},m={start="Far Seer Mok'thardin",["end"]="Far Seer Mok'thardin",level="41",faction="Horde",id=571,ri={"Aged Gorilla Sinew"}},src={"Mok'thardin's Enchantment (2)"}}
E["quest:572"] = {t="quest",n="Mok'thardin's Enchantment",z="stranglethorn",s="At Grom'gol Base Camp, Far Seer Mok'thardin gathers materials for a shamanistic ritual. With feline trophies collected, he now seeks feathers from Stranglethorn Vale's raptors.",h="At Grom'gol Base Camp, Far Seer Mok'thardin gathers materials for a shamanistic ritual.",sec={{t="Feathers of the Stalker",b="Far Seer Mok'thardin still needs more before his shamanistic ritual can begin. He is gathering materials for a tool to aid the Warchief. Now he asks you to bring feathers worn by Jungle Stalkers. The raptors live in the dense jungle south of Grom'gol Base Camp, near the great arena.",sp=0}},faq={{q="Who is asking for the feathers?",a="Far Seer Mok'thardin, an orc shaman at Grom'gol Base Camp in Stranglethorn Vale, seeks feathers for a ritual enchantment.",al={"quest giver","mok'thardin","who needs feathers"}},{q="Where are the Jungle Stalkers located?",a="Jungle Stalkers live in the jungle directly south of Grom'gol Base Camp, near the Gurubashi Arena.",al={"jungle stalker location","where are raptors","jungle stalker feathers where"}},{q="Why does Far Seer Mok'thardin need Jungle Stalker feathers?",a="Mok'thardin uses a shamanistic ritual to combine jungle curiosities and beast trophies into an enchanted tool meant to aid the Horde and the Warchief.",al={"purpose of feathers","why stalker feathers","mok'thardin ritual"}},{q="What came before this request?",a="Before this request, you helped Mok'thardin hunt the Vale's feline beasts and gather the first components for his planned enchantment.",al={"previous quest","prior step"}}},ang={["faction:Horde"]="Far Seer Mok'thardin means the finished enchantment to aid the Horde and the Warchief.",["class:Shaman"]="As a shaman, you know Mok'thardin combines jungle trinkets with his ritual to make an enchanted item."},kw={"enchantment","feathers","grom'gol","jungle stalker","mok'thardin","raptor","stranglethorn"},rel={"subzone:grom-gol-base-camp","zone:stranglethorn","topic:horde","quest:570"},m={start="Far Seer Mok'thardin",["end"]="Far Seer Mok'thardin",level="41",faction="Horde",id=572,ri={"Jungle Stalker Feather"}},src={"Mok'thardin's Enchantment (3)"}}
E["quest:573"] = {t="quest",n="Mok'thardin's Enchantment",z="stranglethorn",s="At Grom'gol Base Camp, Far Seer Mok'thardin seeks the last sacred water for a ceremonial choker. He sends you to a Holy Spring on the southern bluffs near the western sea, where naga explorers have arrived.",h="At Grom'gol Base Camp, Far Seer Mok'thardin seeks the last sacred water for a ceremonial choker.",sec={{t="A Contested Spring",b="Far Seer Mok'thardin needs water from a Holy Spring high above Stranglethorn Vale's southern bluffs, near the western coast. You have helped with the earlier stages of the enchantment. Scholars of the mystic and divine dispute who the spring was sanctified for. Every race across Azeroth claims its holy waters were meant for its own people.",sp=0},{t="The Naga Incursion",b="Naga explorers have reached the spring, and Mok'thardin needs you to drive them away. Bring him a draught of the water and slay ten of the serpent intruders. He needs both to finish the ceremonial choker in the Warchief's name.",sp=0}},faq={{q="Where is the Holy Spring located?",a="The Holy Spring sits high on the bluffs near the western coast, in southern Stranglethorn Vale.",al={"holy spring location","where is holy spring water","holy spring bluffs"}},{q="Why is the Holy Spring considered important?",a="Scholars of the mystic and divine dispute the spring's importance. Every race across Azeroth claims its divine waters were sanctified for its own people.",al={"why is the spring holy","holy spring significance"}},{q="Who is contesting the Holy Spring?",a="An expedition of naga explorers has reached the bluffs around the Holy Spring and menaces the area.",al={"who attacks the spring","holy spring enemies"}},{q="What is the water being used for?",a="Far Seer Mok'thardin needs the water as the final reagent to prepare and enchant a ceremonial choker in defense of the Horde.",al={"why need holy spring water","holy spring water purpose"}}},ang={["faction:Horde"]="As a Horde champion, you can help Far Seer Mok'thardin finish a ceremonial choker to honor the Warchief and protect the Horde."},kw={"ceremonial choker","grom'gol","holy spring","holy spring water","mok'thardin","naga explorer","stranglethorn"},rel={"zone:stranglethorn","topic:horde","topic:naga"},m={start="Far Seer Mok'thardin",["end"]="Far Seer Mok'thardin",level="44",faction="Horde",id=573},src={"Mok'thardin's Enchantment (4)"}}
E["quest:574"] = {t="quest",n="Special Forces",z="stranglethorn",s="At the Kurzen Compound, Sergeant Yohwa sets her sights on the colonel's elite troops. You enter the Stockpile cave to face the commandos and headshrinkers, then report to Lieutenant Doren.",h="At the Kurzen Compound, Sergeant Yohwa sets her sights on the colonel's elite troops.",sec={{t="Striking the Stockpile",b="Sergeant Yohwa now targets the elite specialists at the Kurzen Compound. The Second Rebellion has weakened Kurzen's regular soldiers, and Yohwa knows many of his troops personally. She calls them skilled, loyal and cruel.\n\nWhen they are not in the wilderness slaughtering rebel soldiers, the commandos and headshrinkers gather in the Stockpile cave at the back of the compound. To weaken Kurzen further, you enter and kill ten Kurzen Commandos and six Kurzen Headshrinkers.",sp=0},{t="Reporting to Command",b="After the fight, Sergeant Yohwa sends you to her commanding officer, Lieutenant Doren, at the Rebel Camp. He will want to hear your account firsthand.",sp=0}},faq={{q="Who orders the attack on Kurzen's elite troops?",a="Sergeant Yohwa at the Rebel Camp in northern Stranglethorn Vale orders the attack after you help thin Kurzen's regular infantry.",al={"who gives special forces","special forces questgiver","where to start special forces"}},{q="Where are Kurzen's commandos and headshrinkers located?",a="Kurzen's commandos and headshrinkers gather in the Stockpile, a cave at the back of the Kurzen Compound. They also range into the wilderness to hunt rebels.",al={"where are headshrinkers","where is the stockpile","kurzen commando location"}},{q="To whom do you report after clearing the cave?",a="You give your firsthand report to Lieutenant Doren, the commanding officer at the Rebel Camp.",al={"who to turn in to","where is doren","who completes special forces"}},{q="What comes before this assault in the rebel campaign?",a="The Second Rebellion comes before this assault. You weakened Colonel Kurzen's regular troops across the compound.",al={"special forces prerequisite","what quest comes before special forces"}}},kw={"kurzen commando","kurzen compound","kurzen headshrinker","lieutenant doren","rebel camp","sergeant yohwa","special forces","stockpile"},rel={"quest:203","npc:doren","subzone:rebel-camp","zone:stranglethorn"},m={start="Sergeant Yohwa",["end"]="Lieutenant Doren",level="38",faction="Alliance",id=574},src={"Special Forces"}}
E["quest:575"] = {t="quest",n="Supply and Demand",z="stranglethorn",s="In Booty Bay, Drizzlik is preparing an order for Director Riddlevox, chief inventor of the Tinkers' Union. The leathercrafter claims to be the finest in the South Seas and beyond.",h="In Booty Bay, Drizzlik is preparing an order for Director Riddlevox, chief inventor of the Tinkers' Union.",sec={{t="An Order from the Tinkers' Union",b="Drizzlik calls his leatherwork exquisite and famed everywhere. Director Riddlevox has ordered twelve Excelsior-line boots, among Drizzlik's best sellers and the boots Riddlevox favors. To begin shaping them, Drizzlik needs skins from crocolisks by the northern Stranglethorn river. His equipment is ready, and leaving so important a customer unsatisfied would be a poor idea.",sp=0},{t="Once the Skins Arrive",b="Drizzlik finds the skins good enough for the boots. Their fineness matters little because they form the inner layer, but they still need to be comfortable. If the skins are too stiff, tiger blood can soften them. It is one of the tricks of the trade.",sp=1}},faq={{q="Who is Drizzlik?",a="Drizzlik is a leathercrafter in Booty Bay who claims to be the finest in the South Seas and beyond.",al={"drizzlik booty bay","booty bay leatherworker"}},{q="Who ordered the Excelsior boots?",a="Director Riddlevox, chief inventor of the Tinkers' Union, ordered twelve Excelsior-line boots.",al={"who ordered the boots","director riddlevox","tinkers union order"}},{q="Where are the crocolisks found for this commission?",a="The crocolisks for Drizzlik's commission live by the northern Stranglethorn river.",al={"crocolisk location","where are river crocs","where do i find the skins"}},{q="How many skins does Drizzlik want?",a="Drizzlik wants two large river crocolisk skins.",al={"how many crocolisk skins","large river crocolisk skins"}}},kw={"booty bay","crocolisk","drizzlik","excelsior","leathercraft","riddlevox","stranglethorn","tinkers union"},rel={"quest:577","subzone:booty-bay","zone:stranglethorn","subzone:south-seas"},m={start="Drizzlik",["end"]="Drizzlik",level="31",id=575},src={"Classic quest text: Supply and Demand"}}
E["quest:576"] = {t="quest",n="Keep An Eye Out",z="stranglethorn",s="In Booty Bay, Dizzy One-Eye needs the enchanted eye that gives him sight. Bloodsail Buccaneers ambushed him last night and took it.",h="In Booty Bay, Dizzy One-Eye needs the enchanted eye that gives him sight.",sec={{t="The Enchanted Eye",b="Dizzy One-Eye lost both eyes in battle. Later, his ship docked at Menethil, where a traveling wizard made him an enchanted glass eye. It restored his sight, and Dizzy once kept watch from the crow’s nest. Without it, he feels useless.",sp=0},{t="Taken by the Buccaneers",b="Bloodsail Buccaneers ambushed Dizzy as he was leaving last night and took his eye. Their presence in Booty Bay troubles him. He fears the captain will keelhaul him when the eye’s fate comes out. A lookout who cannot see may be fit only to scrub the bilge, he reckons. So he asks you to get the eye back from the Bloodsail Buccaneers.",sp=0}},faq={{q="Who is Dizzy One-Eye?",a="Dizzy One-Eye is an old sea dog in Booty Bay who worked as a lookout. He lost both eyes in battle and sees through an enchanted glass eye.",al={"dizzy one eye","who gives keep an eye out","who is dizzy"}},{q="Where did Dizzy get the magical eye?",a="Dizzy’s ship docked at Menethil, where a traveling wizard made him an enchanted glass eye. It restored his sight.",al={"how did dizzy get his eye","dizzy enchanted eye origin","glass eye wizard"}},{q="Who took Dizzy's eye?",a="Bloodsail Buccaneers. They ambushed Dizzy last night as he was leaving, and took his eye.",al={"who stole the eye","who took dizzy eye","who has dizzy eye"}},{q="What does Dizzy fear will happen without the eye?",a="Dizzy fears the captain will keelhaul him when the eye’s fate comes out. He reckons a lookout who cannot see may be fit only to scrub the bilge.",al={"what happens if dizzy loses eye","dizzy captain penalty"}}},kw={"bloodsail","booty bay","buccaneers","dizzy","glass eye","menethil","one-eye","stranglethorn"},rel={"subzone:booty-bay","quest:595","zone:stranglethorn"},m={start="Dizzy One-Eye",["end"]="Dizzy One-Eye",level="42",id=576},src={"Classic quest text: Keep An Eye Out"}}
E["quest:577"] = {t="quest",n="Some Assembly Required",z="stranglethorn",s="In Booty Bay, Drizzlik says the Excelsior boots are coming along, but the skins you brought will not cover their insides. He plans to use cheaper, thicker hides from crocolisks near Lake Nazferiti for those hidden layers.",h="In Booty Bay, Drizzlik says the Excelsior boots are coming along, but the skins you brought will not cover...",sec={{t="Filling the Boots",b="Drizzlik says the Excelsior boots are coming along nicely. The skins from Supply and Demand will not cover their insides. Since no one will see those layers, he plans to use thicker, cheaper hides from the crocolisks near Lake Nazferiti.",sp=0},{t="The Sales Pitch",b="Drizzlik promises fine workmanship and boots made of pure, top-grade saltwater crocolisk hide. He compares the boots to sausages: they look and taste great, and are said to hold only the finest ingredients. Trusting the maker without looking too closely at what is inside may be safer and more enjoyable.",sp=1}},faq={{q="Who is asking for these skins?",a="Drizzlik in Booty Bay is working on the Excelsior boots. He needs more skins after those delivered in Supply and Demand.",al={"quest giver","who gives some assembly required","drizzlik location"}},{q="What skins does Drizzlik need?",a="Drizzlik needs five snapjaw crocolisk skins.",al={"what hides do i need","crocolisk skin type","which crocs"}},{q="Where are the required crocolisks found?",a="Drizzlik sends you to the crocolisks around Lake Nazferiti.",al={"lake nazferiti location","where are snapjaws","where to find crocs"}},{q="Why does Drizzlik want cheaper skins?",a="The insides of the boots stay hidden from every eye. So Drizzlik is willing to fill them with thicker, cheaper skins.",al={"why cheaper skins","why snapjaw hides","boot padding"}}},kw={"boots","booty bay","crocolisk","drizzlik","lake nazferiti","snapjaw","stranglethorn vale"},rel={"quest:575","quest:628","subzone:booty-bay","subzone:lake-nazferiti","zone:stranglethorn"},m={start="Drizzlik",["end"]="Drizzlik",level="36",id=577},src={"Classic quest text: Some Assembly Required"}}
E["quest:578"] = {t="quest",n="The Stone of the Tides",z="stranglethorn",s="Off Stranglethorn Vale, strange reports from an island reach Baron Revilgaz. He suspects an ancient troll relic has resurfaced and sends you to scout the shore, with a pass to study it in Stormwind's archives.",h="Off Stranglethorn Vale, strange reports from an island reach Baron Revilgaz.",sec={{t="A Magnate's Ambition",b="Strange apparitions and water elementals haunt an island off Stranglethorn Vale. Baron Revilgaz rules Booty Bay and suspects Gazban, a goblin mage, has found the fabled Stone of the Tides. He sends you to find the island and learn whether the rumors are true. To aid your search, he gives you a library scrip for Stormwind's scholars.",sp=0},{t="An Ancient Ward",b="The strange presence on the isle confirms Baron Revilgaz's hope: the legendary artifact is real. Claiming it will be difficult. The Stone of the Tides bears a powerful magical curse, and Revilgaz cannot break it alone. An experienced wizard must help before anyone can recover the relic.",sp=1}},faq={{q="Who asks you to locate the haunted island?",a="Baron Revilgaz, ruler of Booty Bay, sends you to find the island after hearing tales of strange activity off the coast.",al={"who gives the quest","quest giver stone of the tides","who sends you"}},{q="Where is the haunted island located?",a="The island lies at sea off the coast of Stranglethorn Vale, and you must find it yourself.",al={"where is the island","island location","find haunted island"}},{q="What is the Stone of the Tides?",a="The Stone of the Tides is a legendary troll artifact Revilgaz hopes to add to his collection. He first read of its legend in an old book.",al={"what is the stone","stone of tides lore","what is stone of the tides"}},{q="Why does Baron Revilgaz want the artifact?",a="Baron Revilgaz wants the powerful troll relic for his collection of ancient artifacts and relics.",al={"why does revilgaz want it","revilgaz motives"}},{q="What is the Library Scrip used for?",a="You can take the scrip to Donyal Tovald at the Stormwind Library and receive a copy of the book where the baron first read of the legend.",al={"what is library scrip","stormwind library scrip","where do i take the scrip"}},{q="What was the previous step in this chain?",a="The Haunted Isle came before this investigation and first brought word of the strange sightings to Baron Revilgaz.",al={"what quest comes before","prerequisite quest"}}},kw={"baron revilgaz","booty bay","donyal tovald","gazban","gurubashi","stone of the tides","stormwind library","stranglethorn vale"},rel={"quest:616","quest:601","npc:baron-revilgaz","quest:579","npc:donyal-tovald","subzone:booty-bay","subzone:grom-gol-base-camp","zone:stranglethorn"},m={start="Baron Revilgaz",["end"]="Baron Revilgaz",level="37",faction="Alliance",id=578},src={"The Stone of the Tides (quest)"}}
E["quest:580"] = {t="quest",n="Whiskey Slim's Lost Grog",z="stranglethorn",s="In Booty Bay, Whiskey Slim needs twelve bottles of Pupellyverbos Port back before his ship sails. His crew seized the crate from a privateer, and he fears a flogging if his commanding officer finds it missing.",h="In Booty Bay, Whiskey Slim needs twelve bottles of Pupellyverbos Port back before his ship sails.",sec={{t="A Tempest off the Hinterlands",b="Off the Overlook Cliffs, Whiskey Slim's ship was caught in severe weather with the Hinterlands shore nearby. The crew had seized a crate of Pupellyverbos Port from a privateer bound for Stormwind. As waves threatened to swallow the ship, Slim broke into the captain's crate for courage. Then a sudden surge swept the bottles overboard.",sp=0},{t="A Sailor's Desperation",b="Back in Booty Bay, Whiskey Slim's ship is preparing to weigh anchor. He fears the cat-o'-nine-tails when his commanding officer discovers the confiscated port is missing. Slim needs someone to bring back twelve bottles before his theft comes to light.",sp=0}},faq={{q="Who is Whiskey Slim?",a="Whiskey Slim is a sailor in Booty Bay who lost his captain's stolen alcohol during a sea squall and now fears punishment.",al={"whiskey slim","who gives lost grog","who is slim"}},{q="Where did the grog come from?",a="Slim's crew seized a crate of Pupellyverbos Port from a privateer vessel bound for Stormwind.",al={"pupellyverbos port origin","where did slim get the grog","privateer booze"}},{q="Where did Whiskey Slim lose the bottles?",a="Slim lost the bottles overboard during a fierce storm off the Overlook Cliffs, near the Hinterlands coast, when a massive wave struck the ship.",al={"where was grog lost","overlook cliffs storm","hinterlands grog location"}},{q="Why does Whiskey Slim need the bottles back so quickly?",a="Slim's ship is preparing to depart. He fears a flogging with the cat-o'-nine-tails once his captain discovers the port is missing.",al={"why help slim","what happens to slim","taste of the cat"}}},kw={"booty bay","grog","hinterlands","overlook cliffs","privateer","pupellyverbos port","stormwind","whiskey slim"},rel={"subzone:booty-bay","zone:stranglethorn","topic:stormwind-kingdom"},m={start="Whiskey Slim",["end"]="Whiskey Slim",level="50",id=580,ri={"Pupellyverbos Port"}},src={"Whiskey Slim's Lost Grog"}}
E["quest:581"] = {t="quest",n="Hunt for Yenniku",z="stranglethorn",s="At Grom'gol Base Camp, Nimboya searches for Yenniku, the youngest son of his chieftain. He suspects the Bloodscalp tribe holds the boy and asks you to prove your strength by hunting their warriors and bringing back their tusks.",h="At Grom'gol Base Camp, Nimboya searches for Yenniku, the youngest son of his chieftain.",sec={{t="A Chieftain's Lost Son",b="At Grom'gol Base Camp, Nimboya fears a grim fate for Yenniku, the youngest son of the Darkspear chieftain. An old tribal custom placed the boy among the Gurubashi trolls of Zul'Gurub. When the Darkspear tribe left their homeland with the orc warchief Thrall, Yenniku was left behind and lost. Nimboya has returned from Orgrimmar to Stranglethorn Vale to find the chieftain's son and bring him to safety.",sp=0},{t="Hunting the Bloodscalps",b="Nimboya suspects the Bloodscalp tribe holds Yenniku. To prove you are strong enough to hunt them, he sends you north to gather nine tusks from Bloodscalp trolls. Bring the trophies back to Grom'gol Base Camp as proof of your strength in battle. Then the search for the chieftain's boy can continue with Headhunting.",sp=0}},faq={{q="Who is Yenniku?",a="Yenniku is the youngest son of the Darkspear chieftain. Tribal custom placed him among the Gurubashi trolls in Zul'Gurub, and he became separated from his people when they left the region.",al={"yenniku lore","who is yenniku","chieftain son"}},{q="Why was Yenniku left behind in Stranglethorn?",a="Tribal custom sent Yenniku to the Gurubashi trolls of Zul'Gurub. When the Darkspear tribe left with Thrall, the boy was lost to them.",al={"why did yenniku stay","how was yenniku lost","why zul'gurub"}},{q="Who is Nimboya?",a="Nimboya is a Darkspear troll at Grom'gol Base Camp. He returned from Orgrimmar to Stranglethorn Vale to search for his chieftain's lost son.",al={"who gives hunt for yenniku","nimboya","grom'gol scout"}},{q="Why do you need to collect Bloodscalp tusks?",a="Nimboya suspects the Bloodscalp tribe holds Yenniku. He asks you to bring back nine Bloodscalp tusks as proof that you are strong enough to hunt these hostile trolls.",al={"bloodscalp tusks purpose","why tusks","hunt for yenniku tusks"}},{q="Where are the Bloodscalp trolls located?",a="Nimboya sends hunters north from Grom'gol Base Camp into Bloodscalp territory.",al={"where to find bloodscalps","bloodscalp location","where are bloodscalp trolls"}}},ang={["race:Troll"]="As a Darkspear troll, you can answer Nimboya's call by aiding your chieftain's family and hunting the Bloodscalps who may hold Yenniku.",["faction:Horde"]="As a Horde ally at Grom'gol Base Camp, you can help Nimboya protect the Darkspear chieftain's kin. He came from Orgrimmar to search for the boy."},kw={"bloodscalp","darkspear","grom'gol","hunt for yenniku","nimboya","stranglethorn","tusks","yenniku","zul'gurub"},rel={"subzone:grom-gol-base-camp","topic:darkspear-tribe","zone:stranglethorn","subzone:zul-gurub","npc:thrall","zone:orgrimmar","topic:troll"},m={start="Nimboya",["end"]="Nimboya",level="34",faction="Horde",id=581,ri={"Bloodscalp Tusk"}},src={"Hunt for Yenniku (Classic)","In-game quest text: Hunt for Yenniku"}}
E["quest:582"] = {t="quest",n="Headhunting",z="stranglethorn",s="At Grom'gol Base Camp, Nimboya seeks news of Yenniku, the Darkspear chieftain's son. He sends you to hunt Bloodscalp headhunters and bring back their shrunken heads, hoping to learn whether Yenniku is dead.",h="At Grom'gol Base Camp, Nimboya seeks news of Yenniku, the Darkspear chieftain's son.",sec={{t="Searching the Trophies",b="Nimboya fears the Bloodscalp tribe may have killed Yenniku, the Darkspear chieftain's son. The search began with Hunt for Yenniku, and now he sends you after Bloodscalp Headhunters at the ruins of Zuuldaia and Zul'Kunda along Stranglethorn Vale's northern coast.\n\nBring back twenty shrunken heads. Nimboya will inspect them for signs that Yenniku met a violent end. If the youth is dead, Nimboya curses Gan'zulah, chief of the Bloodscalp.",sp=0}},faq={{q="Who is looking for Yenniku?",a="Nimboya at Grom'gol Base Camp searches for Yenniku, the son of the Darkspear tribe's chieftain.",al={"who gives headhunting","nimboya purpose","why find yenniku"}},{q="Why does Nimboya want shrunken heads?",a="Nimboya will inspect shrunken heads taken from Bloodscalp headhunters to learn whether Yenniku's head is among their trophies.",al={"why collect shrunken heads","shrunken head purpose","what does nimboya do with heads"}},{q="Where can the Bloodscalp Headhunters be found?",a="Bloodscalp Headhunters gather along Stranglethorn Vale's northern coast, especially around the ruins of Zuuldaia and Zul'Kunda.",al={"headhunter location","where are zuuldaia and zulkunda","where to find shrunken heads"}},{q="Who leads the Bloodscalp tribe mentioned here?",a="Chief Gan'zulah leads the Bloodscalp tribe. If Yenniku is dead, Nimboya wishes a six-hundred-year curse upon Gan'zulah's spirit.",al={"bloodscalp chief","who is ganzulah","ganzulah chief"}}},ang={["race:Troll"]="As a troll, you share the Darkspear's concern for the chieftain's son. The Darkspear must face the Bloodscalp tribe to learn what happened to him.",["faction:Horde"]="As a member of the Horde, you help your Darkspear allies at Grom'gol Base Camp discover whether their chieftain's missing son still lives."},kw={"bloodscalp","gan'zulah","grom'gol base camp","headhunting","nimboya","shrunken head","yenniku","zul'kunda","zuuldaia"},rel={"subzone:grom-gol-base-camp","quest:584","zone:stranglethorn"},m={start="Nimboya",["end"]="Nimboya",level="37",faction="Horde",id=582,ri={"Shrunken Head"}},src={"Headhunting (Classic)"}}
E["quest:583"] = {t="quest",n="Welcome to the Jungle",z="stranglethorn",s="In Stranglethorn Vale, Barnil Stonepot welcomes newcomers to the hunting camp and spots a seasoned wanderer. He offers to introduce you to Hemet Nesingwary, the expedition's leader.",h="In Stranglethorn Vale, Barnil Stonepot welcomes newcomers to the hunting camp and spots a seasoned wanderer.",sec={{t="An Audience with the Master",b="Barnil Stonepot greets newcomers at the camp in Stranglethorn Vale. He spots seasoned fighters and points out Hemet Nesingwary, an Alliance war hero and peerless tracker. Nesingwary keeps company with veterans who have proved themselves. Barnil thinks the old marksman may share his hunting wisdom with someone who has endured battle.",sp=0},{t="The Trials of the Expedition",b="Hemet Nesingwary welcomes you and remarks how rare it is to meet someone of your calling in these wild lands. His expedition came to hunt a legendary, elusive jungle beast. He will include you in the chase once you earn his trust by hunting lesser quarry. Nesingwary oversees the raptor hunt. His comrades Ajeck and Sir Erlgadin teach hunters to pursue tigers and panthers.",sp=1}},faq={{q="Who is Hemet Nesingwary?",a="Hemet Nesingwary is a celebrated Alliance war veteran and renowned big game hunter. He leads an expedition camp in Stranglethorn Vale's jungles.",al={"hemet nesingwary","who is hemet","nesingwary lore"}},{q="Who sends you to speak with Nesingwary?",a="Barnil Stonepot, at the jungle encampment, directs seasoned adventurers to greet Nesingwary after recognizing their combat experience.",al={"barnil stonepot","quest giver","who starts welcome to the jungle"}},{q="What comes after speaking with Nesingwary?",a="After you speak with Nesingwary, several hunts open up: Raptor Mastery, Tiger Mastery, Panther Mastery and The Green Hills of Stranglethorn.",al={"how to join the hunt","nesingwary trials","hunting lessons"}}},ang={["class:Hunter"]="As a hunter in Stranglethorn's jungles, you may find Hemet Nesingwary has hunting pointers to share.",["faction:Alliance"]="As an Alliance veteran, you learn from Barnil Stonepot that Hemet Nesingwary is a renowned war hero who favors fellow veterans.",["race:Dwarf"]="As a dwarf, you share a race with the camp's famed hunter, Hemet Nesingwary. Barnil Stonepot points him out as a master big game hunter."},kw={"barnil","hemet","nesingwary","panther","raptor","stonepot","stranglethorn","tiger"},rel={"quest:5762","zone:stranglethorn","quest:194","quest:185","quest:190","quest:338","topic:alliance","topic:hunter"},m={start="Barnil Stonepot",["end"]="Hemet Nesingwary",level="30",faction="Neutral",id=583},src={"Welcome to the Jungle (Classic)"}}
E["quest:584"] = {t="quest",n="Bloodscalp Clan Heads",z="stranglethorn",s="Nimboya still seeks word of Yenniku after the trophies are sorted. The young troll is missing, so the Darkspear turn to the Bloodscalp Clan Heads for answers.",h="Nimboya still seeks word of Yenniku after the trophies are sorted.",sec={{t="Demanding Answers from the Dead",b="Nimboya seeks answers from the Bloodscalp leaders. The earlier hunt found no sign of Yenniku among the fallen. Gan'zulah, the Bloodscalp chief, and Nezzliok the Dire, his witch doctor, are enemies of the Darkspear. Neither would speak willingly. So Nimboya plans to bring their heads to the cauldron at Grom'gol Base Camp and force the truth from their dead lips.",sp=0},{t="Into Zul'Kunda",b="Gan'zulah and Nezzliok dwell deep in the ruins of Zul'Kunda in northwestern Stranglethorn Vale. Nimboya means to cast their heads into the boiling brew and make them speak about Yenniku.",sp=0}},faq={{q="Why does Nimboya want the heads of Gan'zulah and Nezzliok?",a="Yenniku remains missing, and Nimboya believes Gan'zulah and Nezzliok know the truth. They are enemies of the Darkspear and would never speak willingly, so he plans to force answers from them through the cauldron.",al={"why kill bloodscalp leaders","why severed heads","nimboya motivation"}},{q="Where are Gan'zulah and Nezzliok located?",a="Gan'zulah and Nezzliok dwell deep within Zul'Kunda, a ruin in northwestern Stranglethorn Vale, close to the beach.",al={"where is ganzulah","where is nezzliok","find bloodscalp chiefs","zulkunda location"}},{q="What happens once the heads are delivered?",a="The severed heads go into the bubbling cauldron at Grom'gol Base Camp. There, Nimboya means to make the two leaders speak.",al={"where do the heads go","what do i do with the heads","bubbling cauldron turn in"}},{q="How does this connect to the search for Yenniku?",a="The search began with young Yenniku. The earlier hunt found no sign of him among the common dead, so the Darkspear now seek answers from the Bloodscalp leaders to learn where he is.",al={"yenniku questline","hunt for yenniku connection"}}},ang={["race:Troll"]="As a Darkspear, you face the leaders of an enemy tribe when you confront the Bloodscalp chiefs.",["faction:Horde"]="As a member of the Horde, you lend your strength at Grom'gol Base Camp to the Darkspear search for Yenniku."},kw={"bloodscalp","cauldron","darkspear","gan'zulah","grom'gol","nezzliok","nimboya","yenniku","zul'kunda"},rel={"subzone:grom-gol-base-camp","quest:581","topic:darkspear-tribe","topic:troll","zone:stranglethorn"},m={start="Nimboya",["end"]="Bubbling Cauldron",level="41",faction="Horde",id=584,ri={"Gan'zulah's Head","Nezzliok's Head"}},src={"Bloodscalp Clan Heads"}}
E["quest:585"] = {t="quest",n="Speaking with Nezzliok",z="stranglethorn",s="At Grom'gol Base Camp, Nezzliok's severed head speaks from a bubbling cauldron. The Bloodscalp witch doctor knows where Yenniku was taken, but demands a grim tribute before he tells you.",h="At Grom'gol Base Camp, Nezzliok's severed head speaks from a bubbling cauldron.",sec={{t="A Spirit's Price",b="Nezzliok remains bound in the bubbling cauldron after the hunt for Bloodscalp Clan Heads. He knows where Yenniku was taken, but gives up nothing freely. Bring three trophy skulls from the rival Skullsplitter tribe to his resting place. Then his departed spirit can command thralls in the Nether.",sp=0},{t="Skulls of the Rivals",b="Nezzliok demands one skull from the Skullsplitter trophy pile at Balia'mah, one from Ziata'jai, and one from Zul'Mamwe. All three offerings must lie beside his own head before the dead witch doctor will consider his spirit satisfied.",sp=0}},faq={{q="Who is Nezzliok?",a="Nezzliok was a witch doctor of the Bloodscalp tribe. After he fell in battle, his severed head was placed in a bubbling cauldron at Grom'gol Base Camp. His bound spirit still speaks there.",al={"nezzliok","witch doctor nezzliok","nezzliok lore"}},{q="What does Nezzliok demand?",a="Nezzliok demands three trophy skulls from the camps of his hated rivals, the Skullsplitters. Take one from Balia'mah, one from Ziata'jai, and one from Zul'Mamwe.",al={"what does nezzliok want","nezzliok trophies","speaking with nezzliok objective"}},{q="Why does Nezzliok want Skullsplitter trophies?",a="Nezzliok wants the trophy skulls placed beside him so that, when his spirit passes into the Nether, he will have three servants bound to him in death.",al={"why trophy skulls","why nezzliok wants skulls"}},{q="Where does this happen?",a="The encounter takes place at the bubbling cauldron in Grom'gol Base Camp, deep in Stranglethorn Vale.",al={"where is nezzliok","bubbling cauldron location"}}},ang={["faction:Horde"]="As a member of the Horde, you bargain with a bound enemy spirit at Grom'gol Base Camp to learn what happened to Yenniku, the son of the Darkspear chieftain.",["race:Troll"]="As a Darkspear troll, you bargain with the severed head of a hostile Bloodscalp witch doctor to learn what became of your chieftain's stolen son."},kw={"balia'mah","bloodscalp","cauldron","grom'gol","nezzliok","skullsplitter","stranglethorn","yenniku","ziata'jai","zul'mamwe"},rel={"quest:584","quest:586","quest:588","subzone:grom-gol-base-camp","topic:darkspear-tribe","zone:stranglethorn"},m={start="Bubbling Cauldron",["end"]="Bubbling Cauldron",level="40",faction="Horde",id=585,ri={"Balia'mah Trophy","Ziata'jai Trophy","Zul'Mamwe Trophy"}},src={"Speaking with Nezzliok (Classic)"}}
E["quest:586"] = {t="quest",n="Speaking with Gan'zulah",z="stranglethorn",s="At Grom'gol Base Camp, Gan'zulah curses those who stand over the bubbling pot. The Bloodscalp chieftain demands the deaths of his Skullsplitter rivals and the ruin of their ruler, Ana'thek the Cruel.",h="At Grom'gol Base Camp, Gan'zulah curses those who stand over the bubbling pot.",sec={{t="A Chieftain's Vengeance",b="Gan'zulah's severed head curses anyone who stands over the bubbling pot. Though dead, the Bloodscalp chieftain still hates his captors and ancestral enemies. He points you east toward the Skullsplitter stronghold and demands the deaths of its hunters, headhunters, and berserkers. Their ferocious warband may kill those who dare face it.",sp=0},{t="The Broken Armor",b="Gan'zulah expects the assault to end in disaster. He believes Chief Ana'thek the Cruel will tear apart any intruder who challenges him. Still, he demands Ana'thek's shattered armor as proof of triumph. Bring that trophy back to the cauldron at Grom'gol Base Camp to satisfy Gan'zulah's spite.",sp=0},{t="An Uneasy Peace",b="Gan'zulah falls silent when Ana'thek's shattered armor is brought before him. His rival's defeat at last eases the Bloodscalp chieftain's vengeful rage. He recognizes the strength it took to defeat Ana'thek, but vows their reckoning is only delayed. Gan'zulah swears they will clash again in the Nether.",sp=1}},faq={{q="Where does Gan'zulah want you to go?",a="Gan'zulah sends you east into Skullsplitter territory, where their fighters gather under Ana'thek the Cruel.",al={"where are the skullsplitters","where to go speaking with ganzulah","skullsplitter location"}},{q="Who is Ana'thek the Cruel?",a="Ana'thek the Cruel leads the Skullsplitter trolls and is a hated rival of Gan'zulah and the Bloodscalp tribe.",al={"who is anatek","who is the skullsplitter chief","anatek the cruel lore"}},{q="Why is Gan'zulah able to talk?",a="Gan'zulah's severed head rests in the enchanted cauldron at Grom'gol Base Camp. From beyond death, his spirit voices curses and demands.",al={"how is ganzulah talking","why is the head talking","ganzulah cauldron"}},{q="What trophy does Gan'zulah demand?",a="Gan'zulah demands Chief Ana'thek the Cruel's broken armor and the deaths of the Skullsplitter hunters, headhunters, and berserkers.",al={"what item does ganzulah need","broken armor of anatek","ganzulah turn in item"}},{q="What comes next after helping Gan'zulah?",a="After the tribal chieftains are dealt with, you continue the search with The Fate of Yenniku to learn what became of the young Darkspear troll.",al={"what follows speaking with ganzulah","next quest after ganzulah","speaking with ganzulah follow up"}}},ang={["faction:Horde"]="Gan'zulah's head rests in the cauldron at Grom'gol Base Camp. He sends Horde champions against his Skullsplitter enemies.",["race:Troll"]="As a Darkspear troll, you see the Bloodscalp and Skullsplitter chieftains turn their undying hatred against each other. Their feud shows the jungle's brutality."},kw={"ana'thek","berserker","bloodscalp","cauldron","gan'zulah","grom'gol","headhunter","skullsplitter","stranglethorn"},rel={"quest:584","quest:585","quest:588","subzone:grom-gol-base-camp","subzone:ruins-of-zul-mamwe","zone:stranglethorn"},m={start="Bubbling Cauldron",["end"]="Bubbling Cauldron",level="46",faction="Horde",id=586,ri={"Broken Armor of Ana'thek"}},src={"Speaking with Gan'zulah"}}
E["quest:587"] = {t="quest",n="Up to Snuff",z="stranglethorn",s="In Booty Bay, Deeg is waiting for the snuff he likes, but the herbalist has none to sell. Bloodsail Raiders are said to have taken the shipment, and Deeg asks you to bring him fifteen shares.",h="In Booty Bay, Deeg is waiting for the snuff he likes, but the herbalist has none to sell.",sec={{t="Vices Ashore",b="Deeg knows life at sea may be poor, yet it is the only life he has. Whenever he reaches port, he looks for grog and fine snuff.\n\nThe Booty Bay herbalist has run out. The herbalist says Bloodsail Raiders hijacked the shipment, so Deeg hopes a fearless traveler can persuade them to share it. He wants fifteen shares of snuff.",sp=0},{t="Deeg's Thanks",b="Deeg is delighted when the snuff arrives just before he ships out. He thanks you warmly, as he would an old friend.",sp=1}},faq={{q="Who is Deeg?",a="Deeg is a pirate in Booty Bay who looks for grog and fine snuff whenever he comes to port.",al={"deeg booty bay","who gives up to snuff"}},{q="Why is the herbalist out of snuff?",a="The Booty Bay herbalist says Bloodsail Raiders hijacked the shipment of snuff.",al={"why no snuff","herbalist shipment hijacked"}},{q="Who has the snuff?",a="The herbalist says Bloodsail Raiders hijacked the shipment, and Deeg hopes you can persuade them to share it.",al={"who took the snuff","bloodsail snuff"}},{q="How much snuff does Deeg want?",a="Deeg wants fifteen shares of snuff brought to him in Booty Bay.",al={"how many snuff","up to snuff requirement"}}},kw={"bloodsail","booty bay","deeg","grog","herbalist","snuff"},rel={"subzone:booty-bay","zone:stranglethorn","topic:pirate"},m={start="Deeg",["end"]="Deeg",level="41",id=587},src={"Classic quest text: Up to Snuff"}}
E["quest:588"] = {t="quest",n="The Fate of Yenniku",z="stranglethorn",s="At Grom'gol Base Camp, Nezzliok's head speaks of Yenniku from the cauldron. Kin'weelay waits beside it for the spirit's words.",h="At Grom'gol Base Camp, Nezzliok's head speaks of Yenniku from the cauldron.",sec={{t="Words from the Kettle",b="You've appeased the spirits of Gan'zulah and Nezzliok. Now Nezzliok's head speaks from the bubbling cauldron. Kin'weelay waits beside it to hear the secret.",sp=0},{t="What the Head Revealed",b="Nezzliok names Zanzil the Outcast, a witch doctor, as the one who took Yenniku from his clan. Strong magic alone can free the boy from Zanzil's binding. Kin'weelay hears the words, with only a faint hope left.",sp=1}},faq={{q="Who reveals Yenniku's whereabouts?",a="Nezzliok's head speaks through the bubbling cauldron and tells what happened to Yenniku.",al={"who speaks from cauldron","who reveals fate of yenniku","cauldron voice"}},{q="Who should be informed of Nezzliok's words?",a="Kin'weelay waits beside the bubbling cauldron at the northern edge of Grom'gol Base Camp. Nezzliok's words are meant for Kin'weelay.",al={"who do i talk to","turn in fate of yenniku","kin'weelay location"}}},ang={["faction:Horde"]="As a member of the Horde, you know the Darkspear tribe and its allies at Grom'gol Base Camp care deeply about recovering the chief's son."},kw={"cauldron","grom'gol","kin'weelay","nezzliok","yenniku","zanzil"},rel={"npc:kin-weelay","quest:589","subzone:grom-gol-base-camp","zone:stranglethorn","topic:troll"},m={start="Bubbling Cauldron",["end"]="Kin'weelay",level="45",faction="Horde",id=588},src={"The Fate of Yenniku"}}
E["quest:589"] = {t="quest",n="The Singing Crystals",z="stranglethorn",s="Kin'weelay seeks a way to free Yenniku from the darkness holding him. He turns to the Mind's Eye and asks you to gather shards that may help him command its power.",h="Kin'weelay seeks a way to free Yenniku from the darkness holding him.",sec={{t="Echoes of the Mind's Eye",b="Kin'weelay searches old jungle lore for a way to free Yenniku's spirit. The tales speak of the Mind's Eye, a gem hidden deep in Stranglethorn and mighty in magic. Kin'weelay believes it may hold the answer. As he seeks the jungle spirits' guidance to find it, he needs rare catalysts to control its sorcery safely.",sp=0},{t="The Crystalvein Caverns",b="Kin'weelay sends you southeast to Crystalvein Mine, where ironjaw basilisks dwell beneath the earth. He asks you to recover three pulsing blue shards from them. He plans to channel the magic in these singing stones during a final ritual. Once he has recovered the Mind's Eye, he means to bend its power to his will.",sp=0}},faq={{q="Who offers this task?",a="Kin'weelay, a troll medicine man at Grom'gol Base Camp in Stranglethorn Vale, offers this work.",al={"who gives the singing crystals","quest giver","where to start the singing crystals"}},{q="Why are the pulsing blue shards needed?",a="Kin'weelay needs the shards' magic to control the Mind's Eye. He hopes to use the powerful jewel to pull Yenniku back from the dark forces holding him.",al={"why do we need blue shards","what are the shards for","pulsing blue shard purpose"}},{q="Where can the ironjaw basilisks be found?",a="Ironjaw basilisks live inside Crystalvein Mine, southeast of Grom'gol Base Camp in the peaks east of the Gurubashi Arena.",al={"ironjaw basilisk location","where are ironjaw basilisks","where is crystalvein mine"}},{q="What came before this task?",a="The Fate of Yenniku came first and revealed the young troll's dire circumstances.",al={"singing crystals prequest","previous quest"}},{q="What is Kin'weelay doing while you gather the shards?",a="Kin'weelay communes with the jungle spirits to find where the Mind's Eye is hidden and learn what protects it.",al={"what is kinweelay doing","kinweelay role"}}},ang={["faction:Horde"]="As a member of the Horde, you aid the Darkspear tribe at Grom'gol Base Camp as they struggle to recover the lost son of their chief."},kw={"crystalvein mine","grom'gol","ironjaw basilisk","kin'weelay","mind's eye","pulsing blue shard","stranglethorn","yenniku"},rel={"quest:588","quest:591","npc:kin-weelay","subzone:crystalvein-mine","subzone:grom-gol-base-camp","zone:stranglethorn","subzone:gurubashi-arena"},m={start="Kin'weelay",["end"]="Kin'weelay",level="45",faction="Horde",id=589,ri={"Pulsing Blue Shard"}},src={"The Singing Crystals"}}
E["quest:591"] = {t="quest",n="The Mind's Eye",z="stranglethorn",s="At Grom'gol Base Camp, Kin'weelay seeks The Mind's Eye to save Yenniku. Mai'Zoth holds the gem deep in the Mosh'Ogg Ogre Mound.",h="At Grom'gol Base Camp, Kin'weelay seeks The Mind's Eye to save Yenniku.",sec={{t="A Powerful Gem",b="After the singing crystals are recovered, Kin'weelay turns to The Mind's Eye. He believes only the gem can help save Yenniku, son of the Darkspear chieftain. Mai'Zoth holds it. Kin'weelay remembers the ogre mage from the Darkspear tribe's earlier days in the jungle.",sp=0},{t="The Depths of Mosh'Ogg",b="Mai'Zoth dwells deep in the Mosh'Ogg Ogre Mound, east of Grom'gol. His magic was formidable before he took The Mind's Eye, and the stone has made him stronger still. The ogre stronghold is perilous. Yet the gem is the young troll's only hope of freedom.",sp=0},{t="Into the Nether",b="Mai'Zoth's defeat casts the ogre mage from the realm of flesh and bone into the Nether, Kin'weelay says. His physical threat has ended, but Kin'weelay quietly fears Mai'Zoth may build a new dominion in the spirit world. For now, those worries can wait. The witch doctor prepares the ritual to save Yenniku.",sp=1}},faq={{q="Who possesses the Mind's Eye?",a="Mai'Zoth holds The Mind's Eye deep inside the Mosh'Ogg Ogre Mound, east of Grom'gol Base Camp.",al={"who has minds eye","where is the minds eye","who drops the minds eye"}},{q="Why does Kin'weelay need the Mind's Eye?",a="Kin'weelay needs The Mind's Eye for a ritual he believes is the only way to save Yenniku, the lost son of the Darkspear chief.",al={"why do we need minds eye","purpose of minds eye","why get the minds eye"}},{q="Where does this stand in the search for Yenniku?",a="The search follows The Singing Crystals. Securing The Mind's Eye opens the way to Saving Yenniku.",al={"what quest comes before the minds eye","previous quest minds eye","what comes after singing crystals"}},{q="Who is Mai'Zoth?",a="Mai'Zoth is an ogre mage Kin'weelay knew from the time the Darkspear trolls lived in the jungle. His formidable magic grew stronger with The Mind's Eye.",al={"who is maizoth","about maizoth","maizoth lore"}}},ang={["race:Troll"]="As a troll, you need The Mind's Eye to help free Yenniku, son of the Darkspear chieftain.",["faction:Horde"]="As a member of the Horde, you help the Darkspear trolls strike at the Mosh'Ogg stronghold from Grom'gol Base Camp."},kw={"darkspear","grom'gol","kin'weelay","mai'zoth","mind's eye","mosh'ogg","ogre mound","yenniku"},rel={"quest:589","quest:592","npc:kin-weelay","quest:206","subzone:mosh-ogg-ogre-mound","subzone:grom-gol-base-camp","zone:stranglethorn","topic:mage"},m={start="Kin'weelay",["end"]="Kin'weelay",level="46",faction="Horde",id=591,ri={"Mind's Eye"}},src={"The Mind's Eye (Classic)"}}
E["quest:592"] = {t="quest",n="Saving Yenniku",z="stranglethorn",s="Kin'weelay has found a way to bring Yenniku home from Zanzil the Outcast. He reshapes the recovered Mind's Eye into a soul gem that can stun Yenniku and hold his spirit until you take it to Nimboya.",h="Kin'weelay has found a way to bring Yenniku home from Zanzil the Outcast.",sec={{t="A Vessel for the Spirit",b="Kin'weelay turns the recovered Mind's Eye into a magical soul gem. Its enchantment lets you stun Yenniku and set the stone on his head to capture his spirit. With Yenniku's spirit inside, you can carry the gem safely to his kin at Grom'gol Base Camp.",sp=0},{t="The Outcast's Lair",b="Zanzil the Outcast holds Yenniku in the Ruins of Aboraz, along the Crystal Shore on the southern Cape of Stranglethorn. You enter Zanzil's territory and use the gem to break the witch doctor's hold over the young troll. Then you carry the filled gem back to Nimboya.",sp=0}},faq={{q="Who provides the Soul Gem for this task?",a="Kin'weelay makes the Soul Gem from the recovered Mind's Eye and gives it to you to capture Yenniku's spirit.",al={"who gives the soul gem","where do I get the soul gem","who starts saving yenniku"}},{q="Where is Yenniku located?",a="Yenniku is with Zanzil the Outcast at the Ruins of Aboraz, along the Crystal Shore on the Cape of Stranglethorn.",al={"where is yenniku","yenniku location","ruins of aboraz location"}},{q="How does the Soul Gem work?",a="The Soul Gem first stuns Yenniku. Then you place it on his head to draw his spirit inside.",al={"how to use soul gem","what does the soul gem do","soul gem stranglethorn"}},{q="Who receives the Filled Soul Gem once Yenniku is secured?",a="You deliver the Filled Soul Gem to Nimboya at Grom'gol Base Camp.",al={"where to turn in filled soul gem","who gets the gem","where to deliver yenniku"}}},ang={["race:Troll"]="As a troll, you help bring young Darkspear Yenniku back toward his people and free him from Zanzil the Outcast's vile magic.",["faction:Horde"]="As a Horde adventurer from Grom'gol Base Camp, you carry Nimboya's search for Yenniku to Zanzil at the Ruins of Aboraz."},kw={"aboraz","kin'weelay","nimboya","saving yenniku","soul gem","stranglethorn","yenniku","zanzil"},rel={"quest:591","quest:593","quest:581","npc:kin-weelay","subzone:ruins-of-aboraz","subzone:crystal-shore","subzone:cape-of-stranglethorn","zone:stranglethorn"},m={start="Kin'weelay",["end"]="Nimboya",level="46",faction="Horde",id=592,ri={"Filled Soul Gem"}},src={"Saving Yenniku (Classic)"}}
E["quest:593"] = {t="quest",n="Filling the Soul Gem",z="stranglethorn",s="In Stranglethorn Vale, you reach Yenniku while he remains caught in a trance. A prepared soul gem may preserve him by taking his spirit.",h="In Stranglethorn Vale, you reach Yenniku while he remains caught in a trance.",sec={{t="A Trance in the Jungle",b="Yenniku, the young troll you have tried to save, stands motionless before you in Stranglethorn Vale. His mind is far away. The enchanted gem prepared to hold his essence is the only path forward.",sp=0},{t="The Vessel",b="The soul gem pressed to Yenniku's forehead draws his spirit into the stone. His body shudders, then collapses as an empty, mindless shell.",sp=1}},faq={{q="What condition is Yenniku in when you reach him?",a="When you reach Yenniku, he is stunned and unresponsive, his thoughts held far from the world around him.",al={"yenniku status","what is wrong with yenniku","yenniku stunned"}},{q="What item is used on Yenniku?",a="You use a soul gem brought from Stranglethorn Vale on Yenniku.",al={"what item is needed","gem used on yenniku","yenniku item"}},{q="What came before this moment?",a="This moment follows the events of Saving Yenniku in the jungles of Stranglethorn Vale.",al={"previous quest","prereq for filling the soul gem","what leads to this"}}},kw={"saving yenniku","soul gem","stranglethorn vale","troll","yenniku"},rel={"quest:592","zone:stranglethorn"},m={start="None",["end"]="Yenniku",level="46",faction="Horde",id=593},src={"Filling the Soul Gem"}}
E["quest:594"] = {t="quest",n="Message in a Bottle",z="stranglethorn",s="Along Stranglethorn Vale's shore, Message in a Bottle bears a plea from someone held captive. The writer says a great beast keeps them on an isolated island in the South Seas.",h="Along Stranglethorn Vale's shore, Message in a Bottle bears a plea from someone held captive.",sec={{t="A Plea from the Waves",b="A plea for rescue rests in a glass container, half-buried in the sand. The captive is trapped beneath thick jungle canopies on a foreign island, held by a great Skymane. Wild Shore lies to the northwest through the trees. Large sailing vessels drift to the southwest.",sp=0},{t="The Writer of the Note",b="Across the water, the nautical directions point to an offshore isle where Princess Poobah waits. Stranded there, she is desperate for an adventurer to reach her and give her a chance at freedom.",sp=1}},faq={{q="What does the note in the bottle say?",a="The note is a neatly penned plea for rescue. Its writer says a great Skymane holds them prisoner on an island in the South Seas, and begs whoever finds the note to come to their aid.",al={"note contents","bottle note","what is written in the bottle"}},{q="Where does the writer say the island is located?",a="The captive says Wild Shore can be seen to the northwest on clear days, while large sailing vessels appear to the southwest. At night, jungle trees hide the stars.",al={"island location","how to find the captive","island landmarks"}},{q="What is holding the author captive?",a="The note says a creature called a great Skymane holds its writer prisoner on the island.",al={"who captured the author","what holds the author captive","skymane captor"}},{q="Does this lead to further adventures?",a="Finding the sender begins a two-part chain. The second part follows when you locate the captive.",al={"next quest","is there a follow up","what happens after this"}}},kw={"half-buried bottle","message in a bottle","princess poobah","skymane","south seas","stranglethorn vale","wild shore"},rel={"subzone:wild-shore","subzone:south-seas","zone:stranglethorn"},m={start="Half-Buried Bottle",["end"]="Princess Poobah",level="45",id=594},src={"Message in a Bottle (Classic)"}}
E["quest:595"] = {t="quest",n="The Bloodsail Buccaneers",z="stranglethorn",s="Along the Savage Coast, rumors of rival pirates trouble the newly arrived Blackwater Raiders. First Mate Crazz sends you to scout a cove while his crew drinks and seeks company in Booty Bay.",h="Along the Savage Coast, rumors of rival pirates trouble the newly arrived Blackwater Raiders.",sec={{t="A Scout along the Savage Coast",b="The Blackwater Raiders have just docked in Booty Bay when word reaches them of rivals across southern Stranglethorn Vale. The crew is busy with grog and company ashore, so First Mate Crazz asks you to go in their place. Head north along the Savage Coast and scout a cove for signs of what the Bloodsail Buccaneers are doing.",sp=0},{t="Signs in the Cove",b="In the cove, you find a barrel with a map resting on top. Hastily scribbled notes cover it, and some coins lie beside it.",sp=1}},faq={{q="Who is First Mate Crazz?",a="First Mate Crazz is an officer among the Blackwater Raiders in Booty Bay. Rumors of rival pirates are spreading, and his crew is busy ashore, so he hires passing adventurers to scout the coast.",al={"first mate crazz","who gives the quest","who is crazz"}},{q="Why does First Mate Crazz need an outsider?",a="The Blackwater crew has only just docked and is too busy carousing ashore to scout the coast themselves.",al={"why hire an adventurer","why cant his crew do it","why help crazz"}},{q="Where does Crazz send you to investigate?",a="Crazz sends you to a cove immediately north of Booty Bay, along the Savage Coast.",al={"where do i go","where is the cove","where are the bloodsail"}},{q="What rivalry is troubling the Blackwater Raiders?",a="The Blackwater Raiders are in a bitter feud with the Bloodsail Buccaneers, who have recently been seen across southern Stranglethorn Vale.",al={"who are the rivals","why do they hate bloodsail","bloodsail rivalry"}}},kw={"blackwater raiders","bloodsail buccaneers","booty bay","correspondence","first mate crazz","savage coast","stranglethorn vale"},rel={"subzone:booty-bay","subzone:savage-coast","zone:stranglethorn"},m={start="First Mate Crazz",["end"]="Bloodsail Correspondence",level="41",id=595},src={"The Bloodsail Buccaneers (Classic)"}}
E["quest:596"] = {t="quest",n="Bloody Bone Necklaces",z="stranglethorn",s="At Grom'gol Base Camp, Kin'weelay turns the Bloodscalp conflict into a private struggle.",h="At Grom'gol Base Camp, Kin'weelay turns the Bloodscalp conflict into a private struggle.",sec={{t="Trophies of War",b="Kin'weelay came to Grom'gol Base Camp to help Nimboya, yet he has purposes of his own. The Bloodscalp trolls to the north are enemies of the Darkspears. Kin'weelay believes trophies taken from fallen foes grant spiritual power over them. So he asks travelers to hunt Bloodscalp warriors and take the bloody bone necklaces they wear.",sp=0},{t="Leeching the Spirits",b="Kin'weelay plans to boil the bone necklaces and leech them down to paste. Through this ritual, he hopes to wither and weaken the lingering spirits of slain Bloodscalp.",sp=1}},faq={{q="Who asks for the bone necklaces?",a="Kin'weelay asks for the bone necklaces at Grom'gol Base Camp in Stranglethorn Vale. He came to aid Nimboya, yet pursues his own spiritual vendetta.",al={"quest giver","who gives bloody bone necklaces","kin'weelay quest"}},{q="Why does Kin'weelay want trophies from the Bloodscalp tribe?",a="The Bloodscalps are bitter enemies of the Darkspear tribe. Kin'weelay believes trophies from slain foes grant power over them, giving the Darkspears a way to assert dominance over their rivals.",al={"why collect necklaces","bloodscalp necklaces purpose","why hunt bloodscalp"}},{q="Where are the Bloodscalps located?",a="The Bloodscalp trolls dwell north of Grom'gol Base Camp, across northern Stranglethorn Vale.",al={"where to find bloodscalp","bloodscalp location","where are the trolls"}},{q="What comes next after this hunt?",a="After the hunt, Kin'weelay sends you on to Split Bone Necklace.",al={"next quest","bloody bone necklaces followup","what after bloody bone necklaces"}}},ang={["race:Troll"]="As a Darkspear, hunting the Bloodscalp means gaining power over an enemy tribe.",["faction:Horde"]="Kin'weelay came to Grom'gol Base Camp to aid Nimboya. He uses his time there to hunt the Bloodscalp to the north."},kw={"bloodscalp","darkspear","grom'gol","kin'weelay","necklaces","nimboya","stranglethorn"},rel={"npc:kin-weelay","subzone:grom-gol-base-camp","zone:stranglethorn","topic:troll"},m={start="Kin'weelay",["end"]="Kin'weelay",level="37",faction="Horde",id=596,ri={"Bloody Bone Necklace"}},src={"Bloody Bone Necklaces","In-game quest text: Bloody Bone Necklaces"}}
E["quest:597"] = {t="quest",n="The Bloodsail Buccaneers",z="stranglethorn",s="At Booty Bay, the Bloodsail Buccaneers’ plans now point to a camp and an attack signal.",h="At Booty Bay, the Bloodsail Buccaneers’ plans now point to a camp and an attack signal.",sec={{t="A Plot Revealed",b="A map marks the Bloodsail Buccaneers’ intended camp in Booty Bay with a red X. Their orders call for silence. The crew must kill anyone who approaches and wait for a signal from the southern command post before attacking.",sp=0},{t="Reporting to the Harbor",b="You carry the findings back to First Mate Crazz in Booty Bay. He sent you to scout, and the pirates are still waiting for the signal before they attack.",sp=0}},faq={{q="What is written on the Bloodsail correspondence?",a="The recovered Bloodsail Buccaneers correspondence orders the crew to camp quietly at the marked spot, kill anyone who approaches, and wait for a signal from their southern command post before attacking.",al={"bloodsail orders text","what does the note say","bloodsail map details"}},{q="Where does the map point?",a="A red X on the map of Booty Bay marks the pirates’ intended camp.",al={"bloodsail map x","what does the red x mean","where is the camp"}},{q="Who needs to hear about this discovery?",a="First Mate Crazz in Booty Bay needs to hear of the discovery. He sent you to scout the area.",al={"who do i turn this in to","who gets the bloodsail map","first mate crazz report"}},{q="What came before finding this correspondence?",a="First Mate Crazz first sent you from Booty Bay to investigate the Bloodsail Buccaneers.",al={"prerequisite quest","previous quest bloodsail","bloodsail chain start"}}},kw={"bloodsail buccaneers","bloodsail correspondence","booty bay","first mate crazz","southern command post","stranglethorn vale"},rel={"subzone:booty-bay","zone:stranglethorn"},m={start="Bloodsail Correspondence",["end"]="First Mate Crazz",level="41",id=597},src={"The Bloodsail Buccaneers (2)"}}
E["quest:598"] = {t="quest",n="Split Bone Necklace",z="stranglethorn",s="Kin'weelay at Grom'gol Base Camp sends you southeast to hunt the Skullsplitters. The Darkspears left Stranglethorn Vale, yet their old feud with these jungle rivals continues. Bring back twenty-five split bone trophies to aid the Darkspears and earn their friendship.",h="Kin'weelay at Grom'gol Base Camp sends you southeast to hunt the Skullsplitters.",sec={{t="An Unbroken Feud",b="After the Bloodscalp hunt, Kin'weelay turns to another old enemy. Southeast of Grom'gol Base Camp, the Skullsplitter tribe has fought the Darkspears for many years. The Darkspears no longer live in Stranglethorn Vale, yet they remain bound to this war.",sp=0},{t="Trophies of War",b="You travel into Skullsplitter territory to claim twenty-five split bone necklaces and earn the Darkspears' friendship and respect. Kin'weelay takes pride in seeing these hostile trolls cut down like young saplings by a basilisk. Each trophy you bring back counts as a victory for his people.",sp=0}},faq={{q="Who offers this hunt, and where is he located?",a="Kin'weelay offers the hunt from Grom'gol Base Camp, a Horde outpost on Stranglethorn Vale's western coast.",al={"who gives split bone necklace","kinweelay location","quest giver split bone necklace"}},{q="What came before this task?",a="This hunt follows Bloody Bone Necklaces, when Kin'weelay sent adventurers after trophies from the Bloodscalp tribe.",al={"split bone necklace prerequisite","prior quest to split bone necklace","previous step"}},{q="Why do the Darkspears fight the Skullsplitters if they left Stranglethorn Vale?",a="The Darkspears and Skullsplitters fought for years in the jungle. Though the Darkspears left Stranglethorn Vale, Kin'weelay says they remain bound to the conflict and mean to make their foes regret starting it.",al={"why darkspears hate skullsplitters","skullsplitter war lore","darkspear skullsplitter conflict"}},{q="Where can the Skullsplitter tribe be found?",a="The Skullsplitter tribe lives southeast of Grom'gol Base Camp in Stranglethorn Vale.",al={"skullsplitter location","where are skullsplitters","skullsplitter camps"}},{q="What proof does Kin'weelay demand from the hunt?",a="Kin'weelay asks for twenty-five Split Bone Necklaces taken from fallen Skullsplitter trolls.",al={"what items needed for kinweelay","split bone necklace item","how many necklaces"}}},ang={["faction:Horde"]="As a Horde ally, helping Kin'weelay at Grom'gol Base Camp in the war against the Skullsplitters earns the Darkspears' friendship.",["race:Troll"]="As a Darkspear troll, taking trophies from the Skullsplitters carries on a long war that did not end when your tribe left Stranglethorn."},kw={"darkspear","grom'gol base camp","kin'weelay","skullsplitter","split bone necklace","stranglethorn vale"},rel={"quest:596","npc:kin-weelay","subzone:grom-gol-base-camp","topic:troll","zone:stranglethorn"},m={start="Kin'weelay",["end"]="Kin'weelay",level="42",faction="Horde",id=598,ri={"Split Bone Necklace"}},src={"Split Bone Necklace (quest)"}}
E["quest:599"] = {t="quest",n="The Bloodsail Buccaneers",z="stranglethorn",s="First Mate Crazz has learned that the Bloodsail Buccaneers mean to strike Booty Bay. He sends you to warn Fleet Master Seahorn, commander of the Blackwater Raiders, before they move.",h="First Mate Crazz has learned that the Bloodsail Buccaneers mean to strike Booty Bay.",sec={{t="A Warning for the Fleet Master",b="First Mate Crazz sends you to warn Fleet Master Seahorn of an attack on Booty Bay. Crazz has learned the Bloodsail Buccaneers mean to strike the port directly, and the threat is greater than he first thought. Seahorn is somewhere in town. He must hear the warning before the rival pirates move.",sp=0},{t="Seahorn's Defiance",b="Fleet Master Seahorn dismisses the Bloodsail Buccaneers' plan to attack Booty Bay. He says it is as foolish as leaping from the Overlook Cliffs. Still, he sees the worth of your warning and thanks you on behalf of the Blackwater Raiders.",sp=1}},faq={{q="Who sends you to warn Fleet Master Seahorn?",a="First Mate Crazz sends you to warn Fleet Master Seahorn after learning how far the Bloodsail Buccaneers' hostile plans reach.",al={"who starts this quest","first mate crazz quest","bloodsail buccaneers quest giver"}},{q="Where can Fleet Master Seahorn be found?",a="Fleet Master Seahorn is in Booty Bay, the pirate haven in southern Stranglethorn Vale.",al={"where is seahorn","seahorn location","fleet master seahorn town"}},{q="What is the Bloodsail Buccaneers' scheme?",a="The Bloodsail Buccaneers are preparing an outright attack on Booty Bay, challenging the Blackwater Raiders' rule over the town.",al={"what are bloodsail doing","bloodsail attack plan","bloodsail buccaneers plot"}},{q="Which faction controls Booty Bay?",a="The Blackwater Raiders hold and operate Booty Bay, and fiercely protect the port from their Bloodsail rivals.",al={"who runs booty bay","booty bay pirates faction"}}},kw={"blackwater raiders","bloodsail bucaneers","booty bay","first mate crazz","fleet master seahorn","stranglethorn vale"},rel={"npc:fleet-master-seahorn","subzone:booty-bay","zone:stranglethorn","quest:595"},m={start="First Mate Crazz",["end"]="Fleet Master Seahorn",level="41",id=599},src={"The Bloodsail Buccaneers (3)"}}
E["quest:600"] = {t="quest",n="Venture Company Mining",z="stranglethorn",s="In northern Stranglethorn, the Venture Company keeps finding Singing Blue Crystals. Crank Fizzlebub in Booty Bay wants ten brought back from the hills near Crystalvein Mine.",h="In northern Stranglethorn, the Venture Company keeps finding Singing Blue Crystals.",sec={{t="Disrupting the Competition",b="You’ve gathered Singing Blue Shards, and now Crank Fizzlebub points you toward a larger rival. The Venture Company’s work across the jungle cuts into the profits of independent goblins. Basilisks keep its miners out of Crystalvein Mine, so they dig in the hills around it for Singing Blue Crystals. Crank asks you to take ten from the miners and bring them to Booty Bay as proof of their setback.",sp=0},{t="After the Crystals Arrive",b="Crank Fizzlebub calls his request righteous retribution against a ruthless cartel. When he sees the Singing Blue Crystals, his excitement gives away his true interest. He means to sell the stones in Booty Bay for a substantial fortune.",sp=1}},faq={{q="Who gives the Venture Company Mining quest?",a="Crank Fizzlebub, a goblin in Booty Bay, asks for your help after you complete Singing Blue Shards.",al={"who starts venture company mining","venture company mining questgiver"}},{q="Where are the miners digging for these crystals?",a="Venture Company miners dig in the hills around Crystalvein Mine in northern Stranglethorn Vale.",al={"where is venture company mining","venture company mine location stranglethorn"}},{q="Why aren't the Venture Company miners inside the mine?",a="Basilisks in Crystalvein Mine keep the Venture Company miners out, so they dig in the surrounding hills instead.",al={"why outside crystalvein mine","crystalvein mine basilisks"}},{q="What does Crank Fizzlebub ask you to bring him?",a="Crank Fizzlebub asks you to bring him ten Singing Blue Crystals taken from Venture Company miners near Crystalvein Mine.",al={"venture company mining items needed","what items for crank fizzlebub"}},{q="What came before Venture Company Mining?",a="Singing Blue Shards came first. Crank asks you to gather smaller crystal shards in Stranglethorn Vale.",al={"venture company mining chain","prerequisite for venture company mining"}}},kw={"booty bay","crank fizzlebub","crystalvein mine","singing blue crystals","stranglethorn vale","venture company"},rel={"quest:605","subzone:crystalvein-mine","topic:venture-company","subzone:booty-bay","topic:goblin","zone:stranglethorn"},m={start="Crank Fizzlebub",["end"]="Crank Fizzlebub",level="41",id=600,ri={"Singing Blue Crystal"}},src={"Venture Company Mining (Classic)"}}
E["quest:601"] = {t="quest",n="Water Elementals",z="stranglethorn",s="On the island off the coast, Water Elementals may offer a clue to the Stone of the Tides' curse. Baron Revilgaz wants their bracers examined for a way to counter it.",h="On the island off the coast, Water Elementals may offer a clue to the Stone of the Tides' curse.",sec={{t="Curbing the Curse",b="Baron Revilgaz suspects the Water Elementals' magical residue may help fight the Stone of the Tides' curse. The stone is said to make anyone who wields it drift in and out of reality. So he sends you back to the island off the coast to gather bracers for the scholarly mages of Dalaran to examine.",sp=0},{t="Booty Bay's Master",b="Baron Revilgaz admits he lacks the skill to judge whether the bracers can help. He refuses to leave Booty Bay just to speak with tiresome old mages. So he sends you north to have a mage examine them.",sp=0}},faq={{q="Who wants the water elemental bracers?",a="Baron Revilgaz, leader of the Blackwater Raiders in Booty Bay, wants the bracers examined for clues to the magic surrounding the Stone of the Tides.",al={"who gives water elementals quest","baron revilgaz quest","who wants bracers"}},{q="Why does Baron Revilgaz need elemental bracers?",a="Revilgaz hopes the bracers' magical residue will reveal how to counter the Stone of the Tides' curse. The curse makes its bearer fade in and out of existence.",al={"why collect bracers","water elemental bracers purpose","curse of the stone of the tides"}},{q="Who summoned these water elementals?",a="Baron Revilgaz believes Gazban, a goblin wizard said to have found the Stone of the Tides, conjured the Water Elementals.",al={"who summoned elementals","gazban lore","goblin wizard"}},{q="Where does this task lead next?",a="Revilgaz sends the bracers north to Dalaran, where a mage can examine their residue.",al={"what is after water elementals","next quest","where do bracers go"}},{q="Why doesn't Revilgaz take the bracers to Dalaran himself?",a="Revilgaz refuses to leave Booty Bay just to speak with tiresome old mages. He insists he has nothing to fear from would-be rivals.",al={"why doesnt revilgaz go","revilgaz dalaran","why stay in booty bay"}}},kw={"booty bay","bracers","curse","dalaran","gazban","revilgaz","stone of the tides","water elemental"},rel={"quest:578","quest:602","npc:baron-revilgaz","subzone:booty-bay","subzone:dalaran","topic:mage","topic:goblin","zone:stranglethorn"},m={start="Baron Revilgaz",["end"]="Baron Revilgaz",level="37",faction="Alliance",id=601,ri={"Water Elemental Bracers"}},src={"Water Elementals (Classic)"}}
E["quest:602"] = {t="quest",n="Magical Analysis",z="stranglethorn",s="From Booty Bay, Baron Revilgaz sends you north to Dalaran with water elemental bracers. He hopes Archmage Ansirem Runeweaver can study the curse tied to the Stone of the Tides.",h="From Booty Bay, Baron Revilgaz sends you north to Dalaran with water elemental bracers.",sec={{t="A Plea to Dalaran",b="Baron Revilgaz has the bracers in Booty Bay, but their secret lies beyond his reach. The town has no mage skilled enough to unravel the curse behind the Stone of the Tides, so he points you toward Dalaran. Its wizards are working to rebuild their broken kingdom. Revilgaz has dealt with Archmage Ansirem Runeweaver before and trusts his knowledge. He believes no mage can resist an intriguing puzzle.",sp=0},{t="The Archmage's Lore",b="In Dalaran, Archmage Ansirem Runeweaver pauses his work when you tell him about the relic. Years ago, he wrote a scholarly treatise on the ancient legends of the Gurubashi Empire. That study gives him rare insight into the relic’s past. He examines the bracers and finds trace magical residue to study. Setting aside his work, he turns to uncovering the enchantment’s nature.",sp=1}},faq={{q="Who sends you to Dalaran for this study?",a="Baron Revilgaz in Booty Bay gives you a bag of elemental bracers and sends you to consult Dalaran’s wizards.",al={"who gives magical analysis","magical analysis quest giver","who starts magical analysis"}},{q="Why does Baron Revilgaz pick Archmage Ansirem Runeweaver?",a="Revilgaz has dealt with Ansirem Runeweaver before and trusts the archmage’s vast knowledge. He believes mages cannot resist a magical puzzle.",al={"why ansirem","revilgaz ansirem connection","why ansirem runeweaver"}},{q="What came before this journey to Dalaran?",a="Before traveling to Dalaran, you gathered water elemental bracers for Baron Revilgaz in Water Elementals.",al={"previous quest","prereq magical analysis","what quest leads here"}},{q="What comes next after reaching the archmage?",a="Giving the bracers to Ansirem leads to Ansirem’s Key.",al={"next quest","what follows magical analysis","after delivering bracers"}}},ang={["class:Mage"]="As a mage, you carry arcane artifacts to an archmage of the Kirin Tor. Baron Revilgaz believes mages cannot resist a magical puzzle."},kw={"ansirem runeweaver","baron revilgaz","booty bay","dalaran","gurubashi empire","magical analysis","stone of the tides","water elemental bracers"},rel={"npc:baron-revilgaz","npc:archmage-ansirem-runeweaver","quest:603","subzone:dalaran","zone:stranglethorn","quest:578","topic:mage"},m={start="Baron Revilgaz",["end"]="Archmage Ansirem Runeweaver",level="37",faction="Alliance",id=602},src={"Magical Analysis"}}
E["quest:604"] = {t="quest",n="The Bloodsail Buccaneers",z="stranglethorn",s="On the Wild Shore, the Bloodsail Buccaneers have raised a southern command post. Fleet Master Seahorn sends a trusted Blackwater Raider to seize their charts and orders, so the fleet can learn their plans.",h="On the Wild Shore, the Bloodsail Buccaneers have raised a southern command post.",sec={{t="Raiding the Wild Shore",b="Crazz’s praise has brought you to Fleet Master Seahorn’s notice. The Bloodsail Buccaneers have raised a southern command post on the Wild Shore. Seahorn sends you to strike their camp, cut down their swashbucklers, and seize their naval charts and written orders. The fleet needs those papers to learn what its rivals intend.",sp=0},{t="Uncovering the Fleet's Scheme",b="The Bloodsail charts and orders reveal the pirates’ plan. Seahorn concludes they have anchored close to the cape.",sp=1}},faq={{q="Who assigns this raid?",a="Fleet Master Seahorn assigns the raid from Booty Bay after Crazz praises your dedication.",al={"who gives the bloodsail buccaneers quest","seahorn quest"}},{q="Where is the Bloodsail command post located?",a="The Bloodsail Buccaneers’ southern command camp lies along the Wild Shore, south of Booty Bay in Stranglethorn Vale.",al={"bloodsail southern command post location","where is wild shore"}},{q="What items are needed from the Bloodsail encampment?",a="Seahorn asks you to recover the Bloodsail Charts and written Bloodsail Orders to learn what the rival buccaneers intend.",al={"what documents does seahorn want","bloodsail orders and charts"}},{q="Why does Fleet Master Seahorn want their charts and orders?",a="Fleet Master Seahorn wants the charts and orders to learn what the Bloodsail Buccaneers are planning.",al={"why raid wild shore","what does seahorn want to know"}}},kw={"blackwater raiders","bloodsail buccaneers","bloodsail charts","bloodsail orders","booty bay","fleet master seahorn","wild shore"},rel={"npc:fleet-master-seahorn","subzone:wild-shore","subzone:booty-bay","zone:stranglethorn","quest:595"},m={start="Fleet Master Seahorn",["end"]="Fleet Master Seahorn",level="42",id=604,ri={"Bloodsail Charts","Bloodsail Orders (Classic)"}},src={"The Bloodsail Buccaneers (4)"}}
E["quest:605"] = {t="quest",n="Singing Blue Shards",z="stranglethorn",s="In Stranglethorn Vale, buyers seek Singing Blue Shards. The Venture Company makes it hard for Crank Fizzlebub to gather raw Singing Crystals, so he offers you a cut of the profits for ten shards taken from basilisk hides.",h="In Stranglethorn Vale, buyers seek Singing Blue Shards.",sec={{t="A Lucrative Opportunity",b="Crank Fizzlebub has buyers for Singing Crystals, found only in Stranglethorn Vale. The Venture Company makes gathering raw crystals hard for him. So he seeks another way to get them. Basilisks eat the crystals, and the mineral becomes part of their hardened hides. You can recover usable shards there.",sp=0},{t="Hunting the Coast",b="Basilisks across the jungle may yield crystal fragments. Fizzlebub points you to the gentler ones along the northern shores south of Zul'Kunda. Bring him ten shards so he can move ahead with his buyers. Then his attention turns to the Venture Company's operations.",sp=0}},faq={{q="Why does Crank Fizzlebub want Singing Crystal Shards?",a="Singing Crystals are unique to Stranglethorn Vale, and select buyers value them highly. Crank Fizzlebub says he can sell them and offers you a cut of the profits.",al={"why singing crystals","crank fizzlebub purpose","what are singing crystals for"}},{q="Why cannot Crank Fizzlebub harvest the crystals directly?",a="Fizzlebub says the Venture Company makes it hard for him to gather raw crystals himself.",al={"why kill basilisks","venture company problem","why not mine crystals"}},{q="Why do basilisks have these crystals?",a="Basilisks in Stranglethorn Vale eat the crystals. The mineral becomes part of their hides and gives them their hard, rocky skin.",al={"basilisk crystal lore","why do basilisks drop crystals"}},{q="Where does Crank Fizzlebub suggest looking for basilisks?",a="Fizzlebub says any basilisk may yield shards. Gentler ones live along the northern shores south of Zul'Kunda.",al={"where to find shards","basilisk location","zul kunda basilisks"}},{q="What happens after turning in the shards?",a="When you bring Fizzlebub ten shards, he pays your promised cut of the profits. Then he turns his attention to the Venture Company's operations.",al={"what next after singing blue shards","singing blue shards follow up"},sp=1}},kw={"basilisks","crank fizzlebub","singing blue shards","singing crystals","stranglethorn vale","venture company","zul'kunda"},rel={"topic:venture-company","zone:stranglethorn"},m={start="Crank Fizzlebub",["end"]="Crank Fizzlebub",level="35",id=605,ri={"Singing Crystal Shard"}},src={"Singing Blue Shards","In-game quest text: Singing Blue Shards"}}
E["quest:606"] = {t="quest",n="Scaring Shaky",z="stranglethorn",s="At Booty Bay's docks, “Shaky” Phillipe still owes “Sea Wolf” MacKinley from last week's game. MacKinley sends you outside town for Elder Mistvale Gorilla giblets to frighten Phillipe into paying.",h="At Booty Bay's docks, “Shaky” Phillipe still owes “Sea Wolf” MacKinley from last week's game.",sec={{t="Collecting a Debt",b="“Sea Wolf” MacKinley wants his gambling debts paid, and many people owe him. “Shaky” Phillipe is first. He waits by the docks in Booty Bay and owes a large sum from last week's game. MacKinley sends you outside town to hunt Elder Mistvale Gorillas and bring back plenty of giblets. Keep their animal origin quiet, so Phillipe imagines the worst.",sp=0},{t="Phillipe's Reaction",b="“Shaky” Phillipe recoils at the giblets and wants nothing to do with where they came from. Then he asks whether Sea Wolf sent you.",sp=1}},faq={{q="Who is \"Sea Wolf\" MacKinley?",a="“Sea Wolf” MacKinley is owed gambling debts by many people. He wants help collecting them, beginning with “Shaky” Phillipe.",al={"who is mackinley","sea wolf mackinley","who gives scaring shaky"}},{q="Why does MacKinley want to scare \"Shaky\" Phillipe?",a="Phillipe still owes MacKinley a large sum from last week's game. MacKinley hopes a fright will make him pay.",al={"why scare shaky","shaky phillipe debt","why target phillipe"}},{q="What creatures provide the giblets?",a="MacKinley says the giblets come from Elder Mistvale Gorillas outside town.",al={"where do giblets come from","mistvale giblets source","what do i kill for giblets"}},{q="Where can \"Shaky\" Phillipe be found?",a="“Shaky” Phillipe can be found by the docks in Booty Bay.",al={"where is shaky phillipe","shaky location","find shaky phillipe"}},{q="What should you tell Phillipe about the giblets?",a="Say nothing about where the giblets came from. MacKinley wants Phillipe to imagine the worst.",al={"do i tell shaky where giblets came from"}}},kw={"booty bay","gambling debt","mistvale giblets","mistvale gorillas","scaring shaky","sea wolf mackinley","shaky phillipe","stranglethorn vale"},rel={"quest:607","subzone:booty-bay","zone:stranglethorn"},m={start="\"Sea Wolf\" MacKinley",["end"]="\"Shaky\" Phillipe",level="41",id=606},src={"Classic quest text: Scaring Shaky"}}
E["quest:607"] = {t="quest",n="Return to MacKinley",z="stranglethorn",s="You carry Phillipe’s pouch to Sea Wolf MacKinley, who is owed payment. Phillipe says he meant to pay all along and asks that you go easy.",h="You carry Phillipe’s pouch to Sea Wolf MacKinley, who is owed payment.",sec={{t="Shaky's Plea",b="\"Shaky\" Phillipe hands you a pouch of payment for Sea Wolf MacKinley. He swears he always meant to repay the debt. Phillipe says he got a little drunk and lost the way. He thinks MacKinley will understand, and insists there is no need to get rough.",sp=0},{t="Sea Wolf Hears the Tale",b="Sea Wolf MacKinley chuckles as he recalls showing Phillipe the giblets. He asks how hard Phillipe shook. MacKinley says Phillipe is easy to read, and that winning comes without effort when they play cards.",sp=1}},faq={{q="Who gives you the pouch?",a="\"Shaky\" Phillipe gives you a pouch of payment for Sea Wolf MacKinley.",al={"who gives return to mackinley","where do i start return to mackinley"}},{q="What excuse does Phillipe give for not paying?",a="Phillipe says he got a little drunk and lost the way, but swears he always meant to repay the debt.",al={"why didn't shaky pay","phillipe excuse","why was shaky phillipe late"}},{q="What came before this step?",a="Before this, MacKinley had you frighten Phillipe with giblets in Scaring Shaky.",al={"what comes before return to mackinley","previous quest"}}},kw={"debt","mackinley","sea wolf","shaky phillipe","stranglethorn vale"},rel={"quest:606","quest:609","zone:stranglethorn"},m={start="\"Shaky\" Phillipe",["end"]="\"Sea Wolf\" MacKinley",level="41",id=607},src={"Classic quest text: Return to MacKinley"}}
E["quest:608"] = {t="quest",n="The Bloodsail Buccaneers",z="stranglethorn",s="In Stranglethorn, the Bloodsail Buccaneers gather strength for an attack. Fleet Master Seahorn will not risk his whole fleet in a counterstrike, so he sends a small crew against their leaders before they can begin.",h="In Stranglethorn, the Bloodsail Buccaneers gather strength for an attack.",sec={{t="Decapitating the Pirate Fleet",b="Fleet Master Seahorn means to halt the Bloodsail attack before it gains strength. He mocks Fleet Master Firallon's skill at sea, then chooses to strike at the commanders. Seahorn will not risk a full naval battle. Instead, he sends a small crew to Firallon's landing camp to kill Firallon, Captain Stillwater, and Captain Keelhaul. Without their leaders, the buccaneers will be left without command.",sp=0}},faq={{q="Who orders the strike on the Bloodsail leadership?",a="Fleet Master Seahorn in Booty Bay orders the strike. He hopes to break the hostile fleet before it can attack.",al={"who gives the bloodsail buccaneers quest","bloodsail buccaneers questgiver","who sends you after firallon"}},{q="Which buccaneer commanders need to be eliminated?",a="The targets are Fleet Master Firallon, Captain Stillwater, and Captain Keelhaul, leaders of the Bloodsail forces.",al={"targets for bloodsail buccaneers","bloodsail commanders to kill","who are the bloodsail bosses"}},{q="Why does Fleet Master Seahorn send adventurers instead of his ships?",a="Seahorn believes a capable crew can strike the landing camp and kill the enemy officers. That could bring down the fleet without risking his ships.",al={"why send adventurers to firallon","why not send the blackwater fleet","seahorn plan"}},{q="Where does this clash fit in the broader confrontation with the Bloodsail Buccaneers?",a="The clash follows the discovery of the buccaneers' written attack plans during the earlier stages of the Bloodsail investigation in Stranglethorn Vale.",al={"previous bloodsail quest","what quest comes before this","bloodsail chain order"}}},kw={"blackwater","bloodsail","booty bay","firallon","keelhaul","pirates","seahorn","stillwater"},rel={"npc:fleet-master-seahorn","subzone:booty-bay","zone:stranglethorn","quest:595"},m={start="Fleet Master Seahorn",["end"]="Fleet Master Seahorn",level="42",id=608},src={"The Bloodsail Buccaneers (5)"}}
E["quest:609"] = {t="quest",n="Voodoo Dues",z="stranglethorn",s="In Booty Bay, “Sea Wolf” MacKinley is still waiting for three old debts to be paid. Maury “Club Foot” Wilkins, Jon-Jon the Crow, and Chucky “Ten Thumbs” owe him, but rumors say curses and enchantment sent them wandering ancient jungle ruins. MacKinley wants their prized possessions, whatever their fate.",h="In Booty Bay, “Sea Wolf” MacKinley is still waiting for three old debts to be paid.",sec={{t="Unpaid Accounts",b="You have already collected debts for “Sea Wolf” MacKinley, but three accounts remain unpaid. Maury “Club Foot” Wilkins, Jon-Jon the Crow, and Chucky “Ten Thumbs” have owed him for months. MacKinley first thought they had left Booty Bay to escape their debts. Then he heard they had met a stranger, darker fate deep in the jungle.",sp=0},{t="Bewitched in the Ruins",b="Whispers say curses and enchantment have left the three men wandering ancient stonework northeast of Booty Bay. They are said to roam the Ruins of Aboraz and the Ruins of Jubuwal. MacKinley wants you to find each man and take his notable valuables: Jon-Jon's Golden Spyglass, Chucky's Huge Ring, and Maury's Clubbed Foot.",sp=0}},faq={{q="Who is asking to collect these debts?",a="“Sea Wolf” MacKinley asks you to collect the debts from his post in Booty Bay. He is working through his list of debtors and will not let their debts slip away.",al={"who gives voodoo dues","sea wolf mackinley quest"}},{q="Who are the three debtors?",a="The three debtors are Maury “Club Foot” Wilkins, Jon-Jon the Crow, and Chucky “Ten Thumbs”. They have owed their payments for several months.",al={"who owes mackinley","voodoo dues targets"}},{q="Where can the three debtors be found?",a="The three men wander ancient stone structures northeast of Booty Bay, in the Ruins of Aboraz and the Ruins of Jubuwal.",al={"where are the debtors","where are aboraz and jubuwal"}},{q="What happened to the three men?",a="Word reaching MacKinley says the men were bewitched and cursed. They now roam the jungle ruins instead of returning to port.",al={"why are they cursed","what is wrong with them"}},{q="What specific items must be recovered?",a="MacKinley wants Jon-Jon's Golden Spyglass, Chucky's Huge Ring, and Maury's Clubbed Foot.",al={"what items does mackinley want","voodoo dues items"}},{q="What came before this task in the chain?",a="This follows your earlier work in Scaring Shaky and Return to MacKinley, helping the pirate collect his debts.",al={"voodoo dues prerequisites","previous quest"}}},kw={"booty bay","chucky ten thumbs","jon-jon the crow","maury club foot wilkins","ruins of aboraz","ruins of jubuwal","sea wolf mackinley","stranglethorn vale","voodoo dues"},rel={"subzone:booty-bay","subzone:ruins-of-aboraz","subzone:ruins-of-jubuwal","quest:613","zone:stranglethorn"},m={start="\"Sea Wolf\" MacKinley",["end"]="\"Sea Wolf\" MacKinley",level="44",faction="Neutral",id=609,ri={"Chucky's Huge Ring","Jon-Jon's Golden Spyglass","Maury's Clubbed Foot"}},src={"Voodoo Dues"}}
E["quest:610"] = {t="quest",n="\"Pretty Boy\" Duncan",z="stranglethorn",s="Catelyn the Blade has lost the dagger her father asked her to return. She wants it back from Pretty Boy Duncan before she helps you further.",h="Catelyn the Blade has lost the dagger her father asked her to return.",sec={{t="A Pirate's Grievance",b="Catelyn the Blade has left the mages and their dusty tomes behind. Ansirem's Key led you to her, but she cannot give you the dagger her father asked her to return. A Bloodsail Buccaneer took it. Until her blade is recovered, Catelyn will hand over nothing else.",sp=0},{t="The Stolen Steel",b="Pretty Boy Duncan struck Catelyn unconscious and took the knife she carried in a fight. She relies on that weapon. Now she insists on getting that very blade back from the buccaneer before she helps you further.",sp=0}},faq={{q="Who is Pretty Boy Duncan?",a="Pretty Boy Duncan is a Bloodsail Buccaneer near Booty Bay. He defeated Catelyn the Blade, knocked her unconscious, and took her dagger.",al={"pretty boy duncan","who is duncan","duncan pirate"}},{q="Why does Catelyn want her dagger back?",a="Catelyn relies on her knife in a fight and will not settle for another. She wants the dagger Duncan took back before helping anyone searching for her.",al={"catelyn dagger","catelyn knife","why get blade back"}},{q="Why did Catelyn run away from home?",a="Catelyn left her family to escape a dull life reading old books among rigid, aged mages. She refused to spend her days that way.",al={"why catelyn ran away","ansirem daughter","catelyn backstory"}},{q="Where does this step fit into the search?",a="This encounter follows the recovery of Ansirem's Key and comes before the search uncovers The Curse of the Tides.",al={"quest chain","what leads to pretty boy duncan"}}},ang={["class:Mage"]="As a Mage, you may hear Catelyn mock arcane scholars. She says she fled home to avoid spending her days among stuffy, grey-haired spellcasters."},kw={"bloodsail buccaneers","booty bay","catelyn the blade","catelyn's blade","pretty boy duncan","stranglethorn vale"},rel={"quest:603","quest:611","quest:578","subzone:booty-bay","zone:stranglethorn","topic:mage"},m={start="Catelyn the Blade",["end"]="Catelyn the Blade",level="39",faction="Alliance",id=610,ri={"Catelyn's Blade"}},src={"\"Pretty Boy\" Duncan (quest)"}}
E["quest:611"] = {t="quest",n="The Curse of the Tides",z="stranglethorn",s="Off Stranglethorn's coast, Catelyn the Blade lends you her recovered knife to strike a sunken altar. Baron Revilgaz in Booty Bay seeks the Stone of the Tides for his collection of ancient troll artifacts.",h="Off Stranglethorn's coast, Catelyn the Blade lends you her recovered knife to strike a sunken altar.",sec={{t="The Sunken Altar",b="Catelyn the Blade lends you her recovered troll dagger to break an altar beneath the waves. She knows less of troll ruins than her father, but has heard of a sunken troll city. So she points you northwest of Grom'gol Base Camp. There, in the Vile Reef's underwater ruins, the Altar of the Tides glows blue among sea life and murlocs.",sp=0},{t="The Trapped Mage",b="Striking the Altar of the Tides with Catelyn's blade breaks its magic and draws forth Gazban, a goblin mage carrying the Stone of the Tides. Challenged, Gazban takes the form of a water elemental. Once you overcome him, you can carry the stone and the borrowed dagger back to Booty Bay. Baron Revilgaz has prepared a special display stand for the relic's captured oceanic magic, among his prized collection.",sp=1}},faq={{q="Where is the Altar of the Tides located?",a="The Altar of the Tides lies beneath the sea in the Vile Reef, a sunken ruin northwest of Grom'gol Base Camp. Its blue glow is easy to see underwater.",al={"where is the altar","altar of the tides location","where do i find the altar"}},{q="Why does Baron Revilgaz want the stone?",a="Baron Revilgaz collects ancient troll antiquities. He has cleared space and bought a fine stand to display the relic.",al={"revilgaz stone","why revilgaz wants the stone","what does revilgaz do with it"}},{q="Why does Catelyn lend her blade?",a="Catelyn lends you her recovered special knife to shatter the altar, asking you to return it safely when the deed is done.",al={"catelyn knife","why lend knife","catelyn blade"}}},ang={["faction:Alliance"]="As an Alliance adventurer, you complete Baron Revilgaz's search for the ancient relic in waters near the Horde encampment at Grom'gol Base Camp."},kw={"altar of the tides","baron revilgaz","booty bay","catelyn the blade","gazban","stone of the tides","stranglethorn vale","vile reef"},rel={"quest:578","subzone:vile-reef","npc:baron-revilgaz","subzone:booty-bay","subzone:grom-gol-base-camp","zone:stranglethorn","topic:goblin","topic:alliance"},m={start="Catelyn the Blade",["end"]="Baron Revilgaz",level="40",faction="Alliance",id=611,ri={"Stone of the Tides"}},src={"The Curse of the Tides"}}
E["quest:613"] = {t="quest",n="Cracking Maury's Foot",z="stranglethorn",s="At Booty Bay, MacKinley still cannot claim what Maury owed him. Maury locked the debt inside his own foot, so MacKinley sends travelers to the Mosh'Ogg ogre mound in Stranglethorn Vale to find the key.",h="At Booty Bay, MacKinley still cannot claim what Maury owed him.",sec={{t="A Locked Prize",b="After the foot was recovered in Voodoo Dues, \"Sea Wolf\" MacKinley faces another obstacle in Booty Bay. His late debtor locked the foot, sealing the valuables he owes inside.",sp=0},{t="The Ogres' Mound",b="Maury gambled with the ogres at the Mosh'Ogg mound northeast of Booty Bay. MacKinley recalls Maury saying they drove him away after he won too much. So MacKinley suspects they have the key and sends you to search for it.",sp=0}},faq={{q="Why does \"Sea Wolf\" MacKinley need Maury's key?",a="Maury locked what he owed inside his own foot. MacKinley needs the key to open it and claim the debt.",al={"why need key","what is the key for","maury key purpose"}},{q="Where is Maury's key thought to be?",a="MacKinley suspects the Mosh'Ogg ogres may have the key at their mound northeast of Booty Bay.",al={"where is key","key location","where to find maury key"}},{q="Why would the Mosh'Ogg ogres have the key?",a="Maury often gambled with the Mosh'Ogg ogres. MacKinley recalls they drove Maury away after a big win, so he suspects they may have the key.",al={"why ogres have key","maury ogres connection","did maury know the ogres"}},{q="What comes before this in MacKinley's business?",a="The collection in Voodoo Dues followed Scaring Shaky and Return to MacKinley, as MacKinley settled debts around Booty Bay.",al={"previous quest","chain order","what comes first"}}},kw={"booty bay","key","mackinley","maury","mosh'ogg","ogres","sea wolf","stranglethorn"},rel={"subzone:booty-bay","quest:609","zone:stranglethorn"},m={start="\"Sea Wolf\" MacKinley",["end"]="\"Sea Wolf\" MacKinley",level="44",id=613,ri={"Maury's Key"}},src={"Cracking Maury's Foot"}}
E["quest:616"] = {t="quest",n="The Haunted Isle",z="stranglethorn",s="In Booty Bay, Krazek hears a tale of an isle haunted by a goblin ghost. He gathers unusual rumors for Baron Revilgaz, and this one recalls an old troll legend.",h="In Booty Bay, Krazek hears a tale of an isle haunted by a goblin ghost.",sec={{t="Tavern Tales in Booty Bay",b="Krazek gathers reports of strange happenings throughout Stranglethorn Vale for Baron Revilgaz. In a Booty Bay tavern, sailors tell him of an isle off the coast where water elementals dwell. They say the ghost of a raving goblin haunts it. Krazek gives little heed to spectral gossip, but this tale catches his attention. He asks you to carry it to the baron.",sp=0},{t="A Troll Legend",b="Baron Revilgaz remembers an old troll legend from a book when he hears Krazek's report. The water elementals and goblin apparition make him suspect that the Stone of the Tides may be within his grasp. He hopes to add the ancient relic to his personal collection of artifacts.",sp=0}},faq={{q="Who sends you to speak with Baron Revilgaz?",a="Krazek asks you to carry the rumor to Baron Revilgaz after hearing sailors tell an unsettling tale in a Booty Bay tavern.",al={"who gives the haunted isle","haunted isle quest giver","krazek rumor"}},{q="What rumors did the sailors share?",a="The sailors tell of an isle off the coast where water elementals dwell and the ghost of a raving goblin haunts it.",al={"what is on the island","haunted island rumor","sailor stories"}},{q="Why does Baron Revilgaz care about a ghost story?",a="Baron Revilgaz remembers an old troll legend from a book. The reports suggest that the ancient Stone of the Tides may be on the isle.",al={"why revilgaz wants to know","revilgaz reaction","stone of the tides interest"}},{q="Where does this investigation lead next?",a="Baron Revilgaz points you toward the Stone of the Tides, carrying the pursuit forward.",al={"what quest is next","haunted isle follow up","next step after haunted isle"}}},kw={"baron revilgaz","booty bay","goblin ghost","krazek","stone of the tides","stranglethorn vale","troll legend","water elementals"},rel={"quest:578","npc:baron-revilgaz","subzone:booty-bay","zone:stranglethorn","topic:goblin","topic:troll"},m={start="Krazek",["end"]="Baron Revilgaz",level="37",faction="Alliance",id=616},src={"The Haunted Isle"}}
E["quest:617"] = {t="quest",n="Akiris by the Bundle",z="stranglethorn",s="In Booty Bay, Privateer Bloads seeks akiris reeds for an associate who pays well. The naga were last seen on the northern beach, where you must take the reeds from them.",h="In Booty Bay, Privateer Bloads seeks akiris reeds for an associate who pays well.",sec={{t="A Profitable Ocean Plant",b="Privateer Bloads offers seaside work in Booty Bay. His associate Groy pays well for bundles of akiris reed, a plant that grows by the sea and bears the name the naga give it. Bloads does not know why Groy wants the reeds. He needs ten stalks, and the naga were last seen on the northern beach.",sp=0}},faq={{q="Who is Privateer Bloads?",a="Privateer Bloads is a privateer in Booty Bay who offers work to those who ask.",al={"bloads","who gives akiris by the bundle","who is bloads"}},{q="What is an akiris reed?",a="Akiris reed is a valuable ocean plant that the naga call by that name. Privateer Bloads does not know its purpose, but collectors pay well for bundles of stalks.",al={"akiris reed","what are akiris reeds","what is akiris used for"}},{q="Where can the naga holding the reeds be found?",a="The naga with the stalks prowl the coastline north of Booty Bay, along the beaches of Stranglethorn Vale.",al={"where are the naga","where to get akiris reed","akiris reed location"}},{q="Who buys the reeds from Privateer Bloads?",a="Bloads gathers the bundles for an associate named Groy, who earns a substantial profit by selling the ocean reeds.",al={"who is groy","who wants akiris reed","bloads buyer"}}},kw={"akiris reed","booty bay","groy","naga","privateer bloads","reeds","stranglethorn vale"},rel={"subzone:booty-bay","topic:naga","zone:stranglethorn"},m={start="Privateer Bloads",["end"]="Privateer Bloads",level="43",id=617,ri={"Akiris Reed"}},src={"Akiris by the Bundle (Classic)"}}
E["quest:618"] = {t="quest",n="Facing Negolash",z="stranglethorn",s="Along Stranglethorn Vale's coast, a stolen cutlass sets events in motion. Sprogger knows how to draw Negolash out with the giant's favorite food and drink.",h="Along Stranglethorn Vale's coast, a stolen cutlass sets events in motion.",sec={{t="A Hungry Giant",b="When giants wrecked Captain Smotts' vessel, Negolash headed for the galley. He left the crew alone and went after wine and Barbecued Buzzard Wings, Sprogger's specialty. Sprogger had traveled to the Badlands to learn the recipe.",sp=0},{t="The Trap in the Lifeboat",b="Sprogger plans to lure Negolash with a feast. You carry ten servings of wings and five bottles of wine to Captain Smotts' ruined lifeboat on the southeastern shore. The banquet draws the giant near. Then you can confront him and reclaim the captain's cutlass.",sp=0}},faq={{q="Who is Negolash?",a="Negolash is a giant who helped wreck Captain Smotts' ship. He ransacked the galley for food and drink instead of hunting the sailors.",al={"what is negolash","who is the giant","negolash lore"}},{q="Why does Sprogger know how to lure Negolash?",a="Sprogger saw Negolash raid his kitchen during the shipwreck. The giant favored Sprogger's Barbecued Buzzard Wings and bottles of Junglevine Wine, so those provisions make suitable bait.",al={"how to bait negolash","why buzzard wings","negolash food"}},{q="Where does the confrontation take place?",a="The confrontation takes place in Captain Smotts' ruined lifeboat, stranded on the coast southeast of Sprogger.",al={"where is negolash","where to place the food","lifeboat location"}},{q="What came before this task?",a="The trail begins with The Monogrammed Sash and continues through The Captain's Cutlass before this confrontation.",al={"what quest comes first","facing negolash previous quest","prereqs for negolash"}}},ang={["profession:Cooking"]="As a cook, you can appreciate Sprogger's craft. He traveled to the Badlands to learn the specialized recipe for Barbecued Buzzard Wings at the heart of his plan."},kw={"badlands","buzzard wings","captain smotts","junglevine wine","negolash","smotts' cutlass","sprogger","stranglethorn vale"},rel={"quest:8553","quest:619","quest:8552","zone:stranglethorn","zone:badlands"},m={start="Sprogger",["end"]="Captain Hecklebury Smotts",level="42",faction="Both",id=618,ri={"Smotts' Cutlass"}},src={"Facing Negolash"}}
E["quest:619"] = {t="quest",n="Enticing Negolash",z="stranglethorn",s="Along Stranglethorn Vale's shore, a marked lifeboat offers a way to lure Negolash. Ten barbecued buzzard wings and five bottles of junglevine wine lie on the wreck.",h="Along Stranglethorn Vale's shore, a marked lifeboat offers a way to lure Negolash.",sec={{t="A Tempting Offering",b="The abandoned lifeboat bears the faded words Smotts' Revenge. While hunting Negolash, arrange ten barbecued buzzard wings and five bottles of junglevine wine on the wreck to draw him out.",sp=0}},faq={{q="What is the Ruined Lifeboat?",a="The Ruined Lifeboat is an abandoned, broken boat marked with the faded words Smotts' Revenge. You can arrange food and drink there to lure Negolash.",al={"smotts revenge boat","lifeboat strangletorn","what is smotts revenge"}},{q="What provisions are required for the offering?",a="The offering requires ten barbecued buzzard wings and five bottles of junglevine wine, stacked on the wreck.",al={"what food is needed","enticing negolash items","what items for negolash"}},{q="When does this task become available?",a="You can prepare the offering only while hunting Negolash.",al={"when can i do enticing negolash","facing negolash prerequisite","how to unlock enticing negolash"}}},kw={"barbecued buzzard wing","junglevine wine","negolash","ruined lifeboat","smotts revenge","stranglethorn vale"},rel={"quest:618","zone:stranglethorn"},m={start="Ruined Lifeboat",["end"]="Ruined Lifeboat",level="42",faction="Neutral",id=619},src={"Enticing Negolash"}}
E["quest:621"] = {t="quest",n="Zanzil's Secret",z="stranglethorn",s="Crank Fizzlebub seeks Zanzil's Secret in the ruins northeast of Booty Bay. The exiled troll's brew bends minds and strengthens bodies, and Crank wants samples for himself.",h="Crank Fizzlebub seeks Zanzil's Secret in the ruins northeast of Booty Bay.",sec={{t="Mind-Bending Draughts",b="Northeast of Booty Bay, Zanzil has made his home in the ruins of Jubuwal and Aboraz. His former tribal leaders cast him out, fearing his mastery over other minds. Now he rules followers with concoctions made from jungle plants. The mixtures dull their will and heighten their strength, leaving them docile but sturdy.",sp=0},{t="A Lucrative Mixture",b="Crank Fizzlebub sees profit in Zanzil's craft. Those who want power over others might pay handsomely for such a brew, so the goblin wants a supply from the ruins. Deliver enough samples and Crank offers the usual coin, with a quiet bonus if you keep the bargain private.",sp=0}},faq={{q="Who is Zanzil the Outcast?",a="Zanzil is a troll exile who lives in the ruins northeast of Booty Bay. His leaders banished him because they feared his power over other minds.",al={"who is zanzil","zanzil lore","why was zanzil exiled"}},{q="What does Zanzil's mixture actually do?",a="Made from jungle plants, Zanzil's brew suppresses the drinker's free will and unnaturally strengthens the body.",al={"what is zanzils mixture","effects of zanzils mixture","zanzil potion effects"}},{q="Where does Zanzil reside?",a="Zanzil and his followers live in the ruins of Jubuwal and Aboraz, northeast of Booty Bay in Stranglethorn Vale.",al={"zanzil location","where is zanzil","where are the ruins"}},{q="Why does Crank Fizzlebub want the mixture?",a="Crank Fizzlebub believes those who want power over others would pay well for the brew, and he has uses of his own in mind.",al={"why does crank want the mixture","what will crank do with zanzils mixture"}},{q="Why did Crank pay extra upon delivery?",a="Crank adds a bonus to buy your discretion and keep the acquisition of the mind-bending brew private.",al={"crank fizzlebub extra pay","discretion pay crank"},sp=1}},kw={"aboraz","booty bay","fizzlebub","jubuwal","mixture","stranglethorn","zanzil"},rel={"subzone:booty-bay","zone:stranglethorn"},m={start="Crank Fizzlebub",["end"]="Crank Fizzlebub",level="44",faction="Neutral",id=621,ri={"Zanzil's Mixture"}},src={"Zanzil's Secret (Classic)"}}
E["quest:622"] = {t="quest",n="Return to Corporal Kaleb",z="stranglethorn",s="At the Rebel Camp, Corporal Kaleb waits for the pot Krazek repaired in Booty Bay. It has a second steam whistle and a chopper built into its base.",h="At the Rebel Camp, Corporal Kaleb waits for the pot Krazek repaired in Booty Bay.",sec={{t="A Better Pot",b="Krazek has finished repairing the pot you brought him. He added another steam whistle and fitted a chopper to its base, sharp enough to cut through leg bones. He calls it a sure way to please the cook and expects its owner to be glad of the changes. Now it is ready to return to Corporal Kaleb at the Rebel Camp.",sp=0},{t="Back at the Camp",b="Corporal Kaleb is delighted to see the pot working, and at last dinner can begin. He hopes your time in Booty Bay went well, though he calls it a rough town. He also shares a rumor: goblins sometimes drag drunken sailors away to slave boats bound for parts unknown.",sp=1}},faq={{q="Who is Corporal Kaleb?",a="Corporal Kaleb waits at the Rebel Camp for the cooking pot Krazek has been repairing in Booty Bay.",al={"corporal kaleb","who is kaleb","kaleb rebel camp","where is corporal kaleb","kaleb location"}},{q="What did Krazek do to the pot?",a="Krazek repaired the pot, added another steam whistle, and fitted a new chopper into its base, sharp enough to cut through leg bones.",al={"krazek pot upgrades","what did krazek fix","krazek crock pot"}},{q="What came before this step?",a="Favor for Krazek came first.",al={"previous quest","what led to return to corporal kaleb"}}},kw={"booty bay","corporal kaleb","crock pot","krazek","rebel camp","stranglethorn vale"},rel={"quest:627","subzone:rebel-camp","subzone:booty-bay","topic:goblin","zone:stranglethorn"},m={start="Krazek",["end"]="Corporal Kaleb",level="37",id=622},src={"Classic quest text: Return to Corporal Kaleb"}}
E["quest:623"] = {t="quest",n="Akiris by the Bundle",z="stranglethorn",s="In Stranglethorn Vale, Bloads has a fresh bundle of akiris reeds bound for Theramore Isle. His contact, Privateer Groy, has a client eager for more, but Bloads cannot sail to Dustwallow Marsh for another week.",h="In Stranglethorn Vale, Bloads has a fresh bundle of akiris reeds bound for Theramore Isle.",sec={{t="A Crossing to Theramore",b="While you are away, word reaches you from across the sea. Privateer Groy in Theramore Isle is pleased with the last shipment of akiris reeds, and a client wants another bundle at once. Privateer Bloads cannot sail to Dustwallow Marsh for another week. So he gives you the parcel to carry across the sea by hand.",sp=0},{t="Delivery on the Docks",b="Privateer Groy waits on the docks of Theramore. He first dismisses strangers, but inspects the bundle closely when he learns Bloads arranged its delivery. Pleased with the reeds, he pays you a cut of coin for carrying them. Then he warns travelers not to linger around his docks.",sp=1}},faq={{q="Who is Privateer Groy?",a="Privateer Groy is Privateer Bloads's contact in Theramore Isle, Dustwallow Marsh. Groy has a client who wants more akiris reeds.",al={"who is groy","groy theramore","privateer groy"}},{q="Why does Privateer Bloads need a courier?",a="Bloads has heard that Groy's client urgently wants another bundle of akiris reeds. Bloads cannot sail to Dustwallow Marsh for another week, so he asks you to carry it across the sea.",al={"why carry reeds","why theramore","bloads delivery"}},{q="Where does this shipment need to go?",a="The bundle is bound for Theramore Isle, an Alliance port in Dustwallow Marsh.",al={"where do i take the reeds","akiris delivery location","dustwallow marsh delivery"}},{q="What came before this journey?",a="This delivery follows the first gathering of akiris reeds in Stranglethorn Vale, when bundles were brought to Privateer Bloads.",al={"previous quest","akiris reed chain","prerequisite"}}},ang={["faction:Alliance"]="Theramore Isle is an Alliance stronghold in Dustwallow Marsh. Bloads warns that visitors can still find trouble if they are the wrong kind of crowd."},kw={"akiris","bloads","dustwallow","groy","privateer","reeds","stranglethorn","theramore"},rel={"quest:617","zone:dustwallow","zone:stranglethorn"},m={start="Privateer Bloads",["end"]="Privateer Groy",level="43",faction="Alliance",id=623},src={"Akiris by the Bundle (2)"}}
E["quest:624"] = {t="quest",n="Cortello's Riddle",z="stranglethorn",s="A parchment bearing Cortello's Riddle turns up aboard Bloodsail Buccaneer vessels along the Wild Shore. Its verse sends you toward a clue beneath an ornate bridge.",h="A parchment bearing Cortello's Riddle turns up aboard Bloodsail Buccaneer vessels along the Wild Shore.",sec={{t="A Buccaneer's Riddle",b="Bloodsail Buccaneers anchored off Stranglethorn Vale's southern coast carry scattered notes with a rhyme. Cortello's verse describes a finely worked bridge, worn by many travelers. It lies east of Deadwind and south of Redridge. Follow the directions out of the jungle and into the marshes, where something waits below.",sp=0},{t="The Marsh Crossing",b="The verse leads beneath an ornate bridge spanning the Swamp of Sorrows. In the murky water below lies a soggy parchment with the next step in Cortello's puzzle.",sp=1}},faq={{q="Where does this mystery begin?",a="The mystery begins with a scrap of parchment among the Bloodsail Buccaneers' fleet, anchored off the Wild Shore south of Booty Bay.",al={"where to start cortello's riddle","cortellos riddle start location","where is cortello's riddle found"}},{q="What location is described in the riddle?",a="The rhyme describes a well-traveled, ornate bridge in the Swamp of Sorrows, east of Deadwind Pass and south of the Redridge Mountains.",al={"what bridge is in cortellos riddle","where is the riddle pointing","bridge east of deadwind south of redridge"}},{q="What are you searching for beneath the bridge?",a="The riddle points to a hint waiting beneath the bridge.",al={"what do you find in swamp of sorrows","cortello clue under bridge","what is under the bridge"}},{q="Who wrote the riddle?",a="The riddle bears Cortello's name, but the parchment says nothing more about who he was.",al={"who is cortello","cortello lore","who made cortello's riddle"}}},kw={"bloodsail buccaneers","bridge","cortello","riddle","scroll","swamp of sorrows","wild shore"},rel={"subzone:wild-shore","zone:stranglethorn","zone:swampofsorrows","subzone:booty-bay"},m={start="Cortello's Riddle",["end"]="A Soggy Scroll",level="43",faction="Neutral",id=624},src={"Cortello's Riddle (quest)"}}
E["quest:627"] = {t="quest",n="Favor for Krazek",z="stranglethorn",s="In Booty Bay, Krazek pauses his work on a broken crock pot to ask you for four loads of lesser bloodstone ore from the northern hills. He will return the cookware when you bring them.",h="In Booty Bay, Krazek pauses his work on a broken crock pot to ask you for four loads of lesser bloodstone ore...",sec={{t="A Northern Bargain",b="Krazek pauses his repair of the broken cookware in Booty Bay to offer a trade. He sends you far north to the Arathi Highlands. There, a cave in Drywhisker Gorge holds lesser bloodstone ore. The mineral is low grade, yet those who know its uses prize it.",sp=0},{t="Ore from the Gorge",b="Krazek keeps working on the pot while you travel north. He expects four loads of bloodstone and promises payment if you bring back enough. The ore must be mined. If you lack the skill, you need someone who can extract it.",sp=0}},faq={{q="Who is Krazek and what does he want?",a="Krazek is a goblin in Booty Bay. As he repairs a broken crock pot, he asks you to bring back four loads of rare bloodstone ore from the north.",al={"who is krazek","krazek request"}},{q="Where is the bloodstone ore located?",a="Lesser bloodstone ore lies in a mountain cave in Drywhisker Gorge, far north in the Arathi Highlands.",al={"where is bloodstone ore","bloodstone location","drywhisker gorge location"}},{q="Why does Krazek want low-grade ore?",a="The cave's bloodstone is low grade, but Krazek says it has value for those with the craft and knowledge to use it.",al={"why lesser bloodstone","bloodstone value"}},{q="What happens before this task?",a="Before Krazek makes his demand, you deliver the damaged vessel to Booty Bay in Krazek's Cookery.",al={"previous quest","what came before"}},{q="What happens after gathering the bloodstone?",a="After Krazek receives the four loads of ore and pays you, you continue with Return to Corporal Kaleb.",al={"next quest","what comes next"}}},ang={["profession:Mining"]="As a miner, you can extract the ore yourself. Krazek warns that if you lack the skill, you need someone who can mine the veins."},kw={"arathi highlands","bloodstone","booty bay","drywhisker gorge","favor for krazek","krazek","lesser bloodstone ore","stranglethorn vale"},rel={"subzone:booty-bay","zone:stranglethorn","zone:arathi","subzone:drywhisker-gorge"},m={start="Krazek",["end"]="Krazek",level="37",faction="Alliance",id=627},src={"Favor for Krazek"}}
E["quest:628"] = {t="quest",n="Excelsior",z="stranglethorn",s="In Booty Bay, Drizzlik is ready for the last piece of the Excelsior boots. He needs an elder saltwater crocolisk skin for their outer layer.",h="In Booty Bay, Drizzlik is ready for the last piece of the Excelsior boots.",sec={{t="The Outer Layer",b="Drizzlik has finished the boots’ inner layer. For the outside, he uses the finest elder crocolisk skins. They are tougher and give the Excelsior designs and accents a better surface. Only an elder saltwater crocolisk skin fits his plan.\n\nFinding one is difficult. Elders come out only to guard other saltwater crocolisks. Drizzlik has also read that saltwater crocolisk numbers are dwindling, which worries him for his business.",sp=0},{t="Drizzlik's Thanks",b="Drizzlik can fill the order and send it early to Director Riddlevox aboard the next boat bound for Undermine. He has made extras and gives you a pair for your trouble. No boot, he insists, is as fine as the Excelsior line.",sp=1}},faq={{q="Who is Drizzlik?",a="Drizzlik makes the Excelsior line of boots in Booty Bay.",al={"drizzlik","booty bay bootmaker","drizzlik npc"}},{q="Why does Drizzlik need an elder saltwater crocolisk skin?",a="Drizzlik says elder skins are tougher and give the Excelsior designs and accents a better surface. Only an elder saltwater crocolisk skin fits his plan.",al={"why croc skin","excelsior boot materials","elder crocolisk skin use"}},{q="Why are elder saltwater crocolisks hard to find?",a="Elder saltwater crocolisks come out only to defend other saltwater crocolisks, Drizzlik says.",al={"where are elder crocs","find elder saltwater crocolisk","how to summon elder croc"}},{q="What came before this request?",a="Some Assembly Required came first.",al={"previous quest","excelsior prerequisite","some assembly required link"}},{q="What concern does Drizzlik have about saltwater crocolisks?",a="Drizzlik has read that saltwater crocolisk numbers are dwindling, a concern for his business.",al={"are crocs dying out","saltwater croc population","crocolisk extinction"}}},kw={"booty bay","crocolisk","drizzlik","elder crocolisk","excelsior","saltwater crocolisk","stranglethorn"},rel={"quest:577","subzone:booty-bay","zone:stranglethorn"},m={start="Drizzlik",["end"]="Drizzlik",level="38",id=628},src={"Classic quest text: Excelsior"}}
E["quest:629"] = {t="quest",n="The Vile Reef",z="stranglethorn",s="Beneath the Savage Coast, Kin'weelay seeks a shard from the sunken troll city. He hopes to carry Gri'lek's story to Orgrimmar, where the Darkspear can preserve it.",h="Beneath the Savage Coast, Kin'weelay seeks a shard from the sunken troll city.",sec={{t="Sunken Legends",b="Northwest of Grom'gol Base Camp, the Savage Coast hides an ancient troll city beneath the water. A violent earthquake shattered the land long ago and sank the city. Now called the Vile Reef, its flooded ruins are home to hostile murlocs who attack anyone who ventures near.\n\nOn the sea floor rests a massive stone tablet carved with the story of Gri'lek. He was a legendary troll hero, and the Darkspear still hold his memory sacred.",sp=0},{t="A Keepsake for Orgrimmar",b="The monument is too massive to carry from the depths, so Kin'weelay asks you to break off a shard. He plans to take the fragment to Orgrimmar and enshrine it in a sacred place. There, the Darkspear can keep Gri'lek's strength and honor in their memory.",sp=0}},faq={{q="Where is the Vile Reef located?",a="The Vile Reef lies beneath the Savage Coast, northwest of Grom'gol Base Camp in Stranglethorn Vale.",al={"vile reef location","where is vile reef","how to find vile reef"}},{q="Why does Kin'weelay want the tablet shard?",a="The tablet preserves the sacred story of Gri'lek, a troll hero. Kin'weelay plans to bring a shard to Orgrimmar and place it in a sacred site, keeping the Darkspear's memory of him alive in their new home.",al={"why get tablet shard","tablet shard purpose","why griklek tablet"}},{q="What happened to the ancient city at the Vile Reef?",a="Long ago, a tremendous earthquake shook the Savage Coast and sank the entire troll city beneath the ocean.",al={"what happened to vile reef","how did vile reef sink","sunken troll city history"}},{q="What creatures inhabit the Vile Reef now?",a="Hostile murlocs inhabit the submerged ruins and attack anyone who approaches the sunken city.",al={"monsters in vile reef","vile reef enemies","who lives in vile reef"}},{q="Who is Gri'lek?",a="Gri'lek is a legendary troll hero whose story was carved on the tablet beneath the Savage Coast. The Darkspear hold his memory sacred.",al={"who is griklek","grilek lore","hero griklek"}},{q="Why take only a shard instead of the whole tablet?",a="The carved monument on the ocean floor is too massive to carry from the ruins. A single shard can be brought back to Orgrimmar.",al={"why only a shard","can we take whole tablet","bring whole tablet"}}},ang={["race:Troll"]="For the Darkspear, this fragment keeps their ancient traditions and reverence for the great hero Gri'lek alive in their new home in Orgrimmar.",["faction:Horde"]="By helping Kin'weelay recover this relic for Orgrimmar, you strengthen the bond of trust between the Horde and the Darkspear tribe."},kw={"darkspear","gri'lek","grom'gol base camp","kin'weelay","murloc","savage coast","stranglethorn","tablet shard","vile reef"},rel={"npc:kin-weelay","subzone:vile-reef","subzone:grom-gol-base-camp","subzone:savage-coast","zone:stranglethorn","topic:darkspear-tribe","zone:orgrimmar","topic:murloc"},m={start="Kin'weelay",["end"]="Kin'weelay",level="37",faction="Horde",id=629,ri={"Tablet Shard"}},src={"The Vile Reef (quest)","In-game quest text: The Vile Reef"}}
E["quest:630"] = {t="quest",n="Message in a Bottle",z="stranglethorn",s="The message in a bottle brings you to an island off the Stranglethorn coast, where Princess Poobah waits in chains. King Mukla commands the island’s beasts and keeps her captive. To free her, you need the key to her shackle.",h="The message in a bottle brings you to an island off the Stranglethorn coast, where Princess Poobah waits in...",sec={{t="A Captive on the Isle",b="On an island off the Stranglethorn coast, Princess Poobah waits in chains. The message in the bottle has brought you to her. King Mukla is a great Skymane gorilla who commands the creatures roaming the island. He keeps Poobah imprisoned, and she trusts you to face the ape and bring back her shackle key.",sp=0},{t="The Beast to the Southeast",b="Princess Poobah says her captor often prowls the island’s southeastern side. King Mukla is a formidable foe. Defeating him is the only way to claim the shackle key and free Poobah.",sp=0},{t="Deliverance and Gratitude",b="The key frees Princess Poobah from her chains and saves her from what she sees as a deep dishonor. She cannot grant you full induction into her tribe. Instead, she offers a token of thanks for your courage.",sp=1}},faq={{q="Who is Princess Poobah?",a="Princess Poobah is a tribal captive chained on an island off the coast of Stranglethorn Vale. She sent out a plea in a bottle and waits for someone daring enough to overcome her captor and unlock her shackle.",al={"poobah","who is poobah","princess poobah lore"}},{q="Who holds Princess Poobah captive?",a="King Mukla holds Princess Poobah captive. He is a massive Skymane gorilla who commands the beasts around him on the island.",al={"who captured poobah","poobah captor","king mukla captive"}},{q="Where is King Mukla found?",a="Princess Poobah says King Mukla often prowls the southeastern side of the island.",al={"where is mukla","mukla location","find king mukla"}},{q="What is needed to free Princess Poobah?",a="To free Princess Poobah, defeat King Mukla and take the key to her shackle. Bring it back to unlock her chain.",al={"poobah shackle key","how to free poobah","key to free princess poobah"}},{q="Where does this step fit in the story?",a="This follows the plea found in a bottle and brings you face to face with King Mukla. You can then free Princess Poobah from her chains.",al={"message in a bottle chain","message in a bottle part 2","poobah quest line"}}},kw={"jaguero island","king mukla","princess poobah","shackle key","skymane","stranglethorn"},rel={"quest:594","zone:stranglethorn"},m={start="Princess Poobah",["end"]="Princess Poobah",level="51",faction="Neutral",id=630,ri={"Shackle Key (Stranglethorn Vale)"}},src={"Message in a Bottle (2)"}}
E["quest:638"] = {t="quest",n="Trollbane",z="stranglethorn",s="At Hammerfall, the Darkspear prepare for battles against Zul'Gurub's jungle trolls. Vol'jin has sent them to recover Trol'kalar from ruined Stromgarde, where the blade rested in human hands.",h="At Hammerfall, the Darkspear prepare for battles against Zul'Gurub's jungle trolls.",sec={{t="A King Fallen, A Blade Coveted",b="After King Thoras Trollbane fell, Stromgarde became a ruin. Chieftain Vol'jin then ordered the Darkspear to spirit Trol'kalar away. The storied sword had long rested in human hands. Now the tribe seeks it for the battles ahead against Zul'Gurub's jungle trolls.",sp=0},{t="Journey to Hammerfall",b="Vol'jin sent Zengu, a seasoned hunter, to Hammerfall in the northeastern Arathi Highlands. From Stranglethorn Vale, Nimboya directs travelers to find Zengu and help secure the legendary sword.",sp=0}},faq={{q="Why does Vol'jin want the sword Trol'kalar?",a="Vol'jin wants Trol'kalar for the coming battles against Zul'Gurub's hostile jungle trolls.",al={"why trolkalar","why trollbane sword","purpose of trolkalar"}},{q="Who is Zengu?",a="Zengu is a seasoned Darkspear hunter sent to Hammerfall in the Arathi Highlands to oversee the recovery of Trol'kalar.",al={"who is zengu","zengu role","hunter zengu"}},{q="Where does this journey send you?",a="You travel north from Stranglethorn Vale to Hammerfall, an outpost in the northeastern Arathi Highlands.",al={"where to go","quest destination","where is zengu"}},{q="What happened to Stromgarde?",a="Stromgarde lies in ruins after its ruler, King Thoras Trollbane, fell.",al={"stromgarde status","what happened to thoras trollbane"}}},ang={["race:Troll"]="As a troll, you know Vol'jin seeks Trol'kalar to arm the Darkspear against their ancient kin in Zul'Gurub.",["faction:Horde"]="As a member of the Horde, you can find Zengu at Hammerfall, where he awaits the recovery of the legendary sword from human hands."},kw={"hammerfall","nimboya","stromgarde","trol'kalar","trollbane","vol'jin","zengu","zul'gurub"},rel={"npc:vol-jin","subzone:hammerfall","zone:arathi","subzone:zul-gurub","zone:stranglethorn","topic:troll","topic:human","topic:hunter"},m={start="Nimboya",["end"]="Zengu",level="37",faction="Horde",id=638},src={"Trollbane (quest)"}}
E["quest:670"] = {t="quest",n="Sunken Treasure",z="stranglethorn",s="Fleet Master Seahorn waits in Booty Bay with a letter for Shakes O'Breen off the Arathi coast. His ships cannot sail until they restock.",h="Fleet Master Seahorn waits in Booty Bay with a letter for Shakes O'Breen off the Arathi coast.",sec={{t="A Letter for O'Breen",b="Fleet Master Seahorn sees an adventurer in you. His ships must restock before they can leave Booty Bay. Heavy things are brewing here and abroad, he says, and he has a secret letter for Shakes O'Breen off the Arathi coast. Can he trust you to deliver it safely and keep it confidential?",sp=0}},faq={{q="Who sends you to deliver this letter?",a="Fleet Master Seahorn in Booty Bay gives you a sealed letter for Shakes O'Breen.",al={"who gives sunken treasure 5","who starts this quest","seahorns letter questgiver"}},{q="Why doesn't Fleet Master Seahorn deliver the letter himself?",a="His ships cannot sail from Booty Bay until they restock.",al={"why can't seahorn leave booty bay","why is fleet master seahorn stuck"}},{q="Where is Shakes O'Breen located?",a="Shakes O'Breen is busy off the coast of the Arathi Highlands.",al={"where to find shakes obreen","shakes obreen location","where is shakes"}},{q="What came before this delivery?",a="This delivery follows the fourth part of Sunken Treasure.",al={"sunken treasure chain","what quest comes before sunken treasure 5"}}},kw={"arathi highlands","blackwater raiders","booty bay","fleet master seahorn","seahorn's sealed letter","shakes o'breen","sunken treasure"},rel={"npc:fleet-master-seahorn","subzone:booty-bay","zone:arathi"},m={start="Fleet Master Seahorn",["end"]="Shakes O'Breen",level="40",id=670},src={"Sunken Treasure (5)"}}
E["quest:7810"] = {t="quest",n="Arena Master",z="stranglethorn",s="At the Stranglethorn Arena, Short John Mithril may know what more mastering its contests requires.",h="At the Stranglethorn Arena, Short John Mithril may know what more mastering its contests requires.",sec={{t="Seeking the Pirate",b="You have gained something at Gurubashi, yet mastering the arena asks for more. Short John Mithril organizes the contests and may know what is needed. Find him inside the Stranglethorn Arena.",sp=0},{t="Short John's Word",b="Short John Mithril tells you that one trinket is not enough to master the arena. The true proving of your steel begins now.",sp=1}},faq={{q="Who do I need to speak with?",a="Speak with Short John Mithril, the Pirate behind the Gurubashi event.",al={"who do i talk to","arena master turn in","where to go"}},{q="Where is Short John Mithril?",a="Find Short John Mithril in the Stranglethorn Arena at Gurubashi in Stranglethorn Vale.",al={"gurubashi location","where is stranglethorn arena","arena location"}},{q="What is hinted about being master of the arena?",a="You have done something at Gurubashi, yet mastering the arena seems to ask for more. Short John Mithril, the Pirate behind the event, may know what is needed.",al={"how to be arena master","am i arena master yet"}}},kw={"arena master","gurubashi","pirate","short john mithril","stranglethorn arena","stranglethorn vale"},rel={"zone:stranglethorn","topic:pirate"},m={start="Arena Master",["end"]="Short John Mithril",level="55",id=7810},src={"Wowpedia: Arena Master (quest)"}}
E["quest:78823"] = {t="quest",n="Terror of the Desert Skies",z="stranglethorn",s="A rough drawing shows a great bird of prey that inspired fear and awe. Hemet Nesingwary in Stranglethorn Vale may know more about it.",h="A rough drawing shows a great bird of prey that inspired fear and awe.",sec={{t="A Fearful Image",b="The Primitive Drawing reaches you with a request to take it to Hemet Nesingwary in Stranglethorn Vale. Its broad strokes show a large bird of prey, and the artist's fear and awe are plain in the image. Hemet is asked to judge what it depicts.",sp=0}},faq={{q="What does the drawing show?",a="The Primitive Drawing depicts a large bird of prey.",al={"bird drawing","what is in the picture"}},{q="Who can tell me about the bird?",a="Hemet Nesingwary in Stranglethorn Vale may be able to tell you more about the creature.",al={"who knows about it","bird expert"}},{q="Where do I take the drawing?",a="Bring the Primitive Drawing to Hemet Nesingwary in Stranglethorn Vale.",al={"where to bring drawing","Hemet drawing"}}},kw={"bird of prey","hemet nesingwary","primitive drawing","stranglethorn vale","terror of the desert skies"},rel={"zone:stranglethorn"},m={id=78823},src={"In-game quest text: Terror of the Desert Skies"},fv=true}
E["quest:78830"] = {t="quest",n="Terror of the Desert Skies",z="stranglethorn",s="Hemet Nesingwary has heard of Gharrik, a great bird that hunts in the Badlands. He lends you a cage for live bait and seeks one of her quills.",h="Hemet Nesingwary has heard of Gharrik, a great bird that hunts in the Badlands.",sec={{t="A Desert Hunter",b="A drawing brings Gharrik to mind for Hemet Nesingwary, who has heard of her on another expedition. The great bird is said to rule the Badlands as an apex predator. You are asked to seek her northeast of Camp Cagg, where she was last spotted, and use live bait to draw her out. Small wildlife is scarce in the Badlands, so Hemet lends you a cage to catch bait elsewhere. He hopes for one of Gharrik's quills.",sp=0}},faq={{q="Who is Gharrik?",a="Gharrik is a great bird said to be an apex predator in the Badlands.",al={"gharrik bird","desert bird","who is gharrik"}},{q="Where was Gharrik last seen?",a="Gharrik was last spotted northeast of Camp Cagg in the Badlands.",al={"gharrik location","where gharrik","northeast camp cagg"}},{q="Why does Hemet want a quill?",a="Hemet says a quill from Gharrik would make a fine prize and make you the talk of the camp.",al={"gharrik feather","quill prize","why quill"}},{q="Where can you find bait?",a="Small wildlife is scarce in the Badlands, so Hemet says to find live bait elsewhere and lends you a cage to catch some.",al={"live bait","bait for gharrik","cage bait"}},{q="Who sent me after Gharrik?",a="Hemet Nesingwary asks you to seek Gharrik and bring back one of her quills.",al={"gharrik quest giver","hemet gharrik","who wants the quill"}}},kw={"badlands","camp cagg","crimson trophy quill","gharrik","great bird","hemet nesingwary","live bait"},rel={"quest:5762","zone:badlands","zone:stranglethorn"},m={id=78830},src={"In-game quest text: Terror of the Desert Skies"},fv=true}
E["quest:79236"] = {t="quest",n="Cherry for Your Thoughts?",z="stranglethorn",s="In Booty Bay, Tokal offers a drink for the truth about attacks on human and dwarven outposts. Rumors blame the Horde, but her band served a private mercenary contract.",h="In Booty Bay, Tokal offers a drink for the truth about attacks on human and dwarven outposts.",sec={{t="The Whispers in Booty Bay",b="Tokal keeps out of sight in Booty Bay and watches for law enforcement. Recent raids devastated human and dwarven camps, and rumors blame the Horde. When travelers come who clearly do not work for the marshal asking questions, Tokal gives another account. She offers to tell it in exchange for a drink.",sp=0},{t="Private Mercenaries",b="Tokal admits she joined the pillaging of human and dwarven outposts, but says the Horde did not carry out the raids. Her band worked under a private contract for an unnamed third party. Tokal insists on a Cherry Grog before she names who paid for the operation and why.",sp=1}},faq={{q="Who is Tokal?",a="Tokal is a mercenary hiding in Booty Bay. A marshal is investigating raids on human and dwarven settlements, and Tokal offers to tell who hired her for a Cherry Grog.",al={"who is tokal","tokal booty bay","cherry grog quest giver"}},{q="Why does Tokal want a Cherry Grog?",a="Tokal wants a Cherry Grog before discussing her past contracts. Then she will explain who privately funded the raids on Alliance camps.",al={"why buy cherry grog","cherry grog tokal","what does tokal want"}},{q="Was the Horde responsible for pillaging the human and dwarven camps?",a="Tokal says the Horde did not order the raids on human and dwarven camps. Rumors blame the Horde, but her group worked under a private mercenary contract.",al={"who hired tokal","did horde attack alliance camps","was horde behind the raids"}},{q="Why is Tokal worried about a marshal?",a="Tokal fears a marshal investigating the pillaging of human and dwarven settlements. She checks that anyone approaching her in Booty Bay was not sent to bring her to justice.",al={"who is the marshal","is tokal hiding from marshal","marshal looking for tokal"}},{q="Where do you get Cherry Grog for Tokal?",a="Tavern keepers and barkeepers in Booty Bay sell Cherry Grog. Bringing Tokal a mug meets her demand and prompts her to tell her story.",al={"where to get cherry grog","cherry grog location","booty bay grog"}},{q="Why is Tokal staying in Booty Bay?",a="Booty Bay is a freebooter port beyond the strict jurisdiction of the Alliance and Horde. It gives a mercenary hiding after raids on human and dwarven camps a place to lie low.",al={"why is tokal in booty bay","tokal hiding place"}}},ang={["faction:Alliance"]="As an Alliance member, you can learn that a private patron hired the raiders who struck human and dwarven camps. The Horde did not hire them.",["faction:Horde"]="As a Horde adventurer, you can learn from Tokal that private mercenary contracts led to the attacks on Alliance camps. They were not official Horde aggression."},kw={"booty bay","cherry for your thoughts","cherry grog","marshal","mercenary","pillaging","private contract","tokal"},rel={"subzone:booty-bay","topic:horde","topic:human"},m={id=79236},src={"In-game quest text: Cherry for Your Thoughts?"},fv=true}
E["quest:79242"] = {t="quest",n="No Honor Among Thieves",z="stranglethorn",s="A former thief names Illari Duskfeather as the night elf who led the gang and left them behind. You are pointed toward her hideout on the coast of Arathi Highlands and her cache of stolen goods.",h="A former thief names Illari Duskfeather as the night elf who led the gang and left them behind.",sec={{t="A Gang Betrayed",b="The marshal is on the gang's trail when Illari Duskfeather abandons them. A surviving thief believes they were used as patsies, though he cannot say why. He leaves the pursuit to anyone willing to follow it. Illari once spoke of a hideout on the coast of Arathi Highlands, where her stolen goods remain.",sp=0}},faq={{q="Who is Illari Duskfeather?",a="Illari Duskfeather is a night elf who led a gang of thieves. She gave them information on the camps and kept only some of their rarer finds.",al={"Illari","who's Illari","Illari Duskfeather backstory"}},{q="Why did Illari leave the gang?",a="The surviving thief does not know why Illari abandoned the gang when the marshal was on their trail.",al={"why'd she leave","Illari motives","why abandon the thieves"}},{q="Where can I find Illari?",a="Illari once mentioned a hideout on the coast of Arathi Highlands.",al={"Illari location","where is Illari","Arathi hideout"}},{q="What does the gang want from Illari?",a="The gang's former member points you toward Illari's hideout and her cache of stolen goods.",al={"Illari cache","stolen goods","what's in her hideout"}},{q="Who was the gang's boss?",a="Illari Duskfeather, a night elf, was the gang's boss.",al={"thief boss","gang leader","who led the thieves"}}},ang={["race:NightElf"]="As a night elf, you learn that Illari Duskfeather led a gang of thieves and left them behind when the marshal pursued them."},kw={"arathi highlands","cache","hideout","illari duskfeather","marshal","night elf","no honor among thieves","stolen loot","thieves"},rel={"zone:arathi","topic:night-elf","topic:horde"},m={id=79242},src={"In-game quest text: No Honor Among Thieves"},fv=true}
E["quest:8193"] = {t="quest",n="Master Angler",z="stranglethorn",s="Every Sunday, an angling contest seeks the greatest anglers. Bring Tastyfish from Stranglethorn’s coastal schools among the first fifty to be declared a Master Angler.",h="Every Sunday, an angling contest seeks the greatest anglers.",sec={{t="Sunday’s Contest",b="The contest is open each Sunday, and you can earn the title of Master Angler by bringing Tastyfish to the organizer among the first fifty people. The fish come from schools along the coasts of Stranglethorn, and they spoil quickly.",sp=0},{t="A Second Offer",b="If you arrive too late for the first fifty places, the organizer’s apprentice will still pay you for Tastyfish. The fish do not keep until the next Sunday.",sp=0}},faq={{q="When is the angling contest?",a="The contest takes place every Sunday.",al={"master angler day","what day is fishing contest"}},{q="Where do I find Tastyfish?",a="Tastyfish schools are found along the coasts of Stranglethorn.",al={"tastyfish location","where fish tastyfish"}},{q="How do I become a Master Angler?",a="Bring Tastyfish to the contest organizer among the first fifty people.",al={"master angler requirements","win fishing contest"}},{q="What if I arrive too late?",a="The organizer’s apprentice will pay you for Tastyfish if you are too late to be among the first fifty.",al={"missed the contest","too slow fishing"}},{q="Can I save Tastyfish for next week?",a="No. Tastyfish spoil quickly, so they cannot be saved for the next Sunday.",al={"do tastyfish spoil","keep fish until sunday"}}},kw={"angling contest","fishing","fishing schools","master angler","stranglethorn","sunday","tastyfish"},m={id=8193},src={"In-game quest text: Master Angler"},fv=true}
E["quest:8225"] = {t="quest",n="Rare Fish - Brownell's Blue Striped Racer",z="stranglethorn",s="A fishing record marks Brownell's Blue Striped Racer as identified. The identification is complete.",h="A fishing record marks Brownell's Blue Striped Racer as identified.",sec={{t="The Record",b="A brief signal follows the identification of Brownell's Racer. Brownell's Blue Striped Racer is marked complete, and a reward is available.",sp=0}},faq={{q="What is Brownell's Blue Striped Racer?",a="Brownell's Blue Striped Racer is the fish whose identification is marked complete.",al={"brownell racer","blue striped fish"}},{q="Is the identification complete?",a="Yes. The identification of Brownell's Racer is complete.",al={"fish identification","racer identified"}},{q="Is a reward available?",a="Yes. A reward is available after the identification is complete.",al={"fish reward","what do I get"}}},kw={"brownell's blue striped racer","brownell's racer","fish identification","rare fish","reward"},m={id=8225},src={"In-game quest text: Rare Fish - Brownell's Blue Striped Racer"},fv=true}
E["quest:8551"] = {t="quest",n="The Captain's Chest",z="stranglethorn",s="Smotts' lost chest lies with a sea giant after a wreck near Booty Bay. Captain Hecklebury Smotts once sailed between Booty Bay and Ratchet in Kalimdor. Sea giants wrecked his ship and killed the crew, then sent him toward Booty Bay in a lifeboat. Gorlash took his Captain's Chest, and now Smotts wants it back.",h="Smotts' lost chest lies with a sea giant after a wreck near Booty Bay.",sec={{t="A Ruined Captain",b="Captain Hecklebury Smotts once sailed between Booty Bay and Ratchet in Kalimdor, and earned a fine reputation. Then sea giants smashed his ship and killed the crew. They sent Smotts toward Booty Bay in a lifeboat, and he left his voyages and good name behind.",sp=0},{t="The Stolen Chest",b="Gorlash took Smotts' Captain's Chest, saying he wanted it for a snuffbox. The chest was Smotts' favorite, and a secret compartment held his greatest treasures. Smotts has heard that Gorlash roams the shore east of Booty Bay.",sp=0},{t="Smotts' Thanks",b="Smotts is overjoyed to have his chest back, and its return takes some fire from his anger. His revenge is still not complete.",sp=1}},faq={{q="Who is Captain Hecklebury Smotts?",a="Captain Hecklebury Smotts is a ship captain in Booty Bay. He once sailed between Booty Bay and Ratchet in Kalimdor, until sea giants smashed his ship and killed the crew.",al={"captain smotts","who is smotts","hecklebury smotts"}},{q="Who took the chest?",a="Gorlash, one of the sea giants, took Smotts' chest and said he wanted it as a snuffbox.",al={"who stole the chest","who has smotts chest","gorlash"}},{q="Where can Gorlash be found?",a="Along the shore east of Booty Bay, by Smotts's account.",al={"where is gorlash","gorlash location","find gorlash"}},{q="Why does Smotts want the chest back?",a="Smotts wants his chest back because it was his favorite, and its secret compartment held his greatest treasures.",al={"what is in the chest","why does smotts want the chest"}}},kw={"booty bay","gorlash","ratchet","sea giant","smotts","snuffbox","stranglethorn"},rel={"subzone:booty-bay","subzone:ratchet","zone:stranglethorn"},m={start="Captain Hecklebury Smotts",["end"]="Captain Hecklebury Smotts",level="47",id=8551},src={"Classic quest text: The Captain's Chest"}}
E["quest:8552"] = {t="quest",n="The Monogrammed Sash",z="stranglethorn",s="In Stranglethorn Vale, a lost sash bears initials that may lead to its owner. Finding the seafarer who lost it leads on to The Captain's Cutlass.",h="In Stranglethorn Vale, a lost sash bears initials that may lead to its owner.",sec={{t="A Marked Garment",b="You find a fine sash with the initials HS embroidered along its hem. Those two letters are the only clue to who lost it.",sp=0},{t="The Smotts Connection",b="Returning the sash to Captain Hecklebury Smotts confirms it is his. Its recovery brings news that the sea giant Mok'rash has been slain, news to the captain. The brute had helped destroy his vessels and crew more than once, and the news brings him relief.",sp=1}},faq={{q="What letters are stitched into the sash?",a="The sash's hem bears the embroidered initials HS.",al={"what initials are on sash","initials on monogrammed sash","sash letters"}},{q="Where does this lead next?",a="After you return the sash to its owner, the next step leads to The Captain's Cutlass.",al={"what quest comes after monogrammed sash","monogrammed sash next quest","next step"}}},kw={"hecklebury smotts","hs","mok'rash","monogrammed sash","sea giant","stranglethorn vale"},rel={"quest:8553","quest:618","zone:stranglethorn"},m={start="Monogrammed Sash",["end"]="Captain Hecklebury Smotts",level="50",id=8552},src={"The Monogrammed Sash"}}
E["quest:8553"] = {t="quest",n="The Captain's Cutlass",z="stranglethorn",s="Aboard Smotts' Revenge, Captain Hecklebury Smotts faces defeat at sea once more. Sea giants smash his second ship, kill its crew, and take his cutlass. He sends you to Sprogger, his former cook, to find the behemoth.",h="Aboard Smotts' Revenge, Captain Hecklebury Smotts faces defeat at sea once more.",sec={{t="A Second Calamity",b="After losing his first ship, Captain Hecklebury Smotts bought another and named it Smotts' Revenge. He gathered a new crew and provisions to hunt the sea giants who took his first vessel. The giants smashed the ship and killed the crew. Once more, Smotts was left adrift in a lifeboat, and Negolash took his cutlass in the attack.",sp=0},{t="Consulting the Cook",b="Captain Hecklebury Smotts wants his stolen cutlass back, so he turns to Sprogger. Sprogger was the cook aboard Smotts' Revenge and survived the attack. He can help you track down Negolash.",sp=0}},faq={{q="What ship did Captain Hecklebury Smotts lose in this attack?",a="Captain Hecklebury Smotts bought and outfitted Smotts' Revenge to hunt the sea giants who took his first ship. The giants destroyed that vessel too.",al={"what was the second ship called","smotts second ship","what ship was smashed"}},{q="Who stole the captain's cutlass?",a="Negolash, one of the sea giants, took the captain's cutlass when the giants smashed Smotts' Revenge and killed its crew.",al={"who has the cutlass","which giant took the cutlass","who took smotts cutlass"}},{q="Who is Sprogger?",a="Sprogger was the cook aboard Smotts' Revenge and survived the attack that destroyed the vessel. Captain Smotts directs you to consult him for help tracking down Negolash.",al={"who is sprogger","sprogger role","who was the cook"}},{q="Where does this step fit into the hunt for the sea giants?",a="This step follows The Monogrammed Sash and leads directly to Facing Negolash.",al={"what quest comes before this","what is the next quest","cutlass quest chain"}}},kw={"cutlass","hecklebury smotts","negolash","sea giants","smotts revenge","sprogger","stranglethorn"},rel={"quest:8552","quest:618","zone:stranglethorn"},m={start="Captain Hecklebury Smotts",["end"]="Sprogger",level="42",faction="Both",id=8553},src={"The Captain's Cutlass"}}
E["quest:95141"] = {t="quest",n="Report to Rog'mar",z="stranglethorn",s="An Orc directs you to Rog'mar, an outpost in the embattled Riverglades. Report to Krom'rosh, whose experience has helped the outpost endure repeated attacks.",h="An Orc directs you to Rog'mar, an outpost in the embattled Riverglades.",sec={{t="An Outpost Endures",b="The Riverglades lie northeast of Stonard along the eastern coast. Many have tried to claim the land, though few have managed it. Rog'mar is a small outpost that has survived countless attacks. You are sent there to report to Krom'rosh, an old ally whose battle experience has helped the outpost endure.",sp=0}},faq={{q="Where is Rog'mar?",a="Rog'mar lies in the Riverglades, northeast of Stonard along the eastern coast.",al={"rog'mar location","where is rogmar","rog'mar outpost"}},{q="Who am I reporting to?",a="You are to report to Krom'rosh at the Rog'mar outpost.",al={"report to who","who is krom'rosh","kromrosh"}},{q="What is Rog'mar?",a="Rog'mar is a small outpost in the Riverglades that has endured countless attacks.",al={"rogmar what","riverglades outpost","small outpost"}},{q="Why is Krom'rosh at Rog'mar?",a="Krom'rosh's experience battling enemies has helped the outpost endure.",al={"why kromrosh there","krom'rosh role","who runs rogmar"}},{q="What kind of land are the Riverglades?",a="The Riverglades are an embattled land along the eastern coast, northeast of Stonard.",al={"riverglades","what is riverglades like","embattled land"}}},kw={"attacks","eastern coast","krom'rosh","outpost","riverglades","rog'mar","stonard"},rel={"zone:riverglades","subzone:stonard"},m={faction="Horde",id=95141},src={"In-game quest text: Report to Rog'mar"},fv=true}
E["quest:95748"] = {t="quest",n="The Gurubashi Legends of Old",z="stranglethorn",s="A troll scholar seeks a rubbing of an ancient tablet north of Vile Reef. Its legend may clarify the scale of lost I'lalai.",h="A troll scholar seeks a rubbing of an ancient tablet north of Vile Reef.",sec={{t="A Tablet by the Coast",b="The scholar compares a tablet piece you brought with the ruins off Vile Reef. Those ruins seem too small to match the sprawling civilization described in its words. So the scholar asks you to make a rubbing of a tablet in an ancient troll ruin on the coastal hills to the north.",sp=0},{t="An Old Memory",b="The scholar welcomes the rubbing and says the tablet is familiar from youth. Many moons have passed since it was last read, and the scholar's memory has faded.",sp=0}},faq={{q="What does the scholar want?",a="The scholar wants a rubbing of a tablet containing legends of the lost troll city of I'lalai.",al={"tablet rubbing","what does he need","rubbing request"}},{q="Where is the tablet?",a="It is in an ancient troll ruin on the coastal hills north of Vile Reef.",al={"tablet location","where tablet","north of reef"}},{q="Why does the scholar want a rubbing?",a="A tablet piece you brought describes I'lalai as a sprawling civilization, while the ruins off Vile Reef seem too small to match.",al={"why rubbing","I'lalai tablet","lost city legend"}},{q="What is I'lalai?",a="I'lalai is described in the tablet piece as a lost troll city and a sprawling civilization.",al={"I'lalai city","lost troll city","Ilalai"}},{q="What does the scholar say about the tablet?",a="The scholar has read the tablet before, when young, but says many moons have passed and memory has faded.",al={"scholar memory","read tablet before","old troll legend"}}},ang={["race:Troll"]="As a troll, you are asked to help a scholar study legends of a lost troll city."},kw={"ancient ruin","gurubashi","i'lalai","legend","rubbing","tablet","troll","vile reef"},rel={"subzone:vile-reef","quest:629","topic:troll"},m={faction="Horde",id=95748},src={"In-game quest text: The Gurubashi Legends of Old"},fv=true}
E["quest:95770"] = {t="quest",n="Locating the Lost City",z="stranglethorn",s="Kin'weelay asks you to search the Vile Reef for a cavern tied to the lost city. Naga gathering there may have found something worth investigating.",h="Kin'weelay asks you to search the Vile Reef for a cavern tied to the lost city.",sec={{t="A Cavern in the Reef",b="Kin'weelay recalls diving among the Vile Reef ruins before murlocs settled there. He remembers a cavern and asks you to explore the reef for its entrance. Naga now gather in the region, and he wants to know what drew them there.",sp=0},{t="A Possible Discovery",b="When you return, Kin'weelay listens to what you saw. The naga are coming and going from the cavern ruin, though their purpose remains unclear. He wonders if it connects to I'lalai and the Lost City, long held as myth among trolls. Now he wants to investigate.",sp=1}},faq={{q="Who is asking me to search the Vile Reef?",a="Kin'weelay asks you to explore the Vile Reef and look for a cavern entrance.",al={"who sent me","kin weelay request","who wants this"}},{q="Why am I looking for a cavern?",a="Kin'weelay remembers a cavern among the Vile Reef ruins and suspects it may help locate the Lost City.",al={"why cavern","lost city clue","what am i looking for"}},{q="Why are the naga gathering there?",a="Kin'weelay has heard that naga are gathering in the region, but their reason is unknown.",al={"naga at reef","why naga","naga reason"}},{q="What happened to the Vile Reef ruins?",a="Murlocs settled among the Vile Reef ruins after Kin'weelay's younger years, when he used to dive there.",al={"vile reef ruins","murlocs there","who settled reef"}},{q="Where is the cavern entrance?",a="The cavern entrance is in the Vile Reef. Kin'weelay asks you to explore the reef for it.",al={"cavern location","find entrance","where cavern"}}},kw={"cavern","i'lalai","kin'weelay","locating the lost city","lost city","murlocs","naga","vile reef"},rel={"subzone:vile-reef","npc:kin-weelay","quest:629","topic:naga","topic:murloc","topic:troll"},m={faction="Horde",id=95770},src={"In-game quest text: Locating the Lost City"},fv=true}
E["quest:95773"] = {t="quest",n="Enemies in the Water",z="stranglethorn",s="Naga gather near old troll ruins off the coast, while the Horde is already pressed by attacks on its caravans. You are asked to answer this threat and show that you are proving your worth.",h="Naga gather near old troll ruins off the coast, while the Horde is already pressed by attacks on its caravans.",sec={{t="Reports from the Coast",b="The Horde has received reports of naga gathering near old troll ruins beneath the sea. Bloodscalp and ogre attacks are already straining its defenses, so a threat from the water gives little room for delay. You are asked to confront the Brinescale skirmishers and bring back their tridents as proof.",sp=0},{t="A Message at Grom’gol",b="At Grom’gol, the tridents you bring back are meant to be planted outside the gates. Their display will warn that the Horde is not to be trifled with, and your work earns the commander’s praise.",sp=1}},faq={{q="Why are the naga near the coast?",a="Reports say the naga are gathering around old troll ruins beneath the sea.",al={"naga coast","naga in water","why naga here"}},{q="Who are the enemies here?",a="The threat comes from Brinescale skirmishers, a group of naga reported near the coast.",al={"water enemies","who naga","brinescale"}},{q="Why does the Horde want the naga dealt with?",a="The Horde is already stretched thin defending its caravans from Bloodscalp and ogre attacks, and fears a surprise assault from the sea.",al={"why kill naga","horde naga problem","sea attack"}},{q="What proof is requested?",a="You are asked to bring back Brinescale tridents as proof of your success.",al={"trident proof","what bring back","brinescale tridents"}},{q="What will happen to the tridents?",a="They will be planted outside Grom’gol’s gates as a warning that the Horde is not to be trifled with.",al={"trident message","plant tridents","gromgol tridents"}},{q="How does this prove my worth?",a="The commander praises your work and says you are quickly proving your worth to the Horde.",al={"prove worth","horde approval","why am i here"}}},ang={["faction:Horde"]="The Horde seeks to protect its caravans while keeping watch for a possible attack from the sea."},kw={"bloodscalp","brinescale","enemies in the water","grom'gol","horde","naga","ogres","tridents","troll ruins"},rel={"topic:naga","topic:horde","topic:troll"},m={faction="Horde",id=95773},src={"In-game quest text: Enemies in the Water"},fv=true}
E["quest:95775"] = {t="quest",n="The Drowned City",z="stranglethorn",s="A scholar asks you to inspect ruins guarded by naga and copy their tablet etchings. The city may be I’lalai, rich in lost history.",h="A scholar asks you to inspect ruins guarded by naga and copy their tablet etchings.",sec={{t="Across the Cavern",b="The scholar is too old to enter the ruins, so you are asked to go in their stead. Beyond the cavern guarded by naga, the scholar suspects the ruins may be I’lalai. The lost city could hold a wealth of historical knowledge. You are to make rubbings of any tablets you find and bring them back.",sp=0}},faq={{q="What is the Drowned City?",a="The ruins may be the lost city of I’lalai, according to the scholar who sent you.",al={"drowned city","what city is this","I'lalai ruins"}},{q="Who wants me to explore the ruins?",a="A scholar asks you to explore the ruins because they are too old to go themselves.",al={"who sent me","who wants rubbings","scholar request"}},{q="Why am I being sent there?",a="The scholar hopes the ruins hold a great wealth of lost historical knowledge.",al={"why explore","why tablets","lost history"}},{q="What am I supposed to bring back?",a="Make rubbings of any tablets you find using hide and charcoal, then return them to the scholar.",al={"what to bring back","tablet rubbings","rubbing task"}},{q="Where are the ruins?",a="The ruins lie on the other side of the cavern guarded by naga.",al={"where is drowned city","naga cavern","ruins location"}}},kw={"charcoal","drowned city","hide","i'lalai","lost history","naga","rubbings","ruins","tablets"},rel={"topic:naga"},m={faction="Horde",id=95775},src={"In-game quest text: The Drowned City"},fv=true}
E["quest:95776"] = {t="quest",n="The Only Good Brinescale...",z="stranglethorn",s="Naga in the waters near the coast raise concern about a larger threat. You are asked to find their leader in the Drowned City.",h="Naga in the waters near the coast raise concern about a larger threat.",sec={{t="A Threat Offshore",b="The naga near the coast have been slain, yet their numbers point to a greater danger. Kin'weelay believes the Brinescale naga are entering the ruins of the Drowned City. Their presence there suggests they seek something that could put the coast at risk. You are asked to slay their leader, Var'Taka.",sp=0},{t="The Return",b="When you return, your employer takes your arrival to mean Var'Taka is dead. With the naga leader gone, there is one less concern for the coast.",sp=1}},faq={{q="Why are the Brinescale naga in the Drowned City?",a="Kin'weelay believes the Brinescale naga are searching for something in the Drowned City, but what they seek is not known.",al={"why naga there","brinescale purpose","what are naga searching for"}},{q="Who is Kin'weelay?",a="Kin'weelay is the one who believes the Brinescale naga are infiltrating the Drowned City.",al={"kin weelay","who's kin'weelay","kin"}},{q="Who is Var'Taka?",a="Var'Taka is the leader of the Brinescale naga in the Drowned City.",al={"var taka","naga leader","brinescale leader"}},{q="What am I asked to do?",a="You are asked to slay Var'Taka in the Drowned City.",al={"what do i do","what's the task","kill who"}}},kw={"brinescale","coast","drowned city","infiltration","kin'weelay","naga","var'taka"},rel={"npc:kin-weelay","topic:naga","quest:95775"},m={faction="Horde",id=95776},src={"In-game quest text: The Only Good Brinescale..."},fv=true}
E["quest:95786"] = {t="quest",n="An Acquaintance in Southshore",z="stranglethorn",s="Brother Nimetz sends you to Southshore with a report for Loremaster Dibbs. Agitated trolls and the word “I'lalai” may be tied to Colonel Kurzen's corruption.",h="Brother Nimetz sends you to Southshore with a report for Loremaster Dibbs.",sec={{t="A Word in the Report",b="Brother Nimetz sends you from Stranglethorn to Southshore with a bundle of troll legends, fetishes, and a scout's report. The local trolls are agitated and speak of “I'lalai.” Nimetz hopes Loremaster Dibbs can tell whether this has a bearing on Colonel Kurzen's corrupted mind.",sp=0},{t="At Southshore",b="Loremaster Dibbs receives you in Southshore and remarks on the long journey from Stranglethorn. He asks what brought you there, with Nimetz's report and materials in hand.",sp=0}},faq={{q="Who sent me to Southshore?",a="Brother Nimetz sent you from Stranglethorn to speak with Loremaster Dibbs.",al={"who sent me","nimetz southshore","brother nimetz"}},{q="Why am I going to Southshore?",a="Nimetz wants Loremaster Dibbs to examine troll legends, fetishes, and a scout's report for a possible connection to Colonel Kurzen's corruption.",al={"why southshore","dibbs report","what am i taking"}},{q="Who is Loremaster Dibbs?",a="Loremaster Dibbs is Nimetz's friend in the Hillsbrad Foothills, where he studies troll legends and evil magic.",al={"who's dibbs","dibbs southshore","loremaster"}},{q="What does the scout's report say?",a="The report says the local trolls are agitated and have mentioned “I'lalai.”",al={"scout report","trolls agitated","what is ilalai"}},{q="Where do I find Loremaster Dibbs?",a="Loremaster Dibbs is in Southshore.",al={"dibbs location","find dibbs","southshore"}}},kw={"brother nimetz","colonel kurzen","corruption","fetishes","i'lalai","loremaster dibbs","scout report","southshore","stranglethorn","troll legends"},rel={"subzone:southshore","zone:hillsbrad","subzone:savage-coast","topic:troll"},m={faction="Alliance",id=95786},src={"In-game quest text: An Acquaintance in Southshore"},fv=true}
E["quest:95789"] = {t="quest",n="Shady Saltseers",z="stranglethorn",s="A contact of Baron Revilgaz sends you to the Drowned City after the Saltseers, pirates who collect magical artifacts. Their stolen goods have drawn attention now that the sunken troll ruin has risen again.",h="A contact of Baron Revilgaz sends you to the Drowned City after the Saltseers, pirates who collect magical...",sec={{t="A Baron’s Request",b="A contact of Baron Revilgaz asks you to recover artifacts from the Saltseers in the Drowned City. The pirates collect magical objects, and the ruin’s return has left goods there for the taking. Their stolen artifacts are what Revilgaz’s contact seeks.",sp=0}},faq={{q="Who wants the Saltseers’ artifacts?",a="A contact of Baron Revilgaz asks you to recover the artifacts.",al={"who sent me","baron revilgaz contact","who wants artifacts"}},{q="Who are the Saltseers?",a="The Saltseers are pirates who collect magical artifacts.",al={"saltseer pirates","who are saltseers","saltseers"}},{q="Where are the Saltseers?",a="They are in the Drowned City, a sunken troll ruin that has risen again.",al={"where is drowned city","saltseers location","drowned city"}},{q="What artifacts am I looking for?",a="You are asked to recover Voodoo Infused Artifacts stolen by the Saltseers.",al={"what to collect","voodoo artifacts","stolen goods"}}},kw={"baron revilgaz","drowned city","magical artifacts","pirates","saltseers","shady saltseers","troll ruin","voodoo infused artifacts"},rel={"npc:baron-revilgaz","topic:pirate","topic:troll","quest:95775"},m={id=95789},src={"In-game quest text: Shady Saltseers"},fv=true}
E["quest:95791"] = {t="quest",n="The Saltseer Captain",z="stranglethorn",s="A rival hunter wants Captain Dreadrise and his Saltseer Coroners removed from the Drowned City. Their crew keeps gathering the magical artifacts he seeks.",h="A rival hunter wants Captain Dreadrise and his Saltseer Coroners removed from the Drowned City.",sec={{t="A Rival in the City",b="A rival hunter seeks your help in the Drowned City, where the Saltseer pirates have become a thorn in his side. Captain Dreadrise and his Saltseer Coroners gather the magical artifacts he wants. He asks you to remove the captain and three of his crew from the picture.",sp=0}},faq={{q="Who is Captain Dreadrise?",a="Captain Dreadrise leads the Saltseer pirates in the Drowned City.",al={"dreadrise","saltseer captain","captain guy"}},{q="Who are the Saltseer Coroners?",a="The Saltseer Coroners are crew members Captain Dreadrise works with in gathering magical artifacts.",al={"saltseer crew","coroners","dreadrise's crew"}},{q="Why does the giver want Dreadrise gone?",a="Captain Dreadrise and his crew keep gathering magical artifacts the giver has been seeking, and he is tired of the competition.",al={"why kill dreadrise","why remove captain","dreadrise rival"}},{q="Where are Captain Dreadrise and the Saltseers?",a="Captain Dreadrise and the Saltseer pirates are in the Drowned City.",al={"where is dreadrise","saltseer location","drowned city pirates"}},{q="What does the giver ask me to do?",a="The giver asks you to slay Captain Dreadrise and three Saltseer Coroners in the Drowned City.",al={"what do i do","dreadrise quest","saltseer task"}}},kw={"captain dreadrise","drowned city","magical artifacts","pirates","saltseer","saltseer coroners"},rel={"quest:95775","topic:pirate"},m={id=95791},src={"In-game quest text: The Saltseer Captain"},fv=true}
E["quest:96078"] = {t="quest",n="A Tale Spun Around the Fire",z="stranglethorn",s="Kin'weelay asks you to bring tablet etchings to Master Gadrin in Sen'jin Village. The Darkspear preserve traditions through stories, and Gadrin wants to hear this tale.",h="Kin'weelay asks you to bring tablet etchings to Master Gadrin in Sen'jin Village.",sec={{t="A Tale Shared",b="Kin'weelay has prepared another copy of the tale if your own is lost. Darkspear stories pass legends to the young, teaching lessons and caution through words spoken aloud. Take the etchings to Master Gadrin, the Darkspear spiritual leader in Sen'jin Village, so he can hear the tale.",sp=0},{t="Gadrin's Thanks",b="After you explain how the I'lalai tablet etchings came into your hands, Master Gadrin listens closely. He is glad Kin'weelay cares about preserving and uncovering Darkspear heritage lost over the centuries. Gadrin notes that the Darkspear separated from the Gurubashi not long ago in the grand span of history, then gives you something Kin'weelay asked him to pass along in thanks.",sp=1}},faq={{q="Who wants the etchings?",a="Kin'weelay asks you to take the tablet etchings to Master Gadrin in Sen'jin Village.",al={"who sent me","kinweelay tale","kin'weelay"}},{q="Why take them to Master Gadrin?",a="Master Gadrin is the Darkspear spiritual leader, and Kin'weelay says he will want to hear the tale.",al={"why gadrin","where do etchings go","tablet etchings"}},{q="How do the Darkspear preserve traditions?",a="The Darkspear pass legends to the next generation through oral storytelling, teaching lessons and cautionary tales.",al={"darkspear stories","oral tradition","troll tales"}},{q="What are the etchings from?",a="They are etchings from the I'lalai tablet.",al={"ilalai tablet","i'lalai","tablet story"}},{q="Where is Master Gadrin?",a="Master Gadrin is in Sen'jin Village in Durotar.",al={"gadrin location","senjin village","where is gadrin"}}},ang={["race:Troll"]="As a troll, you bring a tale of Darkspear tradition to Master Gadrin, who values preserving and discovering ancestral heritage."},kw={"darkspear","gurubashi","i'lalai","kin'weelay","master gadrin","oral storytelling","sen'jin village","tablet etchings"},rel={"npc:kin-weelay","npc:master-gadrin","subzone:sen-jin-village","zone:durotar"},m={faction="Horde",id=96078},src={"In-game quest text: A Tale Spun Around the Fire"},fv=true}
E["quest:97047"] = {t="quest",n="The Cook in the Cage",z="stranglethorn",s="Wendel asks you to free him from a cage in the Kurzen compound. He needs a key and a disguise to slip away.",h="Wendel asks you to free him from a cage in the Kurzen compound.",sec={{t="Wendel's Plea",b="Wendel is trapped in the Kurzen compound after an ambush in the jungle. He fears what his captors may do and asks you to find a key for his cage and a disguise to help him escape.",sp=0}},faq={{q="Who is trapped in the cage?",a="Wendel is an explorer who was ambushed in the jungle and taken prisoner.",al={"who is Wendel","caged guy","who needs help"}},{q="Where is Wendel being held?",a="Wendel is held in a cage within the Kurzen compound.",al={"where is the cage","Wendel location","where is he"}},{q="What does Wendel need?",a="Wendel asks you to find a key for his cage and a disguise so he can sneak out.",al={"how to free Wendel","what does he want","cage key disguise"}},{q="Why is Wendel afraid?",a="Wendel has heard talk of tigers and headshrinkers, but does not know what his captors plan to do with him.",al={"what are the Kurzen planning","tigers and headshrinkers","why is he scared"}}},kw={"cage","disguise","headshrinkers","jungle","key","kurzen compound","tigers","wendel"},m={id=97047},src={"In-game quest text: The Cook in the Cage"},fv=true}
E["quest:97048"] = {t="quest",n="Returning to Port",z="stranglethorn",s="A rescued cook asks you to speak with Captain Aransas in Booty Bay. His return matters to the captain, who has lost a member of her crew.",h="A rescued cook asks you to speak with Captain Aransas in Booty Bay.",sec={{t="Back to the Captain",b="Captain Aransas is waiting in Booty Bay, where you bring the cook back to her ship. He promises to speak well of you when he returns, and says the captain will be glad to have him back. She welcomes you and hears what Mathers said about your escape from Kurzen's Compound.",sp=0},{t="The Captain's Thanks",b="Captain Aransas knows Mathers' tale of daring swordplay is a fib; she says the cook is fit to wield only a kitchen knife. Still, she thanks you for saving one of her crew. A good cook is precious aboard her ship.",sp=1}},faq={{q="Who is Captain Aransas?",a="Captain Aransas commands the ship whose cook you return to her in Booty Bay.",al={"captain aransas","aransas"}},{q="Who is Mathers?",a="Mathers is Captain Aransas' cook and a member of her crew.",al={"mathers","cook mathers"}},{q="Where do I find Captain Aransas?",a="Captain Aransas is in Booty Bay.",al={"aransas location","captain in booty bay"}},{q="Why does the captain thank me?",a="She thanks you for saving a member of her crew.",al={"why thanks","saved the cook"}},{q="What did Mathers say about the escape?",a="Mathers told Captain Aransas that you and he broke out of Kurzen's Compound together.",al={"mathers story","what did he tell aransas"}}},kw={"booty bay","captain aransas","cook","crew","kurzen's compound","mathers","returning to port"},rel={"subzone:booty-bay","subzone:kurzen-s-compound"},m={id=97048},src={"In-game quest text: Returning to Port"},fv=true}
E["quest:97328"] = {t="quest",n="Anything of Value",z="stranglethorn",s="A zeppelin crash in Stranglethorn Vale leaves signs that a shipment was plundered. Its torn label still points toward Booty Bay.",h="A zeppelin crash in Stranglethorn Vale leaves signs that a shipment was plundered.",sec={{t="A Torn Label",b="In Stranglethorn Vale, the crash debris holds signs of a plundered supply shipment. Its labels are shredded, though one still bears the words Booty Bay. Two-toed footprints and divots in the earth lead toward the ruins of Zul'Kunda in the northwest.",sp=0}},faq={{q="What happened to the shipment?",a="The supplies were plundered, and the shipping labels were torn apart.",al={"stolen shipment","zeppelin cargo","what was plundered"}},{q="Where did the footprints lead?",a="The footprints and divots lead toward the ruins of Zul'Kunda in the northwest.",al={"two toed tracks","where is the trail","footprints"}},{q="What does the surviving label say?",a="One torn label still shows the words Booty Bay.",al={"booty bay label","torn shipping label","where was it going"}},{q="Who needs the recovered shipments?",a="The shipments are to be returned to someone in Booty Bay.",al={"who wants the cargo","where do I take it","shipment return"}}},kw={"anything of value","booty bay","crash","footprints","shipment","stolen supplies","zeppelin","zul'kunda"},rel={"zone:stranglethorn","subzone:booty-bay","quest:98247"},m={id=97328},src={"In-game quest text: Anything of Value"},fv=true}
E["quest:97329"] = {t="quest",n="Where's the Key?",z="stranglethorn",s="Zimmix Sputterspark is trapped in a troll cage after his zeppelin from Booty Bay was shot down. He asks you to bring him a key held by trolls at Zul'Kunda.",h="Zimmix Sputterspark is trapped in a troll cage after his zeppelin from Booty Bay was shot down.",sec={{t="A Downed Zeppelin",b="Zimmix Sputterspark calls you over from his cage among the trolls. He had arranged for Booty Bay to use its zeppelin tower for faster deliveries, but the first route ended with his craft shot down to the east. He survived the crash, then woke to find himself dragged away and locked up among trolls. Now he asks you to bring him the Primitive Key held by trolls at the Ruins of Zul'Kunda in Stranglethorn Vale.",sp=0},{t="The Key",b="At the cage, Zimmix lunges toward the key when you bring it back. He repeatedly tries to snatch it from you and insists that you hand it over.",sp=0}},faq={{q="Who is trapped in the cage?",a="Zimmix Sputterspark is caged by trolls. His zeppelin from Booty Bay was shot down on its first route.",al={"who is Zimmix","caged gnome","zimix"}},{q="What happened to Zimmix's zeppelin?",a="Zimmix says his zeppelin was shot down to the east on its first delivery route.",al={"why did he crash","zeppelin crash","what happened to Zimmix"}},{q="Why is Zimmix in a cage?",a="After surviving the crash, Zimmix woke while he was being dragged by his ears and found himself locked in a cage among trolls.",al={"why caged","troll cage","how did he get caught"}},{q="What key does Zimmix want?",a="Zimmix asks you to bring him the Primitive Key held by trolls at the Ruins of Zul'Kunda in Stranglethorn Vale.",al={"which key","primitive key","key for Zimmix"}},{q="Where is the Primitive Key?",a="The Primitive Key is held by trolls at the Ruins of Zul'Kunda in Stranglethorn Vale.",al={"where key","zul kunda key","key location"}},{q="What does Zimmix do when you bring the key?",a="Zimmix lunges toward the key and repeatedly tries to swipe it from you.",al={"key handover","Zimmix grabs key","what happens with key"}}},kw={"booty bay","cage","primitive key","trolls","where's the key","zeppelin","zimmix sputterspark","zul'kunda"},rel={"subzone:booty-bay","zone:stranglethorn","topic:troll"},m={id=97329},src={"In-game quest text: Where's the Key?"},fv=true}
E["quest:97331"] = {t="quest",n="Zimmix's Great Escape",z="stranglethorn",s="Zimmix Sputterspark asks you to escort him from the Ruins of Zul'Kunda. He fears the trolls may catch him again, and Wharfmaster Lozgil in Booty Bay is to hear of the rescue.",h="Zimmix Sputterspark asks you to escort him from the Ruins of Zul'Kunda.",sec={{t="A Goblin's Plea",b="At the Ruins of Zul'Kunda, Zimmix Sputterspark asks you to keep watch as he leaves. He says the trolls caught him once, and worries they may do so again. You have already weakened their numbers enough to get the key he needed. Now Zimmix wants your help reaching safety, with Wharfmaster Lozgil in Booty Bay awaiting word of the rescue.",sp=0}},faq={{q="Who is Zimmix?",a="Zimmix Sputterspark is a goblin who asks you to escort him from the Ruins of Zul'Kunda.",al={"zimmix","who's zimmix","zimmix sputterspark"}},{q="Why does Zimmix want an escort?",a="Zimmix fears the trolls may catch him again after they caught him once before.",al={"why escort zimmix","zimmix scared","trolls got him"}},{q="Where are you escorting Zimmix from?",a="You are escorting Zimmix away from the Ruins of Zul'Kunda.",al={"where is zimmix","zul'kunda","zimmix location"}},{q="Who should hear about the rescue?",a="Wharfmaster Lozgil in Booty Bay is to hear of Zimmix's successful rescue.",al={"who to tell","lozgil","rescue report"}},{q="What key did Zimmix need?",a="Zimmix says he needed a key, and that you weakened the trolls enough to get it.",al={"zimmix key","why get the key","key for zimmix"}}},kw={"booty bay","great escape","key","ruins of zul'kunda","trolls","wharfmaster lozgil","zimmix","zimmix sputterspark"},rel={"subzone:booty-bay","topic:troll","topic:goblin"},m={id=97331},src={"In-game quest text: Zimmix's Great Escape"},fv=true}
E["subzone:bal-lal-ruins"] = {t="subzone",n="Bal'lal Ruins",z="stranglethorn",s="Bloodscalp trolls guard Bal'lal Ruins on Stranglethorn Vale's northwestern shore, north of Grom'gol Base Camp. The old Gurubashi stones overlook the Vile Reef.",h="Bloodscalp trolls guard Bal'lal Ruins on Stranglethorn Vale's northwestern shore, north of Grom'gol Base Camp.",sec={{t="A Crumbling Outpost on the Reef",b="Bloodscalp trolls keep watch among the weathered stones of Bal'lal Ruins above the Vile Reef. The site lies on Stranglethorn Vale's coast, north of Grom'gol Base Camp. These stones remain from the Gurubashi Empire, the troll civilization that once ruled southern Azeroth. Cracked walls mark the ruins' long decay, and Bloodscalp trolls defend these ancestral relics against intruders.",sp=0}},faq={{q="Who controls Bal'lal Ruins?",a="The Bloodscalp tribe occupies Bal'lal Ruins and guards the territory against outsiders, travelers, and rivals.",al={"who lives here","ballal ruins mobs","who is at ballal ruins"}},{q="Where are the Bal'lal Ruins located?",a="Bal'lal Ruins lie on Stranglethorn Vale's northwestern coast, north of Grom'gol Base Camp and overlooking the Vile Reef.",al={"ballal ruins location","where is ballal ruins","how to find ballal ruins"}},{q="What history do these ruins have?",a="Bal'lal Ruins date to the ancient Gurubashi Empire, before it broke apart into warring jungle troll tribes.",al={"ballal lore","history of ballal ruins","who built ballal ruins"}}},ang={["race:Troll"]="As a Darkspear troll of the Horde, you can see ancient Gurubashi glory at Bal'lal, now held by cousin tribes consumed by bloodlust.",["faction:Horde"]="From Grom'gol Base Camp, Horde patrols along the shoreline face hostile Bloodscalp trolls at Bal'lal Ruins."},kw={"bal'lal ruins","ballal ruins","bloodscalp","grom'gol","gurubashi","stranglethorn vale","vile reef"},rel={"zone:stranglethorn","subzone:vile-reef","subzone:grom-gol-base-camp","topic:troll"},src={"Bal'lal Ruins"}}
E["subzone:balia-mah-ruins"] = {t="subzone",n="Balia'mah Ruins",z="stranglethorn",s="Skullsplitter warriors hold the Balia'mah Ruins in northern Stranglethorn Vale. Across the river east of Grom'gol Base Camp, the old Gurubashi settlement's stone tiers crumble under the jungle.",h="Skullsplitter warriors hold the Balia'mah Ruins in northern Stranglethorn Vale.",sec={{t="A Shattered Heritage",b="Balia'mah's stone terraces recall the Gurubashi Empire, which once ruled much of the southern Eastern Kingdoms. When its ancient capital fell, Gurubashi lands split among warring factions. Now the Skullsplitter tribe holds the ruins. They defend them from beasts, ogres from the Mosh'Ogg mound, and outsiders crossing the river.",sp=0}},faq={{q="Where are the Balia'mah Ruins located?",a="The Balia'mah Ruins lie in northern Stranglethorn Vale, east-southeast across the river from Grom'gol Base Camp and southwest of the Mosh'Ogg Ogre Mound.",al={"bali'mah location","where is balia mah","baliamah ruins map"}},{q="Who controls the ruins right now?",a="The Skullsplitter tribe occupies the ruins and guards the ancient stone terraces.",al={"who lives in balia mah","what mobs are at balia mah","balia mah enemies"}},{q="What is the history of Balia'mah?",a="The Gurubashi built the complex at the height of their empire. After the empire fell, the site decayed, then jungle growth and surviving troll tribes reclaimed it.",al={"balia mah lore","who built balia mah"}},{q="Are the Skullsplitters at Balia'mah connected to other troll camps?",a="Yes. The Skullsplitter tribe keeps several camps and ruins across northern and central Stranglethorn Vale. There, it fights rival tribes such as the Bloodscalp for territory.",al={"skullsplitters in stranglethorn","baliamah skullsplitters"}}},ang={["race:Troll"]="As a Darkspear, these ancient stone terraces recall the proud Gurubashi civilization your ancestors shared. Factionalism later divided jungle troll society.",["faction:Horde"]="Across the river from Grom'gol Base Camp, hostile Skullsplitters at Balia'mah threaten Horde scouts and supply lines."},kw={"balia'mah","baliamah","gurubashi","ruins","skullsplitter","stranglethorn"},rel={"zone:stranglethorn","subzone:grom-gol-base-camp","subzone:mosh-ogg-ogre-mound","topic:troll"},src={"Balia'mah Ruins"}}
E["subzone:booty-bay"] = {t="subzone",n="Booty Bay",z="stranglethorn",s="In Booty Bay, goblins keep a neutral port open to Alliance and Horde alike. The Steamwheedle Cartel's Blackwater Raiders hold this harbor in southern Stranglethorn Vale, where travelers enter by land through a giant shark's jaws.",h="In Booty Bay, goblins keep a neutral port open to Alliance and Horde alike.",sec={{t="A Den of Scoundrels and Profit",b="Booty Bay began as the human settlement of Blackwater Cove. Jungle trolls took it, then goblins of the Steamwheedle Cartel captured it. Now merchants, outcasts, and scoundrels come here from many lands. Baron Revilgaz and Fleet Master Seahorn watch the port from the balconies of the Salty Sailor Tavern.\n\nThe harbor may seem lawless, but the cartel keeps order. Anyone may drink, trade, or hire mercenaries, so long as they respect the cartel's peace and pay the harbor fees.",sp=0},{t="Threats on the Water",b="Booty Bay's docks link the Eastern Kingdoms with ratchet across the Great Sea. Trade and travelers pass between the continents here. Such wealth draws enemies. The Bloodsail Buccaneers are a hostile pirate fleet that raids Blackwater shipping and prowls the Stranglethorn coast. They plot to destroy and plunder the goblin port.",sp=0}},faq={{q="Who rules Booty Bay?",a="Baron Revilgaz rules Booty Bay for the Steamwheedle Cartel, alongside Fleet Master Seahorn, the tauren commander of the Blackwater Raiders. They direct their operations from the Salty Sailor Tavern's upper decks, above the harbor.",al={"booty bay leader","who is in charge of booty bay","booty bay boss"}},{q="Why can Alliance and Horde players stand together here?",a="The neutral Steamwheedle Cartel values profit and trade above the Alliance and Horde conflict. It welcomes anyone with coin. When someone starts a brawl, goblin bruisers go after them.",al={"why is booty bay neutral","booty bay safe zone","can horde attack alliance here"}},{q="Who are the Bloodsail Buccaneers?",a="The Bloodsail Buccaneers are an outlaw syndicate at war with the Blackwater Raiders. Their ships command the waters off southern Stranglethorn Vale, and they plot to overwhelm Booty Bay and seize its lucrative harbor.",al={"bloodsail pirates","why do bloodsail hate booty bay","bloodsail buccaneers lore"}},{q="Where does the boat in Booty Bay sail?",a="The passenger vessel from Booty Bay's lower docks crosses the Great Sea to Ratchet in the Barrens. It is the main neutral passage between the southern Eastern Kingdoms and Kalimdor.",al={"booty bay boat destination","where does the ship go","boat to kalimdor"}},{q="What is the giant statue standing at the bay's entrance?",a="An unknown goblin with outstretched arms is carved into the massive statue at Janeiro's Point, just outside the harbor mouth. It guides merchant ships and pirate crews as a beacon and welcoming monument.",al={"booty bay statue","colossus of booty bay","statue on the island"}}},ang={["class:Rogue"]="As a rogue, you can find underworld contacts, fences, lockboxes, and covert informants in Booty Bay. They trade secrets for coin.",["faction:Alliance"]="Far south of Stormwind's protected borders, Booty Bay offers you neutral amenities, flight routes, and ship passage straight to Kalimdor."},kw={"blackwater raiders","bloodsail buccaneers","booty bay","ratchet","revilgaz","salty sailor","seahorn","steamwheedle cartel","stranglethorn"},rel={"zone:stranglethorn","subzone:salty-sailor-tavern","npc:baron-revilgaz","npc:fleet-master-seahorn","subzone:ratchet","subzone:janeiro-s-point","topic:steamwheedle-cartel","topic:pirate"},src={"Booty Bay"}}
E["subzone:cape-of-stranglethorn"] = {t="subzone",n="Cape of Stranglethorn",z="stranglethorn",s="Booty Bay holds fast as rival crews contest the Cape of Stranglethorn. From Gurubashi Arena to the ocean cliffs, goblins, Bloodsail Buccaneers, ancient jungle trolls, and wildlife struggle for control.",h="Booty Bay holds fast as rival crews contest the Cape of Stranglethorn.",sec={{t="Edge of the Continent",b="South of Gurubashi Arena, dense jungle reaches the coast. The Ruins of Jubuwal and the Ruins of Aboraz mark ground the Gurubashi Empire no longer holds. Now predators, murloc encampments, and rival pirate crews fill the beaches, coves, and clearings. They fight over trade routes and buried plunder.",sp=0},{t="Booty Bay and the Buccaneer War",b="The Blackwater Raiders hold the cape’s greatest power. Baron Revilgaz and Fleet Master Seahorn lead them from Booty Bay, a neutral harbor carved into the southern bay’s cliffs. Steamships link the Eastern Kingdoms to Kalimdor through Ratchet.\n\nYet goblin control remains precarious. Along the southern shoals and outer islands, the Bloodsail Buccaneers raid supply lines and plot to overthrow Booty Bay and seize the South Seas.",sp=0}},faq={{q="What is the difference between Stranglethorn Vale and the Cape of Stranglethorn?",a="The Cape of Stranglethorn is the southern part of the larger Stranglethorn Vale. It runs from south of Gurubashi Arena to Booty Bay and the coast.",al={"cape vs vale","stranglethorn geography","where is the cape"}},{q="Who rules the Cape of Stranglethorn?",a="No single power controls the entire cape. Baron Revilgaz and the goblin-backed Blackwater Raiders govern Booty Bay and nearby waters. Bloodsail Buccaneers, naga, and troll remnants hold beaches and interior ruins.",al={"who leads booty bay","cape ruler","who controls the cape"}},{q="Can Horde and Alliance both use Booty Bay?",a="Yes. Booty Bay is an open, neutral port maintained by the Steamwheedle Cartel. Keep your weapons sheathed and the peace within city limits, and both Alliance and Horde travelers can use its docks, vendors, flight master, and auction house.",al={"is booty bay neutral","alliance horde booty bay","can horde enter booty bay"}},{q="What is the Gurubashi Arena?",a="The Gurubashi Arena is an ancient troll fighting pit near the cape’s northern edge. Combatants gather there to test themselves.",al={"gurubashi chest","arena rules","pvp arena stranglethorn"}},{q="How do travelers get between the Cape and Kalimdor?",a="A goblin-operated steamship regularly sails from Booty Bay to Ratchet, the port town in the Barrens. It is one of the few passenger links across the South Seas.",al={"boat to ratchet","kalimdor transport","booty bay boat"}}},ang={["class:Rogue"]="As a rogue, you can find privateers, scoundrels, and cutthroats across the cape. Pick pockets, run coastal contraband, or play the Blackwater Raiders against the Bloodsail Buccaneers.",["profession:Cooking"]="As a cook, you can fish the rich waters of the South Seas and coast. Booty Bay’s fishmongers and harbor cooks sell rare recipes."},kw={"baron revilgaz","blackwater raiders","bloodsail buccaneers","booty bay","cape of stranglethorn","gurubashi arena","south seas","stranglethorn vale"},rel={"zone:stranglethorn","subzone:booty-bay","npc:baron-revilgaz","npc:fleet-master-seahorn","subzone:gurubashi-arena","subzone:ratchet","subzone:ruins-of-aboraz","subzone:ruins-of-jubuwal"},src={"Cape of Stranglethorn"}}
E["subzone:crystal-shore"] = {t="subzone",n="Crystal Shore",z="stranglethorn",s="Crystal Shore faces the South Seas along Stranglethorn's southeastern coast. Its beach lies south of the Ruins of Aboraz and across the water from Jaguero Isle.",h="Crystal Shore faces the South Seas along Stranglethorn's southeastern coast.",sec={{t="A Secluded Coastal Strip",b="At Stranglethorn Vale's southeastern edge, jungle meets the South Seas along Crystal Shore. Steep ridges divide the beach from the inland wilds of Mistvale Valley, though a couple of rugged passes cross them. The crumbling troll structures of the Ruins of Aboraz stand to the north, while the Wild Shore follows the cape's southern curves. Far from Booty Bay's docks, this coast remains quiet and windswept.",sp=0}},faq={{q="Where is the Crystal Shore located?",a="Crystal Shore runs along Stranglethorn Vale's far southeastern coast, facing the South Seas. It lies south of the Ruins of Aboraz and northeast of the Wild Shore.",al={"crystal shore location","where is crystal shore","crystal shore map"}},{q="How do you access the Crystal Shore from inland?",a="A steep ridge separates Crystal Shore from the mainland jungle. A couple of narrow natural passes cross the cliffs, including a trail into Mistvale Valley.",al={"how to get to crystal shore","path to crystal shore","reach crystal shore"}},{q="What landmarks are nearby?",a="The ancient Ruins of Aboraz lie just north of Crystal Shore, and Jaguero Isle sits across the channel to the southwest. The Wild Shore continues down the coast to the south.",al={"landmarks near crystal shore","what is near crystal shore"}},{q="Is the Crystal Shore settled by any faction?",a="No faction maintains a town or settlement along Crystal Shore. Native wildlife, the ancient troll ruins to the north and the South Seas shape this untamed beach.",al={"who lives at crystal shore","crystal shore settlement","crystal shore towns"}}},kw={"crystal shore","jaguero isle","mistvale valley","ruins of aboraz","south seas","stranglethorn vale","wild shore"},rel={"zone:stranglethorn","subzone:ruins-of-aboraz","subzone:wild-shore","subzone:jaguero-isle","subzone:south-seas"},src={"Crystal Shore"}}
E["subzone:crystalvein-mine"] = {t="subzone",n="Crystalvein Mine",z="stranglethorn",s="In central Stranglethorn Vale, prospectors risk the basilisks of Crystalvein Mine for its Singing Crystals. The cavern lies near the ancient ruins of Zul'Mamwe, and the creatures inside have overrun the site and turned miners to stone.",h="In central Stranglethorn Vale, prospectors risk the basilisks of Crystalvein Mine for its Singing Crystals.",sec={{t="A Lucrative Trap",b="Near Zul'Mamwe, Crystalvein Mine cuts into the jungle hills. Its Singing Crystals fetch a high price in southern trade ports, so the Venture Company came to work the valuable veins.\n\nThe mine's native basilisks have made that work perilous. They eat the strange crystals, which harden their scales and make them unnaturally lethal. Petrified trolls and humans outside the cave mouth mark the failure of the Venture Company's expeditions.",sp=0}},faq={{q="What makes Crystalvein Mine valuable?",a="Crystalvein Mine holds rare Singing Crystals, a valuable mineral found only in Stranglethorn Vale. Goblins such as Crank Fizzlebub prize their sound and worth, drawing prospectors into the dangerous caverns.",al={"why is crystalvein mine important","what is in crystalvein mine","singing crystals"}},{q="Why are there stone statues outside the mine?",a="The statues are petrified troll locals and Venture Company laborers. The basilisks feed on the resonant crystals, hardening their hides and turning intruders to stone.",al={"petrified people crystalvein","crystallized trolls crystalvein","stone bodies stranglethorn"}},{q="Who controls Crystalvein Mine right now?",a="The Venture Company claimed the right to exploit Crystalvein Mine, but the basilisks keep it from them. The goblins have been unable to establish active mining operations in the cavern's depths.",al={"who owns crystalvein","crystalvein faction","venture co crystalvein"}}},ang={["profession:Mining"]="If you are a miner drawn by Singing Crystals, tread carefully. The native basilisks make prospecting here one of Stranglethorn's most dangerous endeavors."},kw={"basilisk","crank fizzlebub","crystalvein mine","singing crystals","stranglethorn vale","venture co","zul'mamwe"},rel={"zone:stranglethorn","quest:764","topic:troll"},src={"Crystalvein Mine"}}
E["subzone:grom-gol-base-camp"] = {t="subzone",n="Grom'gol Base Camp",z="stranglethorn",s="Grom'gol Base Camp holds the Horde's western coast position in Stranglethorn Vale. Commander Aggro'gosh leads the fortified outpost in northern Stranglethorn, with zeppelins linking the camp to Orgrimmar and the Undercity. Jungle trolls and hostile Alliance forces threaten the camp.",h="Grom'gol Base Camp holds the Horde's western coast position in Stranglethorn Vale.",sec={{t="A Bastion in the Jungle",b="In northwestern Stranglethorn Vale, Commander Aggro'gosh holds Grom'gol Base Camp. Palisades and armed grunts guard against Bloodscalp headhunters, lurking naga, and prowling beasts. The camp keeps supply routes north to Stonard in the Swamp of Sorrows open. Its sentries watch Alliance traffic coming down from Duskwood or up from Booty Bay.",sp=0},{t="Airbridge of the Horde",b="Wooden zeppelin towers make Grom'gol a key supply hub in the Eastern Kingdoms. Goblin skycraft fly regular routes from the camp to Orgrimmar and the Undercity. This airbridge brings Horde reinforcements and supplies straight into Stranglethorn, away from Alliance-held highways and the deep sea.",sp=0}},faq={{q="What is the purpose of Grom'gol Base Camp?",a="Grom'gol Base Camp is the Horde's fortified staging point in Stranglethorn Vale. Commander Aggro'gosh leads it, and its supply route to Stonard in the Swamp of Sorrows helps protect Horde interests from jungle trolls and Alliance incursions.",al={"why is gromgol here","gromgol purpose","what is gromgol"}},{q="How do you travel to and from Grom'gol?",a="Zeppelins from Grom'gol fly directly to Orgrimmar in Kalimdor and the Undercity in Tirisfal Glades. A wind rider roost connects the camp to Kargath, Stonard, and Booty Bay.",al={"gromgol zeppelin","gromgol flight paths","how to get to gromgol"}},{q="Who leads Grom'gol Base Camp?",a="Commander Aggro'gosh, an orc, leads Grom'gol Base Camp. He oversees its defense against native troll tribes, wild raptors, and Alliance scouts.",al={"gromgol leader","who runs gromgol","commander of gromgol"}},{q="What threats does the camp face?",a="Grom'gol faces threats on every side. Bloodscalp jungle trolls hunt along its borders, raptors stalk the fields to the north, and Alliance soldiers travel down from Duskwood or up from Booty Bay.",al={"gromgol enemies","who attacks gromgol"}}},ang={["faction:Horde"]="As a member of the Horde, you can use Grom'gol as a safe haven and staging ground while crossing Stranglethorn Vale's jungles and contested roads.",["faction:Alliance"]="As an Alliance traveler, you face a heavily defended Horde bastion at Grom'gol, with zeppelin routes reaching deep into the southern Eastern Kingdoms."},kw={"aggro'gosh","grom'gol","gromgol","orgrimmar","stonard","stranglethorn","undercity","zeppelin"},rel={"zone:stranglethorn","subzone:stonard","zone:undercity","zone:orgrimmar","subzone:booty-bay","zone:duskwood","subzone:kargath","topic:horde"},src={"Grom'gol Base Camp"}}
E["subzone:gurubashi-arena"] = {t="subzone",n="Gurubashi Arena",z="stranglethorn",s="In southern Stranglethorn Vale, pirates and wandering brawlers gather at Gurubashi Arena. Fighters clash over locked chests of treasure in its ancient stone ring.",h="In southern Stranglethorn Vale, pirates and wandering brawlers gather at Gurubashi Arena.",sec={{t="A Legacy of Blood",b="Before humans or orcs came to Stranglethorn Vale, the Gurubashi troll empire raised the Gurubashi Arena, also called the Great Arena. It honored their martial strength. In ancient days, champions fought to the death on its sands, until troll blood slicked the earth.",sp=0},{t="The Booty Run",b="The Gurubashi Empire has fractured into warring tribes, yet bloodshed still comes to the arena floor. Now lawless buccaneers and ruffians gather for another spectacle. Short John Mithril, a pirate, oversees the grounds.\n\nEvery few hours, a chest of plundered booty is hauled to the ring's center. Anyone who steps onto the floor becomes fair game. Faction allegiances fall away, and every combatant must fight all comers to reach the prize.",sp=0}},faq={{q="Who built the Gurubashi Arena?",a="The Gurubashi Empire built the arena centuries ago, while it ruled the southern regions of the Eastern Kingdoms. The enormous stadium hosted lethal combat trials and ancient troll rituals honoring the loa.",al={"who made gurubashi arena","arena origin","troll arena lore"}},{q="Why do people fight here now?",a="Local pirates use the arena for illicit entertainment. Every few hours, a pirate captain brings a treasure chest to the center of the sands, and anyone who dares enter the ring can fight to claim it.",al={"why fight in gurubashi","gurubashi chest","booty run lore"}},{q="Who is Short John Mithril?",a="Short John Mithril is the pirate who oversees the arena and its regular chest deliveries. He rewards combatants who survive the brawls and recover his arena treasures.",al={"short john mithril","arena overseer"}},{q="Why can members of my own faction attack me here?",a="Once you cross onto the arena sands, faction treaties and military alliances are suspended. Only those fighting alongside you in your immediate battle party are spared your blade.",al={"why is gurubashi free for all","friendly fire in gurubashi","arena pvp rules"}}},ang={["race:Troll"]="As a troll, you walk sacred ground, a monument to the old Gurubashi Empire. Champions once shed blood on these sands.",["class:Warrior"]="As a warrior, you face a test of martial skill on these sands. Grand war politics fall away, and personal grit and survival decide the fight."},kw={"arena","booty run","chest","gurubashi","short john mithril","stranglethorn","the great arena"},rel={"zone:stranglethorn","topic:troll","topic:pirate","subzone:booty-bay"},src={"Gurubashi Arena"}}
E["subzone:jaguero-isle"] = {t="subzone",n="Jaguero Isle",z="stranglethorn",s="On Jaguero Isle, King Mukla rules the wild beasts. Fierce panthers and gorillas haunt its jungle off Stranglethorn Vale’s eastern coast.",h="On Jaguero Isle, King Mukla rules the wild beasts.",sec={{t="A Primal Domain",b="Jaguero Isle lies off Stranglethorn Vale’s southeastern coast, far from the mainland pirate camps and troll ruins. Untamed panthers and aggressive gorillas roam the island. King Mukla, a gigantic ape, rules the rocky interior and guards it fiercely.\n\nFew sailors willingly approach the reefs. Bottles found along the mainland beaches sometimes carry desperate pleas for rescue from people stranded ashore.",sp=0},{t="The Captive Princess",b="Princess Poobah, a shipwrecked tauren, is held captive by King Mukla on Jaguero Isle. Stranded among the island’s predators, she sends distress notes in bottles across the Wild Shore’s tides. She hopes someone will brave Mukla’s wrath and help her escape.",sp=1}},faq={{q="Where is Jaguero Isle located?",a="Jaguero Isle lies in the Great Sea, off Stranglethorn Vale’s southeastern coast, just east of the Wild Shore.",al={"jaguero isle location","where is jaguero","find jaguero isle"}},{q="Who is King Mukla?",a="King Mukla is a gigantic, powerful gorilla who rules Jaguero Isle’s interior. He is territorial and aggressive.",al={"mukla","king mukla gorilla","ape boss stranglethorn"}},{q="Who is Princess Poobah?",a="Princess Poobah is a tauren stranded on Jaguero Isle, far from her home. She sends messages in bottles into the sea, hoping for rescue.",al={"tauren captive","who is poobah","princess poobah"}},{q="How do you start the quest to visit the island?",a="You can find half-buried bottles washed ashore along the Wild Shore’s mainland beaches. Inside, a folded note asks for aid.",al={"message in a bottle quest","jaguero island quest","how to get to jaguero"}}},ang={["race:Tauren"]="As a tauren, you may feel a personal duty to free Princess Poobah, a fellow tauren trapped far from Kalimdor among hostile beasts.",["class:Hunter"]="As a hunter, you can test your tracking skills against Jaguero Isle’s exotic predators, from stalking panthers to the mighty King Mukla."},kw={"gorilla","jaguero","jaguero isle","king mukla","panther","princess poobah","stranglethorn","wild shore"},rel={"zone:stranglethorn","subzone:wild-shore","topic:tauren"},src={"Jaguero Isle"}}
E["subzone:janeiro-s-point"] = {t="subzone",n="Janeiro's Point",z="stranglethorn",s="Ships pass Janeiro's Point on their way into Booty Bay. Mok'rash the Cleaver claims the island's shores and waters.",h="Ships pass Janeiro's Point on their way into Booty Bay.",sec={{t="Beacon of the Bay",b="Ships bound for Booty Bay pass Janeiro's Point at the harbor's edge in southern Stranglethorn Vale. A colossal stone goblin spreads its arms atop the rocky crag, welcoming vessels to the bay. Sailors can see the statue for miles, yet Mok'rash the Cleaver claims the island. The sea giant makes landing on its shores perilous.",sp=0}},faq={{q="What is Janeiro's Point?",a="Janeiro's Point is a small, rocky island just outside Booty Bay's harbor in Stranglethorn Vale. Ships bound for the goblin port use it as a landmark.",al={"janeiro point","what is this island","booty bay statue island"}},{q="Who is the giant statue on the island?",a="The colossal statue shows an unknown goblin with arms outstretched. It welcomes trade ships and sailors to Booty Bay.",al={"statue identity","who is the goblin statue","who is depicted"}},{q="What dangerous creature lives on Janeiro's Point?",a="Mok'rash the Cleaver, a sea giant, claims Janeiro's Point and its surrounding waters. He endangers mariners and swimmers who approach the statue.",al={"sea giant island","who lives on janeiro point","mokrash"}}},kw={"booty bay","goblin statue","janeiro's point","mok'rash","sea giant","stranglethorn"},rel={"subzone:booty-bay","zone:stranglethorn","topic:goblin"},src={"Janeiro's Point"}}
E["subzone:kurzen-s-compound"] = {t="subzone",n="Kurzen's Compound",z="stranglethorn",s="Stormwind's expedition has turned against the kingdom at Kurzen's Compound in northern Stranglethorn Vale. Colonel Kurzen's madness has made it a camp of rogue soldiers and wild beasts.",h="Stormwind's expedition has turned against the kingdom at Kurzen's Compound in northern Stranglethorn Vale.",sec={{t="Heart of Darkness",b="Colonel Kurzen's expedition came to Stranglethorn on Stormwind's orders. Then the colonel's madness changed its course, and the garrison broke from the kingdom to follow him. Now the compound is a mercenary stronghold. Its lumber mill and stables hold captured Stranglethorn panthers and tigers trained for war. In the caves called the Stockpile, Kurzen's men keep their plundered supplies.",sp=0},{t="A Divided Regiment",b="Some of Kurzen's original soldiers refused to follow him into savagery. When madness took hold of the colonel, they mutinied and fled west. There they founded the Rebel Camp. A bitter, bloody feud followed beneath the jungle canopy. Kurzen and his loyal men hunt the deserters, and treat every outsider who enters their domain as an enemy.",sp=0}},faq={{q="Who lives in Kurzen's Compound?",a="Rogue remnants of Kurzen's Expedition occupy the compound. The human soldiers, jungle fighters, and mercenaries follow Colonel Kurzen and his lieutenants instead of Stormwind's laws.",al={"who is here","kurzen soldiers","who lives in the compound"}},{q="Why are the humans here hostile?",a="Colonel Kurzen went mad in the jungle and abandoned his allegiance to the Alliance. He and his men see every trespasser as a mortal threat, from Alliance forces to the deserters at the nearby Rebel Camp.",al={"why do they attack","kurzen hostile","are kurzen friendly"}},{q="What is the cave in the back of the camp?",a="The caves behind the compound are called the Stockpile. Kurzen's men use them as a fortified depot for weapons, provisions, and contraband, keeping supplies from jungle scavengers and rebel raids.",al={"cave in kurzen compound","the stockpile","kurzen cave"}},{q="Why are there caged tigers and panthers here?",a="Kurzen's fighters capture native Stranglethorn tigers and panthers and keep them near the stables. They train the predators as Kurzen War Panthers and War Tigers to defend the compound and patrol the surrounding jungle.",al={"kurzen animals","caged panthers","war tigers"}}},ang={["faction:Alliance"]="Stormwind sent Kurzen's expedition under the Alliance banner. The outpost's fall into madness is a shameful scandal, and nearby rebels seek to set things right.",["class:Hunter"]="The compound shows how its fighters try to tame wild Stranglethorn panthers and tigers as beasts of war."},kw={"colonel","compound","kurzen","rebel","stockpile","stranglethorn"},rel={"npc:colonel-kurzen","subzone:rebel-camp","zone:stranglethorn"},src={"Kurzen's Compound"}}
E["subzone:lake-nazferiti"] = {t="subzone",n="Lake Nazferiti",z="stranglethorn",s="In northern Stranglethorn, river waters gather at Lake Nazferiti. Crocolisks and snapping frenzies hunt beneath its surface, while the Venture Company works along the shores.",h="In northern Stranglethorn, river waters gather at Lake Nazferiti.",sec={{t="Heart of the Jungle Waterway",b="The Nazferiti River runs across the southern Eastern Kingdoms and widens into Lake Nazferiti in Stranglethorn. It begins in the northern heights, where it plunges from the Redridge Mountains in waterfalls. Its headwaters may reach as far inland as Deadwind Pass. By the time the river spreads into the lake, its waters are murky. Snapping river frenzies and crocolisks hunt there, making a swim deadly.",sp=0},{t="Venture Company Encroachment",b="The Venture Company has brought heavy operations to Lake Nazferiti's banks. Goblins cut jungle timber and take other resources with saws, drills, and crews that clear the land. Their base pollutes the water. The work brings them into constant clashes with local wildlife and hunters traveling through the vale.",sp=0}},faq={{q="Where does Lake Nazferiti get its water?",a="Lake Nazferiti is fed by the Nazferiti River, which begins high in the northern mountains. A waterfall from the Redridge Mountains marks its confirmed source, though the headwaters may reach as far inland as Deadwind Pass.",al={"nazferiti river source","where does lake nazferiti come from","water source lake nazferiti"}},{q="Who controls the shores of Lake Nazferiti?",a="The Venture Company occupies a major base along Lake Nazferiti's shores. Goblins strip the jungle for wood and minerals, with armed overseers and machinery along the water's edge.",al={"who is at lake nazferiti","goblins at lake nazferiti","venture co lake"}},{q="Is it safe to swim in Lake Nazferiti?",a="Swimming in Lake Nazferiti is dangerous. Aggressive river frenzies and lurking crocolisks attack those who venture beyond the shallows.",al={"lake nazferiti monsters","what lives in lake nazferiti","creatures in lake nazferiti"}},{q="Where is Lake Nazferiti located?",a="Lake Nazferiti lies in northern Stranglethorn Vale, just south of the Duskwood border and west of the Zul'Gurub ruins, along the main river highway.",al={"lake nazferiti location","where is lake nazferiti","find lake nazferiti"}}},ang={["class:Hunter"]="As a hunter, you can find game along Lake Nazferiti's shores and in its depths. Aggressive river beasts and crocolisks prowl the reeds.",["race:NightElf"]="As a night elf, you can see the damage the Venture Company has done along Lake Nazferiti. Goblin greed scars the land."},kw={"crocolisks","frenzies","lake nazferiti","nazferiti","river","stranglethorn vale","venture company"},rel={"topic:venture-company","zone:stranglethorn","topic:goblin","zone:redridge","zone:deadwind"},src={"Lake Nazferiti"}}
E["subzone:mizjah-ruins"] = {t="subzone",n="Mizjah Ruins",z="stranglethorn",s="In northern Stranglethorn Vale, Mosh'Ogg ogres have taken shelter in the Mizjah Ruins, southeast of Grom'gol Base Camp. They ambush supply caravans bound for the Swamp of Sorrows.",h="In northern Stranglethorn Vale, Mosh'Ogg ogres have taken shelter in the Mizjah Ruins, southeast of Grom'gol...",sec={{t="A Den of Ogres",b="The Gurubashi Empire raised the Mizjah Ruins long before modern empires rose. Now Mosh'Ogg ogres dwell among the cracked stones, including brute warriors and crude witch doctors. They raid supply convoys bound for the Horde settlement of Stonard. Their attacks trouble Grom'gol's commanders.",sp=0}},faq={{q="Who built the Mizjah Ruins?",a="Jungle trolls of the Gurubashi Empire built the Mizjah Ruins long before modern empires rose. Centuries of warfare and ruin left them empty.",al={"who made mizjah","mizjah origins","troll ruins mizjah"}},{q="Who lives in the Mizjah Ruins now?",a="Mosh'Ogg ogres now occupy the ruins, including Mosh'Ogg Brutes and Mosh'Ogg Witch Doctors. They have fortified the stone structures as a local encampment.",al={"who lives here","mizjah mobs","mosh'ogg camp"}},{q="Why is the Horde interested in clearing the ruins?",a="Mosh'Ogg ogres ambush Horde convoys traveling between Grom'gol Base Camp and Stonard in the Swamp of Sorrows.",al={"why kill mosh'ogg","grom'gol defense","stonard caravan quest"}}},ang={["faction:Horde"]="Mosh'Ogg ogres at Mizjah threaten Horde supply lines. Grom'gol Base Camp sends warriors to guard the route to Stonard."},kw={"brute","grom'gol","mizjah","mizjah ruins","mosh'ogg","stonard","stranglethorn","witch doctor"},rel={"subzone:grom-gol-base-camp","zone:stranglethorn","subzone:stonard"},src={"Mizjah Ruins"}}
E["subzone:mosh-ogg-ogre-mound"] = {t="subzone",n="Mosh'Ogg Ogre Mound",z="stranglethorn",s="In northern Stranglethorn Vale, Mosh'Ogg Ogre Mound lies south of Zul'Gurub's ruins. The Mosh'Ogg tribe holds its fortified caverns under Mai'Zoth, their ruthless ogre mage chieftain.",h="In northern Stranglethorn Vale, Mosh'Ogg Ogre Mound lies south of Zul'Gurub's ruins.",sec={{t="A Den of Ogres",b="Mosh'Ogg ogres fill the jungle caverns south of Zul'Gurub. Maulers, shamans, and warmongers guard the twisting passages. The tribe seized the ridges as a refuge from hostile jungle trolls and prowling beasts.",sp=0},{t="Mai'Zoth and the Mind's Eye",b="Mai'Zoth commands the Mosh'Ogg clan from deep within the mound. The formidable chieftain has two heads and practices ogre magic. He holds the Mind's Eye, a potent and dangerous arcane relic. Its power strengthens his hold over his followers through mind and sorcery. His magic and brute force make the mound's deepest reaches perilous for travelers in northern Stranglethorn.",sp=0}},faq={{q="Who lives in the Mosh'Ogg Ogre Mound?",a="The Mosh'Ogg ogre tribe lives in the mound, including warriors, maulers, shamans, and warmongers. Their two-headed ogre mage chieftain, Mai'Zoth, rules from deep within the cavern.",al={"who is in the mound","mosh'ogg inhabitants","ogre mound monsters"}},{q="What is the Mind's Eye?",a="The Mind's Eye is a potent magical artifact held by Mai'Zoth inside the mound. Its arcane power fuels his sorcery and his command over the local ogres.",al={"what does mai'zoth have","mind's eye relic","minds eye"}},{q="Where is the mound located?",a="The mound lies in northern Stranglethorn Vale, in the hills just south of Zul'Gurub's entrance.",al={"where is mosh'ogg ogre mound","ogre mound location","how to find ogre mound"}}},ang={["class:Mage"]="As a mage, you can see Mai'Zoth wielding the Mind's Eye deep within the mound. Its raw arcane energy is unusual for brute ogres."},kw={"mai'zoth","mind's eye","mosh'ogg","mound","ogre","stranglethorn","zul'gurub"},rel={"zone:stranglethorn","subzone:zul-gurub"},src={"Mosh'Ogg Ogre Mound"}}
E["subzone:nek-mani-wellspring"] = {t="subzone",n="Nek'mani Wellspring",z="stranglethorn",s="Naga guard Nek'mani Wellspring high above the Southern Savage Coast. Its fountain holds remarkably pure holy water, the only pristine fresh water south of Duskwood.",h="Naga guard Nek'mani Wellspring high above the Southern Savage Coast.",sec={{t="A Sacred Basin",b="Nek'mani Wellspring rises among the coastal heights of western Stranglethorn Vale. Scholars and pilgrims call its waters holy. Each culture claims the divine spring was blessed for its own people, and faiths still dispute whose claim is true. Now a vicious band of naga holds the basin and guards its water against all who approach.",sp=0}},faq={{q="What makes the Nek'mani Wellspring special?",a="Nek'mani Wellspring yields remarkably pure holy water, the only pristine fresh water south of Duskwood. Religious scholars consider it divine, though faiths dispute which people it was meant for.",al={"why is nek'mani important","what is holy water of clarity","holy spring stv"}},{q="Where exactly is the wellspring located?",a="Nek'mani Wellspring sits high on the cliffs overlooking the Southern Savage Coast, along Stranglethorn Vale's western shore.",al={"where is nekmani wellspring","how to find nek'mani","nekmani location"}},{q="Who controls the Nek'mani Wellspring right now?",a="A hostile naga expedition has advanced inland from the ocean and claimed the sacred basin. The naga attack anyone who approaches the water.",al={"who is at nek'mani","nekmani monsters","naga at nekmani"}},{q="Why are adventurers sent to this spring?",a="Travelers and researchers seek the spring's holy water for enchantments, purifications, and alchemical mixtures that require pristine water.",al={"nekmani quests","holy water quest stv","clean water stv"}}},ang={["class:Priest"]="As a priest, you may find the claims of divine origin around Nek'mani Wellspring compelling. Scholars still dispute which faith its waters belong to."},kw={"holy spring","holy water","naga","nek'mani","savage coast","stranglethorn","wellspring"},rel={"subzone:southern-savage-coast","zone:stranglethorn","topic:naga","subzone:savage-coast","zone:duskwood","topic:troll"},src={"Nek'mani Wellspring"}}
E["subzone:nesingwary-s-expedition"] = {t="subzone",n="Nesingwary's Expedition",z="stranglethorn",s="Hunters gather at Nesingwary's Expedition in northern Stranglethorn Vale, north of Lake Nazferiti. Hemet Nesingwary has made this camp a base for hunters who test themselves against the jungle's fiercest predators.",h="Hunters gather at Nesingwary's Expedition in northern Stranglethorn Vale, north of Lake Nazferiti.",sec={{t="A Hunters' Outpost in the Jungle",b="Beside the river north of Lake Nazferiti, Nesingwary's Expedition is a hunters' camp founded by Hemet Nesingwary. Sir S. J. Erlgadin, Ajeck Rouack, and Barnil Stonepot are among its seasoned hunters. Hired marksmen guard the camp, while neutral vendors supply it. Skilled riflemen and bowmen of any allegiance are welcome to hunt the jungle's deadliest predators.",sp=0},{t="Pages and Predators",b="At Nesingwary's Expedition, hunters trade competition and tall tales. They learn to track panthers, raptors, and tigers before turning to the jungle's greatest beasts. There is work for scholars, too. Pages from Nesingwary's long manuscript have scattered across the wilds, and the scholars at camp seek every missing chapter.",sp=0}},faq={{q="Who runs Nesingwary's Expedition?",a="Hemet Nesingwary, the famed dwarven big game hunter, founded the camp and leads it with a circle of veteran marksmen.",al={"who leads this camp","nesingwary camp leader","who is in charge here"}},{q="Why is the expedition here in Stranglethorn Vale?",a="The expedition came to Stranglethorn to hunt its dangerous wildlife, from prowling panthers and aggressive raptors to ferocious tigers and legendary trophy beasts.",al={"what are they doing here","why nesingwary stranglethorn","purpose of camp"}},{q="Is Nesingwary's Expedition friendly to both Alliance and Horde?",a="Yes. Nesingwary's hired guns keep the camp neutral and maintain peace while visitors respect its grounds. Alliance and Horde hunters are welcome to test their tracking skills.",al={"is nesingwary neutral","can horde visit nesingwary","can alliance visit nesingwary"}},{q="What is the story behind the missing manuscript pages?",a="Hemet Nesingwary wrote an extensive hunting memoir titled 'The Green Hills of Stranglethorn.' Its loose pages were lost in the wilderness, and camp archivist Barnil Stonepot enlisted travelers to recover them.",al={"green hills of stranglethorn story","why are pages scattered","barnil stonepot book"}}},ang={["class:Hunter"]="As a hunter, you can hone your tracking skills here against Stranglethorn Vale's deadliest predators.",["race:Dwarf"]="As a dwarf, you may recognize Hemet Nesingwary and fellow Khaz Modan mountaineers in this humid tropical wild. Grit and a love of the hunt brought them here."},kw={"camp","expedition","green hills","hemet","hunters","nazferiti","nesingwary","stranglethorn"},rel={"quest:5762","zone:stranglethorn","subzone:lake-nazferiti"},src={"Nesingwary's Expedition"}}
E["subzone:old-port-authority"] = {t="subzone",n="Old Port Authority",z="stranglethorn",s="In Booty Bay, the Old Port Authority draws travelers to its market stalls. Beneath its roof, they find exotic pets, firearms, hearty rations, and finely crafted weapons.",h="In Booty Bay, the Old Port Authority draws travelers to its market stalls.",sec={{t="Commerce on the Boardwalk",b="Beneath Booty Bay’s boardwalks, the Old Port Authority draws brisk trade in the pirate haven. Its stalls offer supplies, firearms, bows, food, and weapons to scoundrels and privateers. Nautical imports include colorful birds and oddities from the docks, all offered to anyone with coin.",sp=0}},faq={{q="What is the Old Port Authority?",a="In Booty Bay, the Old Port Authority is a prominent warehouse divided into several market stalls. Adventurers and buccaneers come for food, ammunition, weapons, and trade goods.",al={"what is this building","booty bay warehouse","port authority booty bay"}},{q="What shops are found inside?",a="Five stalls fill the warehouse: Nautical Needs, Good Food, Swift Flights, Boomstick Imports East, and Cuts-N-Bruises Incorporated. They sell rations, weapons, pet birds, and basic provisions.",al={"vendors inside","shops in port authority","what can i buy here"}},{q="Can you buy pets here?",a="Yes. At Nautical Needs, you can acquire exotic birds such as cockatiels and Senegal parrots. Local sailors and privateers favor them as companions.",al={"pet vendor booty bay","parrots booty bay","nautical needs vendor"}}},ang={["class:Hunter"]="As a hunter, you can restock shot and powder at Boomstick Imports East before heading into Stranglethorn’s deep jungles.",["profession:Cooking"]="At Good Food, you can find regional cooking ingredients and provisions brought by trading vessels passing through."},kw={"blackwater cartel","boomstick imports","booty bay","cuts-n-bruises","nautical needs","old port authority","stranglethorn vale"},rel={"subzone:booty-bay","zone:stranglethorn","topic:goblin"},src={"Old Port Authority"}}
E["subzone:rebel-camp"] = {t="subzone",n="Rebel Camp",z="stranglethorn",s="At Rebel Camp, Alliance soldiers hold a fortified refuge in northern Stranglethorn Vale. Lieutenant Doren leads those who broke from Colonel Kurzen and now fight to survive and end his tyranny.",h="At Rebel Camp, Alliance soldiers hold a fortified refuge in northern Stranglethorn Vale.",sec={{t="A Stand Against Madness",b="Colonel Kurzen's expedition pushed deep into Stranglethorn Vale on Stormwind's behalf. But the jungle turned against it. Dark magic and the curse of the ogre mage Mai'Zoth drove Kurzen and his closest loyalists mad. They went rogue and terrorized the wilds.\n\nLieutenant Doren led the handful who kept their minds. They refused to join the atrocities and broke from Kurzen's Compound before building a hidden camp in the north. From there, they wage a desperate guerrilla campaign against their former comrades.",sp=0},{t="Holding the Line",b="Near the Duskwood border, the Rebel Camp perches precariously under constant threat. Stormwind sends no regular relief, so Doren relies on covert supplies and defensive arms to hold the perimeter against Kurzen's raiding parties. Goblin explosives brokered through Booty Bay help fortify the camp.\n\nFor Alliance travelers heading south into the savage jungle, the camp is a vital first foothold of sanity.",sp=0}},faq={{q="Who are the rebels at the Rebel Camp?",a="The rebels are former Stormwind soldiers from Colonel Kurzen's expedition into Stranglethorn Vale. When Kurzen and his inner circle fell to madness and tyranny, Lieutenant Doren led them in mutiny so they could escape and oppose their former commander.",al={"who lives at rebel camp","who are these soldiers","rebel camp alliance"}},{q="Why is it called the Rebel Camp if they are loyal to Stormwind?",a="They rebelled against Colonel Kurzen's command, not Stormwind. Since Kurzen commanded them, defying his orders counted as mutiny, though they remain loyal to the Alliance and Stormwind.",al={"why rebel camp","are they traitors","who did they rebel against"}},{q="How does the camp survive without official Stormwind support?",a="Lieutenant Doren keeps the camp supplied through covert connections beyond official supply lines. Krazek in Booty Bay provides land mines and vital gear to strengthen its defenses.",al={"rebel camp supplies","where do they get food","rebel camp logistics"}},{q="Where is Colonel Kurzen located?",a="Kurzen and his deranged followers occupy Kurzen's Compound, a fortified base directly southeast of the Rebel Camp.",al={"kurzen location","where is kurzen","kurzens compound"}}},ang={["faction:Alliance"]="The Rebel Camp is your main staging ground and safest haven as you cross south from Duskwood over the bridge into Stranglethorn Vale.",["race:Human"]="As a human, seeing fellow Stormwind regulars unravel in the jungle is sobering. Lieutenant Doren needs fellow subjects of the kingdom to help end Kurzen's disgraced outfit."},kw={"colonel kurzen","doren","kurzen","kurzen's compound","mai'zoth","rebel camp","stranglethorn","stranglethorn vale"},rel={"subzone:kurzen-s-compound","npc:colonel-kurzen","npc:doren","zone:stranglethorn","zone:duskwood","subzone:booty-bay","topic:stormwind-kingdom","topic:alliance"},src={"Rebel Camp"}}
E["subzone:ruins-of-aboraz"] = {t="subzone",n="Ruins of Aboraz",z="stranglethorn",s="Zanzil the Outcast and his mind-addled thralls now hold the old Gurubashi terraces on Stranglethorn Vale's southeastern cliffs.",h="Zanzil the Outcast and his mind-addled thralls now hold the old Gurubashi terraces on Stranglethorn Vale's...",sec={{t="A Witch Doctor's Domain",b="At Aboraz, weathered stone crowns the bluffs southeast of the Ruins of Jubuwal and south of the Crystalvein Mine. Zanzil the Outcast, an exiled witch doctor, has turned the courtyards into a place for alchemy. Banished by local tribes and mainlanders alike, he fled here to brew potions that alter the mind and toxic elixirs. His servants are shambling undead ghouls, corrupted troll thralls, and coastal naga under his control.",sp=0},{t="Pawns and Captives",b="Yenniku wanders the terraces, his mind still held by Zanzil's sorcery. Chucky 'Ten Thumbs' wanders there too. A pirate debtor fleeing the collection efforts of Booty Bay's 'Sea Wolf' MacKinley, Chucky has drunk Zanzil's draughts and now guards the compound, unaware of his plight.",sp=1}},faq={{q="Who rules over the Ruins of Aboraz?",a="Zanzil the Outcast rules the ruins. The exiled witch doctor is known across Stranglethorn Vale for dark alchemy and powerful brews that control minds.",al={"who leads aboraz","aboraz boss","who is in ruins of aboraz"}},{q="Why are there naga and ghouls together here?",a="Zanzil has bound troll outcasts, raised jungle ghouls, and ensnared coastal naga to guard his terraces. His mixtures let him dominate minds and animate corpses.",al={"why are naga here","aboraz ghouls","aboraz mobs"}},{q="Where are the Ruins of Aboraz located?",a="The Ruins of Aboraz stand on high bluffs in southeastern Stranglethorn Vale, south of the Crystalvein Mine and just southeast of the Ruins of Jubuwal. They overlook the eastern sea.",al={"aboraz location","where is aboraz","how to get to ruins of aboraz"}}},ang={["race:Troll"]="For the Darkspear, Aboraz is an affront. An outcast uses perverted voodoo to enslave fellow trolls and hold young Yenniku in the ancestral lands of the Gurubashi.",["faction:Alliance"]="Alliance privateers and mercenaries often cross paths with Zanzil's affairs while pursuing debts or bounties tied to Booty Bay's goblins and pirates."},kw={"aboraz","chucky","jubuwal","stranglethorn","witch doctor","yenniku","zanzil"},rel={"subzone:ruins-of-jubuwal","subzone:crystalvein-mine","zone:stranglethorn","topic:troll","topic:naga"},src={"Ruins of Aboraz"}}
E["subzone:ruins-of-jubuwal"] = {t="subzone",n="Ruins of Jubuwal",z="stranglethorn",s="East of the Gurubashi Arena, Zanzil the Outcast and his followers hold the Ruins of Jubuwal. The old Gurubashi settlement lies in ruins.",h="East of the Gurubashi Arena, Zanzil the Outcast and his followers hold the Ruins of Jubuwal.",sec={{t="A Refuge for the Exiled",b="Jubuwal once belonged to the great Gurubashi civilization. Stone carvings and ivy-covered walls remain beside Stranglethorn Vale’s main road. Now Zanzil the Outcast holds the ruins. The eccentric witch doctor is known for potent concoctions and foul voodoo.\n\nHis followers include enthralled ghouls, subjugated naga and renegade trolls. Desperate fugitives shelter beneath the stone arches too. Jon-Jon the Crow and Maury 'Club Foot' Wilkins hide here from 'Sea Wolf' MacKinley, the ruthless debt collector in Booty Bay.",sp=0}},faq={{q="Where are the Ruins of Jubuwal located?",a="The Ruins of Jubuwal lie in central Stranglethorn Vale, just east of the Gurubashi Arena. They stand beside the dirt road between northern and southern Stranglethorn.",al={"ruins of jubuwal location","where is jubuwal","jubuwal map"}},{q="Who controls the Ruins of Jubuwal?",a="Zanzil the Outcast and his followers hold the ruins. They include brainwashed trolls, reanimated ghouls, allied naga and scoundrels seeking shelter from the law.",al={"who lives in jubuwal","jubuwal enemies","who controls jubuwal"}},{q="Why are ghouls and naga working together here?",a="Zanzil the Outcast uses toxic voodoo mixtures and mind-altering potions to subdue and command those around him. He binds risen undead, naga and trolls into an obedient fighting force.",al={"why are there ghouls in jubuwal","zanzil minions"}},{q="Why are outlaws like Jon-Jon and Maury hiding here?",a="Jon-Jon the Crow and Maury 'Club Foot' Wilkins fled to Jubuwal to escape 'Sea Wolf' MacKinley. The notorious debt collector operates out of Booty Bay.",al={"jon-jon the crow","maury club foot wilkins","mackinley debtors"}}},ang={["race:Troll"]="As a Darkspear troll, you can see Jubuwal as a tragic ruin of Gurubashi heritage. Rogues like Zanzil twist the ancestral voodoo.",["class:Rogue"]="As a rogue, you can use Jubuwal's shadows and crumbling walls as cover. There, you can ambush outlaws hiding from Booty Bay's bounty hunters."},kw={"gurubashi","jon-jon","jubuwal","mackinley","maury club foot","stranglethorn","zanzil"},rel={"zone:stranglethorn","subzone:gurubashi-arena","topic:troll","topic:naga"},src={"Ruins of Jubuwal"}}
E["subzone:ruins-of-zul-mamwe"] = {t="subzone",n="Ruins of Zul'Mamwe",z="stranglethorn",s="Skullsplitter warriors hold the Ruins of Zul'Mamwe in central Stranglethorn Vale, south of the Mosh'Ogg Ogre Mound. Cliffs ring the ancient stone platforms on nearly every side, and Ana'thek the Cruel rules the stronghold.",h="Skullsplitter warriors hold the Ruins of Zul'Mamwe in central Stranglethorn Vale, south of the Mosh'Ogg Ogre...",sec={{t="Stronghold of the Skullsplitters",b="In central Stranglethorn Vale, the Skullsplitters hold the Ruins of Zul'Mamwe as one of their chief seats of power. Mountains form a natural amphitheater around the site, open only to the north. From weathered ziggurats and stone terraces, Chief Ana'thek the Cruel directs his warriors and witch doctors. They defend their ground fiercely against intruders and rival jungle troll tribes.",sp=0},{t="Remnants of an Ancient Empire",b="Zul'Mamwe's stones come from the ancient Gurubashi Empire, which once ruled the southern reaches of the continent without rival. The empire broke apart long ago into hostile factions. Among the overgrown masonry and broken monoliths, the Skullsplitters guard these ancestral stones and keep their age-old tribal rituals.",sp=0}},faq={{q="Who controls the Ruins of Zul'Mamwe?",a="The Skullsplitter troll tribe holds the ruins, one of Stranglethorn Vale's two dominant and aggressive jungle troll tribes. Their chieftain, Ana'thek the Cruel, commands them there.",al={"who lives here","zul'mamwe trolls","who owns zul'mamwe"}},{q="Where is Zul'Mamwe located?",a="Zul'Mamwe lies in central Stranglethorn Vale, just south of the Mosh'Ogg Ogre Mound. Mountains ring the encampment on nearly every side, with a valley pass to the north as its main approach.",al={"how to get to zul'mamwe","zul'mamwe location","where is it"}},{q="Why are the Skullsplitters hostile to travelers?",a="The Skullsplitters are fiercely isolationist and hostile to outsiders. They see all other races and rival troll tribes as trespassers on their ancestral lands, and Ana'thek the Cruel leads them against anyone who approaches their jungle sanctuary.",al={"why do trolls attack","skullsplitter hostility"}},{q="What is the history behind these ruins?",a="Zul'Mamwe's stone structures date to the height of the Gurubashi Empire. After the empire collapsed into warring splinter factions, the Skullsplitters claimed the site as an inland base of operations and kept its ancient stone terraces.",al={"ruins history","who built zul'mamwe","zul'mamwe lore"}}},ang={["race:Troll"]="As a Darkspear troll of the Horde, you may see Zul'Mamwe as a reminder of jungle kin who clung to savage, insular ways. They kept bloodthirsty traditions and refused to adapt to the wider world."},kw={"ana'thek","ana'thek the cruel","gurubashi","jungle troll","skullsplitter","stranglethorn","zul'mamwe"},rel={"zone:stranglethorn","subzone:mosh-ogg-ogre-mound","topic:troll"},src={"Ruins of Zul'Mamwe"}}
E["subzone:salty-sailor-tavern"] = {t="subzone",n="Salty Sailor Tavern",z="stranglethorn",s="In Booty Bay, travelers from both factions find shelter at the Salty Sailor Tavern. Goblin Innkeeper Skindle runs the port's inn and watering hole, where scoundrels and mercenaries seek respite from the jungle.",h="In Booty Bay, travelers from both factions find shelter at the Salty Sailor Tavern.",sec={{t="A Safe Haven in the Jungle",b="Among Booty Bay's wooden tiers, the Salty Sailor Tavern offers warm beds and strong drinks. The Blackwater Raiders watch over the place. Innkeeper Skindle tends the bar as buccaneers, traders, and adventurers mingle on neutral ground. Outside hangs a massive Zul'Gurub Protector Stone, a curious trophy in this den of commerce.",sp=0}},faq={{q="Who runs the Salty Sailor Tavern?",a="Innkeeper Skindle, an industrious goblin, runs the tavern and its inn. Sailors, mercenaries, and adventurers passing through Booty Bay come to drink and rest.",al={"innkeeper","who is the innkeeper","skindle"}},{q="What is that large stone hanging outside the tavern?",a="A Zul'Gurub Protector Stone hangs outside the tavern. It is an ominous relic brought back from ancient troll ruins deep in the jungle.",al={"stone outside","zul'gurub stone","protector stone"}},{q="Can both Alliance and Horde stay here?",a="Yes. The Steamwheedle Cartel keeps Booty Bay neutral, so Alliance and Horde travelers may rest at the tavern. They must mind their manners and keep their weapons sheathed.",al={"is it neutral","alliance and horde allowed","can horde use the inn"}}},ang={["class:Rogue"]="As a rogue, you can trade rumors and listen for pirate chatter on the Salty Sailor's crowded, smoky floor. Keep your purse guarded."},kw={"blackwater raiders","booty bay inn","protector stone","salty sailor","skindle"},rel={"subzone:booty-bay","zone:stranglethorn","subzone:zul-gurub"},src={"Salty Sailor Tavern"}}
E["subzone:savage-coast"] = {t="subzone",n="Savage Coast",z="stranglethorn",s="Along Stranglethorn Vale’s western shore, danger follows the Savage Coast from Westfall toward Grom'gol Base Camp. Crocolisks, basilisks, and hostile troll tribes make the beaches perilous.",h="Along Stranglethorn Vale’s western shore, danger follows the Savage Coast from Westfall toward Grom'gol Base...",sec={{t="A Treacherous Strand",b="The Savage Coast follows the western edge of northern Stranglethorn Vale. Its beaches run south from the cliffs by Westfall toward Grom'gol Base Camp. Crocolisks and stonestalkers roam among tide pools and drift logs, while territorial jungle troll camps threaten anyone walking the shore. Beyond the sand, the water deepens toward the submerged dangers of the Vile Reef.",sp=0}},faq={{q="Where is the Savage Coast?",a="The Savage Coast follows the western ocean edge of northern Stranglethorn Vale. It begins near Westfall's border and runs south past the waters near the Vile Reef toward Grom'gol Base Camp.",al={"savage coast location","where is savage coast","savage coast map"}},{q="What creatures live along the Savage Coast?",a="Crocolisks and basilisks prowl the shore. Hostile troll tribes keep camps beyond the waterline and along the nearby jungle bluffs.",al={"savage coast mobs","what is on savage coast","savage coast beasts"}},{q="Is the Savage Coast safe for travelers moving south from Westfall?",a="No. The coast offers a route around the dense canopy, but amphibious predators and troll warriors make the way dangerous for travelers.",al={"can you walk to stranglethorn from westfall","westfall to savage coast path"}},{q="What landmarks are near the Savage Coast?",a="The sunken Vile Reef lies offshore, and Grom'gol Base Camp sits farther south along the coast. To the north, bluffs rise toward Westfall's farmlands and coast.",al={"savage coast points of interest","what is near savage coast"}}},ang={["faction:Horde"]="The northern stretch of the coast lies just above Grom'gol Base Camp. Nearby wildlife and aggressive troll bands near the Great Sea threaten the outpost.",["class:Hunter"]="Along the shoreline, you can track, skin, and tame crocolisks and basilisks."},kw={"basilisk","crocolisk","grom'gol","savage coast","stranglethorn","vile reef","westfall"},rel={"zone:stranglethorn","subzone:grom-gol-base-camp","subzone:vile-reef","zone:westfall","topic:troll"},src={"Savage Coast"}}
E["subzone:southern-savage-coast"] = {t="subzone",n="Southern Savage Coast",z="stranglethorn",s="Along the Southern Savage Coast, jungle opens onto beaches and South Seas waters. Travelers face danger from wildlife, naga, and raiders.",h="Along the Southern Savage Coast, jungle opens onto beaches and South Seas waters.",sec={{t="A Treacherous Shoreline",b="The Southern Savage Coast follows the western edge of southern Stranglethorn. Warm South Seas currents meet the mainland, and the Vile Reef with its submerged ruins divides this shore from the northern Savage Coast. Inlets lie near the Gurubashi Arena and Nek'mani Wellspring; the coast then runs past Booty Bay to Janeiro's Point. The beaches give you more room than the jungle, but reptilian predators prowl the sand, naga hunt in the shallows, and corsairs watch for easy prey.",sp=0}},faq={{q="Where does the Southern Savage Coast begin and end?",a="The Southern Savage Coast begins below the Vile Reef and runs south along Stranglethorn Vale's southwestern shore. It passes Booty Bay and Janeiro's Point before meeting the Wild Shore.",al={"southern savage coast location","where is southern savage coast","savage coast borders"}},{q="How is it different from the northern Savage Coast?",a="The Vile Reef divides the two coasts. The northern Savage Coast follows the Great Sea waters off northern Stranglethorn, while the Southern Savage Coast borders the South Seas along the lower cape.",al={"difference between savage coast and southern","why two savage coasts","vile reef border"}},{q="What threats can travelers expect along the beach?",a="Vicious basilisk lizards and snapping crocolisks roam the open sand. Hostile naga emerge from the shallows, and territorial pirates patrol the coast.",al={"is southern savage coast dangerous","mobs on southern savage coast","threats along the coast"}},{q="Does Booty Bay control this coastline?",a="No. The Blackwater Raiders and Steamwheedle Cartel control Booty Bay's harbor and its immediate approaches. The wild beaches to the north and south remain lawless, untamed territory.",al={"does booty bay own the beach","steemwheedle control of coast","goblin territory"}}},ang={["class:Hunter"]="As a hunter, you find clear tracking ground on the wide beaches, where amphibious game, coastal cats, and basilisks roam. The open shore gives you better sightlines than the close brush inland."},kw={"booty bay","janeiro's point","savage coast","south seas","southern savage coast","stranglethorn vale","vile reef"},rel={"zone:stranglethorn","subzone:savage-coast","subzone:vile-reef","subzone:booty-bay","subzone:janeiro-s-point","subzone:nek-mani-wellspring","subzone:wild-shore","topic:naga"},src={"Southern Savage Coast"}}
E["subzone:tkashi-ruins"] = {t="subzone",n="Tkashi Ruins",z="stranglethorn",s="Bloodscalp trolls guard the Tkashi Ruins southwest of Nesingwary's Expedition in northern Stranglethorn Vale.",h="Bloodscalp trolls guard the Tkashi Ruins southwest of Nesingwary's Expedition in northern Stranglethorn Vale.",sec={{t="Stones of the Bloodscalp",b="Southwest of Hemet Nesingwary's hunting camp, crumbling stones mark an ancient domain of Stranglethorn's jungle trolls. The Bloodscalp tribe now occupies the ruins and fiercely defends its territory. Among the vines and decayed stone, they practice shamanistic rituals. Hemet Nesingwary wrote that he passed through without trouble, but travelers now face Bloodscalp guards protecting tribal relics buried in the rubble.",sp=0}},faq={{q="Who lives in the Tkashi Ruins?",a="The Bloodscalp tribe lives in the ruins. These hostile jungle trolls defend the crumbling compound against outsiders and rival tribes.",al={"who is here","tkashi ruins mobs","trolls at tkashi"}},{q="Where are the Tkashi Ruins located?",a="The Tkashi Ruins lie in northern Stranglethorn Vale, just southwest of the river crossing near Nesingwary's Expedition.",al={"tkashi location","where is tkashi","find tkashi ruins"}},{q="What is mentioned about Tkashi in Hemet Nesingwary's writings?",a="In chapter three of The Green Hills of Stranglethorn, Hemet Nesingwary writes that he and his hunting party crossed the Tkashi Ruins without incident during their early days in the jungle. He records it on page twenty-one.",al={"nesingwary tkashi","green hills tkashi"}}},ang={["race:Troll"]="As a Darkspear troll, you may see Tkashi as a grim reminder of ancient tribal ruins left by your hostile Gurubashi kin. Savage Bloodscalp holdouts now defend the site."},kw={"bloodscalp","nesingwary","stranglethorn","stranglethorn vale","tkashi","tkashi ruins","troll ruins"},rel={"zone:stranglethorn","subzone:nesingwary-s-expedition","topic:troll","subzone:kurzen-s-compound","topic:alliance","quest:5762"},src={"Tkashi Ruins"}}
E["subzone:venture-co-base-camp"] = {t="subzone",n="Venture Co. Base Camp",z="stranglethorn",s="In northern Stranglethorn, Venture Co. Base Camp cuts into the jungle. Goblin overseers and laborers harvest timber, hunt wildlife, and search nearby waterways for tumbled crystals.",h="In northern Stranglethorn, Venture Co.",sec={{t="Industrial Encroachment",b="Venture Co. Base Camp sends crews into the jungle for profit. Steam-powered machines and rough goblin shacks break through the ancient canopy. Armed mercenaries guard the camp. Foremen and workers direct the gathering of resources across nearby valleys. They search the waterways for tumbled crystals and clear jungle that blocks their work.",sp=0}},faq={{q="What is the Venture Company doing in Stranglethorn Vale?",a="The Venture Company logs northern Stranglethorn's dense jungle, builds heavy operations, and gathers valuable minerals. Tumbled crystals from nearby waterways are among its prizes.",al={"why are goblins here","venture co purpose","venture company stranglethorn"}},{q="Are the goblins here affiliated with the Steamwheedle Cartel in Booty Bay?",a="No. The Venture Company is separate from Baron Revilgaz and the Steamwheedle Cartel. Booty Bay's merchants build trade ties, while the Venture Company exploits the land and turns hostile toward those who hinder its profits.",al={"is venture co booty bay","are they friendly to booty bay","venture co steamwheedle"}},{q="What lies beyond the base camp?",a="The Venture Co. Operations Center lies beside the base camp. Its logging machinery, lumber stores, and company managers direct the clearing of jungle across the region.",al={"where does this camp lead","what is adjacent to base camp","venture co operations center"}}},ang={["class:Druid"]="As a druid, you see the Venture Company tear into jungle habitats and disturb nature's balance with crude machinery.",["profession:Mining"]="As a miner, you find company prospectors searching the jungle for raw materials and rare tumbled crystals."},kw={"goblin lumber","operations center","stranglethorn vale","tumbled crystals","venture co base camp","venture company"},rel={"topic:venture-company","zone:stranglethorn","topic:goblin","quest:764"},src={"Venture Co. Base Camp"}}
E["subzone:vile-reef"] = {t="subzone",n="Vile Reef",z="stranglethorn",s="Murlocs guard Vile Reef beneath the Great Sea, just off Stranglethorn Vale near Grom'gol Base Camp. Coral, troll ruins, shipwrecks, and giant clams fill its waters.",h="Murlocs guard Vile Reef beneath the Great Sea, just off Stranglethorn Vale near Grom'gol Base Camp.",sec={{t="Sunken Stones and Coral Beds",b="Beneath the Great Sea, Vile Reef lies just offshore from Grom'gol Base Camp. Vivid coral grows across the seabed beside weathered troll ruins and the Altar of the Tides. Territorial murlocs lurk among the coral and shattered ship timbers. They defend the shallows and prey on divers seeking giant clams and rare blue pearls.",sp=0}},faq={{q="Where is the Vile Reef located?",a="Vile Reef lies in the Great Sea off Stranglethorn Vale's western shore, directly northwest of Grom'gol Base Camp.",al={"vile reef location","where is vile reef","how to find vile reef"}},{q="What creatures inhabit the Vile Reef?",a="Hostile murlocs swim among the coral and sunken structures. Giant clams rest on the sea floor.",al={"vile reef mobs","monsters in vile reef","who lives in vile reef"}},{q="What ruins are found underwater here?",a="Ancient troll ruins and the Altar of the Tides lie on the sea floor, remnants of troll civilization swallowed by the ocean.",al={"vile reef ruins","sunken ruins stranglethorn","altar of the tides location"}},{q="Why do adventurers dive into the Vile Reef?",a="Divers brave the murlocs to explore shipwrecks, investigate the Altar of the Tides, and harvest giant clams that may conceal precious blue pearls.",al={"why go to vile reef","vile reef treasures","blue pearls stranglethorn"}}},ang={["faction:Horde"]="Just offshore from Grom'gol Base Camp, Vile Reef remains a maritime threat to Horde supply vessels and coastal patrols in Stranglethorn Vale.",["race:Troll"]="The sunken stones and Altar of the Tides recall the long-lost coastal territory once commanded by the jungle trolls."},kw={"altar of the tides","blue pearls","giant clams","grom'gol","murloc","stranglethorn vale","vile reef"},rel={"zone:stranglethorn","subzone:grom-gol-base-camp","topic:murloc","topic:troll"},src={"Vile Reef"}}
E["subzone:wild-shore"] = {t="subzone",n="Wild Shore",z="stranglethorn",s="Bloodsail Buccaneers anchor along Wild Shore, where Stranglethorn Vale's jungle meets the South Seas.",h="Bloodsail Buccaneers anchor along Wild Shore, where Stranglethorn Vale's jungle meets the South Seas.",sec={{t="Edge of the South Seas",b="At Stranglethorn Vale's southern tip, you reach the Wild Shore and the South Seas. Booty Bay's fortified inlet lies northwest, while a shallow strait separates the mainland beach from Jaguero Isle to the east. The shore runs northeast toward the Crystal Shore. Blackwater Raiders' cannons cannot reach this coast directly, so pirates gather here among wild dangers.",sp=0},{t="Pirates and Giants",b="Bloodsail Buccaneers hold much of the shore. Their wooden ships anchor in the surf, and their camps spread across the sand. They stage operations here, store illicit cargo, and plan strikes against their goblin rivals.\n\nProwling beasts also haunt the beaches. Gorlash, a colossal sea giant, stomps through the surf and crushes anyone who lingers along the tide line.",sp=0}},faq={{q="Where is the Wild Shore located?",a="Wild Shore forms Stranglethorn Vale's southern coastline in the Eastern Kingdoms. South of Booty Bay, it faces the South Seas and Jaguero Isle.",al={"wild shore location","where is wild shore","wild shore map"}},{q="Who controls the Wild Shore?",a="Bloodsail Buccaneers dominate the coastline. They moor several ships in the shallows and keep camps along the sandy beaches.",al={"who lives on the wild shore","wild shore factions","wild shore pirates"}},{q="Who is Gorlash?",a="Gorlash is an enormous sea giant who prowls Wild Shore's shallows. He threatens unwary sailors and pirates walking the beach.",al={"gorlash giant","who is the giant on the beach","gorlash wild shore"}},{q="How does the Wild Shore relate to Booty Bay?",a="A rocky point separates Booty Bay from Wild Shore. Booty Bay is the stronghold of the Blackwater Raiders and the Steamwheedle Cartel. Nearby, Wild Shore gives their sworn enemies, the Bloodsail Buccaneers, a natural staging ground.",al={"booty bay connection","wild shore booty bay"}}},ang={["class:Rogue"]="As a rogue, you can pick pockets in Bloodsail camps and aboard anchored vessels. You can also study rival swashbucklers operating beyond the Steamwheedle Cartel's law."},kw={"bloodsail buccaneers","booty bay","gorlash","jaguero isle","pirates","south seas","stranglethorn","wild shore"},rel={"subzone:booty-bay","subzone:jaguero-isle","subzone:crystal-shore","subzone:southern-savage-coast","zone:stranglethorn","subzone:south-seas"},src={"Wild Shore"}}
E["subzone:yojamba-isle"] = {t="subzone",n="Yojamba Isle",z="stranglethorn",s="On Yojamba Isle, Zandalari emissaries seek champions to face horrors awakening in Zul'Gurub. Their camp lies off Stranglethorn Vale's northwestern coast, near the waters leading to Westfall, and calls on Horde and Alliance alike.",h="On Yojamba Isle, Zandalari emissaries seek champions to face horrors awakening in Zul'Gurub.",sec={{t="The Emissaries of Zandalar",b="The Zandalar Tribe keeps an uneasy peace on Yojamba Isle, though most trolls in Stranglethorn Vale are hostile to outsiders. As priests and lorekeepers of troll civilization, the Zandalari have watched the Gurubashi trolls of Zul'Gurub turn to Hakkar the Soulflayer.\n\nA fully summoned blood god threatens the world, so the Zandalari have traveled far from their ancestral home to establish a staging ground. They call on capable adventurers from either faction to help curb the danger.",sp=0},{t="Guarded Waters",b="Yojamba Isle lies northwest of the Vile Reef and the haunted ruins along the mainland beaches. Ironclad Cove's massive hidden sea-gate lies to the north, and wandering sea beasts frequent the shallows. Though its position is precarious, the Zandalari camp offers a quiet refuge. Exotic rituals, sacred altars, and ancient knowledge give solace and power to those preparing to march into the jungle's darkest ruins.",sp=0}},faq={{q="Why are the trolls on Yojamba Isle friendly?",a="The Zandalar Tribe are priests and historians revered by trolls. They have come to stop Hakkar the Soulflayer in Zul'Gurub, and need champions from both the Horde and the Alliance to help.",al={"friendly trolls yojamba","why don't yojamba trolls attack","zandalar friendly"}},{q="Where is Yojamba Isle located?",a="Yojamba Isle lies in the far northwestern sea of Stranglethorn Vale, just off the coast northwest of the Vile Reef. It sits near the maritime boundary where the southern sea borders Westfall.",al={"yojamba isle location","how to get to yojamba","where is yojamba"}},{q="What is the Zandalar Tribe doing out here?",a="The Zandalar Tribe has established a forward camp to watch Hakkar the Soulflayer's dangerous resurgence in Zul'Gurub. From Yojamba Isle, its emissaries recruit, supply, and reward powerful adventurers willing to enter the ancient troll city and defeat the corrupted priesthood before Hakkar's full power is unleashed upon Azeroth.",al={"zandalar purpose","what do zandalari want","why are zandalar here"}}},ang={["race:Troll"]="As a Darkspear troll, you meet the ancient ancestral root of troll civilization. Its traditions, prestige, and demands command deep cultural reverence.",["faction:Alliance"]="As an Alliance adventurer, you may be startled to find a peaceful troll encampment so close to Westfall. The Zandalari set politics aside before the cataclysmic threat of the Soulflayer."},kw={"blood god","hakkar","stranglethorn","vile reef","yojamba island","yojamba isle","zandalar","zandalari","zul'gurub"},rel={"subzone:zul-gurub","zone:stranglethorn","subzone:vile-reef","subzone:ironclad-cove","zone:westfall","topic:troll","topic:horde","topic:alliance"},src={"Yojamba Isle"}}
E["subzone:zul-gurub"] = {t="subzone",n="Zul'Gurub",z="stranglethorn",s="In northeastern Stranglethorn Vale, Zul'Gurub's jungle trolls scheme to summon an ancient entity into the world. The ruined temple city once stood at the heart of the Gurubashi Empire.",h="In northeastern Stranglethorn Vale, Zul'Gurub's jungle trolls scheme to summon an ancient entity into the...",sec={{t="Heart of the Fallen Empire",b="Thousands of years ago, Zul'Gurub was the vibrant capital of the Gurubashi Empire. Its stone ziggurats rose over a realm united under Gurubashi rule. Then civil war came, roughly fifteen hundred years before the Dark Portal opened.\n\nThe Atal'ai, a radical sect of priests, tried to summon Hakkar the Soulflayer and claim absolute power. Loyalist tribes joined forces and defeated them. The Atal'ai were banished north to the Swamp of Sorrows. The war broke the empire, and Zul'Gurub became a violent shadow of its former grandeur.",sp=0},{t="The Looming Shadow of the Soulflayer",b="The fanatical worshippers of Hakkar kept their devotion after exile. They learned that his physical avatar could be summoned only from Zul'Gurub, his ancient ritual seat. Within the city, dark sorcerers such as Jin'do the Hexxer have sought to enslave Gurubashi high priests for blood rituals in Hakkar's name.\n\nHyper-aggressive Gurubashi trolls prowl the jungle around the ruins, driven into a murderous frenzy. Zul'Gurub remains an epicenter of dread for anyone who ventures near its borders.",sp=1}},faq={{q="What is Zul'Gurub?",a="Zul'Gurub is an ancient temple city in northeastern Stranglethorn Vale. Thousands of years ago, it was the vibrant capital of the Gurubashi Empire. Now the ruined city is a dangerous stronghold inhabited by hostile Gurubashi trolls.",al={"zg history","what is zg","about zulgurub"}},{q="Who is Hakkar the Soulflayer?",a="Hakkar the Soulflayer is an ancient, terrible blood god. The fanatical Atal'ai worship him, and his cultists have long plotted to bring his physical avatar into Azeroth through rituals in Zul'Gurub.",al={"hakkar","blood god","who is the soulflayer"}},{q="Why did the Gurubashi Empire collapse?",a="Roughly fifteen hundred years before the Dark Portal opened, civil war tore the Gurubashi Empire apart. The radical Atal'ai priests tried to summon Hakkar. The other trolls defeated and banished them, but the war left the empire shattered.",al={"why gurubashi fell","gurubashi civil war","fall of zul'gurub"}},{q="Can adventurers safely explore the ruins?",a="No. Zul'Gurub is exceptionally hazardous. The trolls in its ruins are violently aggressive and driven by bloody fervor. Treasure hunters and artifact seekers regularly disappear within its stone walls, and very few return.",al={"is zg safe","zg treasure","exploring zg"}}},ang={["race:Troll"]="For the Darkspear tribe, Zul'Gurub is a monument to their ancestors' fallen grandeur and a warning of the ruinous price of serving Hakkar.",["faction:Horde"]="The Horde watches Zul'Gurub's dark rituals warily. Hakkar's return threatens nearby settlements and tribes across Stranglethorn."},kw={"atal'ai","gurubashi","hakkar","jin'do","soulflayer","stranglethorn vale","troll capital","zul'gurub"},rel={"zone:stranglethorn","topic:troll","topic:darkspear-tribe","zone:swampofsorrows","subzone:dark-portal","topic:horde","quest:2300","npc:mathias-shaw"},src={"Zul'Gurub"}}
E["zone:stranglethorn"] = {t="zone",n="Stranglethorn Vale",z="stranglethorn",s="Trolls, goblins, pirates, and soldiers contest Stranglethorn Vale. South of Duskwood, the old Gurubashi heartland has become a maze of ruins, beasts, and rival camps.",h="Trolls, goblins, pirates, and soldiers contest Stranglethorn Vale.",sec={{t="Ruins of an Empire",b="Zul'Gurub once ruled the vale as the Gurubashi Empire's capital. That rule ended when radical priests summoned Hakkar the Soulflayer, and civil war tore through the region. The Zandalari crushed the blood god's uprising, but the empire never recovered. Now successor factions fight across the jungle. The Bloodscalp hold the northwest, while the Skullsplitter occupy the east. Both tribes slaughter outsiders as they fight to reclaim their ancestral home.",sp=0},{t="Pirates and Profiteers",b="Booty Bay fills the vale's southern tip with trade and sea traffic. The Steamwheedle Cartel carved out the port, and the Blackwater Raiders run it under Baron Revilgaz. Bloodsail Buccaneers anchored along the coast keep the port under constant threat. Farther inland, the Venture Company cuts timber and mines the hills for rare singing crystals.",sp=0},{t="A Contested Wilderness",b="Rival powers meet across the vale's dangerous borderland. The Horde holds Grom'gol Base Camp on the western coast, and goblin zeppelins link it to Durotar and Tirisfal Glades. Alliance loyalists at the Rebel Camp hunt for the rogue Colonel Kurzen. In the thick jungle, famed hunter Hemet Nesingwary leads big-game expeditions. Wanderers drawn to his hunts face prowling panthers, enormous apes, and enemy soldiers.",sp=0},{t="The Madness in the Jungle",b="Colonel Kurzen led a Stormwind expedition into the northern jungle, then went mad and built a tyrannical mercenary redoubt. The Mind's Eye, wielded by Mai'Zoth, an ogre mage from the nearby Mosh'Ogg Ogre Mound, ensnared Kurzen's mind with sorcery. The expedition fell into madness, and Kurzen's former men broke away to form the Rebel Camp.",sp=1}},faq={{q="Who controls Stranglethorn Vale?",a="No single power controls Stranglethorn Vale. Bloodscalp and Skullsplitter trolls, Kurzen's Compound, the Venture Company, and Horde and Alliance military posts hold rival ground. Booty Bay is the largest settlement, governed by Baron Revilgaz and the Blackwater Raiders.",al={"who owns stranglethorn","who rules stv","stranglethorn factions"}},{q="What is Booty Bay?",a="Booty Bay is a port city on the southern bluffs of the Cape of Stranglethorn. Once the human settlement of Blackwater Cove, it was captured by trolls and later secured by the Steamwheedle Cartel. Baron Revilgaz and Fleet Master Seahorn run it as a neutral trading port, linking travelers with Ratchet across the Great Sea.",al={"what is booty bay","booty bay port","who runs booty bay"}},{q="Why did Colonel Kurzen go rogue?",a="Colonel Kurzen went rogue after Mai'Zoth, an ogre mage wielding the Mind's Eye, ensnared his mind. Kurzen had led a Stormwind expedition into the jungle, but grew erratic and despotic. Lieutenant Doren and loyal soldiers broke away to form the Rebel Camp and stop him.",al={"why is kurzen evil","what happened to kurzen","kurzen backstory"},sp=1},{q="What is Zul'Gurub?",a="Zul'Gurub is the ruined capital of the Gurubashi Empire in northeastern Stranglethorn. Fifteen centuries ago, radical priests summoned Hakkar the Soulflayer there, starting the civil war that ended the empire. Vines and ruins cover the abandoned city, but dark rituals still threaten its halls.",al={"what is zg","zul gurub history","capital of gurubashi"}},{q="What was the Stone of the Tides?",a="The Stone of the Tides is a legendary relic from ancient Gurubashi history, found on the coast by a troll warrior. It gave its bearer control over water and elemental summons like a powerful mage, earning the name Tidebearer. Its curse slowly drew each bearer from the physical realm until they walked into the sea and vanished.",al={"stone of the tides","tidebearer legend","gurubashi water stone"}},{q="How do I travel to Stranglethorn Vale?",a="You can walk south from Duskwood across the river border into northern Stranglethorn. Horde zeppelins link Grom'gol Base Camp with Durotar and Tirisfal Glades. From Kalimdor, take the merchant vessel that sails between Ratchet in the Barrens and Booty Bay.",al={"how to get to stv","getting to stranglethorn","stv travel"}}},ang={["race:Troll"]="As a troll, your ancestral homeland is the jungle troll cradle of Stranglethorn. Civil war followed the Gurubashi Empire's worship of Hakkar the Soulflayer, driving tribes like the Darkspear across the seas.",["faction:Horde"]="As Horde, you can rely on Grom'gol Base Camp as a strategic stronghold on the southern continent, supplied by zeppelins from Durotar and the Undercity.",["faction:Alliance"]="As Alliance, you inherit Stormwind's costly efforts to conquer and pacify the jungle. Now hard-pressed mutineers at the Rebel Camp defend the kingdom's interests.",["class:Hunter"]="As a hunter, you can meet famed big-game hunter Hemet Nesingwary on the northern riverbank. He challenges marksmen to track the jungle's fiercest raptors, panthers, and crocolisks.",["profession:Herbalism"]="As a herbalist, you can search the humid canopy's riverbanks and coastlines for Wild Steelbloom, Fadeleaf, Goldthorn, and Purple Lotus."},kw={"bloodsail","booty bay","grom'gol","gurubashi","kurzen","nesingwary","revilgaz","stranglethorn","venture co","zul'gurub"},rel={"subzone:booty-bay","subzone:grom-gol-base-camp","subzone:zul-gurub","npc:baron-revilgaz","npc:colonel-kurzen","quest:5762","subzone:nesingwary-s-expedition","subzone:rebel-camp"},src={"Stranglethorn Vale (Classic)","Stranglethorn Vale"}}
